// Function to serialize a log event into a binary format
size_t serialize_log_event(LogEvent *event, void **buffer) {
    size_t size = sizeof(event->timestamp) + sizeof(event->event_code);
    switch (event->context.integer_data) {
        case 0:
            size += strlen(event->context.text_data) + 1;
            break;
        case 1:
            size += sizeof(event->context.integer_data);
            break;
        // Add cases for other data types as needed
    }

    *buffer = malloc(size);
    if (!*buffer) {
        return 0; // Memory allocation failed
    }

    memcpy(*buffer, &event->timestamp, sizeof(event->timestamp));
    memcpy((char*)*buffer + sizeof(event->timestamp), &event->event_code, sizeof(event->event_code));
    switch (event->context.integer_data) {
        case 0:
            memcpy((char*)*buffer + sizeof(event->timestamp) + sizeof(event->event_code),
                   event->context.text_data,
                   strlen(event->context.text_data) + 1);
            break;
        case 1:
            memcpy((char*)*buffer + sizeof(event->timestamp) + sizeof(event->event_code),
                   &event->context.integer_data,
                   sizeof(event->context.integer_data));
            break;
        // Add cases for other data types as needed
    }

    return size;
}

// Function to deserialize a binary buffer into a log event
LogEvent *deserialize_log_event(void *buffer, size_t size) {
    LogEvent *event = malloc(sizeof(LogEvent));
    if (!event) {
        return NULL; // Memory allocation failed
    }

    memcpy(&event->timestamp, buffer, sizeof(event->timestamp));
    memcpy(&event->event_code, (char*)buffer + sizeof(event->timestamp), sizeof(event->event_code));
    switch (event->context.integer_data) {
        case 0:
            event->context.text_data = malloc(size - sizeof(event->timestamp) - sizeof(event->event_code) - 1);
            if (!event->context.text_data) {
                free(event);
                return NULL; // Memory allocation failed
            }
            memcpy(event->context.text_data, (char*)buffer + sizeof(event->timestamp) + sizeof(event->event_code), size - sizeof(event->timestamp) - sizeof(event->event_code) - 1);
            event->context.text_data[size - sizeof(event->timestamp) - sizeof(event->event_code) - 1] = '\0';
            break;
        case 1:
            memcpy(&event->context.integer_data, (char*)buffer + sizeof(event->timestamp) + sizeof(event->event_code), sizeof(event->context.integer_data));
            break;
        // Add cases for other data types as needed
    }

    return event;
}

