}

// Thread function for concurrent logging
void *thread_function(void *arg) {
    LogEvent *event = (LogEvent*)arg;
    log_event(event);
    free(event); // Free allocated memory when done
    return NULL;
}

int main() {
    pthread_t thread1, thread2;

    // Create and log events concurrently
    LogEvent *event1 = malloc(sizeof(LogEvent));
    event1->timestamp = time(NULL);
    event1->event_code = 1;
    event1->context.integer_data = 42; // Example integer data

    pthread_create(&thread1, NULL, thread_function, (void*)event1);

    LogEvent *event2 = malloc(sizeof(LogEvent));
    event2->timestamp = time(NULL) + 1;
    event2->event_code = 2;
    event2->context.text_data = "Example text data"; // Example text data

