#define MAX_MEMORY_USAGE 0.6

typedef struct {
    int key;
    long offset;
    time_t timestamp;
} record;

record* records = NULL;
int num_records = 0;
size_t total_memory = 0;
pthread_mutex_t records_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_records(int dataset_size) {
    pthread_mutex_lock(&records_lock);

    if (dataset_size <= 0) {
        fprintf(stderr, "Invalid dataset size\n");
        pthread_mutex_unlock(&records_lock);
        return;
    }

    // Calculate total memory required for records
    size_t required_memory = sizeof(record) * dataset_size;

    // Check if the requested memory usage is within limits
    if (required_memory > MAX_MEMORY_USAGE * total_memory) {
        fprintf(stderr, "Memory allocation exceeds 60%% of available system RAM\n");
        pthread_mutex_unlock(&records_lock);
        return;
    }

    // Allocate memory for records
    records = realloc(records, required_memory);
    if (!records) {
        perror("Failed to allocate memory for records");
        pthread_mutex_unlock(&records_lock);
        return;
    }

    num_records = dataset_size;

    // Initialize records with random offsets and sequential keys
    srand(time(NULL));
    long offset_range_start = 1000; // Example start of offset range
    long offset_range_end = 10000;  // Example end of offset range

    for (int i = 0; i < num_records; ++i) {
        records[i].key = i + 1;
        records[i].offset = rand() % (offset_range_end - offset_range_start + 1) + offset_range_start;
        records[i].timestamp = time(NULL);
    }

    pthread_mutex_unlock(&records_lock);
}

void free_records() {
    pthread_mutex_lock(&records_lock);
    if (records) {
        free(records);
        records = NULL;
        num_records = 0;
    }
    pthread_mutex_unlock(&records_lock);
}
