#define MAX_INPUT_SIZE 1024

typedef struct {
    int* data;
    size_t size;
    size_t capacity;
} IntegerArray;

void init_integer_array(IntegerArray* array) {
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
}

void resize_integer_array(IntegerArray* array, size_t new_capacity) {
    if (new_capacity > array->capacity) {
        array->data = realloc(array->data, new_capacity * sizeof(int));
        if (array->data == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        array->capacity = new_capacity;
    }
}

void add_integer_to_array(IntegerArray* array, int value) {
    if (array->size >= array->capacity) {
        resize_integer_array(array, array->capacity == 0 ? 1 : array->capacity * 2);
    }
    array->data[array->size++] = value;
}

int find_largest_integer(const IntegerArray* array) {
    int largest = INT_MIN;
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i] > largest) {
            largest = array->data[i];
        }
    }
    return largest;
}

void free_integer_array(IntegerArray* array) {
    free(array->data);
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <input_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    IntegerArray integer_array;
    init_integer_array(&integer_array);

    FILE* input_file = fopen(argv[1], "r");
    if (input_file == NULL) {
        perror("Failed to open input file");
        return EXIT_FAILURE;
    }

    char line[MAX_INPUT_SIZE];
    while (fgets(line, sizeof(line), input_file)) {
        char* token = strtok(line, " \t\n");
        while (token != NULL) {
            if (isdigit(*token) || (*token == '-' && isdigit(*(token + 1)))) {
                int value = atoi(token);
                add_integer_to_array(&integer_array, value);
            } else {
                fprintf(stderr, "Malformed input: %s\n", token);
            }
            token = strtok(NULL, " \t\n");
        }
    }

    fclose(input_file);

    if (integer_array.size > 0) {
        int largest = find_largest_integer(&integer_array);
        printf("Largest integer: %d at position: %zu\n", largest, 
               find_index_of_largest_integer(&integer_array));
    } else {
        fprintf(stderr, "No valid integers found in input file\n");
    }

    free_integer_array(&integer_array);

    return EXIT_SUCCESS;
}
