    char message[256];
    time_t timestamp;
} LogEntry;

// Buffer for log entries
#define LOG_BUFFER_SIZE 100
LogEntry log_buffer[LOG_BUFFER_SIZE];
int log_index = 0;
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

// Asynchronous logging thread function
void* async_log_thread(void* arg) {
    while (1) {
        pthread_mutex_lock(&log_lock);
        if (log_index > 0) {
            // Send log entries to cloud-based logging service
            for (int i = 0; i < log_index; i++) {
                printf("Logging: %s\n", log_buffer[i].message); // Placeholder for actual cloud log submission
            }
            log_index = 0;
        }
        pthread_mutex_unlock(&log_lock);
        sleep(1); // Adjust sleep time based on performance and log volume
    }
    return NULL;
}

// Initialize logging framework
void init_logging() {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, async_log_thread, NULL);
}

// Log a message with dynamic formatting and rate-limiting
void log_message(LogLevel level, const char* format, ...) {
    if (level == ERROR) {
        static time_t last_error_time = 0;
        static int error_count = 0;

        time_t current_time = time(NULL);
        if (current_time != last_error_time || ++error_count > 10) {
            va_list args;
            va_start(args, format);
            char buffer[256];
            vsnprintf(buffer, sizeof(buffer), format, args);
            va_end(args);

            LogEntry entry = {level, buffer, current_time};
            pthread_mutex_lock(&log_lock);
            log_buffer[log_index++] = entry;
            if (log_index >= LOG_BUFFER_SIZE) {
                log_index = 0; // Simplified for demonstration
            }
            pthread_mutex_unlock(&log_lock);

            last_error_time = current_time;
            error_count = 0;
        }
    } else {
        va_list args;
        va_start(args, format);
        char buffer[256];
        vsnprintf(buffer, sizeof(buffer), format, args);
        va_end(args);

        LogEntry entry = {level, buffer, time(NULL)};
        pthread_mutex_lock(&log_lock);
        log_buffer[log_index++] = entry;
        if (log_index >= LOG_BUFFER_SIZE) {
            log_index = 0; // Simplified for demonstration
        }
        pthread_mutex_unlock(&log_lock);
    }
}

// Example usage
int main() {
    init_logging();

    log_message(INFO, "Application started");
    log_message(ERROR, "An error occurred: %s", "file not found");

    return 0;
}
