['```python
# Import necessary libraries
import hashlib
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
import time
import logging

# Set up logging configuration
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class FileHasher:
    def __init__(self, cache=None):
        self.cache = cache or {}

    def hash_file(self, file_path):
        if file_path in self.cache:
            return self.cache[file_path]
        with open(file_path, 'rb') as f:
            hasher = hashlib.sha256()
            for chunk in iter(lambda: f.read(4096), b''):
                hasher.update(chunk)
            hash_value = hasher.hexdigest()
            self.cache[file_path] = hash_value
            return hash_value

class CloudStorageHasher(FileHasher):
    def hash_file(self, file_url):
        if file_url in self.cache:
            return self.cache[file_url]
        try:
            response = requests.get(file_url, stream=True, timeout=30)
            hasher = hashlib.sha256()
            for chunk in response.iter_content(chunk_size=4096):
                hasher.update(chunk)
            hash_value = hasher.hexdigest()
            self.cache[file_url] = hash_value
            return hash_value
        except requests.exceptions.RequestException as e:
            logging.error(f"Failed to fetch file from {file_url}: {e}")
            raise

class ExternalAPILoader(FileHasher):
    def __init__(self, api_endpoint, cache=None):
        super().__init__(cache)
        self.api_endpoint = api_endpoint

    def hash_file(self, file_id):
        if file_id in self.cache:
            return self.cache[file_id]
        try:
            response = requests.get(f"{self.api_endpoint}/{file_id}", timeout=30)
            response.raise_for_status()
            data = response.json()
            file_url = data['url']
            return super().hash_file(file_url)
        except (requests.exceptions.RequestException, ValueError) as e:
            logging.error(f"Failed to fetch file {file_id} from API: {e}")
            raise

def estimate_remaining_time(start_time, processed_bytes, total_bytes):
    elapsed_time = time.time() - start_time
    bytes_per_second = processed_bytes / elapsed_time if elapsed_time > 0 else float('inf')
    remaining_time = (total_bytes - processed_bytes) / bytes_per_second if bytes_per_second > 0 else float('inf')
    return remaining_time

def process_files(file_paths, file_hasher, progress_callback):
    start_time = time.time()
    total_bytes = sum(os.path.getsize(path) for path in file_paths)
    processed_bytes = 0
    with ThreadPoolExecutor(max_workers=5) as executor:
        futures = {executor.submit(file_hasher.hash_file, path): path for path in file_paths}
        for future in as_completed(futures):
            path = futures[future]
            try:
                hash_value = future.result()
                processed_bytes += os.path.getsize(path)
                remaining_time = estimate_remaining_time(start_time, processed_bytes, total_bytes)
                progress_callback(processed_bytes, total_bytes, remaining_time)
            except Exception as e:
                logging.error(f"Error processing file {path}: {e}")

# Example usage
def progress_callback(processed_bytes, total_bytes, remaining_time):
    percentage = (processed_bytes / total_bytes) * 100 if total_bytes > 0 else 0
    print(f"Processed: {percentage:.2f}% | Remaining time: {remaining_time:.2f}s")

file_paths = ['local_file.txt', 'https://cloudstorage.com/file', 'https://api.example.com/files/123']
file_hasher = ExternalAPILoader('https://api.example.com/files')
process_files(file_paths, file_hasher, progress_callback)
