typedef enum {
    ECB, EDE, EDE3, CFB
} CipherMode;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    int mode;
    unsigned char iv[16];
} EncryptionLibrary;

void init_library(EncryptionLibrary *lib, CipherMode mode) {
    lib->mode = mode;
    switch (mode) {
        case ECB:
            EVP_EncryptInit_ex(lib->ctx, EVP_aes_256_ecb(), NULL, NULL, NULL);
            break;
        case EDE:
            EVP_EncryptInit_ex(lib->ctx, EVP_aes_256_cbc(), NULL, NULL, lib->iv);
            break;
        // Add cases for other modes
    }
}

void encrypt_file(EncryptionLibrary *lib, const char *input_file, const char *output_file) {
    FILE *in = fopen(input_file, "rb");
    if (!in) { perror("Failed to open input file"); return; }

    FILE *out = fopen(output_file, "wb");
    if (!out) { perror("Failed to open output file"); fclose(in); return; }

    unsigned char in_buf[4096], out_buf[4096];
    int in_len, out_len;

    while ((in_len = fread(in_buf, 1, sizeof(in_buf), in)) > 0) {
        if (lib->mode == ECB) {
            EVP_EncryptUpdate(lib->ctx, out_buf, &out_len, in_buf, in_len);
        } else {
            EVP_EncryptUpdate(lib->ctx, out_buf, &out_len, in_buf, in_len);
        }
        fwrite(out_buf, 1, out_len, out);
    }

    fclose(in); fclose(out);
}

void decrypt_file(EncryptionLibrary *lib, const char *input_file, const char *output_file) {
    // Similar to encrypt_file but using EVP_DecryptUpdate
}

