import json
import requests
from cachetools import cached, TTLCache
from concurrent.futures import ThreadPoolExecutor
import logging

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Define the cache with a time-to-live (TTL) of 60 seconds
cache = TTLCache(maxsize=100, ttl=60)

def fetch_data_from_api(api_url):
    try:
        response = requests.get(api_url)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        logger.error(f"Failed to fetch data from {api_url}: {e}")
        raise

@cached(cache)
def get_cached_data(api_url):
    return fetch_data_from_api(api_url)

def update_config(config_file_path, api_urls):
    with open(config_file_path, 'r') as file:
        config = json.load(file)

    for key, value in config.items():
        if isinstance(value, str) and value.startswith('http'):
            try:
                updated_value = get_cached_data(value)
                config[key] = updated_value
            except requests.exceptions.RequestException:
                logger.error(f"Failed to update {key} from API")

    with open(config_file_path, 'w') as file:
        json.dump(config, file, indent=4)

def handle_config_updates(api_urls, config_files):
    with ThreadPoolExecutor(max_workers=5) as executor:
        futures = [executor.submit(update_config, file, api_urls) for file in config_files]
        for future in futures:
            try:
                future.result()
            except Exception as e:
                logger.error(f"An error occurred: {e}")

