import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.HashMap;
import java.util.Map;
import org.json.JSONObject;

public class PokemonWeaknessService {
    private static final String API_URL = "https://pokeapi.co/api/v2/pokemon";
    private Map<Integer, JSONObject> cache = new HashMap<>();
    private Object lock = new Object();

    public JSONObject getPokemonWeakness(int id) throws IOException {
        if (cache.containsKey(id)) {
            return cache.get(id);
        }

        synchronized (lock) {
            if (!cache.containsKey(id)) {
                String response = fetchFromAPI(id);
                JSONObject pokemonData = new JSONObject(response);
                cache.put(id, pokemonData);
            }
        }

        return cache.get(id);
    }

    private String fetchFromAPI(int id) throws IOException {
        URL url = new URL(API_URL + "/" + id);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        int responseCode = connection.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_OK) {
            try (java.util.Scanner scanner = new java.util.Scanner(connection.getInputStream())) {
                return scanner.useDelimiter("\\A").next();
            }
        } else {
            throw new IOException("API request failed with code " + responseCode);
        }
    }

    public void clearCache() {
        synchronized (lock) {
            cache.clear();
        }
    }

    public static void main(String[] args) {
        PokemonWeaknessService service = new PokemonWeaknessService();
        try {
            System.out.println(service.getPokemonWeakness(1)); // Pikachu
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

