['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_SEMAPHORES 1000
#define MAX_THREADS 500

typedef struct {
    sem_t semaphore;
    int value;
} Semaphore;

Semaphore semaphores[MAX_SEMAPHORES];
int semaphore_count = 0;
pthread_mutex_t semaphore_lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file;

void log_semaphore_operation(char *operation, int id, int result) {
    fprintf(log_file, "%s - Semaphore ID: %d, Result: %d\n", operation, id, result);
}

int initialize_semaphore(int initial_value) {
    if (initial_value < 0 || initial_value > 1000 || semaphore_count >= MAX_SEMAPHORES) {
        return -1;
    }
    sem_init(&semaphores[semaphore_count].semaphore, 0, initial_value);
    semaphores[semaphore_count].value = initial_value;
    pthread_mutex_lock(&semaphore_lock);
    semaphore_count++;
    pthread_mutex_unlock(&semaphore_lock);
    log_semaphore_operation("Initialized", semaphore_count - 1, 0);
    return semaphore_count - 1;
}

int increment_semaphore(int id) {
    if (id < 0 || id >= semaphore_count) {
        return -1;
    }
    int result = sem_post(&semaphores[id].semaphore);
    pthread_mutex_lock(&semaphore_lock);
    semaphores[id].value++;
    pthread_mutex_unlock(&semaphore_lock);
    log_semaphore_operation("Incremented", id, result);
    return result;
}

int decrement_semaphore(int id) {
    if (id < 0 || id >= semaphore_count) {
        return -1;
    }
    int result = sem_wait(&semaphores[id].semaphore);
    pthread_mutex_lock(&semaphore_lock);
    semaphores[id].value--;
    pthread_mutex_unlock(&semaphore_lock);
    log_semaphore_operation("Decremented", id, result);
    return result;
}

int delete_semaphore(int id) {
    if (id < 0 || id >= semaphore_count) {
        return -1;
    }
    int result = sem_destroy(&semaphores[id].semaphore);
    pthread_mutex_lock(&semaphore_lock);
    for (int i = id; i < semaphore_count - 1; i++) {
        semaphores[i] = semaphores[i + 1];
    }
    semaphore_count--;
    pthread_mutex_unlock(&semaphore_lock);
    log_semaphore_operation("Deleted", id, result);
    return result;
}

void* thread_function(void* arg) {
    int id = *(int*)arg;
    for (int i = 0; i < 100; i++) { // Simulate work
        decrement_semaphore(id % semaphore_count);
        increment_semaphore((id + 1) % semaphore_count);
    }
    pthread_exit(NULL);
}

int main() {
    log_file = fopen("semaphore_log.txt", "w");
    for (int i = 0; i < 100; i++) {
        initialize_semaphore(rand() % 1001);
    }

    pthread_t threads[MAX_THREADS];
    int thread_ids[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, thread_function, &thread_ids[i]);
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < semaphore_count; i++) {
        delete_semaphore(i);
    }
    fclose(log_file);
    return 0;
}
```

This code provides a basic implementation of a semaphore system in C. It includes functions to initialize, increment, decrement, and delete semaphores, as well as a logging mechanism for tracking operations. The main function simulates a high-concurrency environment by creating multiple threads that access shared resources controlled by the semaphores.']

