#include <iostream>
#include <forward_list>
#include <string>
#include <chrono>
#include <thread>
#include <mutex>

std::mutex logMutex;

void logError(const std::string& message) {
    std::lock_guard<std::mutex> lock(logMutex);
    auto now = std::chrono::system_clock::now();
    auto timePoint = std::chrono::system_clock::to_time_t(now);
    std::cerr << "[" << std::ctime(&timePoint) << "] ERROR: " << message << std::endl;
}

void fetchMetadata(std::string& request) {
    // Simulate network operation
    std::this_thread::sleep_for(std::chrono::seconds(1));
    if (request == "error") {
        throw std::runtime_error("Failed to fetch metadata");
    }
    request += "_meta";
}

void appendOrInsertAfter(std::forward_list<std::string>& requests, const std::string& target, const std::string& newRequest, bool fetchMetadataFlag) {
    if (requests.empty()) {
        requests.push_front(newRequest);
        return;
    }

    auto it = requests.before_begin();
    auto beforeIt = requests.begin();

    while (beforeIt != requests.end()) {
        if (*beforeIt == target) {
            requests.insert_after(it, newRequest);
            if (fetchMetadataFlag && *newRequest != "error") {
                try {
                    fetchMetadata(const_cast<std::string&>(*newRequest));
                } catch (const std::exception& e) {
                    logError("Failed to fetch metadata for request: " + *newRequest + ". Error: " + std::string(e.what()));
                }
            }
            return;
        }
        ++it;
        ++beforeIt;
    }

    if (fetchMetadataFlag && newRequest != "error") {
        try {
            fetchMetadata(const_cast<std::string&>(newRequest));
        } catch (const std::exception& e) {
            logError("Failed to fetch metadata for request: " + newRequest + ". Error: " + std::string(e.what()));
        }
    }

    requests.push_front(newRequest);
}
