        : config_(config) {}

    std::string GetRequest(const std::string& endpoint) {
        std::this_thread::sleep_for(std::chrono::milliseconds(config_.response_delay));
        if (config_.simulate_failure) {
            throw std::runtime_error("Mock service failure");
        }
        return "Data from " + config_.base_url + endpoint;
    }

private:
    MockServiceConfig config_;
};

// HTTP Client Configuration
struct HttpClientConfig {
    std::string base_url;
    std::function<std::string(const std::string&)> token_provider;
};

class HttpClient {
public:
    HttpClient(const HttpClientConfig& config)
        : config_(config) {}

    std::string FetchData(const std::string& endpoint) {
        auto token = config_.token_provider();
        std::string url = config_.base_url + endpoint + "?auth_token=" + token;
        // Simulate HTTP GET request
        return mock_service_->GetRequest(url);
    }

private:
    HttpClientConfig config_;
    std::unique_ptr<MockHttpService> mock_service_ = std::make_unique<MockHttpService>(mock_service_config_);
};

// Exponential Backoff with Retry
void ExponentialBackoffWithRetry(HttpClient& client, const std::string& endpoint, int max_retries) {
    for (int attempt = 0; attempt < max_retries; ++attempt) {
        try {
            auto data = client.FetchData(endpoint);
            // Process the data
            std::cout << "Data: " << data << std::endl;
            break;
        } catch (const std::exception& e) {
            if (attempt == max_retries - 1) throw;
            std::this_thread::sleep_for(std::chrono::milliseconds(100 * (1 << attempt)));
        }
    }
}

