#include <iostream>
#include <random>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <memory>

class RandomEngine {
public:
    using Seed = unsigned long;
    using UniformDistribution = std::uniform_int_distribution<int>;
    using NonUniformDistribution = std::normal_distribution<double>;

    struct Configuration {
        Seed initialSeed;
        int maxSeeds;
    };

    static std::shared_ptr<RandomEngine> Create(Configuration config);
    void Initialize(Seed seed);
    double GenerateNonUniform(double mean, double stddev);
    int GenerateUniform(int min, int max);

private:
    RandomEngine(Configuration config);
    ~RandomEngine();

    Configuration config_;
    std::unique_ptr<std::random_device> rd_;
    std::vector<std::mt19937_64> generators_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

std::shared_ptr<RandomEngine> RandomEngine::Create(Configuration config) {
    return std::make_shared<RandomEngine>(config);
}

RandomEngine::RandomEngine(Configuration config)
    : config_(config), rd_(new std::random_device()), generators_(config.maxSeeds) {
    Initialize(config.initialSeed);
}

RandomEngine::~RandomEngine() {}

void RandomEngine::Initialize(Seed seed) {
    std::unique_lock<std::mutex> lock(mutex_);
    for (int i = 0; i < config_.maxSeeds; ++i) {
        generators_[i].seed(seed + i);
    }
    cv_.notify_all();
}

double RandomEngine::GenerateNonUniform(double mean, double stddev) {
    std::unique_lock<std::mutex> lock(mutex_);
    cv_.wait(lock, [this] { return !generators_.empty(); });
    int index = generators_.front()() % generators_.size();
    NonUniformDistribution dist(mean, stddev);
    return dist(generators_[index]);
}

int RandomEngine::GenerateUniform(int min, int max) {
    std::unique_lock<std::mutex> lock(mutex_);
    cv_.wait(lock, [this] { return !generators_.empty(); });
    int index = generators_.front()() % generators_.size();
    UniformDistribution dist(min, max);
    return dist(generators_[index]);
}
