using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Common;
using System.Linq;
using System.Threading.Tasks;

public class DatabaseService
{
    private readonly Dictionary<string, DbProviderFactory> _databaseProviders = new();

    public void RegisterDatabaseProvider(string connectionString, DbProviderFactory factory)
    {
        var connection = factory.CreateConnection();
        if (connection == null) throw new ArgumentNullException(nameof(factory));
        connection.ConnectionString = connectionString;
        try
        {
            connection.Open();
            _databaseProviders[connectionString] = factory;
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException("Failed to open database connection.", ex);
        }
    }

    public async Task ExecuteParameterizedQueryAsync(string connectionString, string commandText, List<DbParameter> parameters)
    {
        if (!_databaseProviders.ContainsKey(connectionString))
        {
            throw new ArgumentException("Database provider not registered for the specified connection string.");
        }

        var factory = _databaseProviders[connectionString];
        using (var connection = factory.CreateConnection())
        {
            if (connection == null) throw new InvalidOperationException("Failed to create database connection.");
            connection.ConnectionString = connectionString;
            await connection.OpenAsync();

            using (var command = connection.CreateCommand())
            {
                command.CommandText = commandText;
                foreach (var parameter in parameters)
                {
                    command.Parameters.Add(parameter);
                }

                try
                {
                    await command.ExecuteNonQueryAsync();
                }
                catch (Exception ex)
                {
                    LogError(ex, "ExecuteParameterizedQueryAsync");
                    throw new DatabaseExecutionException("An error occurred while executing the query.", ex);
                }
            }
        }
    }

    private void LogError(Exception exception, string methodName)
    {
        // Integrate with an external logging service
        // Example: Logger.Error(exception, methodName);
    }
}

public class DatabaseExecutionException : Exception
{
    public DatabaseExecutionException(string message, Exception innerException) : base(message, innerException) { }
}
```

