using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading.Tasks;

public class WeatherDataFetcher
{
    private readonly ConcurrentDictionary<string, (DateTime LastFetchTime, string Data)> cache = new();
    private readonly HttpClient httpClient = new();

    public async Task FetchWeatherAsync(string area)
    {
        if (!cache.TryGetValue(area, out var cachedData) || DateTime.Now - cachedData.LastFetchTime > TimeSpan.FromMinutes(5))
        {
            try
            {
                var response = await httpClient.GetAsync($"https://api.weather.com/data/{area}");
                if (response.IsSuccessStatusCode)
                {
                    var data = await response.Content.ReadAsStringAsync();
                    cache[area] = (DateTime.Now, data);
                }
                else
                {
                    throw new Exception("Failed to fetch weather data.");
                }
            }
