using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml.Linq;

public class XmlService
{
    private readonly HttpClient _httpClient;
    private readonly ConcurrentDictionary<string, XDocument> _cache = new ConcurrentDictionary<string, XDocument>();
    private readonly string _apiEndpoint;
    private readonly int _cacheTimeout;

    public XmlService(string apiEndpoint, int cacheTimeout)
    {
        _httpClient = new HttpClient();
        _apiEndpoint = apiEndpoint;
        _cacheTimeout = cacheTimeout;
    }

    public async Task<XDocument> GetXmlAsync(string resourceKey, bool useCache = true)
    {
        if (useCache && _cache.TryGetValue(resourceKey, out var cachedDoc))
            return cachedDoc;

        var xmlString = await FetchXmlAsync(resourceKey);
        var xmlDoc = XDocument.Parse(xmlString);

        if (useCache)
            _cache.TryAdd(resourceKey, xmlDoc, TimeSpan.FromSeconds(_cacheTimeout));

        return xmlDoc;
    }

    private async Task<string> FetchXmlAsync(string resourceKey)
    {
        try
        {
            var response = await _httpClient.GetAsync($"{_apiEndpoint}/{resourceKey}");
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsStringAsync();
        }
        catch (HttpRequestException ex)
        {
            // Handle network errors and log them
            Console.WriteLine($"Error fetching XML: {ex.Message}");
            throw;
        }
    }

    public void ClearCache()
    {
        _cache.Clear();
    }
}

