        var xml2 = await xmlService.GetXmlAsync("resource1");

        Assert.Same(xml1, xml2);
    }

    [Fact]
    public async Task TestGetXmlAsync_RefreshesCache()
    {
        var xmlService = new XmlService("https://example.com/api", 5);
        var xml1 = await xmlService.GetXmlAsync("resource1");
        await Task.Delay(6000); // Wait past cache timeout
        var xml2 = await xmlService.GetXmlAsync("resource1");

        Assert.NotSame(xml1, xml2);
    }

