import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import java.util.concurrent.ConcurrentHashMap;

@SpringBootApplication
public class ResourceManagementService {

    private static final ConcurrentHashMap<String, Resource> resources = new ConcurrentHashMap<>();

    public static void main(String[] args) {
        SpringApplication.run(ResourceManagementService.class, args);
    }

    @RestController
    @RequestMapping("/api/resources")
    public static class ResourceController {

        @PutMapping("/{uuid}")
        public ResponseEntity<String> updateResource(@PathVariable String uuid, @RequestBody Resource resource) {
            if (!resources.containsKey(uuid)) {
                return ResponseEntity.notFound().build();
            }
            // Check metadata from external API
            Resource currentResource = resources.get(uuid);
            if (currentResource.getMetadata().equals(resource.getMetadata())) {
                resources.put(uuid, resource);
                return ResponseEntity.ok("Resource updated successfully.");
            } else {
                return ResponseEntity.status(412).body("Precondition failed. Metadata mismatch.");
            }
        }

        @DeleteMapping("/{uuid}")
        public ResponseEntity<String> deleteResource(@PathVariable String uuid) {
            if (resources.containsKey(uuid)) {
                // Check metadata from external API
                Resource currentResource = resources.get(uuid);
                if (currentResource.isDeletable()) {
                    resources.remove(uuid);
                    return ResponseEntity.ok("Resource deleted successfully.");
                } else {
                    return ResponseEntity.status(412).body("Precondition failed. Resource not deletable.");
                }
            } else {
                return ResponseEntity.notFound().build();
            }
        }

        @GetMapping("/health")
        public ResponseEntity<String> healthCheck() {
            return ResponseEntity.ok("Service is running.");
        }
    }
}

class Resource {
    private String uuid;
    private String metadata;

    // Getters and setters

    public boolean isDeletable() {
        // Logic to determine if the resource can be deleted
        return true;
    }
}
