<?php

namespace App\Services;

use Illuminate\Support\Facades\Log;
use App\Library\Cryptography;
use App\Models\User;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\Validator;

class UserAccountManager
{
    private $encryptionService;

    public function __construct(Cryptography $encryptionService)
    {
        $this->encryptionService = $encryptionService;
    }

    public function createUser(Request $request)
    {
        $validator = Validator::make($request->all(), [
            'name' => 'required|string|max:255',
            'email' => 'required|email|unique:users,email',
            'password' => 'required|string|min:8|confirmed',
        ]);

        if ($validator->fails()) {
            return response()->json(['status' => 'error', 'message' => $validator->errors()], 400);
        }

        $user = User::create([
            'name' => $request->input('name'),
            'email' => $request->input('email'),
            'password' => bcrypt($request->input('password')),
        ]);

        return response()->json(['status' => 'success', 'message' => 'User created successfully'], 201);
    }

    public function updateUser(Request $request, $id)
    {
        $user = User::find($id);

        if (!$user) {
            return response()->json(['status' => 'error', 'message' => 'User not found'], 404);
        }

        $validator = Validator::make($request->all(), [
            'name' => 'string|max:255',
            'email' => 'email|unique:users,email,' . $user->id,
            'password' => 'sometimes|string|min:8|confirmed',
        ]);

        if ($validator->fails()) {
            return response()->json(['status' => 'error', 'message' => $validator->errors()], 400);
        }

        $user->update($request->all());

        return response()->json(['status' => 'success', 'message' => 'User updated successfully'], 200);
    }

    public function deleteUser($id)
    {
        $user = User::find($id);

        if (!$user) {
            return response()->json(['status' => 'error', 'message' => 'User not found'], 404);
        }

        $user->delete();

        return response()->json(['status' => 'success', 'message' => 'User deleted successfully'], 200);
    }

    public function encryptData($data, $cipherMode = 'AES-128-ECB')
    {
        try {
            $startTime = microtime(true);
            $encryptedData = $this->encryptionService->encrypt($data, $cipherMode);
            $endTime = microtime(true);

            Log::info('Encryption', [
                'user_id' => Auth::id(),
                'cipher_mode' => $cipherMode,
                'duration' => $endTime - $startTime,
            ]);

            return response()->json(['status' => 'success', 'data' => $encryptedData], 200);
        } catch (\Exception $e) {
            Log::error('Encryption Error', ['user_id' => Auth::id(), 'exception' => $e->getMessage()]);
            return response()->json(['status' => 'error', 'message' => 'Failed to encrypt data'], 500);
        }
    }

    public function decryptData($data, $cipherMode = 'AES-128-ECB')
    {
        try {
            $startTime = microtime(true);
            $decryptedData = $this->encryptionService->decrypt($data, $cipherMode);
            $endTime = microtime(true);

            Log::info('Decryption', [
                'user_id' => Auth::id(),
                'cipher_mode' => $cipherMode,
                'duration' => $endTime - $startTime,
            ]);

            return response()->json(['status' => 'success', 'data' => $decryptedData], 200);
        } catch (\Exception $e) {
            Log::error('Decryption Error', ['user_id' => Auth::id(), 'exception' => $e->getMessage()]);
            return response()->json(['status' => 'error', 'message' => 'Failed to decrypt data'], 500);
        }
    }
}
