async function runModuleTests(moduleName, testCases, externalServiceClient, testConfig) {
    const { concurrencyLimit, logLevel } = testConfig;
    let results = [];

    // Function to log messages with appropriate level and format
    const logMessage = (testCaseLabel, status, startTime, endTime) => {
        if (logLevel === 'verbose') {
            console.log(`[${new Date().toISOString()}] ${testCaseLabel} - ${status}`);
        } else if (logLevel === 'brief' && status === 'fail') {
            console.error(`[${new Date().toISOString()}] ${testCaseLabel} - ${status}`);
        }
    };

    // Function to handle test case execution and logging
    const runTestCase = async (testCase, index) => {
        const startTime = new Date();
        try {
            await testCase.testCaseFunction(externalServiceClient);
            results[index] = { label: testCase.label, status: 'pass', duration: new Date() - startTime };
            logMessage(testCase.label, 'pass', startTime, new Date());
        } catch (error) {
            results[index] = { label: testCase.label, status: 'fail', error, duration: new Date() - startTime };
            logMessage(testCase.label, 'fail', startTime, new Date());
        }
    };

    // Execute test cases with concurrency limit
    const semaphore = Array.from({ length: concurrencyLimit }, () => Promise.resolve());
    for (let i = 0; i < testCases.length; i++) {
        semaphore[i] = semaphore[i].then(() => runTestCase(testCases[i], i));
    }

    await Promise.all(semaphore);

    // Return results after all tests have completed
    return results;
}
