function isValidScript(script) {
    // Custom validation logic here
    return typeof script === 'object' && script.url;
}

function sanitizeScriptURL(url) {
    // Basic URL sanitization (XSS prevention)
    const urlRegex = /^(https?:\/\/[^<>\s]+)/i;
    return urlRegex.test(url) ? url : '';
}

async function fetchMetadata(script) {
    try {
        const response = await fetch(API_URL + '/' + encodeURIComponent(sanitizeScriptURL(script.url)), {
            method: 'GET',
            timeout: SCRIPT_TIMEOUT
        });

        if (!response.ok) {
            throw new Error('Network response was not ok');
        }

        return await response.json();
    } catch (error) {
        console.error('Failed to fetch metadata for script:', error);
        return null;
    }
}

function createScriptElement(script, metadata) {
    const scriptEl = document.createElement('script');
    scriptEl.src = script.url;
    scriptEl.async = true; // Consider using defer if order is important
    scriptEl.onload = () => console.log(`Script ${script.url} loaded`);
    scriptEl.onerror = (err) => console.error(`Failed to load script ${script.url}`, err);

    // Add metadata or custom attributes here

    return scriptEl;
}

async function renderFooterScripts(scripts) {
    if (!Array.isArray(scripts)) {
        console.error('Invalid input: Expected an array of scripts');
        return;
    }

    const validScripts = scripts.filter(isValidScript);

    for (const script of validScripts) {
        const metadata = await fetchMetadata(script);
        const scriptEl = createScriptElement(script, metadata);
        document.body.appendChild(scriptEl);
    }
}

