// Define constants
const MAX_RETRIES = 3;
const CACHE_EXPIRY_TIME = 3600; // 1 hour in seconds

// Create a cache object to store frequently accessed data
const cache = new Map();

// Function to fetch and cache data from external API
async function fetchData(url) {
  if (cache.has(url)) {
    const cachedData = cache.get(url);
    if (Date.now() - cachedData.timestamp < CACHE_EXPIRY_TIME * 1000) {
      return cachedData.data;
    }
  }

  try {
    const response = await axios.get(url);
    cache.set(url, { data: response.data, timestamp: Date.now() });
    return response.data;
  } catch (error) {
    console.error(`Error fetching data from ${url}:`, error);
    throw error;
  }
}

