    this.filters.push(criteria);
  }

  // Apply filters to the DOM
  async applyFilters() {
    const nodes = document.querySelectorAll('*');
    for (const node of nodes) {
      if (this.matchesFilters(node)) {
        await this.fetchMetadata(node);
      }
    }
  }

  // Check if a node matches all filters
  matchesFilters(node) {
    return this.filters.every(filter => filter(node));
  }

  // Fetch metadata for a node
