public class DisjointPairService {

    private final ExecutorService threadPool;
    private final ExternalMetadataProvider metadataProvider;
    private final RateLimiter rateLimiter;

    public DisjointPairService(int maxThreads, ExternalMetadataProvider provider) {
        this.threadPool = Executors.newFixedThreadPool(maxThreads);
        this.metadataProvider = provider;
        this.rateLimiter = new RateLimiter(100, 1, TimeUnit.SECONDS);
    }

    public Map<Integer, Integer> countDisjointPairs(List<Integer> array) throws InterruptedException {
        List<Future<Map.Entry<Integer, Integer>>> futures = array.stream()
                .map(item -> threadPool.submit(() -> {
                    rateLimiter.acquire();
                    return processItem(item);
                }))
                .collect(Collectors.toList());

        Map<Integer, Integer> result = new HashMap<>();
        for (Future<Map.Entry<Integer, Integer>> future : futures) {
            result.merge(future.get().getKey(), future.get().getValue(), Integer::sum);
        }

        threadPool.shutdown();
        return result;
    }

    private Map.Entry<Integer, Integer> processItem(Integer item) {
        // Fetch metadata and determine disjoint pairs
        String metadata = metadataProvider.getMetadata(item);
        // Perform disjoint pair detection using Union-Find data structure
        int disjointPairs = detectDisjointPairs(metadata);

        return new AbstractMap.SimpleEntry<>(item, disjointPairs);
    }

