package main

import (
    "context"
    "database/sql"
    "fmt"
    "log"
    "net/http"
    "time"

    "github.com/gomodule/redigo/redis"
    _ "github.com/lib/pq"
    k8sClient "k8s.io/client-go/kubernetes"
)

type Session struct {
    ID        string
    UserID    int64
    Data      map[string]interface{}
    LastAccess time.Time
}

var (
    redisClient *redis.Client
    db          *sql.DB
    kubeClient  k8sClient.Interface
)

func init() {
    var err error

    // Initialize Redis client
    redisClient, err = redis.DialURL("redis://localhost:6379")
    if err != nil {
        log.Fatalf("Failed to connect to Redis: %v", err)
    }

    // Initialize PostgreSQL database connection
    db, err = sql.Open("postgres", "user=postgres password=secret dbname=mydb sslmode=disable")
    if err != nil {
        log.Fatalf("Failed to connect to PostgreSQL: %v", err)
    }
    if err := db.Ping(); err != nil {
        log.Fatalf("Failed to ping PostgreSQL: %v", err)
    }

    // Initialize Kubernetes client
    kubeClient, err = k8sClient.NewForConfig(k8sClient.InClusterConfigOrDie())
    if err != nil {
        log.Fatalf("Failed to create Kubernetes client: %v", err)
    }
}

func getSession(w http.ResponseWriter, r *http.Request) {
    sessionID := r.Header.Get("X-Session-ID")
    sessionData, err := fetchSession(sessionID)
    if err != nil {
        http.Error(w, "Internal Server Error", http.StatusInternalServerError)
        return
    }

    w.Header().Set("Content-Type", "application/json")
    fmt.Fprintf(w, "%v", sessionData)
}

func fetchSession(sessionID string) (*Session, error) {
    // Fetch session from Redis first
    sessionBytes, err := redisClient.Get(sessionID).Bytes()
    if err == nil {
        var session Session
        if err := json.Unmarshal(sessionBytes, &session); err != nil {
            return nil, err
        }
        return &session, nil
    }

    // If Redis fetch fails, fallback to PostgreSQL
    var sessionData map[string]interface{}
    query := "SELECT data FROM sessions WHERE id = $1"
    if err := db.QueryRow(query, sessionID).Scan(&sessionData); err != nil {
        return nil, err
    }
    session := &Session{
        ID:   sessionID,
        Data: sessionData,
    }
    return session, nil
}

func main() {
    http.HandleFunc("/session", getSession)
    log.Fatal(http.ListenAndServe(":8080", nil))
}
```

