use reqwest::ClientBuilder;
use tokio::sync::{mpsc, Semaphore};
use tracing::{error, info};

struct AsyncHttpClient {
    client: ClientBuilder,
    pool_size: usize,
    semaphore: Semaphore,
    logger_url: String,
}

impl AsyncHttpClient {
    async fn new(pool_size: usize, logger_url: String) -> Self {
        let client = ClientBuilder::new();
        let semaphore = Semaphore::new(pool_size);
        AsyncHttpClient { client, pool_size, semaphore, logger_url }
    }

    async fn send_request(&self, url: &str, use_tls: bool) -> Result<String, reqwest::Error> {
        let _permit = self.semaphore.acquire().await.unwrap();
        let response = if use_tls {
            self.client.get(url).send().await?
        } else {
            self.client.get(url).insecure().send().await?
        };
        self.log_request_metrics(&response);
        response.text().await
    }

    fn log_request_metrics(&self, response: &reqwest::Response) {
        let status = response.status();
        let latency = response.elapsed();
        info!("Request to {} took {:?} with status {}", url, latency, status);
        // Code to send metrics to external logging service
    }
}

#[tokio::main]
async fn main() {
    let client = AsyncHttpClient::new(1000, "http://example-logging-service.com".to_string()).await;
    let (tx, mut rx) = mpsc::channel(100);

    for _ in 0..1000 {
        tokio::spawn(async move {
            let url = "https://api.example.com/data";
            let response = client.send_request(url, true).await;
            tx.send(response).unwrap();
        });
    }

    while let Some(result) = rx.recv().await {
        match result {
            Ok(text) => info!("Received text: {}", text),
            Err(e) => error!("Request failed: {:?}", e),
        }
    }
}
