<?php

// Define the interface for authentication adapters
interface AuthenticationAdapter {
    public function authenticate($provider, $credentials);
}

// Implement an OAuth 2.0 adapter for a third-party identity provider
class OAuth2Adapter implements AuthenticationAdapter {
    private $client;

    public function __construct($clientId, $clientSecret) {
        $this->client = new GuzzleHttp\Client([
            'base_uri' => 'https://provider.com/api/v1/',
            'auth' => [$clientId, $clientSecret],
        ]);
    }

    public function authenticate($provider, $credentials) {
        // Implement the logic to exchange credentials for an access token
        $response = $this->client->post('token', [
            'form_params' => [
                'grant_type' => 'password',
                'username' => $credentials['username'],
                'password' => $credentials['password'],
            ],
        ]);

        return json_decode($response->getBody());
    }
}

// Implement a cache adapter for storing access tokens
class CacheAdapter {
    private $cache;

    public function __construct($cache) {
        $this->cache = $cache;
    }

    public function get($key) {
        return $this->cache->get($key);
    }

    public function set($key, $value, $ttl = 3600) {
        $this->cache->set($key, $value, $ttl);
    }
}

// Implement the authentication service
class AuthenticationService {
    private $adapters;
    private $cache;

    public function __construct(array $adapters, CacheAdapter $cache) {
        $this->adapters = $adapters;
        $this->cache = $cache;
    }

    public function authenticate($provider, $credentials) {
        $key = "token_{$provider}_{$credentials['username']}";
        $token = $this->cache->get($key);

        if (!$token) {
            foreach ($this->adapters as $adapter) {
                if ($adapter instanceof AuthenticationAdapter) {
                    $token = $adapter->authenticate($provider, $credentials);
                    break;
                }
            }

            if ($token) {
                $this->cache->set($key, $token, 3600); // Cache for 1 hour
            }
        }

        return $token;
    }
}

// Example usage
$adapters = [
    new OAuth2Adapter('client_id', 'client_secret'),
    // Add more adapters as needed
];

$cache = new CacheAdapter(new \Doctrine\Common\Cache\FilesystemCache('/path/to/cache'));

$authenticationService = new AuthenticationService($adapters, $cache);

$token = $authenticationService->authenticate('provider_name', [
    'username' => 'user@example.com',
    'password' => 'password123',
]);

if ($token) {
    // Proceed with authentication
} else {
    // Handle authentication failure
}
```

