class PasswordUpdateService {
    private $dbClient;
    private $passwordCheckerApi;
    private $cache;
    private $logger;

    public function __construct($dbConfig, $apiUrl, $cacheInstance) {
        $this->dbClient = new DatabaseClient($dbConfig);
        $this->passwordCheckerApi = new PasswordStrengthCheckerAPI($apiUrl);
        $this->cache = $cacheInstance;
        $this->logger = new Logger('PasswordUpdateService');
        $this->logger->pushHandler(new StreamHandler(__DIR__ . '/password_update.log', Logger::DEBUG));
    }

    public function updatePassword($userId, $newPassword) {
        try {
            if (!$this->validatePasswordStrength($newPassword)) {
                throw new Exception("Invalid password strength");
            }

            if ($this->isUpdateNeeded($userId, $newPassword)) {
                $this->dbClient->updateUserPassword($userId, $newPassword);
                $this->cache->invalidateCache($userId);
                $this->logger->info("Password updated successfully for user: $userId");
            } else {
                $this->logger->debug("No change needed for password update request for user: $userId");
            }

            return "Password updated successfully";
        } catch (Exception $e) {
            $this->logger->error("Error updating password for user $userId: " . $e->getMessage());
            throw $e;
        }
    }

    private function validatePasswordStrength($password) {
        $strength = $this->cache->get('password_strength_cache');
        if (empty($strength)) {
            $strength = $this->passwordCheckerApi->checkStrength($password);
            $this->cache->set('password_strength_cache', $strength, 3600); // Cache for 1 hour
        }

        return $strength > 80;
    }

    private function isUpdateNeeded($userId, $newPassword) {
        $currentHash = $this->dbClient->getUserPasswordHash($userId);
        return password_verify($newPassword, $currentHash) === false;
    }
