#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct State {
    int id;
    char* description;
    double** transitionMatrix;
} State;

typedef struct FsaReport {
    State* states;
    int numStates;
} FsaReport;

FsaReport* fsa_analyze(int numStates, double** transitionMatrix) {
    // Allocate memory for the report structure
    FsaReport* report = (FsaReport*)malloc(sizeof(FsaReport));
    if (!report) {
        fprintf(stderr, "Memory allocation failed for FsaReport\n");
        return NULL;
    }

    // Initialize the report with the number of states
    report->numStates = numStates;
    report->states = (State*)malloc(numStates * sizeof(State));
    if (!report->states) {
        fprintf(stderr, "Memory allocation failed for states\n");
        free(report);
        return NULL;
    }

    // Populate each state with its ID and transition matrix
    for (int i = 0; i < numStates; i++) {
        report->states[i].id = i;
        report->states[i].description = (char*)malloc(256 * sizeof(char));
        if (!report->states[i].description) {
            fprintf(stderr, "Memory allocation failed for state description\n");
            fsa_report_cleanup(report);
            return NULL;
        }
        snprintf(report->states[i].description, 256, "State %d", i);

        // Allocate memory for the transition matrix
        report->states[i].transitionMatrix = (double**)malloc(numStates * sizeof(double*));
        if (!report->states[i].transitionMatrix) {
            fprintf(stderr, "Memory allocation failed for transition matrix\n");
            fsa_report_cleanup(report);
            return NULL;
        }
        for (int j = 0; j < numStates; j++) {
            report->states[i].transitionMatrix[j] = (double*)malloc(numStates * sizeof(double));
            if (!report->states[i].transitionMatrix[j]) {
                fprintf(stderr, "Memory allocation failed for transition matrix row\n");
                fsa_report_cleanup(report);
                return NULL;
            }
        }

        // Copy the transition probabilities from the provided matrix
        for (int j = 0; j < numStates; j++) {
            for (int k = 0; k < numStates; k++) {
                report->states[i].transitionMatrix[j][k] = transitionMatrix[i * numStates + j];
            }
        }
    }

    return report;
}

void fsa_report_cleanup(FsaReport* report) {
    if (!report) return;

    for (int i = 0; i < report->numStates; i++) {
        free(report->states[i].description);
        for (int j = 0; j < report->numStates; j++) {
            free(report->states[i].transitionMatrix[j]);
        }
        free(report->states[i].transitionMatrix);
    }
    free(report->states);
    free(report);
}

// Example usage
int main() {
    int numStates = 3;
    double transitionMatrix[9] = {0.5, 0.25, 0.25,
                                  0.3, 0.4, 0.3,
                                  0.1, 0.7, 0.2};

    FsaReport* report = fsa_analyze(numStates, transitionMatrix);
    if (report) {
        for (int i = 0; i < report->numStates; i++) {
            printf("State %d - Description: %s\n", report->states[i].id, report->states[i].description);
            printf("Transition Matrix:\n");
            for (int j = 0; j < numStates; j++) {
                for (int k = 0; k < numStates; k++) {
                    printf("%.2f ", report->states[i].transitionMatrix[j][k]);
                }
                printf("\n");
            }
        }
        fsa_report_cleanup(report);
    }

    return 0;
}
```']

