using System;
using System.Collections.Concurrent;
using System.Threading;

public class DynamicRangeGenerator<T> where T : IComparable<T>
{
    private readonly ConcurrentDictionary<long, string> _logs = new ConcurrentDictionary<long, string>();
    private readonly Random _random = new Random();
    private T _minValue;
    private T _maxValue;
    private long _logFrequency;
    private bool _isLoggingEnabled;

    public DynamicRangeGenerator(T minValue, T maxValue, bool isLoggingEnabled, long logFrequency)
    {
        SetRange(minValue, maxValue);
        EnableLogging(isLoggingEnabled, logFrequency);
    }

    public void SetRange(T minValue, T maxValue)
    {
        if (Comparer<T>.Default.Compare(minValue, maxValue) >= 0)
            throw new ArgumentException("Min value must be less than max value.");

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public void EnableLogging(bool isLoggingEnabled, long logFrequency)
    {
        _isLoggingEnabled = isLoggingEnabled;
        _logFrequency = logFrequency;
    }

    public T GetRandomInclusive()
    {
        var value = GetRandomValue(true);
        Log(value);
        return value;
    }

    public T GetRandomExclusive()
    {
        var value = GetRandomValue(false);
        Log(value);
        return value;
    }

    private T GetRandomValue(bool inclusive)
    {
        if (typeof(T) == typeof(double))
            return (T)(object)((inclusive ? _random.NextDouble() : _random.NextDouble() + 1) * (_maxValue.ToDouble() - _minValue.ToDouble()) + _minValue.ToDouble());
        else if (typeof(T) == typeof(float))
            return (T)(object)((inclusive ? _random.NextSingle() : _random.NextSingle() + 1) * (_maxValue.ToFloat() - _minValue.ToFloat()) + _minValue.ToFloat());
        else
            throw new InvalidOperationException("Unsupported type for random generation.");
    }

    private void Log(T value)
    {
        if (!_isLoggingEnabled) return;

        var timestamp = DateTimeOffset.UtcNow;
        var logEntry = $"{timestamp:O} - Generated value: {value}";
        _logs.TryAdd(timestamp.ToUnixTimeMilliseconds(), logEntry);

        // Efficiently trim logs based on frequency
        if (_logs.Count > _logFrequency)
        {
            long oldestTimestamp = _logs.Keys.Min();
            _logs.TryRemove(oldestTimestamp, out _);
        }
    }

    public string GetLogs()
    {
        return string.Join(Environment.NewLine, _logs.Values);
    }
}

public static class TypeExtensions
{
    public static double ToDouble(this object obj) => Convert.ToDouble(obj);
    public static float ToFloat(this object obj) => Convert.ToSingle(obj);
}
