typedef struct ResourceItem {
    char* key;
    char* value;
} ResourceItem;

typedef struct ResourceBundle {
    ResourceItem** items;
    size_t itemCount;
    pthread_mutex_t lock;
} ResourceBundle;

typedef void (*LoadCallback)(int errorCode, const char* errorMessage);

void* loadResourceBundleTask(void* arg) {
    // Simulate loading resource bundle from a file
    sleep(2); // Simulating delay for network access or external service lookup

    // Load the resource bundle from the file specified in 'path'
    ResourceBundle* bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    bundle->items = (ResourceItem**)malloc(10 * sizeof(ResourceItem*)); // Allocate initial space
    bundle->itemCount = 5; // Example number of items

    for (size_t i = 0; i < bundle->itemCount; ++i) {
        bundle->items[i] = (ResourceItem*)malloc(sizeof(ResourceItem));
        snprintf(bundle->items[i]->key, 256, "Key%d", i);
        snprintf(bundle->items[i]->value, 256, "Value%d", i);
    }

    pthread_mutex_init(&bundle->lock, NULL);

    return bundle;
}

void loadResourceBundle(const char* path, LoadCallback callback) {
    pthread_t thread;
    if (pthread_create(&thread, NULL, loadResourceBundleTask, (void*)path) != 0) {
        callback(-1, "Failed to create thread");
        return;
    }

    // Wait for the thread to complete
    void* result;
    if (pthread_join(thread, &result) != 0) {
        callback(-2, "Thread join failed");
        return;
    }

    ResourceBundle* bundle = (ResourceBundle*)result;

    // Simulate error during processing
    if (bundle->itemCount == 5) {
        // Success
        for (size_t i = 0; i < bundle->itemCount; ++i) {
            printf("Key: %s, Value: %s\n", bundle->items[i]->key, bundle->items[i]->value);
        }
        callback(0, "Success");
    } else {
        // Error during processing
        callback(-3, "Failed to process bundle");
    }

    // Clean up resources
    for (size_t i = 0; i < bundle->itemCount; ++i) {
        free(bundle->items[i]->key);
        free(bundle->items[i]->value);
        free(bundle->items[i]);
    }
    free(bundle->items);
    free(bundle);
}

void onResourceLoad(int errorCode, const char* errorMessage) {
    if (errorCode == 0) {
        printf("Resource bundle loaded successfully.\n");
    } else {
        printf("Failed to load resource bundle: %s\n", errorMessage);
    }
}

int main() {
    loadResourceBundle("/path/to/resource/file", onResourceLoad);

    return 0;
}
