#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

#define MAX_STRING_SIZE 1024

typedef enum {
    COMPRESS_NONE,
    COMPRESS_ZLIB
} CompressionType;

typedef struct {
    char *data;
    size_t length;
    size_t max_size;
    CompressionType compression_type;
    uLong compressed_length;
} DynamicString;

DynamicString* dynamic_string_create(size_t initial_size, CompressionType type) {
    DynamicString *ds = (DynamicString*)malloc(sizeof(DynamicString));
    ds->data = (char*)malloc(initial_size);
    ds->length = 0;
    ds->max_size = initial_size;
    ds->compression_type = type;
    ds->compressed_length = 0;
    return ds;
}

void dynamic_string_destroy(DynamicString *ds) {
    free(ds->data);
    free(ds);
}

int dynamic_string_set(DynamicString *ds, const char *new_data) {
    size_t new_length = strlen(new_data);
    if (new_length > ds->max_size) {
        if (ds->compression_type == COMPRESS_ZLIB) {
            uLong compressed_len;
            Bytef *compressed = (Bytef*)malloc(compressBound(new_length));
            deflateInit(&ds->stream, Z_DEFAULT_COMPRESSION);
            deflateSetDictionary(&ds->stream, ds->data, ds->length);
            deflateReset(&ds->stream);
            deflateEnd(&ds->stream);
            free(ds->data);
            ds->data = (char*)compressed;
        } else {
            return -1; // Compression required but not supported
        }
    }

    memcpy(ds->data + ds->length, new_data, new_length);
    ds->length += new_length;

    if (ds->compression_type == COMPRESS_ZLIB) {
        deflateInit(&ds->stream, Z_DEFAULT_COMPRESSION);
        deflateSetDictionary(&ds->stream, ds->data, ds->length);
        deflateReset(&ds->stream);
        compress(ds->data, &compressed_len, ds->data + ds->length, new_length);
        deflateEnd(&ds->stream);
        ds->compressed_length = compressed_len;
    }

    return 0;
}

int dynamic_string_get(const DynamicString *ds, char **output) {
    if (ds->compression_type == COMPRESS_ZLIB) {
        Bytef *decompressed = (Bytef*)malloc(ds->max_size);
        inflateInit(&ds->stream);
        decompress(decompressed, &ds->max_size, ds->data + ds->length, ds->compressed_length);
        inflateEnd(&ds->stream);

        *output = (char*)malloc(strlen((const char*)decompressed) + 1);
        strcpy(*output, (const char*)decompressed);
        free(decompressed);

    } else {
        *output = strdup(ds->data);
    }

    return 0;
}

int dynamic_string_compress(DynamicString *ds) {
    if (ds->compression_type != COMPRESS_ZLIB) {
        return -1; // Compression not supported
    }

    uLong compressed_len;
    Bytef *compressed = (Bytef*)malloc(compressBound(ds->length));
    deflateInit(&ds->stream, Z_DEFAULT_COMPRESSION);
    deflateSetDictionary(&ds->stream, ds->data, ds->length);
    deflateReset(&ds->stream);
    deflateEnd(&ds->stream);

    free(ds->data);
    ds->data = (char*)compressed;
    return 0;
}

int dynamic_string_decompress(DynamicString *ds) {
    if (ds->compression_type != COMPRESS_ZLIB) {
        return -1; // Compression not supported
    }

    Bytef *decompressed = (Bytef*)malloc(ds->max_size);
    inflateInit(&ds->stream);
    decompress(decompressed, &ds->max_size, ds->data + ds->length, ds->compressed_length);
    inflateEnd(&ds->stream);

    free(ds->data);
    ds->data = (char*)decompressed;
    return 0;
}
