static int detect_format(const unsigned char *header, size_t length) {
    // Simple header checks for JPEG, PNG, and WEBP
    if (length >= 2 && header[0] == 0xFF && header[1] == 0xD8)
        return JPEG;
    else if (length >= 4 && !memcmp(header, "\x89PNG\r\n\x1a\n", 8))
        return PNG;
    else if (length >= 6 && !memcmp(header, "\x52494646", 8))
