// Function prototype for logging
void log_message(const char *message, const char *status);

// Function to generate a new filename based on the provided configuration
char* generate_new_filename(Config *config) {
    time_t current_time = time(NULL);
    struct tm *time_info = localtime(&current_time);

    // Allocate memory for the new filename
    size_t filename_length = strlen(config->base_dir) + 20 + config->max_filename_length;
    char *new_filename = (char *)malloc(filename_length);

    if (!new_filename) {
        log_message("Failed to allocate memory for new filename", "Error");
        return NULL;
    }

    // Format the new filename
    snprintf(new_filename, filename_length, "%s/%d_%s", config->base_dir, time_info->tm_year + 1900, config->max_filename_length > 0 ? "" : "");

    log_message("Generated new filename: %s", "Success");
    return new_filename;
}

// Example usage
int main() {
    Config config = {"./uploads", 5};
    char *filename = generate_new_filename(&config);
    if (filename) {
        printf("New Filename: %s\n", filename);
        free(filename); // Don't forget to free the allocated memory
    }
    return 0;
}
