}

// Function to finalize SHA-256 hash and get digest
unsigned char* sha256_final(SHA256_CTX *ctx) {
    unsigned char *digest = (unsigned char*)malloc(32);
    SHA256_Final(digest, ctx);
    free(ctx);
    return digest;
}

// Function to initialize RSA encryption key
RSA* rsa_encrypt_init(const BIGNUM *n, const BIGNUM *e) {
    RSA *rsa = RSA_new();
    RSA_set0_key(rsa, BN_dup(n), BN_dup(e), NULL);
    return rsa;
}

// Function to initialize RSA decryption key
RSA* rsa_decrypt_init(const BIGNUM *n, const BIGNUM *d) {
    RSA *rsa = RSA_new();
    RSA_set0_key(rsa, BN_dup(n), NULL, BN_dup(d));
    return rsa;
}
