#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <openssl/pbkdf2.h>
#include <sqlite3.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX *enc_ctx;
    EVP_CIPHER_CTX *dec_ctx;
    unsigned char iv[EVP_MAX_BLOCK_LENGTH];
    unsigned char key[32]; // AES-256 key
} EncryptionContext;

void log_error(const char *error_message) {
    fprintf(stderr, "Error: %s\n", error_message);
}

int initialize_encryption_context(const char *password, int iterations, EncryptionContext **ctx_ptr) {
    EncryptionContext *ctx = (EncryptionContext *)malloc(sizeof(EncryptionContext));
    if (!ctx) {
        log_error("Memory allocation failed");
        return -1;
    }

    memset(ctx->iv, 0, sizeof(ctx->iv));
    if (RAND_bytes(ctx->iv, EVP_CIPHER_iv_length(EVP_aes_256_cbc())) != 1) {
        log_error("Failed to generate IV");
        free(ctx);
        return -1;
    }

    if (PBKDF2_HMAC_CTX_set_password(PBKDF2_HMAC_CTX_new(), password, strlen(password), NULL, 0, iterations, EVP_sha256()) != 1 ||
        PBKDF2_HMAC_CTX_derive_key(PBKDF2_HMAC_CTX_new(), ctx->key, sizeof(ctx->key)) != 1) {
        log_error("PBKDF2 failed");
        free(ctx);
        return -1;
    }

    EVP_CIPHER_CTX_init(ctx->enc_ctx);
    if (EVP_EncryptInit_ex(ctx->enc_ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv) != 1) {
        log_error("Encryption context initialization failed");
        free(ctx);
        return -1;
    }

    EVP_CIPHER_CTX_init(ctx->dec_ctx);
    if (EVP_DecryptInit_ex(ctx->dec_ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv) != 1) {
        log_error("Decryption context initialization failed");
        free(ctx);
        return -1;
    }

    *ctx_ptr = ctx;
    return 0;
}

void cleanup_encryption_context(EncryptionContext *ctx) {
    EVP_CIPHER_CTX_cleanup(ctx->enc_ctx);
    EVP_CIPHER_CTX_cleanup(ctx->dec_ctx);
    free(ctx);
}
