        {
            if (!response.IsSuccessStatusCode)
                throw new Exception($"Failed to fetch config: {response.StatusCode}");
            var configJson = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<Config>(configJson);
        }
