public class HashingService
{
    private readonly ConnectionMultiplexer _redis;
    private readonly IAuthenticationApiClient _authApi;
    private readonly ILoggerService _logger;

    public HashingService(ConnectionMultiplexer redis, IAuthenticationApiClient authApi, ILoggerService logger)
    {
        _redis = redis;
        _authApi = authApi;
        _logger = logger;
    }

    public string ComputeHash(string input)
    {
        if (string.IsNullOrEmpty(input))
            throw new ArgumentException("Input cannot be null or empty.");

        var hash = ComputeMD5Hash(input);
        _logger.LogHashComputation(input, hash);

        return hash;
    }

    private string ComputeMD5Hash(string input)
    {
        using (var md5 = MD5.Create())
        {
            var inputBytes = System.Text.Encoding.ASCII.GetBytes(input);
            var hashBytes = md5.ComputeHash(inputBytes);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
        }
    }

    public void CacheHash(string key, string hash)
    {
        var db = _redis.GetDatabase();
        db.StringSet(key, hash, TimeSpan.FromMinutes(10)); // Example cache time
    }

    public bool IsCached(string key)
    {
        var db = _redis.GetDatabase();
        return db.KeyExists(key);
    }

    public string GetCachedHash(string key)
    {
        var db = _redis.GetDatabase();
        if (db.KeyExists(key))
            return db.StringGet(key);
        return null;
    }

    public void InvalidateCache(string key)
    {
        var db = _redis.GetDatabase();
        db.KeyDelete(key);
    }
}

