using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text.Json;
using Grpc.Core;

public class EncryptionService : Encryption.EncryptionBase
{
    private readonly Dictionary<string, (byte[] Key, byte[] IV)> _keyCache = new Dictionary<string, (byte[], byte[])>();

    public override Task<EncryptResponse> Encrypt(EncryptRequest request, ServerCallContext context)
    {
        var dataObject = JsonSerializer.Deserialize<DataObject>(request.Data);
        using (var aes = Aes.Create())
        {
            aes.Key = GenerateKey(request.KeyId);
            aes.IV = GenerateIV();
            var encryptedData = EncryptData(dataObject, aes);
            return Task.FromResult(new EncryptResponse { EncryptedData = encryptedData });
        }
    }

    public override Task<DecryptResponse> Decrypt(DecryptRequest request, ServerCallContext context)
    {
        var encryptedData = request.EncryptedData;
        using (var aes = Aes.Create())
        {
            aes.Key = _keyCache[request.KeyId].Key;
            aes.IV = _keyCache[request.KeyId].IV;
            var decryptedDataObject = DecryptData(encryptedData, aes);
            return Task.FromResult(new DecryptResponse { Data = JsonSerializer.Serialize(decryptedDataObject) });
        }
    }

    private byte[] GenerateKey(string keyId)
    {
        if (!_keyCache.ContainsKey(keyId))
        {
            // Fetch key from KMS or generate and cache it
            _keyCache[keyId] = (GenerateRandomBytes(32), GenerateRandomBytes(16));
        }
        return _keyCache[keyId].Key;
    }

    private byte[] GenerateIV()
    {
        return GenerateRandomBytes(16);
    }

    private byte[] EncryptData(DataObject data, Aes aes)
    {
        using (var ms = new MemoryStream())
        {
            using (var cs = new CryptoStream(ms, aes.CreateEncryptor(aes.Key, aes.IV), CryptoStreamMode.Write))
            {
                JsonSerializer.Serialize(cs, data);
            }
            return ms.ToArray();
        }
    }

    private DataObject DecryptData(byte[] encryptedData, Aes aes)
    {
        using (var ms = new MemoryStream(encryptedData))
        {
            using (var cs = new CryptoStream(ms, aes.CreateDecryptor(aes.Key, aes.IV), CryptoStreamMode.Read))
            {
                return JsonSerializer.Deserialize<DataObject>(cs);
            }
        }
    }

    private byte[] GenerateRandomBytes(int length)
    {
        using (var rng = RandomNumberGenerator.Create())
        {
            var bytes = new byte[length];
            rng.GetBytes(bytes);
            return bytes;
        }
    }
}

public class DataObject
{
    public string Name { get; set; }
    public int Age { get; set; }
}
