["```javascript
const express = require('express');
const axios = require('axios');
const multer = require('multer');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const app = express();
const upload = multer({ dest: 'uploads/' });

app.use(express.json());

// Define CDN endpoint and credentials
const CDN_URL = 'https://cdn.example.com/upload';
const CDN_AUTH_TOKEN = 'your_cdn_auth_token';

// File type whitelist and size limits
const SUPPORTED_FILE_TYPES = ['image/jpeg', 'image/png', 'application/pdf'];
const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

// Upload endpoint with validation and concurrency management
app.post('/upload', upload.single('file'), async (req, res) => {
    try {
        const file = req.file;
        if (!SUPPORTED_FILE_TYPES.includes(file.mimetype)) {
            return res.status(400).json({ error: 'Unsupported file type' });
        }
        if (file.size > MAX_FILE_SIZE) {
            return res.status(400).json({ error: 'File size exceeds limit' });
        }

        // Generate unique filename
        const ext = path.extname(file.originalname);
        const filename = `${crypto.randomBytes(16).toString('hex')}${ext}`;

        // Prepare file for upload to CDN
        const formData = new FormData();
        formData.append('file', fs.createReadStream(file.path), { filename });

        // Upload file to CDN
        const response = await axios.post(CDN_URL, formData, {
            headers: {
                'Authorization': `Bearer ${CDN_AUTH_TOKEN}`,
                ...formData.getHeaders()
            }
        });

        // Clean up local file storage
        fs.unlinkSync(file.path);

        res.status(201).json({ url: response.data.url });
    } catch (error) {
        console.error(error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

