use reqwest::Client;
use tokio::sync::{mpsc, RwLock};
use tokio_kafka::{producer::Producer, producer::Record};
use std::collections::HashMap;
use std::time::{Duration, Instant};

#[derive(Clone)]
struct AppState {
    client: Client,
    kafka_producer: Producer<String, String>,
    rate_limit_state: RateLimitState,
}

struct RateLimitState {
    last_request_time: Instant,
    requests_made: usize,
}

impl RateLimitState {
    fn new() -> Self {
        Self {
            last_request_time: Instant::now(),
            requests_made: 0,
        }
    }

    fn can_make_request(&mut self, limit: usize) -> bool {
        let now = Instant::now();
        if now.duration_since(self.last_request_time).as_secs() > 1 {
            self.requests_made = 0;
        }
        self.requests_made < limit
    }

    fn make_request(&mut self) {
        self.requests_made += 1;
    }
}

async fn fetch_data(app_state: AppState, symbol: &str) {
    let mut state = app_state.rate_limit_state.write().await;
    if !state.can_make_request(10) {
        tokio::time::sleep(Duration::from_secs(1)).await;
        state.make_request();
    }
    let response = app_state.client.get(&format!("https://api.example.com/{}?token=YOUR_API_KEY", symbol))
        .send()
        .await
        .unwrap()
        .json::<serde_json::Value>()
        .await
        .unwrap();

    // Process data and send to Kafka
    let producer = app_state.kafka_producer.clone();
    tokio::spawn(async move {
        let _ = producer.send(Record::new(symbol, serde_json::to_string(&response).unwrap())).await;
    });
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let client = Client::new();
    let kafka_producer = Producer::from_config("localhost:9092", HashMap::new())?;
    let state = AppState {
        client,
        kafka_producer,
        rate_limit_state: RateLimitState::new(),
    };

    // Simulate fetching data for multiple symbols
    let symbols = vec!["AAPL", "GOOGL", "MSFT"];
    let mut tasks = Vec::new();
    for symbol in symbols {
        tasks.push(fetch_data(state.clone(), symbol));
    }

    futures::future::join_all(tasks).await?;

    Ok(())
}
```']

