use std::collections::HashMap;
use std::env;
use std::fs::{self, DirBuilder};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use tokio::sync::{Mutex as AsyncMutex, RwLock};
use reqwest::Client;
use log::{info, error};

struct DirectoryManager {
    client: Client,
    env_var_name: String,
    db_url: String,
    cache: Arc<RwLock<HashMap<String, PathBuf>>>,
}

impl DirectoryManager {
    async fn new(env_var_name: String, db_url: String) -> Result<Self, Box<dyn std::error::Error>> {
        let client = Client::new();
        Ok(DirectoryManager {
            client,
            env_var_name,
            db_url,
            cache: Arc::new(RwLock::new(HashMap::new())),
        })
    }

    async fn get_directory_path(&self) -> Result<PathBuf, Box<dyn std::error::Error>> {
        if let Some(path) = self.cache.read().await.get("directory_path") {
            return Ok(path.clone());
        }

        let env_var_value = env::var(&self.env_var_name).ok();
        let mut path = match env_var_value {
            Some(value) => PathBuf::from(value),
            None => self.create_directory().await?,
        };

        let db_path = format!("{}/{}", self.db_url, path.to_string_lossy());
        if !self.persist_to_db(&db_path).await? {
            info!("Failed to persist directory path to DB");
            return Err("Failed to persist directory path to DB".into());
        }

        self.cache.write().await.insert("directory_path", path.clone());
        Ok(path)
    }

    async fn create_directory(&self) -> Result<PathBuf, Box<dyn std::error::Error>> {
        let mut path = PathBuf::from(env!("HOME"));
        let timestamp = chrono::Local::now().format("%Y%m%d%H%M%S").to_string();
        path.push(format!("rust_dir_{}", timestamp));

        DirBuilder::new()
            .recursive(true)
            .create(&path)
            .map_err(|e| e.into())?;

        Ok(path)
    }

    async fn persist_to_db(&self, db_path: &str) -> Result<bool, Box<dyn std::error::Error>> {
        for _ in 0..5 {
            let response = self.client.post(db_path).send().await;
            if let Ok(response) = response {
                if response.status().is_success() {
                    info!("Successfully persisted directory path to DB");
                    return Ok(true);
                }
            }

            tokio::time::sleep(tokio::time::Duration::from_secs(2)).await;
        }

        error!("Failed to persist directory path to DB after multiple attempts");
        Ok(false)
    }
}

#[tokio::main]
async fn main() {
    env_logger::init();

    let manager = DirectoryManager::new("DIRECTORY_PATH".to_string(), "http://example.com/db").await.unwrap();
    if let Some(path) = manager.get_directory_path().await.ok() {
        info!("Directory path: {:?}", path);
    }
}
```

