import json
from abc import ABC, abstractmethod
import logging
from concurrent.futures import ThreadPoolExecutor

# Define the base class for JSON Serializable objects
class JSONSerializable(ABC):
    @abstractmethod
    def to_json(self) -> str:
        pass

    @classmethod
    @abstractmethod
    def from_json(cls, json_data: str) -> 'JSONSerializable':
        pass

# Implement a user model as a subclass of JSONSerializable
class User(JSONSerializable):
    def __init__(self, id, name, email):
        self.id = id
        self.name = name
        self.email = email

    def to_json(self) -> str:
        return json.dumps({
            "id": self.id,
            "name": self.name,
            "email": self.email
        })

    @classmethod
    def from_json(cls, json_data: str) -> 'User':
        data = json.loads(json_data)
        return cls(data['id'], data['name'], data['email'])

# Define a registry class to manage factory functions
class Registry:
    _registry = {}

    @staticmethod
    def register(id, func):
        Registry._registry[id] = func

    @staticmethod
    def get_factory(id):
        if id not in Registry._registry:
            raise ValueError(f"No factory registered for ID: {id}")
        return Registry._registry[id]

# Function to deserialize JSON data using the registry
def deserialize_json(json_data, model_id) -> JSONSerializable:
    factory = Registry.get_factory(model_id)
    return factory(json_data)

# Example usage of the framework with a RESTful API
class APIClient:
    def __init__(self, base_url):
        self.base_url = base_url

    def fetch_data(self, endpoint):
        # Simulate fetching data from an external API
        import requests
        response = requests.get(f"{self.base_url}/{endpoint}")
        return response.json()

def main():
    # Register factory functions for different models
    Registry.register("user", User.from_json)

    api_client = APIClient("https://api.example.com")

    with ThreadPoolExecutor(max_workers=5) as executor:
        futures = [executor.submit(fetch_data, endpoint) for endpoint in ["users/1", "products/2", "orders/3"]]
        results = [future.result() for future in futures]

    for result in results:
        user = deserialize_json(result, "user")
        print(user.to_json())

if __name__ == "__main__":
    main()
```

