using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

public class DynamicRangeGenerator<T> where T : IComparable<T>
{
    private readonly Random _random;
    private readonly object _lock = new object();
    private T _minValue, _maxValue;
    private string _logFilePath;
    private int _loggingFrequency;
    private Dictionary<string, bool> _logCategories;
    private long _seed;

    public DynamicRangeGenerator(T minValue, T maxValue, long seed)
    {
        if (minValue.CompareTo(maxValue) >= 0)
            throw new ArgumentException("Min value must be less than max value");

        _minValue = minValue;
        _maxValue = maxValue;
        _random = new Random((int)_seed);
        _logFilePath = "default.log";
        _loggingFrequency = 100;
        _logCategories = new Dictionary<string, bool>
        {
            { "Generation", true },
            { "Validation", true }
        };
    }

    public void SetRange(T minValue, T maxValue)
    {
        if (minValue.CompareTo(maxValue) >= 0)
            throw new ArgumentException("Min value must be less than max value");

        lock (_lock)
        {
            _minValue = minValue;
            _maxValue = maxValue;
        }
    }

    public void SetLoggingOptions(string logFilePath, int loggingFrequency, Dictionary<string, bool> logCategories)
    {
        lock (_lock)
        {
            _logFilePath = logFilePath;
            _loggingFrequency = loggingFrequency;
            _logCategories = logCategories;
        }
    }

    public T GenerateRandomValue()
    {
        lock (_lock)
        {
            var value = (T)Convert.ChangeType(_random.NextDouble() * (_maxValue.CompareTo(_minValue) == 0 ? 1 : Convert.ToDouble(_maxValue.CompareTo(_minValue))) + Convert.ToDouble(_minValue), typeof(T));
            LogValueGeneration(value);
            return value;
        }
    }

    private void LogValueGeneration(T value)
    {
        if (!_logCategories["Generation"])
            return;

        var timestamp = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss.fff");
        using (var writer = System.IO.File.AppendText(_logFilePath))
        {
            writer.WriteLine($"{timestamp} - Generated value: {value}");
        }
    }

    public void AdjustLoggingLevel(string category, bool enabled)
    {
        lock (_lock)
        {
            if (_logCategories.ContainsKey(category))
                _logCategories[category] = enabled;
        }
    }
}
