    AES_set_encrypt_key(key, 128, &enc_key);
    *encrypted_data = (unsigned char *)malloc(AES_BLOCK_SIZE + data_len);
    AES_cbc_encrypt(data, *encrypted_data, data_len, &enc_key, iv, AES_ENCRYPT);
}

// Function to decrypt data using AES
void aes_decrypt(const unsigned char *key, const unsigned char *iv, const unsigned char *data, unsigned int data_len, unsigned char **decrypted_data) {
    AES_KEY dec_key;
    AES_set_decrypt_key(key, 128, &dec_key);
    *decrypted_data = (unsigned char *)malloc(data_len);
    AES_cbc_encrypt(data, *decrypted_data, data_len, &dec_key, iv, AES_DECRYPT);
}

