    RSA *rsa = RSA_new();
    BIGNUM *e = BN_new();
    BN_set_word(e, RSA_F4);
    RSA_generate_key_ex(rsa, 2048, e, NULL);
    BN_free(e);
    return rsa;
}

// Function to sign data using RSA and SHA1
void rsa_sign(const unsigned char *data, unsigned int data_len, RSA *rsa, unsigned char **signature) {
    *signature = (unsigned char *)malloc(RSA_size(rsa));
    RSA_sign(NID_sha1, data, data_len, *signature, &signature_len, rsa);
}

// Function to verify signature using RSA and SHA1
int rsa_verify(const unsigned char *data, unsigned int data_len, const unsigned char *signature, unsigned int sig_len, RSA *rsa) {
    return RSA_verify(NID_sha1, data, data_len, signature, sig_len, rsa);
}

// Function to load RSA key from file
RSA *load_rsa_key_from_file(const char *file_path) {
    FILE *fp = fopen(file_path, "r");
    if (!fp) return NULL;
    RSA *rsa = PEM_read_RSA_PUBKEY(fp, NULL, NULL, NULL);
    fclose(fp);
    return rsa;
}

// Function to save RSA key to file
void save_rsa_key_to_file(RSA *rsa, const char *file_path) {
    FILE *fp = fopen(file_path, "w");
    if (fp) {
        PEM_write_RSA_PUBKEY(fp, rsa);
        fclose(fp);
    }
}
