public class DynamicRangeGenerator<T> where T : IComparable<T>
{
    private readonly Random _random = new Random();
    private T _minValue;
    private T _maxValue;
    private ILogger _logger;
    private readonly CircuitBreaker _circuitBreaker;
    private readonly AsyncCache<Dictionary<string, object>> _cache;

    public DynamicRangeGenerator(T minValue, T maxValue, ILogger logger)
    {
        if (Comparer<T>.Default.Compare(minValue, maxValue) >= 0)
            throw new ArgumentException("Min value must be less than max value.");

        _minValue = minValue;
        _maxValue = maxValue;
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _circuitBreaker = new CircuitBreaker();
        _cache = new AsyncCache<Dictionary<string, object>>(async () =>
