#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <openssl/pbkdf2.h>
#include <sqlite3.h>

#define KEY_SIZE 32
#define SALT_SIZE 16
#define HMAC_SIZE 32

typedef struct {
    unsigned char key[KEY_SIZE];
    unsigned char salt[SALT_SIZE];
} EncryptionKey;

int derive_key(const char *password, size_t password_len, EncryptionKey *key) {
    return PKCS5_PBKDF2_HMAC(password, password_len, NULL, 0, 100000, EVP_sha256(), KEY_SIZE, key->key);
}

void generate_salt(EncryptionKey *key) {
    if (!RAND_bytes(key->salt, SALT_SIZE)) {
        fprintf(stderr, "Error generating salt\n");
        exit(EXIT_FAILURE);
    }
}

int encrypt(const unsigned char *data, size_t data_len, const EncryptionKey *key, unsigned char *ciphertext, unsigned char *iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error creating cipher context\n");
        return -1;
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key->key, iv)) {
        fprintf(stderr, "Error initializing encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, data, data_len)) {
        fprintf(stderr, "Error encrypting data\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        fprintf(stderr, "Error finalizing encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    ciphertext_len += len;
    EVP_CIPHER_CTX_free(ctx);

    return ciphertext_len;
}

int decrypt(const unsigned char *ciphertext, size_t ciphertext_len, const EncryptionKey *key, unsigned char *plaintext, unsigned char *iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error creating cipher context\n");
        return -1;
    }

    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key->key, iv)) {
        fprintf(stderr, "Error initializing decryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        fprintf(stderr, "Error decrypting data\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        fprintf(stderr, "Error finalizing decryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    plaintext_len += len;
    EVP_CIPHER_CTX_free(ctx);

    return plaintext_len;
}

int hmac(const unsigned char *data, size_t data_len, const EncryptionKey *key, unsigned char *hmac_output) {
    HMAC_CTX *ctx = HMAC_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error creating HMAC context\n");
        return -1;
    }

    if (HMAC_Init_ex(ctx, key->key, KEY_SIZE, EVP_sha256(), NULL) != 1) {
        fprintf(stderr, "Error initializing HMAC\n");
        HMAC_CTX_free(ctx);
        return -1;
    }

    if (HMAC_Update(ctx, data, data_len) != 1) {
        fprintf(stderr, "Error updating HMAC\n");
        HMAC_CTX_free(ctx);
        return -1;
    }

    int hmac_len = 0;
    if (HMAC_Final(ctx, hmac_output, &hmac_len) != 1) {
        fprintf(stderr, "Error finalizing HMAC\n");
        HMAC_CTX_free(ctx);
        return -1;
    }

    HMAC_CTX_free(ctx);

    return hmac_len;
}

int store_encrypted_data(sqlite3 *db, const unsigned char *ciphertext, size_t ciphertext_len, const unsigned char *iv) {
    sqlite3_stmt *stmt;
    const char *sql = "INSERT INTO encrypted_data (ciphertext, iv) VALUES (?, ?)";

    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "Error preparing SQL statement: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    if (sqlite3_bind_blob(stmt, 1, ciphertext, ciphertext_len, SQLITE_STATIC) != SQLITE_OK) {
        fprintf(stderr, "Error binding ciphertext to SQL statement: %s\n", sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        return -1;
    }

    if (sqlite3_bind_blob(stmt, 2, iv, EVP_CIPHER_iv_length(EVP_aes_256_cbc()), SQLITE_STATIC) != SQLITE_OK) {
        fprintf(stderr, "Error binding IV to SQL statement: %s\n", sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        return -1;
    }

    if (sqlite3_step(stmt) != SQLITE_DONE) {
        fprintf(stderr, "Error executing SQL statement: %s\n", sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        return -1;
    }

    sqlite3_finalize(stmt);
    return 0;
}

int retrieve_encrypted_data(sqlite3 *db, unsigned char **ciphertext, size_t *ciphertext_len, unsigned char **iv) {
    sqlite3_stmt *stmt;
    const char *sql = "SELECT ciphertext, iv FROM encrypted_data WHERE id = ?";

    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "Error preparing SQL statement: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    if (sqlite3_bind_int(stmt, 1, /* id */ 1) != SQLITE_OK) {
        fprintf(stderr, "Error binding ID to SQL statement: %s\n", sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        return -1;
    }

    if (sqlite3_step(stmt) == SQLITE_ROW) {
        *ciphertext = (unsigned char *)sqlite3_column_blob(stmt, 0);
        *ciphertext_len = sqlite3_column_bytes(stmt, 0);

        *iv = (unsigned char *)sqlite3_column_blob(stmt, 1);
    } else if (sqlite3_step(stmt) == SQLITE_DONE) {
        fprintf(stderr, "No encrypted data found\n");
        sqlite3_finalize(stmt);
        return -1;
    } else {
        fprintf(stderr, "Error retrieving data from database: %s\n", sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        return -1;
    }

    sqlite3_finalize(stmt);
    return 0;
}
```

This code provides a basic implementation of an encryption and decryption module using OpenSSL in C. It includes functions for key derivation, AES-256-CBC encryption and decryption with HMAC-SHA256, and database interaction to store and retrieve encrypted data.

To use this module:
1. Derive a key from a password using `derive_key`.
2. Generate an IV using `generate_salt`.
3. Encrypt data using `encrypt`.
4. Decrypt data using `decrypt`.
5. Store encrypted data in the database using `store_encrypted_data`.
6. Retrieve and decrypt data from the database using `retrieve_encrypted_data`.

This example assumes you have a SQLite database set up with a table named `encrypted_data` that has columns for `ciphertext`, `iv`, and `id`. Adjust the SQL queries and error handling as needed for your specific database schema.

