#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <pthread.h>
#include <time.h>

#define MAX_COMMANDS 1024
#define MAX_CMD_LENGTH 256
#define LOG_FILE "command_execution.log"

typedef struct {
    char command[MAX_CMD_LENGTH];
    int pid;
} Command;

Command commands[MAX_COMMANDS];
int command_count = 0;

void log_command(const char *command, int status) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    fprintf(log_file, "%s: Command '%s' exited with status %d\n", asctime(tm_info), command, status);
    fclose(log_file);
}

void handle_sigchld(int signum) {
    int status;
    pid_t pid;

    while ((pid = waitpid(-1, &status, WNOHANG)) > 0) {
        for (int i = 0; i < command_count; ++i) {
            if (commands[i].pid == pid) {
                log_command(commands[i].command, status);
                commands[i].pid = -1;
                break;
            }
        }
    }
}

void *execute_commands(void *arg) {
    int *index = (int *)arg;

    while (*index < command_count) {
        int i = *index;
        pid_t pid = fork();
        if (pid == -1) {
            perror("Failed to fork");
            exit(EXIT_FAILURE);
        } else if (pid == 0) {
            char *args[MAX_CMD_LENGTH / 2 + 1];
            args[0] = strtok(commands[i].command, " ");
            for (int j = 1; args[j-1] != NULL; ++j)
                args[j] = strtok(NULL, " ");
            args[MAX_CMD_LENGTH / 2] = NULL;

            execvp(args[0], args);
            perror("Failed to execute command");
            exit(EXIT_FAILURE);
        } else {
            commands[i].pid = pid;
        }

        (*index)++;
    }

    return NULL;
}

int main() {
    signal(SIGCHLD, handle_sigchld);

    pthread_t threads[MAX_COMMANDS];
    int indices[MAX_COMMANDS];

    // Simulate receiving commands
    strcpy(commands[0].command, "ls -l");
    commands[1].command = "sleep 5";
    command_count = 2;

    for (int i = 0; i < command_count; ++i)
        indices[i] = i;

    for (int i = 0; i < command_count; ++i) {
        pthread_create(&threads[i], NULL, execute_commands, &indices[i]);
    }

    for (int i = 0; i < command_count; ++i)
        pthread_join(threads[i], NULL);

    return 0;
}
