#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

#define MAX_STRING_SIZE 1024

typedef struct {
    char *data;
    size_t length;
} String;

String* string_create(const char *initial_data, size_t initial_size) {
    String *str = (String*)malloc(sizeof(String));
    if (str == NULL) return NULL;

    str->length = strlen(initial_data);
    str->data = (char*)malloc(str->length + 1);
    if (str->data == NULL) {
        free(str);
        return NULL;
    }
    strcpy(str->data, initial_data);

    return str;
}

void string_destroy(String *str) {
    if (str != NULL) {
        free(str->data);
        free(str);
    }
}

String* string_compress(const String *input, int compression_level) {
    uLong compressed_size = compressBound(input->length);
    Bytef *compressed_data = (Bytef*)malloc(compressed_size);

    if (compressed_data == NULL) return NULL;

    int result = compress2(compressed_data, &compressed_size, (const Bytef*)input->data, input->length, compression_level);
    if (result != Z_OK) {
        free(compressed_data);
        return NULL;
    }

    String *compressed_str = string_create((char*)compressed_data, compressed_size);
    free(compressed_data);

    return compressed_str;
}

String* string_decompress(const String *input) {
    uLong original_size = input->length;
    Bytef *decompressed_data = (Bytef*)malloc(original_size);

    if (decompressed_data == NULL) return NULL;

    int result = uncompress(decompressed_data, &original_size, (const Bytef*)input->data, input->length);
    if (result != Z_OK) {
        free(decompressed_data);
        return NULL;
    }

    String *decompressed_str = string_create((char*)decompressed_data, original_size);
    free(decompressed_data);

    return decompressed_str;
}

int main() {
    String *original = string_create("Hello, world!", 13);
    String *compressed = string_compress(original, Z_BEST_COMPRESSION);
    String *decompressed = string_decompress(compressed);

    printf("Original: %s\n", original->data);
    printf("Compressed: %s (size: %zu)\n", compressed->data, compressed->length);
    printf("Decompressed: %s\n", decompressed->data);

    string_destroy(original);
    string_destroy(compressed);
    string_destroy(decompressed);

    return 0;
}
