#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    sem_t semaphore;
    int value;
} Semaphore;

Semaphore* create_semaphore(int initial_value) {
    if (initial_value < -1000 || initial_value > 1000) {
        perror("Invalid initial value for semaphore");
        exit(EXIT_FAILURE);
    }

    Semaphore* s = malloc(sizeof(Semaphore));
    if (!s) {
        perror("Failed to allocate memory for semaphore");
        exit(EXIT_FAILURE);
    }

    sem_init(&s->semaphore, 0, initial_value);
    s->value = initial_value;
    return s;
}

void destroy_semaphore(Semaphore* s) {
    sem_destroy(&s->semaphore);
    free(s);
}

void semaphore_increment(Semaphore* s) {
    sem_post(&s->semaphore);
    s->value++;
}

void semaphore_decrement(Semaphore* s) {
    if (sem_wait(&s->semaphore) == -1) {
        perror("Semaphore wait failed");
        exit(EXIT_FAILURE);
    }
    s->value--;
}
