#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

#define MAX_STRING_SIZE 1024

typedef struct {
    char *data;
    size_t length;
    size_t max_size;
} TextBuffer;

TextBuffer* create_text_buffer(size_t initial_size) {
    TextBuffer *buffer = (TextBuffer*)malloc(sizeof(TextBuffer));
    buffer->data = (char*)calloc(initial_size, sizeof(char));
    buffer->length = 0;
    buffer->max_size = initial_size;
    return buffer;
}

void free_text_buffer(TextBuffer *buffer) {
    if (buffer) {
        free(buffer->data);
        free(buffer);
    }
}

int resize_text_buffer(TextBuffer *buffer, size_t new_size) {
    char *new_data = (char*)realloc(buffer->data, new_size * sizeof(char));
    if (!new_data) return -1;
    buffer->data = new_data;
    buffer->max_size = new_size;
    return 0;
}

int compress_text(TextBuffer *input, TextBuffer **output) {
    uLongf compressed_size = compressBound(input->length);
    *output = create_text_buffer(compressed_size);
    if (!*output) return -1;

    int result = compress((Bytef*)(*output)->data, &compressed_size, (Bytef*)input->data, input->length);
    if (result != Z_OK) {
        free_text_buffer(*output);
        *output = NULL;
        return result;
    }

    (*output)->length = compressed_size;
    return 0;
}

int decompress_text(TextBuffer *input, TextBuffer **output) {
    uLongf uncompressed_size = input->max_size;
    *output = create_text_buffer(uncompressed_size);
    if (!*output) return -1;

    int result = uncompress((Bytef*)(*output)->data, &uncompressed_size, (Bytef*)input->data, input->length);
    if (result != Z_OK) {
        free_text_buffer(*output);
        *output = NULL;
        return result;
    }

    (*output)->length = uncompressed_size;
    return 0;
}

int main() {
    TextBuffer input = { .data = "Hello, World!", .length = 14, .max_size = MAX_STRING_SIZE };
    TextBuffer *compressed = NULL;
    TextBuffer *decompressed = NULL;

    if (compress_text(&input, &compressed) == 0) {
        printf("Compressed size: %zu\n", compressed->length);
        if (decompress_text(compressed, &decompressed) == 0) {
            printf("Decompressed content: %.*s\n", (int)decompressed->length, decompressed->data);
        }
    }

    free_text_buffer(compressed);
    free_text_buffer(decompressed);

    return 0;
}
```

