#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    int event_code;
    union {
        int int_data;
        double double_data;
        char* string_data;
    } context;
} NetworkEvent;

typedef struct LogNode {
    NetworkEvent event;
    struct LogNode* next;
} LogNode;

LogNode* log_queue = NULL;
pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;

void* log_processor(void* arg) {
    while (1) {
        pthread_mutex_lock(&queue_lock);
        if (log_queue != NULL) {
            NetworkEvent event = log_queue->event;
            LogNode* temp = log_queue;
            log_queue = log_queue->next;
            pthread_mutex_unlock(&queue_lock);

            // Process the event
            printf("Processing event: Timestamp=%ld, Event Code=%d\n", (long)event.timestamp, event.event_code);

            free(temp);  // Free the allocated memory for the node
        } else {
            pthread_mutex_unlock(&queue_lock);
            usleep(1000);  // Sleep for a short duration before checking again
        }
    }
    return NULL;
}

void log_event(NetworkEvent event) {
    LogNode* new_node = (LogNode*)malloc(sizeof(LogNode));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    new_node->event = event;
    new_node->next = NULL;

    pthread_mutex_lock(&queue_lock);
    if (log_queue == NULL) {
        log_queue = new_node;
    } else {
        LogNode* temp = log_queue;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
    pthread_mutex_unlock(&queue_lock);
}

int main() {
    pthread_t processor_thread;
    if (pthread_create(&processor_thread, NULL, log_processor, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    // Example usage
    NetworkEvent event;
    event.timestamp = time(NULL);
    event.event_code = 101;
    event.context.int_data = 42;

    log_event(event);

    pthread_join(processor_thread, NULL);
    return 0;
}
```

