package com.example.loggingframework;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.List;
import java.util.stream.Collectors;

public class LoggingFramework {
    private ExecutorService executorService;
    private List<DataIngestor> dataIngestors;
    private List<StorageBackend> storageBackends;
    private ConfigManager configManager;

    public LoggingFramework(List<Class<? extends DataIngestor>> ingestorClasses, List<Class<? extends StorageBackend>> backendClasses) {
        this.executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        this.dataIngestors = ingestorClasses.stream()
            .map(this::createInstance)
            .collect(Collectors.toList());
        this.storageBackends = backendClasses.stream()
            .map(this::createInstance)
            .collect(Collectors.toList());
        this.configManager = new ConfigManager();
    }

    private <T> T createInstance(Class<T> clazz) {
        try {
            return clazz.getDeclaredConstructor().newInstance();
        } catch (Exception e) {
            throw new RuntimeException("Failed to create instance of " + clazz.getName(), e);
        }
    }

    public void start() {
        dataIngestors.forEach(ingestor -> executorService.submit(() -> ingestor.start()));
        storageBackends.forEach(storageBackend -> executorService.submit(() -> storageBackend.connect()));
    }

    public void stop() {
        executorService.shutdown();
        dataIngestors.forEach(DataIngestor::stop);
        storageBackends.forEach(StorageBackend::disconnect);
    }
}
