    if (!manager) return NULL;
    memset(manager, 0, sizeof(UE_Info_Manager));
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroy_ue_info_manager(UE_Info_Manager *manager) {
    for (int i = 0; i < manager->count; i++) {
        free(manager->ue_info_array[i]);
    }
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int add_ue_info(UE_Info_Manager *manager, NFAPI_CRC_INDICATION_PDU_T *new_info) {
    if (manager->count >= MAX_UE_INFO) return -1;
    manager->ue_info_array[manager->count++] = new_info;
    return 0;
}

