    if (!manager) return 1;

    // Add UE information to the manager
    for (int i = 0; i < MAX_UE_INFO; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_info = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_info) {
            destroy_ue_info_manager(manager);
            return 1;
        }
        // Initialize new_info structure
        add_ue_info(manager, new_info);
    }

    pthread_t validation_thread;
    if (pthread_create(&validation_thread, NULL, validate_crc_indication, manager)) {
        destroy_ue_info_manager(manager);
        return 1;
    }

    // Main loop or other operations

