#include <queue>
#include <atomic>
#include <future>
#include <chrono>
#include <unordered_map>

// Define custom exceptions for better error handling
class LogProcessingError : public std::runtime_error {
public:
    explicit LogProcessingError(const std::string& message) : std::runtime_error(message) {}
};

class CloudLoggingService {
public:
    void logError(const std::string& error) {
        // Simulate logging to a cloud service
        std::cout << "Logged error: " << error << std::endl;
    }
};

// Define input and output formats
enum class LogFormat { TEXT, JSON, CSV };

class LogProcessor {
public:
    LogProcessor(CloudLoggingService& cloudLogger) : cloudLogger_(cloudLogger), stop_(false) {}

    void processLog(const std::string& logData, LogFormat format) {
        // Process log data based on the format
        if (format == LogFormat::TEXT) {
            textProcessor_.process(logData);
        } else if (format == LogFormat::JSON) {
            jsonProcessor_.process(logData);
        } else if (format == LogFormat::CSV) {
            csvProcessor_.process(logData);
        }
    }

    void startProcessing() {
        processingThread_ = std::thread(&LogProcessor::worker, this);
    }

    void stopProcessing() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stop_ = true;
        }
        condition_.notify_one();
        if (processingThread_.joinable()) {
            processingThread_.join();
        }
    }

private:
    void worker() {
        while (true) {
            std::string logData;
            LogFormat format;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                condition_.wait(lock, [this] { return !queue_.empty() || stop_; });
                if (stop_ && queue_.empty()) {
                    break;
                }
                logData = std::move(queue_.front().logData);
                format = queue_.front().format;
                queue_.pop();
            }

            try {
                processLog(logData, format);
            } catch (const LogProcessingError& e) {
                cloudLogger_.logError(e.what());
            }
        }
    }

    struct Task {
        std::string logData;
        LogFormat format;
    };

    CloudLoggingService& cloudLogger_;
    std::queue<Task> queue_;
    std::thread processingThread_;
    std::mutex mutex_;
    std::condition_variable condition_;
    std::atomic<bool> stop_;

    // Assume these are custom processors for different formats
    class TextProcessor {
    public:
        void process(const std::string& logData) {
            // Process text data
        }
    } textProcessor_;

    class JsonProcessor {
    public:
        void process(const std::string& logData) {
            // Process JSON data
        }
    } jsonProcessor_;

    class CsvProcessor {
    public:
        void process(const std::string& logData) {
            // Process CSV data
        }
    } csvProcessor_;
};

int main() {
    CloudLoggingService cloudLogger;
    LogProcessor processor(cloudLogger);

    processor.startProcessing();

    // Simulate incoming log data
    for (const auto& log : {"text log", "json log", "csv log"}) {
        processor.processLog(log, LogFormat::TEXT);
    }

    processor.stopProcessing();
    return 0;
}
