fn run_cli() -> Result<(), String> {
    let matches = App::new("MetaCache")
        .version("1.0")
        .author("Your Name <your.email@example.com>")
        .about("Process image metadata into standardized JSON representations")
        .arg(
            Arg::with_name("image_path")
                .short('i')
                .long("image-path")
                .value_name("PATH")
                .takes_value(true)
                .help("Sets the image path to process"),
        )
        .get_matches();

    let image_path = matches.value_of("image_path").unwrap_or("");

    // Initialize services and processor
    let schema_service = SchemaService::new(String::from("https://mms.example.com"), CacheSystem::new());
    let cache_system = CacheSystem::new();
    let processor = ImageProcessor::new(schema_service, cache_system);

    // Process image
    let metadata = processor.process_image(image_path).await?;
    println!("{}", serde_json::to_string_pretty(&metadata)?);

    Ok(())
}
