#include <iostream>
#include <string>
#include <openssl/evp.h>
#include <openssl/rand.h>

// Function to initialize the encryption context using a passphrase
EVP_CIPHER_CTX* init_encryption_context(const std::string& passphrase) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return nullptr;

    unsigned char salt[8];
    if (RAND_bytes(salt, sizeof(salt)) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return nullptr;
    }

    const int key_length = EVP_aes_256_cbc_nid();
    unsigned char* key = new unsigned char[key_length];
    unsigned char* iv = new unsigned char[EVP_CIPHER_block_size(EVP_aes_256_cbc())];

    if (!PKCS5_PBKDF2_HMAC(passphrase.c_str(), passphrase.size(), salt, sizeof(salt), 100000, EVP_sha256(), key_length, key) ||
        !RAND_bytes(iv, sizeof(iv))) {
        delete[] key;
        delete[] iv;
        EVP_CIPHER_CTX_free(ctx);
        return nullptr;
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        delete[] key;
        delete[] iv;
        EVP_CIPHER_CTX_free(ctx);
        return nullptr;
    }

    return ctx;
}

// Function to clean up resources for the encryption context
void cleanup_encryption_context(EVP_CIPHER_CTX* ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_cleanup(ctx);
        EVP_CIPHER_CTX_free(ctx);
    }
}

int main() {
    std::string passphrase = "securepass123";
    EVP_CIPHER_CTX* ctx = init_encryption_context(passphrase);

    if (!ctx) {
        std::cerr << "Failed to initialize encryption context." << std::endl;
        return 1;
    }

    // Example usage of the encryption context
    unsigned char plaintext[] = "Financial data";
    unsigned char ciphertext[128];
    int ciphertext_len;

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len, plaintext, sizeof(plaintext) - 1)) {
        std::cerr << "Encryption failed." << std::endl;
        cleanup_encryption_context(ctx);
        return 1;
    }

    // Finalize the encryption
    int final_len;
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + ciphertext_len, &final_len)) {
        std::cerr << "Finalization of encryption failed." << std::endl;
        cleanup_encryption_context(ctx);
        return 1;
    }

    ciphertext_len += final_len;

    // Clean up resources
    cleanup_encryption_context(ctx);

    // Output the encrypted data
    for (int i = 0; i < ciphertext_len; ++i) {
        printf("%02x", ciphertext[i]);
    }
    std::cout << std::endl;

    return 0;
}
