#include <iostream>
#include <thread>
#include <vector>
#include <atomic>
#include <mutex>
#include <condition_variable>

class RNGManager {
private:
    std::vector<std::thread> threads;
    std::mutex mtx;
    std::condition_variable cv;
    bool stop;

public:
    RNGManager(size_t num_threads) : stop(false) {
        for (size_t i = 0; i < num_threads; ++i) {
            threads.emplace_back(&RNGManager::worker, this);
        }
    }

    ~RNGManager() {
        {
            std::unique_lock<std::mutex> lock(mtx);
            stop = true;
        }
        cv.notify_all();
        for (auto& thread : threads) {
            thread.join();
        }
    }

    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this] { return stop; });
            if (stop) break;
            // Perform RNG generation here
        }
    }

    void generateRandomNumbers(size_t num_samples) {
        std::unique_lock<std::mutex> lock(mtx);
        for (size_t i = 0; i < threads.size(); ++i) {
            cv.notify_one();
        }
        cv.wait(lock, [this] { return stop; });
    }
};

int main() {
    RNGManager manager(4);
    manager.generateRandomNumbers(1000000);
    return 0;
}
