using System;
using System.Collections.Generic;
using System.Data.Common;
using System.Threading.Tasks;

public interface IDatabaseProvider
{
    Task<DbDataReader> ExecuteReaderAsync(string query, Dictionary<string, object> parameters);
    Task<int> ExecuteNonQueryAsync(string query, Dictionary<string, object> parameters);
}

public class DatabaseProviderFactory : IDatabaseProviderFactory
{
    private readonly List<IDatabaseProvider> _providers;

    public DatabaseProviderFactory(List<IDatabaseProvider> providers)
    {
        _providers = providers;
    }

    public IDatabaseProvider GetProviderFor(string databaseName)
    {
        // Implement logic to select the appropriate provider based on the database name
        return _providers.FirstOrDefault(p => p.DatabaseName == databaseName);
    }
}

public class DatabaseService
{
    private readonly IDatabaseProviderFactory _databaseProviderFactory;
    private readonly ILogger _logger;
    private readonly IDistributedTracer _distributedTracer;

    public DatabaseService(IDatabaseProviderFactory databaseProviderFactory, ILogger logger, IDistributedTracer distributedTracer)
    {
        _databaseProviderFactory = databaseProviderFactory;
        _logger = logger;
        _distributedTracer = distributedTracer;
    }

    public async Task<DbDataReader> ExecuteParameterizedQueryAsync(string databaseName, string query, Dictionary<string, object> parameters, bool isWriteOperation = false)
    {
        var provider = _databaseProviderFactory.GetProviderFor(databaseName);
        if (provider == null)
            throw new ArgumentException("Database provider not found for the given database name.");

        using (_distributedTracer.StartSpan("ExecuteParameterizedQueryAsync"))
        {
            try
            {
                var result = isWriteOperation ? await provider.ExecuteNonQueryAsync(query, parameters) : await provider.ExecuteReaderAsync(query, parameters);
                _logger.Log("Query executed successfully.");
                return result;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex);
                throw new GenericErrorCodeException("An error occurred while executing the query.", ex);
            }
        }
    }

    public async Task<int> ExecuteNonQueryAsync(string databaseName, string query, Dictionary<string, object> parameters)
    {
        return await ExecuteParameterizedQueryAsync(databaseName, query, parameters, true);
    }

    public async Task<DbDataReader> ExecuteReaderAsync(string databaseName, string query, Dictionary<string, object> parameters)
    {
        return await ExecuteParameterizedQueryAsync(databaseName, query, parameters, false);
    }
}

public class GenericErrorCodeException : Exception
{
    public int ErrorCode { get; }

    public GenericErrorCodeException(int errorCode, Exception innerException = null) 
        : base("An error occurred with generic error code.", innerException)
    {
        ErrorCode = errorCode;
    }
}
