                return BadRequest("Invalid request payload.");
            }

            var user = new UserProfile { Id = id, Name = name.GetString(), Email = email.GetString() };
            using (var fileStream = File.Open(_filePath, FileMode.OpenOrCreate))
            {
                _binaryFormatter.Serialize(fileStream, user);
            }

            return Ok();
        }
        catch (SerializationException ex)
        {
            _logger.LogError(ex, "Error serializing user profile.");
            return StatusCode(500, "Internal server error.");
        }
    }

    [HttpDelete("{id}")]
    public async Task<IActionResult> DeleteUserProfile(int id)
    {
        try
        {
            if (!File.Exists(_filePath))
            {
                return NotFound("User profiles file not found.");
            }

            using (var fileStream = File.Open(_filePath, FileMode.Open))
            {
                var userProfiles = _binaryFormatter.Deserialize(fileStream) as List<UserProfile>;
                if (userProfiles == null || !userProfiles.Any(u => u.Id == id))
                {
                    return NotFound("User profile not found.");
                }

                userProfiles.RemoveAll(u => u.Id == id);
                using (var fileStreamWrite = File.Open(_filePath, FileMode.Create))
                {
                    _binaryFormatter.Serialize(fileStreamWrite, userProfiles);
                }
            }

            // Restore last backup
            var backupFilePath = _filePath + ".bak";
            if (File.Exists(backupFilePath))
            {
                File.Copy(backupFilePath, _filePath, true);
            }

            return Ok();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error deleting user profile.");
            return StatusCode(500, "Internal server error.");
        }
    }
}

public class UserProfile
{
    public int Id { get; set; }
    public string Name { get; set; }
    public string Email { get; set; }
}
```

