    public XmlService(HttpClient httpClient, IMemoryCache cache, ILogger<XmlService> logger)
    {
        _httpClient = httpClient;
        _cache = cache;
        _logger = logger;
    }

    public async Task<string> GetXmlAsync(string source, string xpathQuery)
    {
        try
        {
            if (_cache.TryGetValue(source, out var cachedXml))
            {
                return cachedXml;
            }

            string xmlContent = await FetchXmlAsync(source);
            var parsedData = ParseXml(xmlContent, xpathQuery);

            _cache.Set(source, parsedData, new MemoryCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5)
            });

            return parsedData;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error fetching or parsing XML from {Source}", source);
            throw;
        }
    }

    private async Task<string> FetchXmlAsync(string source)
    {
        if (source.StartsWith("http"))
        {
            var response = await _httpClient.GetAsync(source);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsStringAsync();
        }
        else
