import java.io.IOException;
import java.net.URI;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.client.RestTemplate;

@SpringBootApplication
public class ResourceServiceApplication {

    public static void main(String[] args) {
        SpringApplication.run(ResourceServiceApplication.class, args);
    }
}

@RestController
class ResourceController {

    private final RestTemplate restTemplate = new RestTemplate();
    private final ConcurrentHashMap<UUID, String> resourceCache = new ConcurrentHashMap<>();
    private final AtomicInteger lockCounter = new AtomicInteger(0);

    @PutMapping("/resource/{id}")
    public void updateResource(@PathVariable UUID id, @RequestBody String metadata) {
        int lockId = lockCounter.incrementAndGet() % 100; // Simplified locking mechanism
        try {
            validateMetadata(metadata);
            resourceCache.put(id, metadata);
        } finally {
            lockCounter.decrementAndGet();
        }
    }

    @DeleteMapping("/resource/{id}")
    public void deleteResource(@PathVariable UUID id) {
        int lockId = lockCounter.incrementAndGet() % 100; // Simplified locking mechanism
        try {
            resourceCache.remove(id);
        } finally {
            lockCounter.decrementAndGet();
        }
    }

    private void validateMetadata(String metadata) {
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        HttpEntity<String> request = new HttpEntity<>(metadata, headers);

        URI uri = URI.create("https://thirdpartyapi.com/validate");
        try {
            restTemplate.postForObject(uri, request, String.class);
        } catch (IOException e) {
            throw new RuntimeException("Validation API is unavailable", e);
        }
    }

    @GetMapping("/health")
    public String healthCheck() {
        return "Service is running";
    }
}
