using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using MassTransit;
using RedisCache;

[Route("api/[controller]")]
public class HtmlContentController : ControllerBase
{
    private readonly ApplicationDbContext _dbContext;
    private readonly IBusControl _bus;

    public HtmlContentController(ApplicationDbContext dbContext, IBusControl bus)
    {
        _dbContext = dbContext;
        _bus = bus;
    }

    [HttpPost("{elementId}")]
    public async Task<IActionResult> UpdateHtmlContent(string elementId, [FromBody] string newHtmlContent)
    {
        var existingElement = await _dbContext.HtmlElements.FindAsync(elementId);
        if (existingElement == null)
            return NotFound();

        existingElement.Content = newHtmlContent;
        await _dbContext.SaveChangesAsync();

        await _bus.Publish(new HtmlUpdateMessage
        {
            ElementId = elementId,
            NewContent = newHtmlContent
        });

        return Ok();
    }
}

public class ApplicationDbContext : DbContext
{
    public DbSet<HtmlElement> HtmlElements { get; set; }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseSqlServer("YourConnectionStringHere");
    }
}

public class HtmlElement
{
    public string Id { get; set; }
    public string Content { get; set; }
}

public class HtmlUpdateMessage
{
    public string ElementId { get; set; }
    public string NewContent { get; set; }
}

public class HtmlContentConsumer : IConsumer<HtmlUpdateMessage>
{
    private readonly IRedisCacheProvider _cacheProvider;

    public HtmlContentConsumer(IRedisCacheProvider cacheProvider)
    {
        _cacheProvider = cacheProvider;
    }

    public async Task Consume(ConsumeContext<HtmlUpdateMessage> context)
    {
        await _cacheProvider.SetStringAsync(context.Message.ElementId, context.Message.NewContent);
    }
}
```

