// Function to render the sidebar menu
function renderSidebarMenu(menu, parentElement) {
  const menuElement = document.createElement('ul');
  parentElement.appendChild(menuElement);

  menu.forEach(item => {
    const menuItem = document.createElement('li');
    const linkElement = document.createElement('a');
    linkElement.href = item.link;
    linkElement.textContent = item.title;

    if (item.children.length > 0) {
      const subMenuElement = document.createElement('ul');
      renderSidebarMenu(item.children, subMenuElement);
      menuItem.appendChild(subMenuElement);
    }

    menuItem.appendChild(linkElement);
    menuElement.appendChild(menuItem);
  });
}

// Function to fetch and update the sidebar menu from an API
async function fetchAndUpdateMenu(apiUrl) {
  try {
    const response = await fetch(apiUrl);
    if (!response.ok) {
      throw new Error('Network response was not ok');
    }
    const updatedMenu = await response.json();
    // Update the DOM with the new menu configuration
    renderSidebarMenu(updatedMenu, document.getElementById('sidebar'));
  } catch (error) {
    console.error('Error fetching updated menu:', error);
  }
}

// Set up initial rendering and periodic updates
document.addEventListener('DOMContentLoaded', () => {
  const sidebarElement = document.getElementById('sidebar');
  renderSidebarMenu(menuConfig, sidebarElement);

  // Fetch updated menu every 10 minutes
  setInterval(() => fetchAndUpdateMenu('https://api.example.com/menu'), 600000);
});
