app.service('ConcurrencyService', ['$q', 'WebSocketService', function($q, WebSocketService) {
  var versionMap = {};

  this.updateData = function(resourceId, url) {
    return $q(function(resolve, reject) {
      WebSocketService.sendUpdate({ resourceId: resourceId, url: url })
        .then(function() {
          resolve();
        })
        .catch(function(error) {
          reject(error);
        });
    });
  };

  this.getVersionMap = function() {
    return versionMap;
  };
}]);

// Define a controller for handling dialog field updates
app.controller('DialogController', ['$scope', 'WebSocketService', 'APIService', 'CacheService', 'ConcurrencyService', '$q', function($scope, WebSocketService, APIService, CacheService, ConcurrencyService, $q) {
  var vm = this;

  vm.dialogFields = {};

  WebSocketService.onMessage(function(payload) {
    angular.forEach(payload, function(data) {
      if (vm.dialogFields[data.resourceId]) {
        updateDialogField(vm.dialogFields[data.resourceId], data.url);
      } else {
        fetchAndDisplayData(data.resourceId, data.url);
      }
    });
  });

  function updateDialogField(field, url) {
    APIService.fetchData(url)
      .then(function(data) {
        field.status = 'updated';
        field.data = data;
      })
      .catch(function(error) {
        field.status = 'error';
        field.error = error.message;
      });
  }

  function fetchAndDisplayData(resourceId, url) {
    var cachedData = CacheService.get(resourceId);

    if (cachedData) {
      displayCachedData(resourceId, cachedData);
    } else {
      APIService.fetchData(url)
        .then(function(data) {
          CacheService.put(resourceId, data);
          displayData(resourceId, data);
        })
        .catch(function(error) {
          handleFetchError(resourceId, error);
        });
