const express = require('express');
const http = require('http');
const WebSocket = require('ws');
const axios = require('axios');
const lruCache = require('lru-cache');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

const cache = lruCache({
  max: 500,
  maxAge: 1000 * 60 * 60, // 1 hour
  dispose: (key, n) => {
    console.log(`evicting ${key}`);
  }
});

wss.on('connection', async (ws) => {
  ws.on('message', async (message) => {
    const data = JSON.parse(message);
    try {
      const validatedData = await validateData(data);
      cache.set(validatedData.id, validatedData);
      ws.send(JSON.stringify(validatedData));
    } catch (error) {
      console.error(error);
      ws.send(JSON.stringify({ error: 'Data validation failed' }));
    }
  });
});

async function validateData(data) {
  const response = await axios.get('https://api.example.com/validate', { params: data });
  return response.data;
}

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
```

