#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>
#include <redis/redis.h>

#define API_URL "https://api.example.com/resource"
#define CACHE_KEY_PREFIX "resource:"
#define MAX_THREADS 100

typedef struct {
    CURL *curl;
    CURLcode res;
    char *data;
    size_t size;
} ResourceData;

void *fetch_resource(void *arg) {
    ResourceData *data = (ResourceData *)arg;
    data->data = malloc(1); // Start with a small buffer
    data->size = 0;

    CURL *curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, API_URL);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, data);

        do {
            data->data = realloc(data->data, data->size + 1024); // Increase buffer size
            data->res = curl_easy_perform(curl);
            if(data->res != CURLE_OK) {
                fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(data->res));
            }
        } while(data->res == CURLE_AGAIN);

        curl_easy_cleanup(curl);
    }

    return NULL;
}

size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    ResourceData *data = (ResourceData *)userdata;
    size_t total_size = size * nmemb;
    data->data[data->size] = '\0'; // Null-terminate the existing string
    data->data = realloc(data->data, data->size + total_size + 1); // Increase buffer size
    memcpy(&data->data[data->size], ptr, total_size);
    data->size += total_size;
    return total_size;
}

int main() {
    pthread_t threads[MAX_THREADS];
    ResourceData data[MAX_THREADS];

    for(int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, fetch_resource, &data[i]);
    }

    for(int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
        printf("Thread %d fetched resource: %s\n", i, data[i].data);
        free(data[i].data);
    }

    return 0;
}
```

