import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.*;
import java.util.function.Function;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class UserHashService {

    private final RateLimiter rateLimiter;
    private final ExecutorService executorService;
    private final ExternalMetadataProvider metadataProvider;

    public UserHashService(int maxThreads, int requestsPerSecond) {
        this.rateLimiter = RateLimiter.create(requestsPerSecond);
        this.executorService = Executors.newFixedThreadPool(maxThreads);
        this.metadataProvider = new ExternalMetadataProvider();
    }

    public void processUserIdentifiers(String[] userIdentifiers) {
        ConcurrentHashMap<String, String> results = new ConcurrentHashMap<>();

        CompletionService<String> completionService = new ExecutorCompletionService<>(executorService);

        for (String identifier : userIdentifiers) {
            if (rateLimiter.tryAcquire()) {
                completionService.submit(() -> {
                    try {
                        String userInfo = metadataProvider.getUserInfo(identifier);
                        return generateMD5Hash(userInfo);
                    } catch (Exception e) {
                        logError(e);
                        throw new RuntimeException("Failed to process user identifier: " + identifier, e);
                    }
                });
            } else {
                logWarning("Rate limit exceeded for user identifier: " + identifier);
            }
        }

        for (int i = 0; i < userIdentifiers.length; i++) {
            try {
                Future<String> future = completionService.take();
                results.put(future.get(), null);
            } catch (InterruptedException | ExecutionException e) {
                logError(e);
            }
        }

        // Process results
    }

    private String generateMD5Hash(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        BigInteger no = new BigInteger(1, messageDigest);
        StringBuilder hashtext = new StringBuilder(no.toString(16));

        while (hashtext.length() < 32) {
            hashtext.insert(0, "0");
        }
        return hashtext.toString();
    }

    private void logError(Exception e) {
        System.err.println("ERROR: " + e.getMessage());
    }

    private void logWarning(String message) {
        System.out.println("WARNING: " + message);
    }

    public static void main(String[] args) {
        UserHashService service = new UserHashService(10, 50);
        String[] userIdentifiers = {"user1", "user2", "user3", /* ... */};
        service.processUserIdentifiers(userIdentifiers);
    }
}

class RateLimiter {
    private final Semaphore semaphore;

    public RateLimiter(double permitsPerSecond) {
        this.semaphore = new Semaphore((int) (permitsPerSecond * 100));
        new Thread(() -> {
            try {
                while (true) {
                    Thread.sleep(100);
                    semaphore.release();
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }).start();
    }

    public boolean tryAcquire() {
        return semaphore.tryAcquire();
    }
}

class ExternalMetadataProvider {
    private static final int MAX_RETRIES = 3;
    private static final long RETRY_INTERVAL = 1000; // milliseconds

    public String getUserInfo(String identifier) throws Exception {
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            try {
                // Simulate external API call
                return "userInfoFor" + identifier;
            } catch (Exception e) {
                if (attempt == MAX_RETRIES - 1) {
                    throw e;
                }
                Thread.sleep(RETRY_INTERVAL);
            }
        }
        return null; // Unreachable due to retries
    }
}
```

