#include <pthread.h>
#include <semaphore.h>

#define MAX_UE 50000

typedef struct {
    int rnti;
    int crc_flag;
} UE_INFO;

typedef struct {
    UE_INFO ue_info[MAX_UE];
    sem_t semaphore;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_napi_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu) {
        sem_init(&pdu->semaphore, 0, MAX_UE);
        pthread_mutex_init(&pdu->mutex, NULL);
    }
    return pdu;
}

void destroy_napi_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu) {
        sem_destroy(&pdu->semaphore);
        pthread_mutex_destroy(&pdu->mutex);
        free(pdu);
    }
}

void add_ue_info(NFAPI_CRC_INDICATION_PDU_T* pdu, int rnti, int crc_flag) {
    pthread_mutex_lock(&pdu->mutex);
    if (sem_wait(&pdu->semaphore) == 0) {
        for (int i = 0; i < MAX_UE; i++) {
            if (pdu->ue_info[i].rnti == 0) {
                pdu->ue_info[i].rnti = rnti;
                pdu->ue_info[i].crc_flag = crc_flag;
                break;
            }
        }
    }
    pthread_mutex_unlock(&pdu->mutex);
}

void remove_ue_info(NFAPI_CRC_INDICATION_PDU_T* pdu, int rnti) {
    pthread_mutex_lock(&pdu->mutex);
    for (int i = 0; i < MAX_UE; i++) {
        if (pdu->ue_info[i].rnti == rnti) {
            pdu->ue_info[i].rnti = 0;
            pdu->ue_info[i].crc_flag = 0;
            sem_post(&pdu->semaphore);
            break;
        }
    }
    pthread_mutex_unlock(&pdu->mutex);
}

int validate_crc(NFAPI_CRC_INDICATION_PDU_T* pdu, int rnti) {
    for (int i = 0; i < MAX_UE; i++) {
        if (pdu->ue_info[i].rnti == rnti) {
            // Call external API for validation
            return 1; // Assume successful validation for demonstration
        }
    }
    return -1; // UE not found
}

void* process_packets(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)arg;
    while (1) {
        int rnti;
        pthread_mutex_lock(&pdu->mutex);
        if (sem_wait(&pdu->semaphore) == 0) {
            for (int i = 0; i < MAX_UE; i++) {
                if (pdu->ue_info[i].rnti != 0) {
                    rnti = pdu->ue_info[i].rnti;
                    break;
                }
            }
        } else {
            pthread_mutex_unlock(&pdu->mutex);
            continue;
        }
        pthread_mutex_unlock(&pdu->mutex);

        // Validate CRC
        int result = validate_crc(pdu, rnti);
        if (result == -1) {
            printf("CRC validation failed for RNTI %d\n", rnti);
        } else {
            printf("CRC validated successfully for RNTI %d\n", rnti);
        }
    }
    return NULL;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = create_napi_pdu();
    if (pdu) {
        // Add UE info
        add_ue_info(pdu, 12345, 0);
        add_ue_info(pdu, 67890, 1);

        // Create threads for processing packets
        pthread_t thread1, thread2;
        pthread_create(&thread1, NULL, process_packets, pdu);
        pthread_create(&thread2, NULL, process_packets, pdu);

        pthread_join(thread1, NULL);
        pthread_join(thread2, NULL);

        destroy_napi_pdu(pdu);
    }
    return 0;
}
```

