// Thread-safe function using mutex for concurrent requests
void *threaded_loadResourceBundle(void *arg) {
    const char *file_path = (const char *)arg;
    ResourceBundle *bundle;

    int result = loadResourceBundle(file_path, &bundle);
    if (result < 0) {
        printf("Failed to load resource bundle from %s\n", file_path);
    } else {
        printf("Loaded %d items from resource bundle at %s\n", result, file_path);
    }

    return NULL;
}

int main() {
