    pthread_t thread1, thread2;

    if (pthread_create(&thread1, NULL, threaded_loadResourceBundle, "path/to/bundle1.txt") != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    if (pthread_create(&thread2, NULL, threaded_loadResourceBundle, "path/to/bundle2.txt") != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return EXIT_SUCCESS;
}
