        }
        condition_.notify_one();
        if (worker_.joinable()) {
            worker_.join();
        }
    }

private:
    void processTransactions() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this] { return stop_ || !tasks_.empty(); });
            if (stop_ && tasks_.empty()) {
                break;
            }
            Transaction task = std::move(tasks_.front());
            tasks_.pop();
            lock.unlock();

            // Process transaction
            try {
                api_.updateTransaction(task);
                cache_.storeTransaction(task);
                broker_.sendMessage(task);
                metrics_.recordThroughput(1);
            } catch (const std::exception& e) {
                metrics_.recordError();
                std::cerr << "Error processing transaction: " << e.what() << std::endl;
            }
        }
    }

    FinancialAPI& api_;
    DistributedCache& cache_;
    MessageBroker& broker_;
    Metrics& metrics_;
    bool stop_;
    std::thread worker_;
    std::queue<Transaction> tasks_;
    mutable std::mutex mutex_;
    std::condition_variable condition_;
};

// Transaction class
