public:
    void start() {
        producerThread = std::thread(&SensorDataProcessor::produce, this);
        consumerThread = std::thread(&SensorDataProcessor::consume, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            running = false;
        }
        condition.notify_all();
        producerThread.join();
        consumerThread.join();
    }

private:
    void produce() {
        while (true) {
            // Simulate data production
            auto data = fetchDataFromIoTDevices();
            {
                std::unique_lock<std::mutex> lock(mutex);
                queue.push(data);
                condition.notify_one();
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
    }

    void consume() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !queue.empty() || !running; });
            if (!running && queue.empty()) break;
            auto data = queue.front();
            queue.pop();
            lock.unlock();

            // Process the data
            processData(data);

            lock.lock();
        }
    }

    std::vector<std::string> fetchDataFromIoTDevices() {
        // Simulate fetching data from IoT devices
        return {"JSON", "CSV", "Binary"};
    }

