public class HashService : IDisposable
{
    private readonly ConcurrentDictionary<string, string> _cache = new ConcurrentDictionary<string, string>();
    private readonly HttpClient _authClient = new HttpClient();
    private readonly ICircuitBreaker _circuitBreaker;
    private readonly ILogger _logger;
    private Timer _cacheInvalidationTimer;

    public HashService(ICircuitBreaker circuitBreaker, ILogger logger)
    {
        _circuitBreaker = circuitBreaker;
        _logger = logger;
        _cacheInvalidationTimer = new Timer(RecomputeStaleHashes, null, TimeSpan.FromMinutes(5), TimeSpan.FromMinutes(5));
    }

    public async Task<string> ComputeHashAsync(string input)
    {
        if (string.IsNullOrEmpty(input))
            throw new ArgumentException("Input cannot be null or empty.");

        return await _cache.GetOrAddAsync(input, async key =>
        {
            var hash = GetMd5Hash(key);
            try
            {
                using (var tokenSource = new CancellationTokenSource())
                {
                    var response = await _circuitBreaker.ExecuteWithCircuitBreaking(async () =>
                        await _authClient.GetAsync("https://api.auth.com/check", tokenSource.Token), _logger);

                    if (response.IsSuccessStatusCode)
                    {
                        // Role-based access control logic here
                    }
                    else
                    {
                        throw new Exception("Authentication failed.");
                    }
                }

                return hash;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error while computing or validating the hash.");
                throw;
            }
        });
    }

    private string GetMd5Hash(string input)
    {
        using (var md5 = MD5.Create())
        {
            var inputBytes = Encoding.UTF8.GetBytes(input);
            var hashBytes = md5.ComputeHash(inputBytes);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
        }
    }

    private void RecomputeStaleHashes(object state)
    {
        // Logic to recompute hashes for stale entries in the cache
    }

    public Task InvalidateCacheAsync(string input)
    {
        _cache.TryRemove(input, out _);
        return Task.CompletedTask;
    }

    protected virtual void Dispose(bool disposing)
    {
        if (disposing)
        {
            _authClient.Dispose();
            _cacheInvalidationTimer?.Change(Timeout.Infinite, 0);
        }
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
