using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;

public class DataManagementService
{
    private readonly IKmsClient _kmsClient;
    private readonly IMemoryCache _cache;
    private readonly AesGcm _aesGcm;

    public DataManagementService(IKmsClient kmsClient, IMemoryCache cache)
    {
        _kmsClient = kmsClient;
        _cache = cache;
        _aesGcm = new AesGcm();
    }

    public async Task<byte[]> EncryptDataAsync(string data, string keyId)
    {
        var key = await GetKeyFromKmsAsync(keyId);
        byte[] iv = GenerateIV();
        _aesGcm.Encrypt(iv, key.KeyBytes, key.IvBytes, out byte[] encryptedData);
        return encryptedData;
    }

    public async Task<string> DecryptDataAsync(byte[] encryptedData, string keyId)
    {
        var key = await GetKeyFromKmsAsync(keyId);
        _aesGcm.Decrypt(encryptedData, key.KeyBytes, key.IvBytes, out byte[] decryptedData);
        return Encoding.UTF8.GetString(decryptedData);
    }

    private async Task<Key> GetKeyFromKmsAsync(string keyId)
    {
        if (_cache.TryGetValue(keyId, out Key cachedKey))
        {
            return cachedKey;
        }

        var key = await _kmsClient.GetKeyAsync(keyId);
        _cache.Set(keyId, key, new MemoryCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(30)
        });

        return key;
    }

    private byte[] GenerateIV()
    {
        using (var rng = RandomNumberGenerator.Create())
        {
            var iv = new byte[_aesGcm.IVLength];
            rng.GetBytes(iv);
            return iv;
        }
    }
}

public class Key
{
    public byte[] KeyBytes { get; set; }
    public byte[] IvBytes { get; set; }
}

