// Define the microservice structure using Rust's ecosystem
use actix_web::{web, App, HttpResponse, HttpServer, Responder};
use reqwest::Client;
use std::sync::Mutex;

#[derive(Clone)]
struct WeatherService {
    client: Client,
}

impl WeatherService {
    fn new() -> Self {
        WeatherService {
            client: Client::new(),
        }
    }

    async fn get_weather(&self, city: &str) -> Result<String, reqwest::Error> {
        self.client
            .get(format!("https://api.weather.com/data/2.5/weather?q={}&units=metric", city))
            .send()
            .await?
            .json::<serde_json::Value>()
            .await?
            .to_string()
    }
}

struct AppState {
    weather_service: Mutex<WeatherService>,
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let weather_service = WeatherService::new();
    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(AppState {
                weather_service: Mutex::new(weather_service.clone()),
            }))
            .route("/weather/{city}", web::get().to(get_weather))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}

async fn get_weather(
    state: web::Data<AppState>,
    web::Path(city): web::Path<String>,
) -> impl Responder {
    let weather_service = &state.weather_service;
    match weather_service.lock().unwrap().get_weather(&city).await {
        Ok(weather_data) => HttpResponse::Ok().body(weather_data),
        Err(_) => HttpResponse::InternalServerError().finish(),
    }
}
```

