#include <vector>
#include <thread>
#include <atomic>
#include <future>
#include <memory>

class Task {
public:
    virtual ~Task() = default;
    virtual void run() = 0;
};

class AsyncTask : public Task {
public:
    AsyncTask(std::function<void()> func) : func_(func) {}
    void run() override { func_(); }
private:
    std::function<void()> func_;
};

class TaskManager {
public:
    void addTask(std::shared_ptr<Task> task) {
        tasks_.push_back(task);
        scheduleTasks();
    }

    void removeTask(std::shared_ptr<Task> task) {
        tasks_.erase(std::remove(tasks_.begin(), tasks_.end(), task), tasks_.end());
        scheduleTasks();
    }

private:
    std::vector<std::shared_ptr<Task>> tasks_;
    std::atomic<bool> running_{true};

    void scheduleTasks() {
        while (running_) {
            for (auto& task : tasks_) {
                std::future<void> future = std::async(std::launch::async, [task]() { task->run(); });
                // Handle the result or continue with the next task
            }
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    }
};

int main() {
    TaskManager manager;
    manager.addTask(std::make_shared<AsyncTask>([]() {
        std::cout << "Executing task" << std::endl;
    }));
    // Add more tasks or perform other operations
    return 0;
}
