import logging
from concurrent.futures import ThreadPoolExecutor
from queue import Queue, Empty
from time import monotonic

class LogEvent:
    def __init__(self, message, level):
        self.message = message
        self.level = level

class Logger:
    def __init__(self, services):
        self.services = services
        self.executor = ThreadPoolExecutor(max_workers=len(services))
        self.queue = Queue()

    def log(self, event: LogEvent):
        for service in self.services:
            self.executor.submit(service.log_event, event)

class ThirdPartyService:
    def __init__(self, name):
        self.name = name

    def log_event(self, event: LogEvent):
        # Simulate network delay and potential failures
        if self.name == 'SlowService':
            raise Exception("Network failure")
        print(f"Logging to {self.name}: {event.message}")

class LoggingFramework:
    def __init__(self, services, max_queue_size=10000):
        self.logger = Logger(services)
        self.queue = Queue(maxsize=max_queue_size)

    def log(self, message: str, level: int):
        event = LogEvent(message, level)
        try:
            self.queue.put_nowait(event)
        except Full:
            print("Log queue is full. Event dropped.")

    def start_processing(self):
        while True:
            try:
                event = self.queue.get(timeout=1)
                self.logger.log(event)
            except Empty:
                break

# Example usage
services = [ThirdPartyService('FastService'), ThirdPartyService('SlowService')]
framework = LoggingFramework(services)

# Simulate log events
for i in range(10):
    framework.log(f"Log event {i}", 20)  # Log level 20 is INFO

# Start processing logs
framework.start_processing()
