using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public abstract class DynamicRangeGenerator<T> where T : IComparable<T>
{
    private readonly Random _random = new Random();
    private T _minValue;
    private T _maxValue;
    private DateTime? _lastLogTime;
    private int _logFrequency;
    private string _logFilePath;
    private bool _enableLogging;

    protected DynamicRangeGenerator(T minValue, T maxValue, int logFrequency = 10, string logFilePath = "log.txt", bool enableLogging = true)
    {
        if (minValue.CompareTo(maxValue) >= 0)
        {
            throw new ArgumentException("Min value must be less than max value.");
        }

        _minValue = minValue;
        _maxValue = maxValue;
        _logFrequency = logFrequency;
        _logFilePath = logFilePath;
        _enableLogging = enableLogging;
    }

    public T GenerateRandomNumber()
    {
        var randomNumber = GenerateRandom();
        Log(randomNumber);
        return randomNumber;
    }

    private T GenerateRandom()
    {
        if (typeof(T) == typeof(double) || typeof(T) == typeof(float))
        {
            return (T)(object)_random.NextDouble() * (_maxValue.ToNullable<double>() - _minValue.ToNullable<double>()) + _minValue.ToNullable<double>();
        }
        else
        {
            var range = Convert.ToInt64(_maxValue) - Convert.ToInt64(_minValue);
            return (T)(object)(_random.Next(range + 1) + Convert.ToInt64(_minValue));
        }
    }

    private void Log(T randomNumber)
    {
        if (!_enableLogging || _lastLogTime.HasValue && DateTime.Now.Subtract(_lastLogTime.Value).TotalSeconds < _logFrequency)
        {
            return;
        }

        using (var writer = new System.IO.StreamWriter(_logFilePath, true))
        {
            writer.WriteLine($"{DateTime.Now}: {randomNumber}");
        }
        _lastLogTime = DateTime.Now;
    }

    private static T ToNullable<T>(T value) where T : struct
    {
        return value.Equals(default(T)) ? (default(T?)).Value : value;
    }
}
