{
    private readonly Func<Random, T, T, T> _randomNumberGenerator;
    private T _minValue;
    private T _maxValue;

    public DynamicRangeGenerator(Func<Random, T, T, T> randomNumberGenerator, T minValue, T maxValue)
    {
        if (minValue.CompareTo(maxValue) >= 0)
            throw new ArgumentException("Minimum value must be less than maximum value.");

        _randomNumberGenerator = randomNumberGenerator;
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public T GenerateRandom()
    {
        using (var rng = new Random())
        {
            return _randomNumberGenerator(rng, _minValue, _maxValue);
        }
    }

    public void SetRange(T minValue, T maxValue)
    {
        if (minValue.CompareTo(maxValue) >= 0)
            throw new ArgumentException("Minimum value must be less than maximum value.");

        _minValue = minValue;
        _maxValue = maxValue;
    }
