// Define a thread-safe queue for message passing
template <typename T>
class ThreadSafeQueue {
public:
    void enqueue(T value) {
        std::unique_lock<std::mutex> lock(mutex);
        queue.push(value);
        condition.notify_one();
    }

    T dequeue() {
        std::unique_lock<std::mutex> lock(mutex);
        condition.wait(lock, [this] { return !queue.empty(); });
        T value = queue.front();
        queue.pop();
        return value;
    }

private:
    std::queue<T> queue;
    std::mutex mutex;
    std::condition_variable condition;
};

