        int count = 0;
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(1));
            std::string message = "Message " + std::to_string(++count);
            messageQueue.enqueue(message);
        }
    };

    // Function to simulate message consumer
    auto consumer = [&messageQueue]() {
        while (true) {
            std::string message = messageQueue.dequeue();
            processMessage(message);
        }
    };

    // Create threads for producer and consumer
    std::thread producerThread(producer);
    std::thread consumerThread(consumer);

    // Join threads to prevent program from exiting immediately
    producerThread.join();
    consumerThread.join();

    return 0;
}
