// nfaip_crc_indication_pdu_pool.c
#include "nfaip_crc_indication_pdu_pool.h"

int nfaip_crc_indication_pdu_pool_init(NFAPI_CRC_INDICATION_PDU_POOL_T* pool, size_t max_size) {
    pool->pool = (NFAPI_CRC_INDICATION_PDU_T**)malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pool->pool) return -1;

    pool->size = max_size;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return 0;
}

void nfaip_crc_indication_pdu_pool_destroy(NFAPI_CRC_INDICATION_PDU_POOL_T* pool) {
    for (size_t i = 0; i < pool->count; i++) {
        free(pool->pool[i]);
    }
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
}

int nfaip_crc_indication_pdu_enqueue(NFAPI_CRC_INDICATION_PDU_POOL_T* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count >= pool->size) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Pool is full
    }

    pool->pool[pool->count++] = pdu;
    pthread_mutex_unlock(&pool->lock);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* nfaip_crc_indication_pdu_dequeue(NFAPI_CRC_INDICATION_PDU_POOL_T* pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count == 0) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool is empty
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = pool->pool[--pool->count];
    pthread_mutex_unlock(&pool->lock);

    return pdu;
}
