typedef struct {
    NetworkEvent *events;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} EventQueue;

void event_queue_init(EventQueue *queue, size_t initial_capacity) {
    queue->capacity = initial_capacity;
    queue->count = 0;
    queue->events = (NetworkEvent *)malloc(initial_capacity * sizeof(NetworkEvent));
    pthread_mutex_init(&queue->mutex, NULL);
}

void event_queue_push(EventQueue *queue, NetworkEvent event) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->count == queue->capacity) {
        size_t new_capacity = queue->capacity * 2;
        queue->events = realloc(queue->events, new_capacity * sizeof(NetworkEvent));
        queue->capacity = new_capacity;
    }
    queue->events[queue->count++] = event;
    pthread_mutex_unlock(&queue->mutex);
}

void event_queue_destroy(EventQueue *queue) {
    free(queue->events);
    pthread_mutex_destroy(&queue->mutex);
}

