NFAPI_CRC_INDICATION_PDU_T* parseJsonFile(const char* filePath, int* errorCode) {
    // Simulate parsing logic
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        *errorCode = -1;
        return NULL;
    }
    // Populate pdu with data from JSON file
    return pdu;
}

void generateOutputFileName(const char* inputFileName, char* outputFileName) {
    sprintf(outputFileName, "%.*s%s", (int)(strlen(inputFileName) - strlen(JSON_FILE_TYPE)), inputFileName, OUTPUT_FILE_TYPE);
}

void processFile(void* arg) {
    char* filePath = (char*)arg;
    int errorCode = 0;
    NFAPI_CRC_INDICATION_PDU_T* pdu = parseJsonFile(filePath, &errorCode);

    if (!pdu) {
        logError("Failed to parse JSON file.");
        return;
    }

    char outputFileName[MAX_FILENAME_LENGTH];
    generateOutputFileName(filePath, outputFileName);

    FILE* outputFile = fopen(outputFileName, "w");
    if (!outputFile) {
        logError("Failed to open output file.");
        free(pdu);
        return;
    }

    // Simulate writing pdu to output file
    fprintf(outputFile, "{ \"RX_UE_INFORMATION_TAG\": %d, \"RNTI\": %d, \"CRC_INDICATION_REL8_TAG\": %d }\n", 
            pdu->ueInfo, pdu->rnti, pdu->crcTag);

    fclose(outputFile);
    free(pdu);
}

void generateNfadlIndications(const char* directoryPath) {
    DIR* dir;
    struct dirent* ent;

    if ((dir = opendir(directoryPath)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_type, DT_REG) == 0 && strstr(ent->d_name, JSON_FILE_TYPE) != NULL) {
                char filePath[MAX_FILENAME_LENGTH];
                snprintf(filePath, MAX_FILENAME_LENGTH, "%s/%s", directoryPath, ent->d_name);

                pthread_t thread;
                pthread_create(&thread, NULL, processFile, strdup(filePath));
                pthread_detach(thread); // Detach the thread to allow for concurrent processing
            }
        }
        closedir(dir);
    } else {
        logError("Failed to open directory.");
    }
}

// Example usage
int main() {
    generateNfadlIndications("/path/to/json/files");
    return 0;
}
