#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 1024

typedef struct {
    int id;
    time_t timestamp;
    unsigned char *payload;
} DataPacket;

typedef struct {
    DataPacket **pool;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} PacketPool;

PacketPool* create_packet_pool(size_t initial_capacity) {
    PacketPool *pool = malloc(sizeof(PacketPool));
    if (!pool) return NULL;

    pool->capacity = initial_capacity;
    pool->count = 0;
    pool->pool = malloc(initial_capacity * sizeof(DataPacket *));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->mutex, NULL);

    for (size_t i = 0; i < initial_capacity; ++i) {
        pool->pool[i] = NULL;
    }

    return pool;
}

void destroy_packet_pool(PacketPool *pool) {
    for (size_t i = 0; i < pool->capacity; ++i) {
        if (pool->pool[i]) {
            free(pool->pool[i]->payload);
            free(pool->pool[i]);
        }
    }
    pthread_mutex_destroy(&pool->mutex);
    free(pool->pool);
    free(pool);
}

int allocate_packet(PacketPool *pool, DataPacket **packet) {
    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < pool->capacity; ++i) {
        if (!pool->pool[i]) {
            pool->pool[i] = malloc(sizeof(DataPacket));
            if (!pool->pool[i]) {
                pthread_mutex_unlock(&pool->mutex);
                return -1;
            }
            pool->pool[i]->id = (int)i;
            pool->pool[i]->timestamp = time(NULL);
            pool->pool[i]->payload = malloc(MAX_PACKET_SIZE);
            if (!pool->pool[i]->payload) {
                free(pool->pool[i]);
                pthread_mutex_unlock(&pool->mutex);
                return -1;
            }
            random_fill_payload(pool->pool[i]->payload, MAX_PACKET_SIZE);
            *packet = pool->pool[i];
            pthread_mutex_unlock(&pool->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
    return -1; // Pool is full
}

void free_packet(PacketPool *pool, DataPacket *packet) {
    for (size_t i = 0; i < pool->capacity; ++i) {
        if (pool->pool[i] == packet) {
            pthread_mutex_lock(&pool->mutex);
            free(packet->payload);
            free(pool->pool[i]);
            pool->pool[i] = NULL;
            pthread_mutex_unlock(&pool->mutex);
            break;
        }
    }
}

void random_fill_payload(unsigned char *payload, size_t size) {
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        payload[i] = rand() % 256;
    }
}
```

This code snippet provides a basic structure for managing a pool of `DataPacket` structures in C. It includes functions to create and destroy the packet pool, allocate and free packets, and fill payloads with random data. The implementation uses mutexes for thread-safe operations and dynamic memory allocation for payloads. Error handling is minimal but covers basic scenarios such as insufficient memory or invalid operations.']

