#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_THREADS 10

typedef struct {
    int timestamp;
    int event_code;
    union {
        int data_int;
        char* data_str;
        float data_float;
    } context;
} NetworkEvent;

NetworkEvent log_buffer[MAX_THREADS];
int buffer_index = 0;
sem_t buffer_mutex, log_queue;
pthread_cond_t new_log_available;

void* thread_function(void* arg) {
    int thread_id = *(int*)arg;
    while (1) {
        sem_wait(&log_queue);
        pthread_mutex_lock(&buffer_mutex);
        if (buffer_index > 0) {
            NetworkEvent event = log_buffer[0];
            for (int i = 1; i < buffer_index; i++) {
                log_buffer[i - 1] = log_buffer[i];
            }
            buffer_index--;
            printf("Thread %d processed: timestamp=%d, event_code=%d, context.data_int=%d\n",
                   thread_id, event.timestamp, event.event_code, event.context.data_int);
        }
        pthread_mutex_unlock(&buffer_mutex);
    }
}

int main() {
    pthread_t threads[MAX_THREADS];
    int thread_ids[MAX_THREADS];

    sem_init(&buffer_mutex, 0, 1);
    sem_init(&log_queue, 0, 0);
    pthread_cond_init(&new_log_available, NULL);

    for (int i = 0; i < MAX_THREADS; i++) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, thread_function, &thread_ids[i]);
    }

    // Simulate logging events
    for (int i = 0; i < 100; i++) {
        pthread_mutex_lock(&buffer_mutex);
        if (buffer_index >= MAX_THREADS) {
            printf("Log buffer full, waiting...\n");
            sem_wait(&log_queue);
        }
        log_buffer[buffer_index].timestamp = i;
        log_buffer[buffer_index].event_code = 100 + i % 50;
        log_buffer[buffer_index].context.data_int = rand();
        buffer_index++;
        pthread_mutex_unlock(&buffer_mutex);
        sem_post(&log_queue);
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&buffer_mutex);
    sem_destroy(&log_queue);
    pthread_cond_destroy(&new_log_available);

    return 0;
}
