void initializeLogQueue(size_t initialCapacity) {
    logQueue.events = malloc(initialCapacity * sizeof(NetworkEvent));
    if (logQueue.events == NULL) {
        fprintf(stderr, "Failed to allocate memory for event queue\n");
        exit(EXIT_FAILURE);
    }
    logQueue.count = 0;
    logQueue.capacity = initialCapacity;
    pthread_mutex_init(&logQueue.lock, NULL);
}

void enqueueEvent(const NetworkEvent *event) {
    pthread_mutex_lock(&logQueue.lock);
    if (logQueue.count == logQueue.capacity) {
        size_t newCapacity = logQueue.capacity * 2;
        NetworkEvent *newEvents = realloc(logQueue.events, newCapacity * sizeof(NetworkEvent));
        if (newEvents == NULL) {
            fprintf(stderr, "Failed to reallocate memory for event queue\n");
            exit(EXIT_FAILURE);
        }
        logQueue.events = newEvents;
        logQueue.capacity = newCapacity;
    }
    logQueue.events[logQueue.count++] = *event;
    pthread_mutex_unlock(&logQueue.lock);
}

void processEvents() {
    while (1) {
        NetworkEvent event;
        pthread_mutex_lock(&logQueue.lock);
        if (logQueue.count > 0) {
            event = logQueue.events[--logQueue.count];
        } else {
            pthread_mutex_unlock(&logQueue.lock);
            continue;
        }
        pthread_mutex_unlock(&logQueue.lock);

        // Simulate sending the event to an external service
        sendEventToExternalService(event);
    }
}

