#include <iostream>
#include <vector>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <queue>
#include <unordered_map>
#include <memory>
#include <future>

class DistributedFileIndexer {
public:
    void addDocument(const std::string& documentId, const std::string& content) {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            documents_[documentId] = content;
        }
        updateQueue_.push(documentId);
    }

    void removeDocument(const std::string& documentId) {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            documents_.erase(documentId);
        }
        updateQueue_.push(documentId);
    }

    bool search(const std::string& query, std::vector<std::string>& results) {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this] { return !indexingInProgess_; });
        indexingInProgess_ = true;
        lock.unlock();

        // Simulate search logic
        for (const auto& doc : documents_) {
            if (doc.second.find(query) != std::string::npos) {
                results.push_back(doc.first);
            }
        }

        lock.lock();
        indexingInProgess_ = false;
        cv_.notify_all();
        return !results.empty();
    }

private:
    void indexerThread() {
        while (true) {
            std::string documentId;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                updateQueue_.wait(lock, [this] { return !updateQueue_.empty(); });
                documentId = updateQueue_.front();
                updateQueue_.pop();
            }

            // Simulate indexing logic
            if (documents_.find(documentId) != documents_.end()) {
                std::cout << "Indexing document: " << documentId << std::endl;
            } else {
                std::cout << "Removing index for document: " << documentId << std::endl;
            }
        }
    }

    std::unordered_map<std::string, std::string> documents_;
    std::queue<std::string> updateQueue_;
    std::mutex mutex_;
    std::condition_variable cv_;
    std::atomic<bool> indexingInProgess_{false};

    std::thread indexerThread_;
};

int main() {
    DistributedFileIndexer indexer;
    indexer.indexerThread_ = std::thread(&DistributedFileIndexer::indexerThread, &indexer);

    // Simulate adding and removing documents
    indexer.addDocument("doc1", "This is a sample document.");
    indexer.removeDocument("doc2");

    std::vector<std::string> results;
    if (indexer.search("sample", results)) {
        for (const auto& docId : results) {
            std::cout << "Found document: " << docId << std::endl;
        }
    } else {
        std::cout << "No documents found." << std::endl;
    }

    indexer.indexerThread_.join();
    return 0;
}
