#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <chrono>
#include <functional>

// Define Transaction structure
struct Transaction {
    std::chrono::system_clock::time_point timestamp;
    int id;
    std::string accountDetails;
    std::string type;
    double amount;
};

// Custom memory pool allocator for small objects
class MemoryPool {
public:
    MemoryPool(size_t objectSize, size_t initialCapacity)
        : objectSize(objectSize), freeList(initialCapacity) {
        for (size_t i = 0; i < initialCapacity; ++i) {
            freeList.push(new char[objectSize]);
        }
    }

    ~MemoryPool() {
        while (!freeList.empty()) {
            delete[] freeList.front();
            freeList.pop();
        }
    }

    void* allocate() {
        if (freeList.empty()) {
            // Expand pool if needed
            return new char[objectSize];
        }
        void* ptr = freeList.front();
        freeList.pop();
        return ptr;
    }

    void deallocate(void* ptr) {
        freeList.push(static_cast<char*>(ptr));
    }

private:
    size_t objectSize;
    std::queue<void*> freeList;
};

// Batch Processor class
class BatchProcessor {
public:
    BatchProcessor(size_t batchSize, std::chrono::milliseconds interval, MemoryPool& pool)
        : batchSize(batchSize), interval(interval), memoryPool(pool) {}

    void addTransaction(const Transaction& transaction) {
        std::lock_guard<std::mutex> lock(mutex);
        transactions.push(transaction);
        if (transactions.size() >= batchSize || stopProcessing) {
            processBatch();
        }
    }

    void startProcessing() {
        processingThread = std::thread(&BatchProcessor::processLoop, this);
    }

    void stopProcessing() {
        {
            std::lock_guard<std::mutex> lock(mutex);
            stopProcessing = true;
        }
        condition.notify_all();
        if (processingThread.joinable()) {
            processingThread.join();
        }
    }

private:
    size_t batchSize;
    std::chrono::milliseconds interval;
    MemoryPool& memoryPool;
    std::queue<Transaction> transactions;
    std::mutex mutex;
    std::condition_variable condition;
    bool stopProcessing = false;
    std::thread processingThread;

    void processBatch() {
        std::vector<void*> batchMemory(batchSize);
        try {
            for (size_t i = 0; i < batchSize && !transactions.empty(); ++i) {
                Transaction transaction = transactions.front();
                transactions.pop();

                // Allocate memory from pool
                batchMemory[i] = memoryPool.allocate();
                new(batchMemory[i]) Transaction(transaction); // Placement new to construct object in allocated memory

                // Perform validation and transformation here (omitted for brevity)
            }

            // Forward batch to trading platform (simulated with a simple print statement)
            for (size_t i = 0; i < batchSize && !batchMemory.empty(); ++i) {
                Transaction* transaction = static_cast<Transaction*>(batchMemory[i]);
                std::cout << "Forwarding transaction: ID=" << transaction->id << ", Amount=" << transaction->amount << std::endl;
                memoryPool.deallocate(batchMemory[i]); // Deallocate memory after forwarding
            }
        } catch (...) {
            // Handle errors (e.g., retry mechanism)
            for (size_t i = 0; i < batchSize && !batchMemory.empty(); ++i) {
                memoryPool.deallocate(batchMemory[i]); // Ensure all allocated memory is freed
            }
        }

        condition.notify_all();
    }

    void processLoop() {
        while (!stopProcessing || !transactions.empty()) {
            std::unique_lock<std::mutex> lock(mutex);
            if (transactions.empty() && !stopProcessing) {
                condition.wait_for(lock, interval);
            } else {
                processBatch();
            }
        }
    }
};

int main() {
    MemoryPool memoryPool(sizeof(Transaction), 10000); // Initial capacity of 10000 transactions
    BatchProcessor processor(10000, std::chrono::milliseconds(500), memoryPool);

    // Simulate adding transactions
    for (int i = 1; i <= 20000; ++i) {
        Transaction transaction{
            std::chrono::system_clock::now(),
            i,
            "Account" + std::to_string(i % 100),
            "Type" + std::to_string(i % 3),
            static_cast<double>(i)
        };
        processor.addTransaction(transaction);
    }

    processor.startProcessing();
    // Simulate application running for a while
    std::this_thread::sleep_for(std::chrono::seconds(5));
    processor.stopProcessing();

    return 0;
}
