typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int queueSize;
    NetworkEvent *queue;
} LogQueue;

void initLogQueue(LogQueue *queue, int size) {
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
    queue->queueSize = 0;
    queue->queue = (NetworkEvent *)malloc(size * sizeof(NetworkEvent));
}

void enqueueEvent(LogQueue *queue, NetworkEvent event) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->queueSize == MAX_QUEUE_SIZE) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }
    queue->queue[queue->queueSize++] = event;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
}

NetworkEvent dequeueEvent(LogQueue *queue) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->queueSize == 0) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }
    NetworkEvent event = queue->queue[--queue->queueSize];
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
    return event;
}

void *logProcessorThread(void *arg) {
    LogQueue *queue = (LogQueue *)arg;
    while (1) {
        NetworkEvent event = dequeueEvent(queue);
        processEvent(event); // Assume this function is implemented elsewhere
    }
}

