#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

// Define the event structure with a flexible union for various data types
typedef enum { LOG_INFO, LOG_ERROR } LogType;
union LogContext {
    int intValue;
    double doubleValue;
    char stringValue[256];
};
typedef struct {
    time_t timestamp;
    LogType type;
    union LogContext context;
} NetworkEvent;

// Define the logging framework structure
typedef struct {
    pthread_mutex_t lock;
    FILE *logFile;
} LoggingFramework;

// Initialize the logging framework
void initLoggingFramework(LoggingFramework *framework, const char *filename) {
    pthread_mutex_init(&framework->lock, NULL);
    framework->logFile = fopen(filename, "a");
}

// Log a network event to the framework
void logEvent(LoggingFramework *framework, NetworkEvent *event) {
    pthread_mutex_lock(&framework->lock);
    fprintf(framework->logFile, "%ld %d ", (long)event->timestamp, event->type);
    switch (event->type) {
        case LOG_INFO:
            fprintf(framework->logFile, "%d\n", event->context.intValue);
            break;
        case LOG_ERROR:
            fprintf(framework->logFile, "%.2f\n", event->context.doubleValue);
            break;
        default:
            fprintf(framework->logFile, "%s\n", event->context.stringValue);
            break;
    }
    fflush(framework->logFile);
    pthread_mutex_unlock(&framework->lock);
}

// Clean up the logging framework
void cleanupLoggingFramework(LoggingFramework *framework) {
    pthread_mutex_destroy(&framework->lock);
    fclose(framework->logFile);
}
```

