        return std::async(std::launch::async, [userId]() -> std::string {
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            return "User data for ID: " + std::to_string(userId);
        });
    }
};

class ProductAPI {
public:
    std::future<std::string> getProductData(int productId) {
        // Simulate async operation
        return std::async(std::launch::async, [productId]() -> std::string {
            std::this_thread::sleep_for(std::chrono::milliseconds(150));
            return "Product data for ID: " + std::to_string(productId);
        });
    }
};

// Error handling and retry mechanism
class RetryStrategy {
public:
    static std::string executeWithRetry(std::function<std::future<std::string>()> task, int maxRetries = 3) {
        for (int attempt = 0; attempt < maxRetries; ++attempt) {
            try {
                auto resultFuture = task();
                return resultFuture.get();
            } catch (...) {
                if (attempt == maxRetries - 1) throw;
                std::this_thread::sleep_for(std::chrono::milliseconds(50));
            }
        }
        throw std::runtime_error("Max retries exceeded");
    }
};

// Circuit breaker
class CircuitBreaker {
public:
    static std::string executeWithCircuitBreaker(std::function<std::future<std::string>()> task, double failureThreshold = 0.5) {
        if (failureCount / totalAttempts >= failureThreshold) {
            throw std::runtime_error("Circuit breaker open");
        }
        try {
            auto resultFuture = task();
            return resultFuture.get();
        } catch (...) {
            ++failureCount;
            ++totalAttempts;
            throw;
        }
    }

private:
    static int failureCount;
    static int totalAttempts;
};

int CircuitBreaker::failureCount = 0;
int CircuitBreaker::totalAttempts = 0;

// Back-pressure technique
class BackPressureController {
public:
    static void adjustConcurrencyLevel(int currentLoad, int availableResources) {
        if (currentLoad > availableResources) {
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }
};

// Logging and metrics
void logRequestDuration(std::string requestType, double durationMs) {
    std::cout << "Request type: " << requestType << ", Duration: " << durationMs << "ms" << std::endl;
}

// Configuration options
struct Config {
    int maxConcurrentRequests = 10;
    // Add more configuration options here
};

// Main application logic
void aggregateUserData(int userId, int productId, const Config& config) {
    UserAPI userAPI;
    ProductAPI productAPI;

    auto start = std::chrono::high_resolution_clock::now();

    auto userDataFuture = CircuitBreaker::executeWithCircuitBreaker(
        [&userAPI, userId]() { return RetryStrategy::executeWithRetry([&userAPI, userId] { return userAPI.getUserData(userId); }); },
        0.3
    );

    auto productDataFuture = CircuitBreaker::executeWithCircuitBreaker(
        [&productAPI, productId]() { return RetryStrategy::executeWithRetry([&productAPI, productId] { return productAPI.getProductData(productId); }); },
        0.4
    );

    BackPressureController::adjustConcurrencyLevel(userDataFuture.wait_for(std::chrono::milliseconds(1)), config.maxConcurrentRequests);

    auto userData = userDataFuture.get();
    auto productData = productDataFuture.get();

    logRequestDuration("User Data", std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::high_resolution_clock::now() - start).count());
    logRequestDuration("Product Data", std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::high_resolution_clock::now() - start).count());

    std::cout << "Aggregated data: " << userData << ", " << productData << std::endl;
}

int main() {
    Config config = {10}; // Load configuration from environment variables, command-line arguments, or YAML file
    aggregateUserData(1, 2, config);
    return 0;
}
