import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class UserHashService {

    private final ExecutorService executorService = Executors.newCachedThreadPool();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private final RateLimiter rateLimiter = new RateLimiter(50, TimeUnit.SECONDS);
    private final ExternalMetadataProvider metadataProvider;
    private final Logger logger;

    public UserHashService(ExternalMetadataProvider metadataProvider, Logger logger) {
        this.metadataProvider = metadataProvider;
        this.logger = logger;
    }

    public CompletableFuture<String> hashUser(String userId) {
        if (!rateLimiter.tryAcquire()) {
            return CompletableFuture.failedFuture(new RateLimitException("Rate limit exceeded"));
        }

        return CompletableFuture.supplyAsync(() -> {
            try {
                String userInfo = metadataProvider.getUserInfo(userId);
                return generateSHA256Hash(userInfo);
            } catch (APIUnavailableException e) {
                logger.logError("Metadata provider is unavailable", e);
                return null;
            } catch (Exception e) {
                logger.logError("Failed to hash user ID", e);
                return null;
            }
        }, executorService)
        .exceptionally(ex -> {
            rateLimiter.release();
            logger.logError("Hash generation failed", ex);
            return null;
        });
    }

    private String generateSHA256Hash(String input) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public void shutdown() {
        executorService.shutdown();
        scheduler.shutdown();
    }

    private static class RateLimiter {
        private final int maxRequests;
        private final long timeUnit;
        private final ScheduledExecutorService scheduler;
        private volatile int requestCount = 0;

        public RateLimiter(int maxRequests, TimeUnit timeUnit) {
            this.maxRequests = maxRequests;
            this.timeUnit = timeUnit.toMillis();
            this.scheduler = Executors.newScheduledThreadPool(1);
            scheduleReset();
        }

        public boolean tryAcquire() {
            if (requestCount < maxRequests) {
                requestCount++;
                return true;
            }
            return false;
        }

        private void release() {
            requestCount--;
        }

        private void scheduleReset() {
            scheduler.schedule(this::reset, timeUnit, TimeUnit.MILLISECONDS);
        }

        private void reset() {
            requestCount = 0;
            scheduleReset();
        }

        public static class RateLimitException extends RuntimeException {
            public RateLimitException(String message) {
                super(message);
            }
        }
    }

    private interface ExternalMetadataProvider {
        String getUserInfo(String userId) throws APIUnavailableException;
    }

    private static class APIUnavailableException extends Exception {
        public APIUnavailableException() {
            super("External metadata provider is unavailable");
        }
    }

    private interface Logger {
        void logError(String message, Throwable ex);
    }
}
