// C# DynamicRangeGenerator class

using System;
using System.Collections.Generic;
using System.Linq;

public class DynamicRangeGenerator<T> where T : IComparable<T>
{
    private Random random;
    private List<(T start, T end)> ranges;

    public DynamicRangeGenerator(T seed) {
        random = new Random(seed.GetHashCode());
        ranges = new List<(T start, T end)>();
    }

    public void AddRange(T start, T end) {
        ranges.Add((start, end));
    }

    public T GenerateRandomValue() {
        if (ranges.Count == 0) throw new InvalidOperationException("No ranges added.");

        var range = SelectRandomRange();
        return GenerateRandomValueInRange(range);
    }

    private (T start, T end) SelectRandomRange() {
        return random.Next(ranges.Count);
    }

    private T GenerateRandomValueInRange((T start, T end) range) {
        // Implementation details here
        return default(T);
    }
}

// Example usage
public class Program
{
    public static void Main() {
        var generator = new DynamicRangeGenerator<int>(12345);
        generator.AddRange(10, 20);
        generator.AddRange(30, 40);

        int randomValue = generator.GenerateRandomValue();
        Console.WriteLine("Generated Random Value: " + randomValue);
