import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class DataProcessor {
    private static final Logger logger = LoggerFactory.getLogger(DataProcessor.class);
    private ObjectMapper objectMapper;
    private ExecutorService executorService;
    private int concurrencyLevel;

    public DataProcessor(int concurrencyLevel) {
        this.concurrencyLevel = concurrencyLevel;
        this.objectMapper = new ObjectMapper();
        this.executorService = Executors.newFixedThreadPool(concurrencyLevel);
    }

    public <T> T deserialize(byte[] binaryData, Class<T> clazz) throws Exception {
        return objectMapper.readValue(binaryData, clazz);
    }

    public void processAsync(byte[] binaryData, Class<?> clazz, DeserializationCallback callback) {
        executorService.submit(() -> {
            try {
                Object result = deserialize(binaryData, clazz);
                callback.onSuccess(result);
            } catch (Exception e) {
                logger.error("Deserialization failed", e);
                callback.onError(e);
            }
        });
    }

    public void shutdown() throws InterruptedException {
        executorService.shutdown();
        executorService.awaitTermination(1, TimeUnit.MINUTES);
    }

    @FunctionalInterface
    public interface DeserializationCallback {
        void onSuccess(Object result);
        void onError(Exception error);
    }
}
