#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <chrono>

class Message {
public:
    std::string id;
    std::string payload;
    std::string metadata;
    std::string reply_channel;

    Message(std::string id, std::string payload, std::string metadata = "", std::string reply_channel = "")
        : id(id), payload(payload), metadata(metadata), reply_channel(reply_channel) {}
};

class MessageBroker {
private:
    std::vector<std::queue<Message>> queues;
    std::mutex mutex;
    std::condition_variable cond_var;

public:
    void addQueue(int queue_id) {
        std::lock_guard<std::mutex> lock(mutex);
        queues.push_back(std::queue<Message>());
    }

    void publishMessage(int queue_id, const Message& message) {
        std::lock_guard<std::mutex> lock(mutex);
        if (queue_id < 0 || queue_id >= queues.size()) {
            throw std::runtime_error("Invalid queue ID");
        }
        queues[queue_id].push(message);
        cond_var.notify_one();
    }

    void subscribeAndProcess(int queue_id) {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cond_var.wait(lock, [this, queue_id] { return !queues[queue_id].empty(); });
            Message message = queues[queue_id].front();
            queues[queue_id].pop();
            lock.unlock();

            // Process the message
            std::cout << "Processing message: ID=" << message.id << ", Payload=" << message.payload << std::endl;
        }
    }

    void start(int num_queues) {
        for (int i = 0; i < num_queues; ++i) {
            addQueue(i);
            std::thread(&MessageBroker::subscribeAndProcess, this, i).detach();
        }
    }
};

int main() {
    MessageBroker broker;
    broker.start(5);

    // Simulate publishing messages
    for (int i = 0; i < 10; ++i) {
        broker.publishMessage(i % 5, Message("ID" + std::to_string(i), "Payload" + std::to_string(i)));
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }

    return 0;
}
