import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

public class ScalableCachingLayer {
    private final ConcurrentHashMap<String, CacheEntry> cache = new ConcurrentHashMap<>();
    private final AtomicLong requestCount = new AtomicLong(0);
    private final AtomicLong hitCount = new AtomicLong(0);

    public Object get(String key) {
        requestCount.incrementAndGet();
        return cache.computeIfPresent(key, (k, v) -> {
            if (v.isExpired()) {
                hitCount.incrementAndGet();
                return null;
            }
            return v.getValue();
        });
    }

    public void put(String key, Object value, long expirationTimeMillis) {
        CacheEntry entry = new CacheEntry(value, expirationTimeMillis);
        cache.put(key, entry);
    }

    public long getRequestCount() {
        return requestCount.get();
    }

    public long getHitCount() {
        return hitCount.get();
    }

    private static class CacheEntry {
        private final Object value;
        private final long expirationTime;

        public CacheEntry(Object value, long expirationTimeMillis) {
            this.value = value;
            this.expirationTime = System.currentTimeMillis() + expirationTimeMillis;
        }

        public boolean isExpired() {
            return System.currentTimeMillis() > expirationTime;
        }

        public Object getValue() {
            return value;
        }
    }
}
```

