#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

// Define maximum string size and compression threshold
#define MAX_STRING_SIZE 1024
#define COMPRESSION_THRESHOLD 512

typedef struct {
    char *data;
    size_t length;
} DynamicString;

DynamicString* create_dynamic_string(const char *initial_data) {
    DynamicString *str = (DynamicString*)malloc(sizeof(DynamicString));
    str->length = strlen(initial_data);
    if (str->length > MAX_STRING_SIZE) {
        str->length = COMPRESSION_THRESHOLD; // Apply compression threshold
        z_stream strm;
        strm.zalloc = Z_NULL;
        strm.zfree = Z_NULL;
        strm.opaque = Z_NULL;
        deflateInit(&strm, Z_DEFAULT_COMPRESSION);
        strm.avail_in = strlen(initial_data);
        strm.next_in = (unsigned char*)initial_data;
        str->data = (char*)malloc(MAX_STRING_SIZE);
        do {
            strm.avail_out = MAX_STRING_SIZE - strm.total_out;
            strm.next_out = (unsigned char*)(str->data + strm.total_out);
            deflate(&strm, Z_FINISH);
        } while (strm.avail_out == 0);
        deflateEnd(&strm);
    } else {
        str->data = strdup(initial_data);
    }
    return str;
}

void free_dynamic_string(DynamicString *str) {
    free(str->data);
    free(str);
}

int main() {
    const char *initial_data = "This is a very long string that may exceed the compression threshold.";
    DynamicString *dynamic_str = create_dynamic_string(initial_data);

    printf("Dynamic String Length: %zu\n", dynamic_str->length);
    printf("Dynamic String Data: %s\n", dynamic_str->data);

    free_dynamic_string(dynamic_str);
    return 0;
}
