// Define a simple logger event structure
struct Event {
    std::chrono::system_clock::time_point timestamp;
    int code;
    // Flexible context data using union
    union {
        std::string str_data;
        int int_data;
        double double_data;
        void* ptr_data;
    } context;

    // Constructor for string data
    Event(std::chrono::system_clock::time_point ts, int c, std::string s)
        : timestamp(ts), code(c), str_data(s) {}

    // Constructor for integer data
    Event(std::chrono::system_clock::time_point ts, int c, int i)
        : timestamp(ts), code(c), int_data(i) {}

    // Constructor for double data
    Event(std::chrono::system_clock::time_point ts, int c, double d)
        : timestamp(ts), code(c), double_data(d) {}
};

// Thread-safe event queue using condition variables
class EventQueue {
private:
    std::vector<Event> events;
    std::mutex mtx;
    std::condition_variable cond;

public:
    void push(const Event& event) {
        std::lock_guard<std::mutex> lock(mtx);
        events.push_back(event);
        cond.notify_one();
    }

    bool try_pop(Event& out_event) {
        std::unique_lock<std::mutex> lock(mtx);
        if (events.empty()) return false;
        out_event = events.front();
        events.erase(events.begin());
        return true;
    }

    void wait_and_pop(Event& out_event) {
        std::unique_lock<std::mutex> lock(mtx);
        cond.wait(lock, [this] { return !events.empty(); });
        out_event = events.front();
        events.erase(events.begin());
    }
};

// Example usage of the EventQueue
void producer(EventQueue& queue) {
    for (int i = 0; i < 100; ++i) {
        auto now = std::chrono::system_clock::now();
        queue.push({now, i, "Event" + std::to_string(i)});
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }
}

void consumer(EventQueue& queue) {
    while (true) {
        Event event;
        if (!queue.try_pop(event)) break;
        // Process the event
        std::cout << "Processed: " << event.timestamp.time_since_epoch().count() << ", "
                  << event.code << ", " << event.str_data << std::endl;
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }
}

int main() {
    EventQueue queue;

    std::thread producer_thread(producer, std::ref(queue));
    std::thread consumer_thread(consumer, std::ref(queue));

    producer_thread.join();
    consumer_thread.join();

    return 0;
}
