            logger.logAttack(getTimestamp(), playerId, getAttackType(strategy), getMetadata());
        }
    }

private:
    std::string getTimestamp() const {
        // Get current timestamp
        return "2023-10-05T14:30:00Z";
    }

    std::string getAttackType(const AttackStrategy* strategy) const {
        if (dynamic_cast<const BasicAttack*>(strategy)) return "basic";
        else if (dynamic_cast<const SpecialAttack*>(strategy)) return "special";
        else throw std::logic_error("Unknown attack type");
    }

    std::string getMetadata() const {
        // Get detailed metadata on player activity
        return "{\"accuracy\": 0.95, \"damage\": 120}";
    }
};

int main() {
    GameCharacter character;
    character.addStrategy("basic", 1);
    character.addStrategy("special", 2);

    character.executeAttacks(3);

    return 0;
}
