// Define the record structure
typedef struct {
    int key;
    long offset;
} record;

// Function to initialize records dynamically
record* initialize_records(int size) {
    if (size <= 0) {
        fprintf(stderr, "Invalid size for records\n");
        return NULL;
    }

    // Allocate memory for records using malloc
    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize records with unique keys and offsets
    for (int i = 0; i < size; ++i) {
        records[i].key = i + 1;
        records[i].offset = i * 1024L;
    }

    return records;
}

// Example usage of initialize_records function
int main() {
    int dataset_size = 100;
    record* my_records = initialize_records(dataset_size);

    if (my_records) {
        printf("Records initialized successfully\n");
        // Use the records as needed

        // Free allocated memory when done
        free(my_records);
    }

    return 0;
}
