        try {
            bool isValid = validateCRC(pdu);
            if (isValid) {
                promise.set_value(true);
                return;
            }
        } catch (...) {
            // Handle exception
            handleFailure(pdu, MAX_LATENCY);
        }

        std::this_thread::sleep_for(std::chrono::seconds(BACKOFF_FACTOR * attempt));
    }
    promise.set_value(false);
}

