        output[i].RX_UE_INFORMATION_TAG = rand() % 100000 + 1; // Simulate RX_UE_INFORMATION_TAG
        output[i].RNTI = MIN_RNTI + rand() % (MAX_RNTI - MIN_RNTI + 1);
        output[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Simulate CRC_INDICATION_REL8_TAG
    }

    return 0;
}

int main() {
    int N = 500000;
    NFAPI_CRC_INDICATION_PDU_T *data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

