class DatabaseConnection {
public:
    void connect() { /* Implementation */ }
    void disconnect() { /* Implementation */ }
    bool isHealthy() const { return true; } // Simplified for example
};

class ConnectionPool {
private:
    std::vector<std::shared_ptr<DatabaseConnection>> connections;
    size_t maxSize;
    std::mutex poolMutex;
    std::condition_variable notFull, notEmpty;
    std::chrono::seconds idleTimeout;
    std::chrono::seconds maxLifetime;

public:
    ConnectionPool(size_t maxSize, std::chrono::seconds idleTimeout, std::chrono::seconds maxLifetime)
        : maxSize(maxSize), idleTimeout(idleTimeout), maxLifetime(maxLifetime) {
        // Initialize connections
        for (size_t i = 0; i < maxSize; ++i) {
            connections.push_back(std::make_shared<DatabaseConnection>());
        }
    }

    std::shared_ptr<DatabaseConnection> acquire() {
        std::unique_lock<std::mutex> lock(poolMutex);
        notEmpty.wait(lock, [this] { return !connections.empty(); });
        auto connection = connections.back();
        connections.pop_back();
        return connection;
    }

    void release(std::shared_ptr<DatabaseConnection> connection) {
        std::unique_lock<std::mutex> lock(poolMutex);
        connections.push_back(connection);
        notEmpty.notify_one();
    }

    void monitorAndMaintain() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(1));
            std::unique_lock<std::mutex> lock(poolMutex);
            // Evict idle and expired connections
            for (auto it = connections.begin(); it != connections.end();) {
                if (!it->use_count() || !it->isHealthy()) {
                    it = connections.erase(it);
                } else {
                    ++it;
                }
            }
        }
    }
};

int main() {
    ConnectionPool pool(10, std::chrono::seconds(30), std::chrono::hours(24));
    auto connection = pool.acquire();
    // Use the connection
    pool.release(connection);
    return 0;
}
