// Define the log entry structure
typedef struct {
    time_t timestamp;
    int event_code;
    union {
        char* string_data;
        int int_data;
        double float_data;
    } context;
} LogEntry;

// Define the plugin interface
typedef void (*LogPluginFunction)(LogEntry*);

// Define the logging framework structure
typedef struct {
    pthread_mutex_t mutex;
    LogPluginFunction* plugins;
    int num_plugins;
} LoggingFramework;

// Initialize the logging framework
void initialize_logging_framework(LoggingFramework* framework) {
    pthread_mutex_init(&framework->mutex, NULL);
    framework->plugins = NULL;
    framework->num_plugins = 0;
}

// Add a plugin to the logging framework
void add_plugin(LoggingFramework* framework, LogPluginFunction plugin) {
    pthread_mutex_lock(&framework->mutex);
    framework->num_plugins++;
    framework->plugins = realloc(framework->plugins, framework->num_plugins * sizeof(LogPluginFunction));
    framework->plugins[framework->num_plugins - 1] = plugin;
    pthread_mutex_unlock(&framework->mutex);
}

// Log an event using the logging framework
void log_event(LoggingFramework* framework, LogEntry* entry) {
    pthread_mutex_lock(&framework->mutex);
    for (int i = 0; i < framework->num_plugins; i++) {
        framework->plugins[i](entry);
    }
    pthread_mutex_unlock(&framework->mutex);
}

// Example plugin function
void example_plugin(LogEntry* entry) {
    printf("Timestamp: %ld, Event Code: %d\n", entry->timestamp, entry->event_code);
    if (entry->context.string_data != NULL) {
        printf("Context Data: %s\n", entry->context.string_data);
    }
}

int main() {
    LoggingFramework framework;
    initialize_logging_framework(&framework);

    // Add a plugin to the logging framework
    add_plugin(&framework, example_plugin);

    // Create a log entry and log it
    LogEntry entry;
    entry.timestamp = time(NULL);
    entry.event_code = 1001;
    entry.context.string_data = strdup("Example Event");

    log_event(&framework, &entry);

    return 0;
}
