// StreamingProcessor.cpp
#include "StreamingProcessor.h"
#include <iostream>
#include <thread>
#include <chrono>

StreamingProcessor::StreamingProcessor(size_t initialBufferSize, double maxMemoryUsage)
    : bufferSize_(initialBufferSize), maxMemoryUsage_(maxMemoryUsage), currentBufferSize_(0),
      running_(true), errorLog_("error.log") {
    for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
        workerThreads_.emplace_back(&StreamingProcessor::workerThread, this);
    }
}

StreamingProcessor::~StreamingProcessor() {
    running_ = false;
    dataCondition_.notify_all();
    for (auto& thread : workerThreads_) {
        if (thread.joinable()) {
            thread.join();
        }
    }
}

void StreamingProcessor::start() {
    running_ = true;
}

void StreamingProcessor::stop() {
    running_ = false;
    dataCondition_.notify_all();
}

void StreamingProcessor::enqueue(const std::string& data) {
    std::unique_lock<std::mutex> lock(bufferMutex_);
    while (isBufferFull()) {
        dataCondition_.wait(lock);
    }
    dataQueue_.push(data);
    currentBufferSize_ += data.size();
    resizeBuffer();
    if (!sendToConsumers(data)) {
        logError("Failed to send data to consumers");
    }
}

void StreamingProcessor::workerThread() {
    while (running_) {
        std::unique_lock<std::mutex> lock(bufferMutex_);
        dataCondition_.wait(lock, [this] { return !dataQueue_.empty() || !running_; });
        if (!running_ && dataQueue_.empty()) {
            break;
        }
        std::string data = dataQueue_.front();
        dataQueue_.pop();
        currentBufferSize_ -= data.size();
        lock.unlock();

        validateData(data);
        if (isNetworkAvailable()) {
            simulateNetworkLatency();
            sendToConsumers(data);
        } else {
            logError("Network unavailable");
        }
    }
}

void StreamingProcessor::validateData(const std::string& data) {
    // Implement schema validation logic here
}

bool StreamingProcessor::isBufferFull() const {
    return currentBufferSize_ >= bufferSize_;
}

void StreamingProcessor::resizeBuffer() {
    if (currentBufferSize_ * 1.0 / bufferSize_ > maxMemoryUsage_) {
        bufferSize_ *= 2;
    } else if (currentBufferSize_ < bufferSize_ / 4) {
        bufferSize_ /= 2;
    }
}

void StreamingProcessor::logError(const std::string& error) {
