#include <iostream>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <future>
#include <memory>

class Message {
public:
    std::string id;
    std::any payload;
    struct Metadata {
        int timestamp;
        int priority;
        std::string origin;
    };
    Metadata metadata;
    std::optional<std::function<void(const Message&)>> replyChannel;

    Message(std::string id, std::any payload, Metadata metadata)
        : id(id), payload(payload), metadata(metadata) {}
};

class MessageBroker {
public:
    void publish(const Message& message, const std::string& exchange) {
        std::unique_lock<std::mutex> lock(mutex);
        exchanges[exchange].push(message);
        cv.notify_one();
    }

    void subscribe(const std::string& exchange, std::function<void(const Message&)> callback) {
        consumers.push_back({exchange, callback});
        startConsumers();
    }

private:
    std::map<std::string, std::queue<Message>> exchanges;
    std::vector<std::pair<std::string, std::function<void(const Message&)>>> consumers;
    std::mutex mutex;
    std::condition_variable cv;
    bool running = true;

    void startConsumers() {
        if (!consumerThreads.empty()) return; // Avoid starting multiple times
        for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
            consumerThreads.emplace_back(&MessageBroker::consume, this);
        }
    }

    void consume() {
        while (running) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return !exchanges.empty(); });
            auto& exchange = exchanges.begin()->second;
            if (!exchange.empty()) {
                Message message = exchange.front();
                exchange.pop();
                for (auto& consumer : consumers) {
                    if (consumer.first == exchange.queue_name()) {
                        std::invoke(consumer.second, message);
                        break; // Only one consumer per exchange
                    }
                }
            }
        }
    }

    ~MessageBroker() {
        running = false;
        cv.notify_all();
        for (auto& thread : consumerThreads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }
};
```

