#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>
#include <sys/time.h>
#include <unistd.h>

#define SHARED_RESOURCE "/tmp/shared_resource"

sem_t *sem;
int thread_count;
int initial_semaphore_value;

void log_error(const char *message, int error_code) {
    FILE *log_file = fopen("error_log.txt", "a");
    struct timeval tv;
    gettimeofday(&tv, NULL);
    fprintf(log_file, "%ld.%06ld - %s (Error Code: %d)\n",
            tv.tv_sec, tv.tv_usec, message, error_code);
    fclose(log_file);
}

void *thread_function(void *arg) {
    int thread_id = *(int *)arg;
    struct timespec start, end;

    if (clock_gettime(CLOCK_MONOTONIC, &start) == -1) {
        perror("Clock gettime");
        return NULL;
    }

    int ret = sem_wait(sem);
    if (ret == -1) {
        log_error("Failed to wait on semaphore", errno);
        return NULL;
    }

    // Simulate work with the shared resource
    sleep(1);

    ret = sem_post(sem);
    if (ret == -1) {
        log_error("Failed to post on semaphore", errno);
        return NULL;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
        perror("Clock gettime");
        return NULL;
    }

    long time_taken = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000;
    printf("Thread %d: Time taken for semaphore operation = %ld ms\n", thread_id, time_taken);

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <number_of_threads> <initial_semaphore_value>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    thread_count = atoi(argv[1]);
    initial_semaphore_value = atoi(argv[2]);

    sem = sem_open(SHARED_RESOURCE, O_CREAT, 0666, initial_semaphore_value);
    if (sem == SEM_FAILED) {
        perror("Semaphore open");
        exit(EXIT_FAILURE);
    }

    pthread_t threads[thread_count];
    int thread_ids[thread_count];

    for (int i = 0; i < thread_count; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, thread_function, &thread_ids[i]) != 0) {
            perror("Thread creation");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_close(sem);
    sem_unlink(SHARED_RESOURCE);

    return 0;
}
