    // Example usage of exponential backoff with jitter in C++

    int maxRetries = 10;
    double baseDelay = 500.0; // milliseconds
    double jitterFactor = 0.2;

    for (int attempt = 0; attempt < maxRetries; ++attempt) {
        try {
            // Simulate an API call
            throw std::runtime_error("API call failed");

            // If successful, break the loop
            break;
        } catch (...) {
            if (attempt == maxRetries - 1) {
                std::cerr << "Failed to complete after maximum retries." << std::endl;
                return 1;
            }

            // Calculate delay with jitter
            double randomJitter = jitterFactor * baseDelay * ((rand() / static_cast<double>(RAND_MAX)) * 2 - 1);
            double delay = baseDelay * (1 << attempt) + randomJitter;

            std::cout << "Attempt " << attempt + 1 << " failed. Retrying in " << delay << " ms." << std::endl;
            std::this_thread::sleep_for(std::chrono::milliseconds(static_cast<int>(delay)));
        }
    }

    return 0;
}
