import java.util.concurrent.CompletableFuture;

public class ExternalMetadataService {
    private final RateLimiter rateLimiter;
    private final int maxRetries = 5;
    private final long initialBackoff = 100;
    private final double backoffMultiplier = 2.0;

    public ExternalMetadataService(RateLimiter rateLimiter) {
        this.rateLimiter = rateLimiter;
    }

    public String getUserInfo(String userId) {
        int retryCount = 0;
        while (retryCount <= maxRetries) {
            if (!rateLimiter.allowRequest()) {
                try {
                    Thread.sleep((long) Math.pow(backoffMultiplier, retryCount) * initialBackoff);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return null;
                }
                continue;
            }

            try {
                // Simulate external API call
                return CompletableFuture.supplyAsync(() -> fetchUserInfoFromAPI(userId))
                        .get();
            } catch (Exception e) {
                retryCount++;
            }
        }
        return null;
    }

    private String fetchUserInfoFromAPI(String userId) throws Exception {
        // Simulate network delay and error handling
        if (Math.random() < 0.1) {
            throw new RuntimeException("External API outage");
        }
        Thread.sleep(50);
        return "User Info for " + userId;
    }
}
