void validateOAuth2Token(const char* jsonString, AsyncCallback callback, void* userData) {
    json_object* parsedJson = json_tokener_parse(jsonString);
    if (!parsedJson) {
        // Handle JSON parsing error
        callback(false, userData);
        return;
    }

    OAuth2Token token;
