    // Extract access_token
    json_object* accessTokenObj;
    if (json_object_object_get_ex(parsedJson, "access_token", &accessTokenObj)) {
        token.access_token = strdup(json_object_get_string(accessTokenObj));
    } else {
        callback(false, userData);
        return;
    }

    // Extract token_type
    json_object* tokenTypeObj;
    if (json_object_object_get_ex(parsedJson, "token_type", &tokenTypeObj) && strcmp(json_object_get_string(tokenTypeObj), "Bearer") == 0) {
        token.token_type = strdup("Bearer");
    } else {
        callback(false, userData);
        return;
    }

    // Extract expires_in
    json_object* expiresInObj;
    if (json_object_object_get_ex(parsedJson, "expires_in", &expiresInObj)) {
        int expiresIn = json_object_get_int(expiresInObj);
        if (expiresIn > 0 && expiresIn <= 3600) {
            token.expires_in = expiresIn;
        } else {
            callback(false, userData);
            return;
        }
    } else {
        callback(false, userData);
        return;
    }

    // Extract refresh_token
    json_object* refreshTokenObj;
    if (json_object_object_get_ex(parsedJson, "refresh_token", &refreshTokenObj)) {
        token.refresh_token = strdup(json_object_get_string(refreshTokenObj));
        // Validate refresh_token format here
    } else {
        // Optional: If refresh_token is not present, continue validation
    }

    // Perform asynchronous callback with the result
    callback(true, userData);

    // Clean up resources
    json_object_put(parsedJson);
    free(token.access_token);
    free(token.token_type);
    free(token.refresh_token);
}

// Example usage:
void myCallback(bool result, void* userData) {
    printf("Token validation result: %s\n", result ? "Success" : "Failure");
}

int main() {
    const char* tokenJson = "{\"access_token\":\"abc123\",\"token_type\":\"Bearer\",\"expires_in\":3600}";
