import redis.clients.jedis.JedisPoolConfig;

@SpringBootApplication
public class ConfigManagementApplication {

    public static void main(String[] args) {
        SpringApplication.run(ConfigManagementApplication.class, args);
    }

    @Bean
    public StringRedisTemplate stringRedisTemplate() {
        JedisPoolConfig poolConfig = new JedisPoolConfig();
        return new StringRedisTemplate(poolConfig);
    }

    @Bean
    public ExecutorService executorService() {
        return Executors.newCachedThreadPool();
    }

    @Bean
    public ConfigCache configCache(StringRedisTemplate redisTemplate) {
        return new ConfigCache(redisTemplate, executorService());
    }
}

class ConfigCache {
    private final StringRedisTemplate redisTemplate;
    private final ExecutorService executorService;
    private ConcurrentHashMap<String, Config> cache;

    public ConfigCache(StringRedisTemplate redisTemplate, ExecutorService executorService) {
        this.redisTemplate = redisTemplate;
        this.executorService = executorService;
        this.cache = new ConcurrentHashMap<>();
        initializeCache();
    }

    private void initializeCache() {
        // Load initial configurations from Redis into the local cache
        redisTemplate.opsForKeys().keys("*").forEach(key -> {
            String configJson = redisTemplate.opsForValue().get(key);
            Config config = Config.fromJson(configJson);
            cache.put(key, config);
        });
    }

    public Config getConfig(String key) {
        return cache.getOrDefault(key, null);
    }

    public void updateConfig(String key, Config newConfig) {
        // Update the configuration in Redis and refresh the local cache
        redisTemplate.opsForValue().set(key, newConfig.toJson());
        executorService.submit(() -> cache.put(key, newConfig));
    }
}

