#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <unordered_map>
#include <atomic>
#include <chrono>

// Define a simple event structure
struct Event {
    std::string timestamp;
    int code;
    union {
        int intValue;
        double doubleValue;
        std::string stringValue;
    } contextData;
};

class Logger {
private:
    std::queue<Event> eventQueue;
    std::mutex queueMutex;
    std::condition_variable cv;
    bool stop;
    std::unordered_map<int, void(*)(const Event&)> handlers;

public:
    Logger() : stop(false) {}

    void start() {
        std::thread([this]() {
            while (!stop) {
                std::unique_lock<std::mutex> lock(queueMutex);
                cv.wait(lock, [this] { return !eventQueue.empty() || stop; });
                if (stop && eventQueue.empty()) break;
                Event event = eventQueue.front();
                eventQueue.pop();
                lock.unlock();

                // Process the event
                processEvent(event);
            }
        }).detach();
    }

    void stopLogger() {
        std::unique_lock<std::mutex> lock(queueMutex);
        stop = true;
        cv.notify_all();
    }

    void addHandler(int code, void(*handler)(const Event&)) {
        handlers[code] = handler;
    }

    void logEvent(const Event& event) {
        std::unique_lock<std::mutex> lock(queueMutex);
        eventQueue.push(event);
        cv.notify_one();
    }

private:
    void processEvent(const Event& event) {
        auto it = handlers.find(event.code);
        if (it != handlers.end()) {
            it->second(event);
        } else {
            std::cerr << "No handler for event code: " << event.code << std::endl;
        }
    }
};

void handleNetworkError(const Event& event) {
    // Handle network error event
    std::cout << "Handling network error event: " << event.timestamp << ", Code: " << event.code << std::endl;
}

int main() {
    Logger logger;
    logger.addHandler(1, handleNetworkError);

    logger.start();

    // Simulate logging an event
    Event event = {"2023-04-10 12:34:56", 1, { .intValue = 404 } };
    logger.logEvent(event);

    std::this_thread::sleep_for(std::chrono::seconds(2));
    logger.stopLogger();

    return 0;
}
