    }
};

class SpecialAttack : public AttackStrategy {
public:
    void execute() override {
        std::cout << "Executing special attack." << std::endl;
    }
};

class MOBAGameCharacter {
private:
    std::vector<AttackStrategy*> strategies;
    int currentStrategyIndex;

public:
    MOBAGameCharacter() : currentStrategyIndex(0) {}

    void addStrategy(AttackStrategy* strategy) {
        strategies.push_back(strategy);
    }

    void changeStrategy() {
        currentStrategyIndex = (currentStrategyIndex + 1) % strategies.size();
    }

    void executeCurrentStrategy() {
        if (!strategies.empty()) {
            strategies[currentStrategyIndex]->execute();
        }
    }
};

class MOBALogger {
private:
    sqlite3* db;

public:
    MOBALogger(const std::string& dbName) {
        int rc = sqlite3_open(dbName.c_str(), &db);
        if (rc != SQLITE_OK) {
            throw std::runtime_error("Cannot open database: " + std::string(sqlite3_errmsg(db)));
        }
        createTable();
    }

    ~MOBALogger() {
        sqlite3_close(db);
    }

