                id INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
                player_id TEXT NOT NULL,
                attack_type TEXT NOT NULL,
                metadata TEXT
            );
        )";
        sqlite3_exec(db, createQuery, nullptr, nullptr, nullptr);
    }

public:
    void logAttack(const std::string& playerId, const std::string& attackType, const std::string& metadata) {
        const char* insertQuery = "INSERT INTO attack_logs (player_id, attack_type, metadata) VALUES (?, ?, ?);";
        sqlite3_stmt* stmt;
        int rc = sqlite3_prepare_v2(db, insertQuery, -1, &stmt, nullptr);
        if (rc != SQLITE_OK) {
            throw std::runtime_error("Failed to prepare statement: " + std::string(sqlite3_errmsg(db)));
        }
        sqlite3_bind_text(stmt, 1, playerId.c_str(), -1, SQLITE_STATIC);
        sqlite3_bind_text(stmt, 2, attackType.c_str(), -1, SQLITE_STATIC);
        sqlite3_bind_text(stmt, 3, metadata.c_str(), -1, SQLITE_STATIC);
        rc = sqlite3_step(stmt);
        if (rc != SQLITE_DONE) {
            throw std::runtime_error("Failed to execute statement: " + std::string(sqlite3_errmsg(db)));
        }
        sqlite3_finalize(stmt);
    }
};

int main() {
    MOBAGameCharacter character;
    character.addStrategy(new BasicAttack());
    character.addStrategy(new SpecialAttack());

    MOBALogger logger("moba_game.db");

    for (int i = 0; i < 10; ++i) {
        character.executeCurrentStrategy();
        std::string metadata = "Player " + std::to_string(i % 2 + 1);
        logger.logAttack(std::to_string(i), character.currentStrategyIndex == 0 ? "Basic" : "Special", metadata);
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    return 0;
}
```

