using System;
using System.Data;
using System.Data.SqlClient;
using Polly;

public class DatabaseProcessor
{
    private readonly string _connectionString;
    private readonly AsyncCircuitBreakerPolicy<SqlConnection> _circuitBreakerPolicy;

    public DatabaseProcessor(string connectionString)
    {
        _connectionString = connectionString;
        var policy = Policy.BreakerAsync<SqlConnection>(failureThreshold: 5, resetTimeout: TimeSpan.FromSeconds(30));
        _circuitBreakerPolicy = policy.OrResult(sqlConnection => sqlConnection.State == System.Data.ConnectionState.Broken);
    }

    public DataTableReader ExecuteQuery(byte[] data)
    {
        var query = "SELECT * FROM YourTable WHERE Data = @Data";

        return (DataTableReader)_circuitBreakerPolicy.ExecuteAsync(() =>
        {
            using (var connection = new SqlConnection(_connectionString))
            {
                connection.Open();

                using (var command = new SqlCommand(query, connection))
                {
                    command.Parameters.AddWithValue("@Data", data);

                    using (var reader = command.ExecuteReader())
                    {
                        return reader;
                    }
                }
            }
        }).Result;
    }
}
