    void disconnect() { iotClient.disconnect(); }
    bool isConnected() { return iotClient.isConnected(); }

private:
    IoTClient iotClient;
};

// Function to fetch sensor readings with retries and circuit breaker
void fetchSensorReadingsWithRetries(std::vector<double>& readings) {
    static std::atomic<int> failureCount(0);
    while (!ConnectionManager::getInstance().isConnected()) {
        if (failureCount >= 3) break; // Break after multiple failures
        ConnectionManager::getInstance().connect();
        std::this_thread::sleep_for(std::chrono::seconds(1));
        ++failureCount;
    }

    if (ConnectionManager::getInstance().isConnected() && !iotClient.fetchSensorReadings(readings)) {
        std::cout << "Failed to fetch sensor readings." << std::endl;
    } else {
        std::cout << "Successfully fetched sensor readings." << std::endl;
    }
}

int main() {
    std::vector<double> sensorReadings;
    fetchSensorReadingsWithRetries(sensorReadings);

    for (auto reading : sensorReadings) {
        std::cout << "Sensor Reading: " << reading << std::endl;
    }

    return 0;
}
