import java.util.stream.Collectors;

public class NetworkInterfaceService {

    private final ExecutorService executor = Executors.newFixedThreadPool(10);
    private final ExternalDataSource dataSource;
    private final Cache cache;

    public NetworkInterfaceService(ExternalDataSource dataSource, Cache cache) {
        this.dataSource = dataSource;
        this.cache = cache;
    }

    public CompletableFuture<List<NetworkStatus>> processInterfaces(List<String> interfaceNames) {
        return CompletableFuture.supplyAsync(() -> 
            interfaceNames.stream()
                .map(this::processInterface)
                .collect(Collectors.toList()),
            executor
        );
    }

    private NetworkStatus processInterface(String name) {
        if (cache.has(name)) {
            return cache.get(name);
        }

        NetworkStatus status = dataSource.getStatus(name);
        if (status != null) {
            cache.put(name, status);
        }
        return status;
    }

    public void shutdown() {
        executor.shutdown();
    }
}

interface ExternalDataSource {
    NetworkStatus getStatus(String name);
}

class Cache {
    private final java.util.Map<String, NetworkStatus> map = new java.util.concurrent.ConcurrentHashMap<>();

    boolean has(String key) {
        return map.containsKey(key);
    }

    NetworkStatus get(String key) {
        return map.get(key);
    }

    void put(String key, NetworkStatus value) {
        map.put(key, value);
    }
}

