        apis: Vec<Arc<dyn CryptoAPI>>,
        cache: Arc<Mutex<HashMap<String, String>>>,
    }

    trait CryptoAPI {
        fn get_supported_algorithms(&self) -> Result<Vec<String>, String>;
    }

    impl CryptoAPIManager {
        pub fn new(apis: Vec<Arc<dyn CryptoAPI>>) -> Self {
            CryptoAPIManager {
                apis,
                cache: Arc::new(Mutex::new(HashMap::new())),
            }
        }

        pub async fn get_algorithms(&self) -> Result<Vec<String>, String> {
            let mut cache = self.cache.lock().unwrap();
            if let Some(algorithms) = cache.get("algorithms") {
                return Ok(algorithms.split(',').map(String::from).collect());
            }

            for api in &self.apis {
                match api.get_supported_algorithms() {
                    Ok(algorithms) => {
                        *cache = algorithms.split(',').map(String::from).collect();
                        return Ok(algorithms);
                    }
                    Err(_) => continue,
                };
            }

            Err("No available APIs to retrieve supported algorithms".to_string())
        }
    }

    // Implement actual CryptoAPI trait for specific cryptographic libraries
}
