// Placeholder for the Java microservice processing JSON payloads to generate MD5 hashes
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.TimeUnit;

public class MD5HashService {

    private final ForkJoinPool forkJoinPool = new ForkJoinPool(Runtime.getRuntime().availableProcessors());

    public String generateMD5(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hashBytes = digest.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Failed to generate MD5 hash", e);
        }
    }

    public void processJSONPayloads(RateLimiter rateLimiter, ExternalMetadataProvider metadataProvider, List<String> payloads) {
        for (String payload : payloads) {
            if (!rateLimiter.tryAcquire()) {
                continue; // Handle rate limit
            }

            String enhancedData = metadataProvider.enhance(payload);
            forkJoinPool.submit(() -> {
                String hash = generateMD5(enhancedData);
                // Process the hash as needed
            });
        }
    }
}

class RateLimiter {
    private final int maxRequests;
    private final long periodInMillis;
    private int currentRequests;
    private long lastResetTime;

    public RateLimiter(int maxRequests, long periodInMillis) {
        this.maxRequests = maxRequests;
        this.periodInMillis = periodInMillis;
        this.lastResetTime = System.currentTimeMillis();
    }

    public boolean tryAcquire() {
        if (System.currentTimeMillis() - lastResetTime >= periodInMillis) {
            currentRequests = 0;
            lastResetTime = System.currentTimeMillis();
        }
        if (currentRequests < maxRequests) {
            currentRequests++;
            return true;
        }
        return false;
    }
}

interface ExternalMetadataProvider {
    String enhance(String payload);
}
