// Define the context data union for various data types
union ContextData {
    int intValue;
    double doubleValue;
    std::string stringValue;

    ContextData() {}
    ~ContextData() {}

    bool operator==(const ContextData& other) const {
        if (this->intValue == other.intValue &&
            this->doubleValue == other.doubleValue &&
            this->stringValue == other.stringValue) {
            return true;
        }
        return false;
    }
};

// Define the network event structure
struct NetworkEvent {
    std::chrono::system_clock::time_point timestamp;
    int eventCode;
    ContextData context;

    NetworkEvent(std::chrono::system_clock::time_point ts, int code, ContextData ctx)
        : timestamp(ts), eventCode(code), context(ctx) {}
};

// Define the logging framework class
class LoggingFramework {
public:
    LoggingFramework() {}

    // Function to log a network event
    void logEvent(const NetworkEvent& event) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(event);
        condition_variable_.notify_one();
    }

private:
    mutable std::mutex mutex_;
    std::condition_variable condition_variable_;
    std::queue<NetworkEvent> queue_;
};

