    [Route("[controller]")]
    public class RecommendationsController : ControllerBase
    {
        private readonly ILogger<RecommendationsController> _logger;
        private readonly IMachineLearningModel _mlModel;
        private readonly IDistributedCache _cache;
        private readonly IApiClient _apiClient;

        public RecommendationsController(ILogger<RecommendationsController> logger, IMachineLearningModel mlModel, IDistributedCache cache, IApiClient apiClient)
        {
            _logger = logger;
            _mlModel = mlModel;
            _cache = cache;
            _apiClient = apiClient;
        }

        [HttpGet("{userId}")]
        public async Task<IActionResult> GetRecommendationsAsync(string userId)
        {
            try
            {
                var cachedData = await _cache.GetStringAsync(userId);
                if (cachedData != null)
                {
                    return Ok(JsonConvert.DeserializeObject<List<ContentItem>>(cachedData));
                }

                var userPreferences = await _apiClient.GetUserPreferencesAsync(userId);
                var latestContent = await _apiClient.GetLatestContentAsync();
                var recommendations = _mlModel.GetRecommendations(userPreferences, latestContent);

                var cacheEntryOptions = new DistributedCacheEntryOptions()
                    .SetSlidingExpiration(TimeSpan.FromMinutes(10));

                await _cache.SetStringAsync(userId, JsonConvert.SerializeObject(recommendations), cacheEntryOptions);

                return Ok(recommendations);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error fetching recommendations for user: {UserId}", userId);
                return StatusCode(500, "Internal server error");
            }
        }
