    {
        Task<string> GetStringAsync(string key);
        Task SetStringAsync(string key, string value, DistributedCacheEntryOptions options);
    }

    public class MemoryDistributedCache : IDistributedCache
    {
        private readonly ConcurrentDictionary<string, CacheItem> _cache = new ConcurrentDictionary<string, CacheItem>();

        public Task<string> GetStringAsync(string key)
        {
            if (_cache.TryGetValue(key, out var cacheItem) && !cacheItem.IsExpired)
            {
                return Task.FromResult(cacheItem.Value);
            }
            return Task.FromResult((string)null);
        }

        public Task SetStringAsync(string key, string value, DistributedCacheEntryOptions options)
        {
            _cache[key] = new CacheItem { Value = value, ExpirationTime = DateTime.UtcNow.Add(options.SlidingExpiration) };
            return Task.CompletedTask;
        }
    }

