using System;
using System.Collections.Generic;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

public class XmlService
{
    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _cache;
    private readonly ILogger<XmlService> _logger;

    public XmlService(HttpClient httpClient, IMemoryCache cache, ILogger<XmlService> logger)
    {
        _httpClient = httpClient;
        _cache = cache;
        _logger = logger;
    }

    public async Task<string> GetXmlAsync(string sourceUrl, bool isLocalFile = false)
    {
        if (isLocalFile)
        {
            return await GetXmlFromLocalFileAsync(sourceUrl);
        }
        else
        {
            return await GetXmlFromApiAsync(sourceUrl);
        }
    }

    private async Task<string> GetXmlFromApiAsync(string apiUrl)
    {
        var cacheKey = $"api_xml_{apiUrl}";
        if (_cache.TryGetValue(cacheKey, out string cachedXml))
        {
            _logger.LogInformation("Cache hit for API: {apiUrl}", apiUrl);
            return cachedXml;
        }

        try
        {
            HttpResponseMessage response = await _httpClient.GetAsync(apiUrl);
            response.EnsureSuccessStatusCode();
            string xmlContent = await response.Content.ReadAsStringAsync();

            if (response.Content.Headers.ContentType.MediaType == "application/xml")
            {
                _cache.Set(cacheKey, xmlContent, new MemoryCacheEntryOptions
                {
                    AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10)
                });
                _logger.LogInformation("Cache set for API: {apiUrl}", apiUrl);
                return xmlContent;
            }
        }
        catch (HttpRequestException e)
        {
            _logger.LogError(e, "HTTP request error to API: {apiUrl}", apiUrl);
            throw new Exception($"Failed to fetch XML from API: {apiUrl}", e);
        }

        _logger.LogWarning("API response does not contain valid XML: {apiUrl}", apiUrl);
        return string.Empty;
    }

    private async Task<string> GetXmlFromLocalFileAsync(string filePath)
    {
        var cacheKey = $"file_xml_{filePath}";
        if (_cache.TryGetValue(cacheKey, out string cachedXml))
        {
            _logger.LogInformation("Cache hit for file: {filePath}", filePath);
            return cachedXml;
        }

        try
        {
            string xmlContent = File.ReadAllText(filePath);
            _cache.Set(cacheKey, xmlContent, new MemoryCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromHours(1)
            });
            _logger.LogInformation("Cache set for file: {filePath}", filePath);
            return xmlContent;
        }
        catch (IOException e)
        {
            _logger.LogError(e, "IO error reading local XML file: {filePath}", filePath);
            throw new Exception($"Failed to read XML from file: {filePath}", e);
        }
    }
}
