using System;
using System.Diagnostics;
using System.IO;

public class WebsiteDirectoryManager
{
    public static void AddWebsiteToDirectory(string websitePath)
    {
        if (!File.Exists(Path.Combine(websitePath, "web.config")))
        {
            return;
        }

        try
        {
            Process process = new Process();
            process.StartInfo.FileName = "cmd.exe";
            process.StartInfo.Arguments = $"/c cd /d {websitePath} && dotnet publish -c Release";
            process.StartInfo.RedirectStandardOutput = true;
            process.StartInfo.UseShellExecute = false;
            process.StartInfo.CreateNoWindow = true;

            process.OutputDataReceived += (sender, e) =>
            {
                Console.WriteLine(e.Data);
            };

            process.Start();
            process.BeginOutputReadLine();

            process.WaitForExit();
        }
        catch (Exception ex)
        {
            // Log error and handle gracefully
            Console.Error.WriteLine($"Error adding website to directory: {ex.Message}");
        }
    }

    public static void Main(string[] args)
    {
        string websitePath = @"C:\path\to\website";
        AddWebsiteToDirectory(websitePath);
    }
