// file-processing-platform.js

const express = require('express');
const fs = require('fs').promises;
const path = require('path');
const axios = require('axios');
const { promisify } = require('util');
const zlib = require('zlib');
const RateLimiter = require('limiter').RateLimiter;

const app = express();
const limiter = new RateLimiter(10, 'minute'); // Example rate limit
const concurrencyLimit = 5;
let activeTasks = 0;

// Middleware to apply rate limiting
app.use(async (req, res, next) => {
  const rateError = await limiter.tryRemoveTokens(1);
  if (!rateError) {
    return next();
  }
  res.status(429).send('Too many requests');
});

// Endpoint to fetch files from cloud storage
app.get('/files', async (req, res) => {
  try {
    const { directory, extension } = req.query;
    const files = await fs.readdir(directory);
    const filteredFiles = files.filter(file => path.extname(file).toLowerCase() === `.${extension}`);

    for (const file of filteredFiles) {
      if (activeTasks >= concurrencyLimit) {
        return res.status(503).send('Service unavailable');
      }
      activeTasks++;
      await processFile(path.join(directory, file));
      activeTasks--;
    }

    res.json(filteredFiles);
  } catch (error) {
    console.error(error);
    res.status(500).send('Internal Server Error');
  }
});

// Function to process a single file
async function processFile(filePath) {
  try {
    const stats = await fs.stat(filePath);
    if (stats.size > 10 * 1024 * 1024) { // Example size threshold for large files
      await streamProcessFile(filePath);
    } else {
      await bufferProcessFile(filePath);
    }
  } catch (error) {
    console.error(`Error processing file ${filePath}:`, error);
  }
}

// Function to process a large file using streaming
async function streamProcessFile(filePath) {
  const readStream = fs.createReadStream(filePath, { highWaterMark: 1024 * 1024 }); // Example chunk size
  const writeStream = zlib.createGzip();
  writeStream.pipe(process.stdout);

  return new Promise((resolve, reject) => {
    readStream
      .pipe(writeStream)
      .on('finish', resolve)
      .on('error', reject);
  });
}

// Function to process a file using buffer
async function bufferProcessFile(filePath) {
  const data = await fs.readFile(filePath);
  // Process the data here
}

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
