}));

let scriptWhitelist = [];

async function fetchScriptMetadata(scriptId) {
  try {
    const response = await axios.get(`https://script-metadata-service.com/metadata/${scriptId}`);
    return response.data;
  } catch (error) {
    console.error(`Failed to fetch metadata for script ${scriptId}:`, error);
    throw new Error('Failed to load script metadata');
  }
}

function sanitizeScript(script) {
  // Implement sanitization logic here to prevent XSS
  // For example, using a library like DOMPurify
  return script;
}

async function renderFooterScripts(scripts) {
  if (!Array.isArray(scripts) || scripts.length === 0) {
    throw new Error('Invalid or empty list of scripts');
  }

  const validScripts = [];
  for (const script of scripts) {
    if (scriptWhitelist.includes(script.id)) {
      try {
        const metadata = await fetchScriptMetadata(script.id);
        const sanitizedScript = sanitizeScript(metadata.script);
        validScripts.push(sanitizedScript);
      } catch (error) {
        console.error(`Error processing script ${script.id}:`, error);
      }
    } else {
      console.warn(`Script ${script.id} is not allowed`);
    }
  }

  return validScripts;
}

app.post('/render-scripts', async (req, res) => {
  try {
    const scripts = req.body.scripts;
    const footerScripts = await renderFooterScripts(scripts);
    res.send({ scripts: footerScripts });
  } catch (error) {
    res.status(500).send({ error: error.message });
  }
});

app.get('/update-whitelist', async (req, res) => {
  try {
    const newWhitelist = req.query.whitelist.split(',');
    scriptWhitelist = newWhitelist;
    res.send({ message: 'Script whitelist updated successfully' });
  } catch (error) {
    res.status(500).send({ error: error.message });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
