                        var delay = Math.pow(2, retryCount) * 100;
                        setTimeout(function() {
                            fetchDataWithBackoff(retryCount + 1);
                        }, delay);
                    }
                })
                .catch(function(error) {
                    deferred.reject(error);
                });
        }

        fetchDataWithBackoff(0);
        return deferred.promise;
