angular.module('webSocketService', []).factory('WebSocketService', ['$q', function($q) {
    var service = {};
    var socket;
    var messageQueue = [];
    var isProcessing = false;

    // Function to connect to WebSocket server and handle incoming messages
    service.connect = function(url) {
        socket = new WebSocket(url);

        socket.onopen = function() {
            processMessageQueue();
        };

        socket.onmessage = function(event) {
            messageQueue.push(JSON.parse(event.data));
            if (!isProcessing) {
                processMessageQueue();
            }
        };

        socket.onerror = function(error) {
            console.error('WebSocket error:', error);
        };
    };

    // Function to send updates through WebSocket
    service.sendUpdate = function(id, data) {
        var message = JSON.stringify({ id: id, data: data });
        if (socket.readyState === WebSocket.OPEN) {
            socket.send(message);
        } else {
            console.error('WebSocket not open');
        }
    };

    // Function to process the message queue
    function processMessageQueue() {
        isProcessing = true;

        while (messageQueue.length > 0 && socket.readyState === WebSocket.OPEN) {
            var message = messageQueue.shift();
            socket.send(message);
        }

        if (messageQueue.length === 0) {
            isProcessing = false;
        }
    };

    return service;
}]);

