    // Other fields as per NFAPI_CRC_INDICATION_PDU_T structure
} NFAPI_CRC_INDICATION_PDU_T;

void generate_nfaapi_crc_indications(int N, int MIN_RNTI, int MAX_RNTI, NFAPI_CRC_INDICATION_PDU_T *output) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < N; ++i) {
        int rnti = rand() % (MAX_RNTI - MIN_RNTI + 1) + MIN_RNTI;
        // Populate the output structure with valid fields
        output[i].RNTI = rnti;

        pthread_mutex_lock(&mutex);
        // Critical section: access shared resources
        // Example: Log RNTI value or update statistics
        printf("Generated RNTI: %d\n", rnti);
        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *output = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!output) {
        perror("Memory allocation failed");
        return EXIT_FAILURE;
    }

    int N = 100; // Number of structures to generate
    int MIN_RNTI = 1;
    int MAX_RNTI = 1000;

    generate_nfaapi_crc_indications(N, MIN_RNTI, MAX_RNTI, output);

    free(output);
    return EXIT_SUCCESS;
}
