int send_event(NetworkEvent *event, const char *ip_address, int port) {
    int sock = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0);
    if (sock < 0) return -1;

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    inet_pton(AF_INET, ip_address, &server_addr.sin_addr);

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        close(sock);
        return -1;
    }

    send(sock, event, sizeof(NetworkEvent), 0);
    close(sock);
    return 0;
}

void retry_send_event(NetworkEvent *event, const char *ip_address, int port) {
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (send_event(event, ip_address, port) == 0) return;
        usleep(BACKOFF_MS * 1000);
    }
