#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure for messages
typedef struct {
    int id;
    int priority;
    char *payload;
} Message;

// Custom memory allocator
void* custom_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Free memory
void custom_free(void *ptr) {
    free(ptr);
}

// Thread-safe enqueue function
typedef struct QueueNode {
    Message message;
    struct QueueNode *next;
} QueueNode;

typedef struct {
    QueueNode *front;
    QueueNode *rear;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} MessageQueue;

void init_queue(MessageQueue *queue) {
    queue->front = queue->rear = NULL;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
}

void enqueue(MessageQueue *queue, Message message) {
    QueueNode *new_node = (QueueNode*)custom_malloc(sizeof(QueueNode));
    new_node->message = message;
    new_node->next = NULL;

    pthread_mutex_lock(&queue->mutex);
    if (queue->rear == NULL) {
        queue->front = queue->rear = new_node;
    } else {
        queue->rear->next = new_node;
        queue->rear = new_node;
    }
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
}

// Thread-safe dequeue function
Message dequeue(MessageQueue *queue) {
    Message message = {0};
    pthread_mutex_lock(&queue->mutex);
    while (queue->front == NULL) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }
    QueueNode *temp = queue->front;
    message = temp->message;
    queue->front = queue->front->next;
    if (queue->front == NULL) {
        queue->rear = NULL;
    }
    custom_free(temp);
    pthread_mutex_unlock(&queue->mutex);
    return message;
}

// Example producer function
void* producer(void *arg) {
    MessageQueue *queue = (MessageQueue*)arg;
    while (1) {
        // Simulate producing a message
        Message message = {rand() % 1000, rand() % 10, "payload"};
        enqueue(queue, message);
        printf("Produced message with ID: %d\n", message.id);
        sleep(rand() % 2);  // Sleep for a random time
    }
    return NULL;
}

// Example consumer function
void* consumer(void *arg) {
    MessageQueue *queue = (MessageQueue*)arg;
    while (1) {
        Message message = dequeue(queue);
        printf("Consumed message with ID: %d\n", message.id);
        // Simulate processing the message
        sleep(rand() % 2);  // Sleep for a random time
    }
    return NULL;
}

int main() {
    MessageQueue queue;
    init_queue(&queue);

    pthread_t producer_thread, consumer_thread;

    pthread_create(&producer_thread, NULL, producer, &queue);
    pthread_create(&consumer_thread, NULL, consumer, &queue);

    pthread_join(producer_thread, NULL);
    pthread_join(consumer_thread, NULL);

    return 0;
}
