#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <chrono>

class Task {
public:
    using Payload = std::variant<std::string, int, double>;
    enum class Priority { High, Medium, Low };

    Task(Priority p, Payload payload) : priority(p), payload(payload) {}

    void execute() const {
        // Simulate task execution
        if (std::holds_alternative<std::string>(payload)) {
            std::cout << "Executing string task: " << std::get<std::string>(payload) << std::endl;
        } else if (std::holds_alternative<int>(payload)) {
            std::cout << "Executing int task: " << std::get<int>(payload) << std::endl;
        } else if (std::holds_alternative<double>(payload)) {
            std::cout << "Executing double task: " << std::get<double>(payload) << std::endl;
        }
    }

private:
    Priority priority;
    Payload payload;
};

class TaskScheduler {
public:
    using TaskQueue = std::priority_queue<Task, std::vector<Task>, TaskComparator>;

    void submitTask(const Task& task) {
        std::unique_lock<std::mutex> lock(mutex);
        queue.push(task);
        condition.notify_one();
    }

    void run() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !queue.empty(); });
            Task task = queue.top();
            queue.pop();
            lock.unlock();

            try {
                task.execute();
            } catch (...) {
                // Handle exception
                std::cerr << "Task execution failed" << std::endl;
            }
        }
    }

private:
    struct TaskComparator {
        bool operator()(const Task& t1, const Task& t2) {
            return t1.priority < t2.priority;
        }
    };

    TaskQueue queue;
    mutable std::mutex mutex;
    std::condition_variable condition;
};

int main() {
    TaskScheduler scheduler;
    std::vector<std::thread> workers;

    for (int i = 0; i < 4; ++i) {
        workers.emplace_back(&TaskScheduler::run, &scheduler);
    }

    // Submit tasks
    scheduler.submitTask(Task{Task::Priority::High, "High Priority Task"});
    scheduler.submitTask(Task{Task::Priority::Low, 123});
    scheduler.submitTask(Task{Task::Priority::Medium, 3.14});

    for (auto& worker : workers) {
        worker.join();
    }

    return 0;
}
