#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <string.h>
#include <stdio.h>

// Define constants for key derivation and encryption parameters
#define SALT_LENGTH 16
#define KEY_LENGTH 32
#define IV_LENGTH 16

typedef struct {
    unsigned char *salt;
    unsigned char *key;
    unsigned char *iv;
} EncryptionContext;

EncryptionContext* generate_context(const char *password, int password_length) {
    EncryptionContext *ctx = (EncryptionContext*)malloc(sizeof(EncryptionContext));
    ctx->salt = (unsigned char*)malloc(SALT_LENGTH);
    ctx->key = (unsigned char*)malloc(KEY_LENGTH);
    ctx->iv = (unsigned char*)malloc(IV_LENGTH);

    // Generate a random salt and key using PBKDF2
    if (!RAND_bytes(ctx->salt, SALT_LENGTH)) {
        fprintf(stderr, "Error generating salt\n");
        free(ctx->salt);
        free(ctx->key);
        free(ctx->iv);
        free(ctx);
        return NULL;
    }

    if (PKCS5_PBKDF2_HMAC(password, password_length, ctx->salt, SALT_LENGTH, 10000, EVP_sha256(), KEY_LENGTH, ctx->key) != KEY_LENGTH) {
        fprintf(stderr, "Error deriving key\n");
        free(ctx->salt);
        free(ctx->key);
        free(ctx->iv);
        free(ctx);
        return NULL;
    }

    // Generate a random IV
    if (!RAND_bytes(ctx->iv, IV_LENGTH)) {
        fprintf(stderr, "Error generating IV\n");
        free(ctx->salt);
        free(ctx->key);
        free(ctx->iv);
        free(ctx);
        return NULL;
    }

    return ctx;
}

void encrypt_data(const EncryptionContext *ctx, const unsigned char *data, int data_length, unsigned char **encrypted_data, int *encrypted_length) {
    EVP_CIPHER_CTX *ctx_evp = EVP_CIPHER_CTX_new();
    if (!ctx_evp) {
        fprintf(stderr, "Error creating cipher context\n");
        return;
    }

    // Initialize encryption
    if (1 != EVP_EncryptInit_ex(ctx_evp, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv)) {
        fprintf(stderr, "Error initializing encryption\n");
        EVP_CIPHER_CTX_free(ctx_evp);
        return;
    }

    int len = 0;
    if (1 != EVP_EncryptUpdate(ctx_evp, *encrypted_data, &len, data, data_length)) {
        fprintf(stderr, "Error encrypting data\n");
        EVP_CIPHER_CTX_free(ctx_evp);
        free(*encrypted_data);
        *encrypted_data = NULL;
        return;
    }
    *encrypted_length = len;

    // Finalize encryption
    if (1 != EVP_EncryptFinal_ex(ctx_evp, (*encrypted_data) + len, &len)) {
        fprintf(stderr, "Error finalizing encryption\n");
        EVP_CIPHER_CTX_free(ctx_evp);
        free(*encrypted_data);
        *encrypted_data = NULL;
        return;
    }
    *encrypted_length += len;

    // Calculate HMAC
    unsigned char hmac[EVP_MAX_MD_SIZE];
    unsigned int hmac_len;
    if (!HMAC(EVP_sha256(), ctx->key, KEY_LENGTH, data, data_length, hmac, &hmac_len)) {
        fprintf(stderr, "Error calculating HMAC\n");
        EVP_CIPHER_CTX_free(ctx_evp);
        free(*encrypted_data);
        *encrypted_data = NULL;
        return;
    }

    // Resize buffer to hold encrypted data and HMAC
    unsigned char *new_encrypted_data = realloc(*encrypted_data, *encrypted_length + hmac_len);
    if (!new_encrypted_data) {
        fprintf(stderr, "Error resizing encryption buffer\n");
        EVP_CIPHER_CTX_free(ctx_evp);
        free(*encrypted_data);
        *encrypted_data = NULL;
        return;
    }
    *encrypted_data = new_encrypted_data;

    // Append HMAC to encrypted data
    memcpy((*encrypted_data) + *encrypted_length, hmac, hmac_len);
    *encrypted_length += hmac_len;

    EVP_CIPHER_CTX_free(ctx_evp);
}

void decrypt_data(const EncryptionContext *ctx, unsigned char *encrypted_data, int encrypted_length, unsigned char **decrypted_data, int *decrypted_length) {
    EVP_CIPHER_CTX *ctx_evp = EVP_CIPHER_CTX_new();
    if (!ctx_evp) {
        fprintf(stderr, "Error creating cipher context\n");
        return;
    }

    // Initialize decryption
    if (1 != EVP_DecryptInit_ex(ctx_evp, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv)) {
        fprintf(stderr, "Error initializing decryption\n");
        EVP_CIPHER_CTX_free(ctx_evp);
        return;
    }

    int len = 0;
    if (1 != EVP_DecryptUpdate(ctx_evp, *decrypted_data, &len, encrypted_data, encrypted_length - EVP_MAX_MD_SIZE)) {
        fprintf(stderr, "Error decrypting data\n");
        EVP_CIPHER_CTX_free(ctx_evp);
        free(*decrypted_data);
        *decrypted_data = NULL;
        return;
    }
    *decrypted_length = len;

    // Finalize decryption
    if (1 != EVP_DecryptFinal_ex(ctx_evp, (*decrypted_data) + len, &len)) {
        fprintf(stderr, "Error finalizing decryption\n");
        EVP_CIPHER_CTX_free(ctx_evp);
        free(*decrypted_data);
        *decrypted_data = NULL;
        return;
    }
    *decrypted_length += len;

    // Verify HMAC
    unsigned char hmac[EVP_MAX_MD_SIZE];
    unsigned int calculated_hmac_len;
    if (!HMAC(EVP_sha256(), ctx->key, KEY_LENGTH, encrypted_data, encrypted_length - EVP_MAX_MD_SIZE, hmac, &calculated_hmac_len)) {
        fprintf(stderr, "Error calculating HMAC\n");
        EVP_CIPHER_CTX_free(ctx_evp);
        free(*decrypted_data);
        *decrypted_data = NULL;
        return;
    }

    if (calculated_hmac_len != EVP_MAX_MD_SIZE || memcmp(hmac, encrypted_data + encrypted_length - EVP_MAX_MD_SIZE, calculated_hmac_len) != 0) {
        fprintf(stderr, "HMAC verification failed\n");
        EVP_CIPHER_CTX_free(ctx_evp);
        free(*decrypted_data);
        *decrypted_data = NULL;
        return;
    }

    EVP_CIPHER_CTX_free(ctx_evp);
}

void destroy_context(EncryptionContext *ctx) {
    if (ctx->salt) free(ctx->salt);
    if (ctx->key) free(ctx->key);
    if (ctx->iv) free(ctx->iv);
    free(ctx);
}
