namespace LogStreamProcessor
{
    public class Program
    {
        public static void Main(string[] args)
        {
            CreateHostBuilder(args).Build().Run();
        }

        public static IHostBuilder CreateHostBuilder(string[] args) =>
            Host.CreateDefaultBuilder(args)
                .ConfigureServices((hostContext, services) =>
                {
                    services.Configure<AppSettings>(hostContext.Configuration.GetSection("AppSettings"));
                    services.AddSingleton<ILogProcessor, LogProcessor>();
                    services.AddSingleton<IConfigurationRoot>(hostContext.Configuration);
                    services.AddHostedService<LogStreamService>();
                })
                .UseSerilog((context, configuration) =>
                {
                    configuration.ReadFrom.Configuration(context.Configuration)
                                  .Enrich.FromLogContext()
                                  .WriteTo.Console();
                });
    }

    public class AppSettings
    {
        public string LogSources { get; set; }
        public string GlobalCloudLoggingEndpoint { get; set; }
        public string DataWarehouseConnectionString { get; set; }
    }

    public interface ILogProcessor
    {
        Task ProcessLogsAsync(string logData);
    }

    public class LogProcessor : ILogProcessor
    {
        private readonly ILogger<LogProcessor> _logger;

        public LogProcessor(ILogger<LogProcessor> logger)
        {
            _logger = logger;
        }

        public async Task ProcessLogsAsync(string logData)
        {
            // Implement log processing logic here
            await Task.Delay(100); // Simulate processing time
            _logger.LogInformation("Processed log data: {LogData}", logData);
        }
    }

    public interface ILogStreamService : IHostedService
    {
        void StartProcessing();
        void StopProcessing();
    }

    public class LogStreamService : BackgroundService, ILogStreamService
    {
        private readonly ILogger<LogStreamService> _logger;
        private readonly AppSettings _appSettings;
        private readonly ILogProcessor _logProcessor;
        private CancellationTokenSource _cancellationTokenSource;

        public LogStreamService(ILogger<LogStreamService> logger, IConfigurationRoot configuration, ILogProcessor logProcessor)
        {
            _logger = logger;
            _appSettings = configuration.GetSection("AppSettings").Get<AppSettings>();
            _logProcessor = logProcessor;
        }

        protected override async Task ExecuteAsync(CancellationToken stoppingToken)
        {
            _cancellationTokenSource = CancellationTokenSource.CreateLinkedTokenSource(stoppingToken);
            while (!stoppingToken.IsCancellationRequested)
            {
                await ProcessLogsAsync();
                await Task.Delay(1000, stoppingToken); // Check for new logs every second
            }
        }

        public void StartProcessing()
        {
            _logger.LogInformation("Log stream processing started.");
            ExecuteAsync(_cancellationTokenSource.Token);
        }

        public void StopProcessing()
        {
            _logger.LogInformation("Log stream processing stopped.");
            _cancellationTokenSource.Cancel();
        }

        private async Task ProcessLogsAsync()
        {
            var logSources = _appSettings.LogSources.Split(',');
            foreach (var source in logSources)
            {
                try
                {
                    await ProcessSingleSourceAsync(source);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Failed to process log source: {Source}", source);
                }
            }
        }

        private async Task ProcessSingleSourceAsync(string source)
        {
            // Implement logic to read logs from different sources
            var logData = await ReadLogDataAsync(source);
            if (!string.IsNullOrEmpty(logData))
            {
                await _logProcessor.ProcessLogsAsync(logData);
            }
        }

        private async Task<string> ReadLogDataAsync(string source)
        {
            // Implement logic to read log data from the specified source
            return await Task.FromResult("Sample log data");
        }
    }
}
