#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/hmac.h>
#include <openssl/evp.h>
#include <openssl/pbkdf2.h>

#define AES_BLOCK_SIZE 16
#define HMAC_DIGEST_LENGTH 32

typedef struct {
    unsigned char key[AES_BLOCK_SIZE];
    unsigned char iv[AES_BLOCK_SIZE];
} EncryptionContext;

void generate_key(unsigned char *key, size_t key_len, const char *password) {
    EVP_BytesToKey(EVP_aes_256_cbc(), NULL, NULL, (unsigned char *)password, strlen(password), 10000, key);
}

void encrypt(const unsigned char *plaintext, int plaintext_len, const EncryptionContext *ctx, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx_cipher = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx_cipher, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv)) {
        fprintf(stderr, "Failed to initialize encryption context\n");
        exit(EXIT_FAILURE);
    }
    int len;
    if (!EVP_EncryptUpdate(ctx_cipher, ciphertext, &len, plaintext, plaintext_len)) {
        fprintf(stderr, "Encryption failed\n");
        EVP_CIPHER_CTX_free(ctx_cipher);
        exit(EXIT_FAILURE);
    }
    int ciphertext_len = len;
    if (!EVP_EncryptFinal_ex(ctx_cipher, ciphertext + len, &len)) {
        fprintf(stderr, "Encryption finalization failed\n");
        EVP_CIPHER_CTX_free(ctx_cipher);
        exit(EXIT_FAILURE);
    }
    ciphertext_len += len;
    EVP_CIPHER_CTX_free(ctx_cipher);
}

void decrypt(const unsigned char *ciphertext, int ciphertext_len, const EncryptionContext *ctx, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx_cipher = EVP_CIPHER_CTX_new();
    if (!EVP_DecryptInit_ex(ctx_cipher, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv)) {
        fprintf(stderr, "Failed to initialize decryption context\n");
        exit(EXIT_FAILURE);
    }
    int len;
    if (!EVP_DecryptUpdate(ctx_cipher, plaintext, &len, ciphertext, ciphertext_len)) {
        fprintf(stderr, "Decryption failed\n");
        EVP_CIPHER_CTX_free(ctx_cipher);
        exit(EXIT_FAILURE);
    }
    int plaintext_len = len;
    if (!EVP_DecryptFinal_ex(ctx_cipher, plaintext + len, &len)) {
        fprintf(stderr, "Decryption finalization failed\n");
        EVP_CIPHER_CTX_free(ctx_cipher);
        exit(EXIT_FAILURE);
    }
    plaintext_len += len;
    plaintext[plaintext_len] = '\0';
    EVP_CIPHER_CTX_free(ctx_cipher);
}

void hmac_sha256(const unsigned char *data, int data_len, const unsigned char *key, int key_len, unsigned char *output) {
    HMAC(EVP_sha256(), key, key_len, data, data_len, output, NULL);
}

int main() {
    EncryptionContext ctx;
    generate_key(ctx.key, sizeof(ctx.key), "password");

    const char *plaintext = "Hello, world!";
    int plaintext_len = strlen(plaintext);

    unsigned char ciphertext[plaintext_len + AES_BLOCK_SIZE];
    encrypt((const unsigned char *)plaintext, plaintext_len, &ctx, ciphertext);

    unsigned char decryptedtext[plaintext_len];
    decrypt(ciphertext, plaintext_len, &ctx, decryptedtext);

    unsigned char hmac[AES_BLOCK_SIZE];
    hmac_sha256(ciphertext, plaintext_len, ctx.key, sizeof(ctx.key), hmac);

    printf("Original: %s\n", plaintext);
    printf("Decrypted: %s\n", decryptedtext);
    printf("HMAC: ");
    for (int i = 0; i < AES_BLOCK_SIZE; i++) {
        printf("%02x", hmac[i]);
    }
    printf("\n");

    return 0;
}
