#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>

class Task {
public:
    int priority;
    std::string payload;
    size_t size;

    Task(int p, std::string pay, size_t s) : priority(p), payload(pay), size(s) {}
};

class WorkerNode {
public:
    void executeTask(const Task& task) {
        // Simulate task execution
        std::cout << "Executing task: Priority - " << task.priority 
                  << ", Payload Size - " << task.size << std::endl;
        std::this_thread::sleep_for(std::chrono::milliseconds(100 * task.priority));
    }
};

class TaskScheduler {
private:
    std::vector<WorkerNode*> workerNodes;
    std::queue<Task> taskQueue;
    std::mutex queueMutex;
    std::condition_variable cv;
    bool running;

public:
    TaskScheduler(int numWorkers) {
        for (int i = 0; i < numWorkers; ++i) {
            workerNodes.emplace_back(new WorkerNode());
        }
        running = true;
    }

    ~TaskScheduler() {
        running = false;
        cv.notify_all();
        for (auto& node : workerNodes) {
            delete node;
        }
    }

    void submitTask(const Task& task) {
        std::lock_guard<std::mutex> lock(queueMutex);
        taskQueue.push(task);
        cv.notify_one();
    }

    void start() {
        for (auto& node : workerNodes) {
            std::thread([this, node]() {
                while (true) {
                    std::unique_lock<std::mutex> lock(queueMutex);
                    cv.wait(lock, [this] { return !taskQueue.empty() || !running; });
                    if (!running && taskQueue.empty()) break;
                    Task task = taskQueue.front();
                    taskQueue.pop();
                    lock.unlock();

                    node->executeTask(task);
                }
            }).detach();
        }
    }

    void stop() {
        running = false;
        cv.notify_all();
    }
};

int main() {
    TaskScheduler scheduler(4);

    // Submit tasks
    for (int i = 0; i < 10; ++i) {
        scheduler.submitTask(Task(i % 3, "Task" + std::to_string(i), 1024 * i));
    }

    scheduler.start();

    // Simulate some work
    std::this_thread::sleep_for(std::chrono::seconds(5));

    scheduler.stop();

    return 0;
}
