#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>

#define MAX_QUEUE_SIZE 1000
#define MAX_MESSAGE_SIZE 256

typedef struct {
    char message[MAX_MESSAGE_SIZE];
    int size;
} Message;

typedef struct {
    Message messages[MAX_QUEUE_SIZE];
    int front, rear;
    pthread_mutex_t lock;
    pthread_cond_t not_full, not_empty;
} Queue;

Queue* create_queue() {
    Queue* queue = (Queue*)malloc(sizeof(Queue));
    if (!queue) return NULL;
    queue->front = queue->rear = -1;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    return queue;
}

int enqueue(Queue* queue, Message message) {
    pthread_mutex_lock(&queue->lock);
    while ((queue->rear + 1) % MAX_QUEUE_SIZE == queue->front) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }
    if (queue->front == -1) {
        queue->front = queue->rear = 0;
    } else {
        queue->rear = (queue->rear + 1) % MAX_QUEUE_SIZE;
    }
    memcpy(queue->messages[queue->rear], message, sizeof(Message));
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int dequeue(Queue* queue, Message* message) {
    pthread_mutex_lock(&queue->lock);
    while (queue->front == -1) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }
    memcpy(message, queue->messages[queue->front], sizeof(Message));
    if (queue->front == queue->rear) {
        queue->front = queue->rear = -1;
    } else {
        queue->front = (queue->front + 1) % MAX_QUEUE_SIZE;
    }
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

void* producer(void* arg) {
    Queue* queue = (Queue*)arg;
    Message message;
    while (1) {
        // Simulate message generation
        sprintf(message.message, "Message %d", rand() % 100);
        message.size = strlen(message.message) + 1;
        enqueue(queue, message);
        sleep(1); // Simulate time taken to produce messages
    }
    return NULL;
}

void* consumer(void* arg) {
    Queue* queue = (Queue*)arg;
    Message message;
    while (1) {
        dequeue(queue, &message);
        printf("Consumed: %s\n", message.message);
        sleep(2); // Simulate time taken to consume messages
    }
    return NULL;
}

int main() {
    Queue* queue = create_queue();
    pthread_t producer_thread, consumer_thread;

    pthread_create(&producer_thread, NULL, producer, (void*)queue);
    pthread_create(&consumer_thread, NULL, consumer, (void*)queue);

    pthread_join(producer_thread, NULL);
    pthread_join(consumer_thread, NULL);

    free(queue);
    return 0;
}
