#define MAX_NODE_SIZE 100000

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t size;
    pthread_rwlock_t lock;
    sem_t semaphore;
} LinkedList;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) return NULL;
    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void destroy_node(Node* node) {
    free(node);
}

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) return NULL;
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_rwlock_init(&list->lock, NULL);
    sem_init(&list->semaphore, 0, MAX_NODE_SIZE);
    return list;
}

void destroy_linked_list(LinkedList* list) {
    pthread_rwlock_destroy(&list->lock);
    sem_destroy(&list->semaphore);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        destroy_node(current);
        current = next;
    }
    free(list);
}

void insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    sem_wait(&list->semaphore);
    pthread_rwlock_wrlock(&list->lock);
    Node* new_node = create_node(data);
    if (new_node == NULL) {
        sem_post(&list->semaphore);
        pthread_rwlock_unlock(&list->lock);
        return;
    }
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }
    list->size++;
    pthread_rwlock_unlock(&list->lock);
    sem_post(&list->semaphore);
}

