#include <iostream>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>

class Task {
public:
    int priority;
    std::string payload;

    Task(int p, const std::string& payload) : priority(p), payload(payload) {}
};

class Worker {
public:
    void operator()(std::queue<Task>& taskQueue) {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this]{ return !taskQueue.empty(); });
            Task task = taskQueue.front();
            taskQueue.pop();
            lock.unlock();

            // Simulate task execution
            std::cout << "Worker executing task: " << task.payload << " with priority " << task.priority << std::endl;
        }
    }

private:
    std::mutex mutex_;
    std::condition_variable condition_;
};

class TaskScheduler {
public:
    void addTask(const Task& task) {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            tasks_.push(task);
        }
        condition_.notify_one();
    }

    void startWorkers(size_t numWorkers) {
        for (size_t i = 0; i < numWorkers; ++i) {
            workers_.emplace_back(tasks_);
        }
        for (auto& worker : workers_) {
            worker.join();
        }
    }

private:
    std::queue<Task> tasks_;
    std::vector<std::thread> workers_;
    std::mutex mutex_;
    std::condition_variable condition_;
};

int main() {
    TaskScheduler scheduler;
    scheduler.addTask(Task(1, "High priority task"));
    scheduler.addTask(Task(2, "Low priority task"));

    scheduler.startWorkers(2);

    return 0;
}
```

