typedef struct MemoryAllocator {
    void* pool;
    size_t poolSize;
    size_t blockSize;
    size_t freeBlockCount;
    pthread_mutex_t lock;
} MemoryAllocator;

// Initialize custom memory allocator
void initMemoryAllocator(MemoryAllocator* allocator, size_t poolSize, size_t blockSize) {
    allocator->pool = malloc(poolSize);
    allocator->poolSize = poolSize;
    allocator->blockSize = blockSize;
    allocator->freeBlockCount = poolSize / blockSize;
    pthread_mutex_init(&allocator->lock, NULL);
}

// Allocate memory from custom memory allocator
void* allocateMemory(MemoryAllocator* allocator) {
    void* block;
    pthread_mutex_lock(&allocator->lock);
    if (allocator->freeBlockCount > 0) {
        block = allocator->pool + ((allocator->poolSize / allocator->blockSize - allocator->freeBlockCount) * allocator->blockSize);
        allocator->freeBlockCount--;
    } else {
        // Handle out of memory condition
        pthread_mutex_unlock(&allocator->lock);
        return NULL;
    }
    pthread_mutex_unlock(&allocator->lock);
    return block;
}

// Free memory back to custom memory allocator
void freeMemory(MemoryAllocator* allocator, void* block) {
    pthread_mutex_lock(&allocator->lock);
    size_t index = (char*)block - (char*)allocator->pool / allocator->blockSize;
    if (index >= 0 && index < allocator->poolSize / allocator->blockSize) {
        allocator->freeBlockCount++;
    }
    pthread_mutex_unlock(&allocator->lock);
}

