#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

#define MAX_API_URL_LENGTH 256
#define MAX_INT_VALUE 1000000

typedef struct {
    int *data;
    size_t count;
    size_t capacity;
} IntegerArray;

void initialize_array(IntegerArray *arr) {
    arr->data = NULL;
    arr->count = 0;
    arr->capacity = 0;
}

void resize_array(IntegerArray *arr, size_t new_capacity) {
    int *new_data = realloc(arr->data, new_capacity * sizeof(int));
    if (new_data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    arr->data = new_data;
    arr->capacity = new_capacity;
}

void add_to_array(IntegerArray *arr, int value) {
    if (arr->count >= arr->capacity) {
        resize_array(arr, arr->capacity == 0 ? 1 : arr->capacity * 2);
    }
    arr->data[arr->count++] = value;
}

void free_array(IntegerArray *arr) {
    free(arr->data);
    arr->data = NULL;
    arr->count = 0;
    arr->capacity = 0;
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    IntegerArray *array = (IntegerArray *)userp;
    size_t total_size = size * nmemb;
    int value;

    if (sscanf((char *)contents, "%d", &value) == 1) {
        add_to_array(array, value);
    }

    return total_size;
}

int fetch_and_store_integers(const char *api_url, IntegerArray *array) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, api_url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, array);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return -1;
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    return 0;
}

void print_median(IntegerArray *array) {
    if (array->count == 0) {
        printf("No data to calculate median.\n");
        return;
    }

    qsort(array->data, array->count, sizeof(int), (int (*)(const void *, const void *))strcmp);
    double median;

    if (array->count % 2 == 0) {
        median = (array->data[array->count / 2 - 1] + array->data[array->count / 2]) / 2.0;
    } else {
        median = array->data[array->count / 2];
    }

    printf("Median: %.2f\n", median);
}

int main() {
    IntegerArray integers;
    initialize_array(&integers);

    const char *api_url = "https://api.example.com/numbers";
    if (fetch_and_store_integers(api_url, &integers) == 0) {
        print_median(&integers);
    }

    free_array(&integers);
    return 0;
}
