std::string decryptMessage(const std::string& base64EncodedMessage, const std::string& desKey) {
    // Base64 decoding
    int decodedLength = base64DecodedLength(base64EncodedMessage);
    unsigned char* decodedBuffer = new unsigned char[decodedLength];
    base64Decode(decodedBuffer, decodedLength, base64EncodedMessage);

    // Triple DES decryption
    unsigned char desKeyBytes[24];
    convertToDESKey(desKey, desKeyBytes);

    DES_key_schedule keySchedule;
    DES_set_odd_parity((DES_cblock*)desKeyBytes);
    DES_set_key_checked((DES_cblock*)desKeyBytes, &keySchedule);

    int blockSize = 8; // Triple DES block size
    unsigned char* outputBuffer = new unsigned char[decodedLength];
    for (int i = 0; i < decodedLength; i += blockSize) {
        DES_ede3_ecb_encrypt((DES_cblock*)(decodedBuffer + i), (DES_cblock*)(outputBuffer + i), &keySchedule, &keySchedule, &keySchedule, DES_DECRYPT);
    }

    // Convert decrypted buffer to string and clean up
    std::string decryptedMessage(reinterpret_cast<char*>(outputBuffer), decodedLength);
    delete[] outputBuffer;
    delete[] decodedBuffer;

    return decryptedMessage;
}

