    Message *msg = (Message *)custom_malloc(sizeof(Message));
    if (msg == NULL) {
        handle_memory_failure();
        return NULL;
    }
    msg->data = (char *)custom_malloc(length);
    if (msg->data == NULL) {
        custom_free(msg);
        handle_memory_failure();
        return NULL;
    }
    memcpy(msg->data, data, length);
    msg->length = length;
    return msg;
}

void deserialize_message(Message *msg, char **data, size_t *length) {
    *data = (char *)custom_malloc(msg->length);
    if (*data == NULL) {
        handle_memory_failure();
        return;
    }
    memcpy(*data, msg->data, msg->length);
    *length = msg->length;
}

// Example usage
