    const char *original_data = "Hello, World!";
    size_t data_length = strlen(original_data);

    // Serialize the message
    Message *serialized_msg = serialize_message(original_data, data_length);
    if (serialized_msg == NULL) {
        fprintf(stderr, "Failed to serialize message.\n");
        return EXIT_FAILURE;
    }

    // Deserialize the message
    char *deserialized_data;
    size_t deserialized_length;
    deserialize_message(serialized_msg, &deserialized_data, &deserialized_length);

    if (deserialized_data != NULL) {
        printf("Deserialized message: %.*s\n", (int)deserialized_length, deserialized_data);
        custom_free(deserialized_data);
    }

    // Free the serialized message
