};

// Define a class for managing concurrent UE information processing
class NetworkIndicatorManager {
private:
    std::queue<NFAPI_CRC_INDICATION_PDU_T> taskQueue;
    std::vector<std::thread> workers;
    std::mutex queueMutex;
    std::condition_variable condition;
    std::atomic<bool> stopFlag;
    pqxx::connection* dbConnection;

public:
    NetworkIndicatorManager(size_t numThreads) : stopFlag(false), dbConnection(nullptr) {
        // Initialize worker threads
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back(&NetworkIndicatorManager::workerThread, this);
        }
    }

    ~NetworkIndicatorManager() {
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            stopFlag = true;
        }
        condition.notify_all();
        for (auto& worker : workers) {
