using System;
using System.Diagnostics;

public class SiteManager
{
    public string ManageSite(string directoryPath)
    {
        if (!Directory.Exists(directoryPath))
        {
            return null;
        }

        string configFilePath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(configFilePath))
        {
            return null;
        }

        try
        {
            ProcessStartInfo startInfo = new ProcessStartInfo
            {
                FileName = "dotnet",
                Arguments = $"run --project {directoryPath}",
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            using (Process process = new Process { StartInfo = startInfo })
            {
                process.Start();

                string output = process.StandardOutput.ReadToEnd();
                string error = process.StandardError.ReadToEnd();

                process.WaitForExit();

                if (!string.IsNullOrEmpty(error))
                {
                    throw new Exception($"Site startup failed with errors: {error}");
                }

                return output;
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Failed to manage site in directory '{directoryPath}': {ex.Message}");
            return null;
        }
    }
}
