function findMatchingElements(root, selector, testFunction) {
    const matches = [];
    const stack = [root];
    while (stack.length > 0) {
        const node = stack.pop();
        if (node.nodeType === Node.ELEMENT_NODE && testFunction(node)) {
            matches.push(node);
        }
        for (let i = node.childNodes.length - 1; i >= 0; i--) {
            stack.push(node.childNodes[i]);
        }
    }
    return matches;
}
