use hyper::{Body, Client, Method, Request, Uri};
use hyper_tls::HttpsConnector;
use tokio::sync::mpsc;
use tower_http::{
    trace::{TraceLayer, DefaultMakeSpan},
    limit::{ConcurrencyLimitLayer, ThrottleLayer},
    retry::{RetryLayer, RetryPolicy},
};
use std::{
    time::{Duration, Instant},
    sync::Arc,
};

#[derive(Clone)]
struct HttpClient {
    client: Client<HttpsConnector>,
}

impl HttpClient {
    async fn new() -> Self {
        let https = HttpsConnector::new();
        let client = Client::builder().build::<_, Body>(https);
        Self { client }
    }

    async fn request(
        &self,
        method: Method,
        uri: Uri,
        headers: hyper::header::HeaderMap,
        body: Option<hyper::Body>,
    ) -> Result<hyper::Response<Body>, Box<dyn std::error::Error>> {
        let mut req = Request::builder()
            .method(method)
            .uri(uri)
            .headers(headers);

        if let Some(body) = body {
            req = req.body(body)?;
        }

        self.client.request(req).await
    }
}

#[derive(Clone)]
struct Config {
    max_concurrency: usize,
    retry_policy: Arc<RetryPolicy>,
}

impl Config {
    fn new(max_concurrency: usize, retry_policy: Arc<RetryPolicy>) -> Self {
        Self {
            max_concurrency,
            retry_policy,
        }
    }

    async fn create_client(&self) -> HttpClient {
        let client = Client::builder()
            .layer(ConcurrencyLimitLayer::new(self.max_concurrency))
            .layer(RetryLayer::new(self.retry_policy.clone()))
            .build::<_, Body>(HttpsConnector::new());

        HttpClient { client }
    }
}

#[tokio::main]
async fn main() {
    let config = Config::new(
        10_000,
        Arc::new(RetryPolicy::exponential_backoff(Duration::from_millis(500))),
    );

    let client = config.create_client().await;

    let uri = Uri::from_static("https://example.com/api");
    let method = Method::GET;
    let headers = hyper::header::HeaderMap::new();
    let body = None;

    match client.request(method, uri, headers, body).await {
        Ok(response) => println!("Response: {:?}", response),
        Err(e) => eprintln!("Error: {:?}", e),
    }
}
