# Define the SessionManager class
class SessionManager:
    def __init__(self):
        self.sessions = {}
        self.circuit_breaker_state = 'closed'
        self.retry_attempts = 0

    def create_session(self, user_id, storage_option):
        if user_id in self.sessions:
            return "Session already exists"
        session_id = generate_unique_session_id()
        self.sessions[session_id] = {
            'user_id': user_id,
            'storage_option': storage_option,
            'last_accessed': time.time(),
            'is_active': True
        }
        return session_id

    def get_session(self, session_id):
        if session_id in self.sessions:
            session = self.sessions[session_id]
            if not session['is_active']:
                return "Session inactive"
            session['last_accessed'] = time.time()
            return session
        return "Session not found"

    def update_session(self, session_id, data):
        if session_id in self.sessions:
            session = self.sessions[session_id]
            session.update(data)
            return "Session updated"
        return "Session not found"

    def delete_session(self, session_id):
        if session_id in self.sessions:
            del self.sessions[session_id]
            return "Session deleted"
        return "Session not found"

    def handle_external_api_call(self, api_url, payload):
        try:
            response = make_request(api_url, payload)
            return response
        except ExternalAPIError as e:
            if self.circuit_breaker_state == 'closed':
                self.retry_attempts += 1
                if self.retry_attempts >= MAX_RETRIES:
                    self.circuit_breaker_state = 'open'
                    time.sleep(EXPONENTIAL_BACKOFF_TIME * (2 ** self.retry_attempts))
                else:
                    return self.handle_external_api_call(api_url, payload)
            else:
                raise CircuitBreakerOpenException("Circuit breaker open")
