class PasswordUpdateService {
    private $db;
    private $authProviders = [];
    private $loggingSystem;
    private $passwordStrengthChecker;
    private $messageQueue;

    public function __construct($db, $authProviders, $loggingSystem, $passwordStrengthChecker, $messageQueue) {
        $this->db = $db;
        $this->authProviders = $authProviders;
        $this->loggingSystem = $loggingSystem;
        $this->passwordStrengthChecker = $passwordStrengthChecker;
        $this->messageQueue = $messageQueue;
    }

    public function updatePassword($userId, $newPassword) {
        // Validate password strength
        if (!$this->isPasswordStrong($newPassword)) {
            $this->log("Password does not meet the required strength criteria.", $userId);
            throw new Exception("Invalid password.");
        }

        // Check for consecutive repeating characters
        if ($this->hasConsecutiveRepeatingCharacters($newPassword)) {
            $this->log("Password contains consecutive repeating characters.", $userId);
            throw new Exception("Invalid password.");
        }

        // Enforce multi-factor authentication
        $mfaVerified = $this->verifyMFA($userId);
        if (!$mfaVerified) {
            $this->log("Multi-factor authentication failed.", $userId);
            throw new Exception("Failed to verify identity.");
        }

        // Update password in database asynchronously
        $this->messageQueue->enqueue(['type' => 'UPDATE_PASSWORD', 'data' => ['user_id' => $userId, 'new_password' => $newPassword]]);

        $this->log("Password update request enqueued.", $userId);
    }

    private function isPasswordStrong($password) {
        // Custom password strength policy implementation
        return strlen($password) >= 12 &&
               preg_match('/[a-z]/', $password) > 0 &&
               preg_match('/[A-Z]/', $password) > 0 &&
               preg_match('/[0-9]/', $password) > 0 &&
               preg_match('/[^a-zA-Z0-9]/', $password) > 0;
    }

    private function hasConsecutiveRepeatingCharacters($password) {
        for ($i = 0; $i < strlen($password) - 1; $i++) {
