using boost::asio::ip::tcp;

class DataReceiver {
public:
    DataReceiver(boost::asio::io_context& io_context, short port)
        : acceptor_(io_context, tcp::endpoint(tcp::v4(), port)) {
        start_accept();
    }

private:
    void start_accept() {
        auto new_socket = std::make_shared<tcp::socket>(acceptor_.get_executor().context());
        acceptor_.async_accept(*new_socket, [this, new_socket](const boost::system::error_code& error) {
            if (!error) {
                // Handle data reception
                handle_data(*new_socket);
            }
            start_accept();
        });
    }

    void handle_data(tcp::socket& socket) {
        // Implement data parsing and processing logic here
    }

    tcp::acceptor acceptor_;
};
