    useNewUrlParser: true,
    useUnifiedTopology: true,
    serverSelectionTimeoutMS: 5000,
});

const db = mongoose.connection;
db.on('error', console.error.bind(console, 'connection error:'));
db.once('open', () => {
    console.log('Connected to MongoDB');
});

// Kafka Producer
const client = new kafka.KafkaClient({ kafkaHost: 'localhost:9092' });
const producer = new kafka.HighLevelProducer(client);

producer.on('ready', () => {
    console.log('Kafka producer is ready');
});

producer.on('error', (err) => {
    console.error('Error in Kafka producer:', err);
});

// Route to receive IoT data
app.post('/data', async (req, res) => {
    const { deviceId, timestamp, data } = req.body;

    try {
        // Validate and sanitize data

        // Save data to MongoDB
        const newData = new Data({ deviceId, timestamp, data });
        await newData.save();

        // Send data to Kafka
        producer.send([{ topic: 'iot-data', messages: JSON.stringify(newData) }], (err, result) => {
            if (err) {
                console.error('Error sending message to Kafka:', err);
                res.status(500).send('Internal Server Error');
            } else {
                res.status(201).send('Data received and processed successfully');
            }
        });
    } catch (error) {
        console.error('Error processing data:', error);
        res.status(400).send('Bad Request');
    }
});

// Start server
app.listen(port, () => {
    console.log(`Server is running on port ${port}`);
});
