from flask import Flask, request, jsonify
from requests import get, post, put, delete
from werkzeug.middleware.proxy_fix import ProxyFix

app = Flask(__name__)
app.wsgi_app = ProxyFix(app.wsgi_app, x_for=1, x_proto=1, x_host=1, x_prefix=1)

# Define a dictionary to hold service mappings
service_map = {
    "api1": "http://service1:5001",
    "api2": "http://service2:5002"
}

# Middleware for enforcing security policies
def secure_request(func):
    def wrapper(*args, **kwargs):
        # Add your security logic here (e.g., authentication, authorization)
        return func(*args, **kwargs)
    return wrapper

@app.route('/<service_name>', methods=['GET', 'POST', 'PUT', 'DELETE'])
@secure_request
def route_to_service(service_name):
    if service_name in service_map:
        url = f"{service_map[service_name]}/{request.path[len(service_name):]}"
        method = request.method.lower()

        # Handle different HTTP methods
        if method == 'get':
            response = get(url, headers=request.headers)
        elif method == 'post':
            response = post(url, json=request.json, headers=request.headers)
        elif method == 'put':
            response = put(url, json=request.json, headers=request.headers)
        elif method == 'delete':
            response = delete(url, headers=request.headers)

        # Transform and return the response
        transformed_response = transform_response(response)
        return jsonify(transformed_response), response.status_code
    else:
        return jsonify({"error": "Service not found"}), 404

# Define a function to transform responses (e.g., data formatting, encryption)
def transform_response(response):
    # Add your transformation logic here
    transformed_data = response.json()  # Example: No transformation
    return transformed_data

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
```

This code sets up a basic Flask application that acts as an API gateway. It routes requests to different microservices based on the service name provided in the URL path. The `secure_request` decorator can be expanded with security policies as needed. The `transform_response` function is a placeholder for any necessary transformations of responses from microservices, such as data formatting or encryption.

For more advanced features like load balancing, caching, and integration with legacy systems, you would need to extend this application using additional libraries and techniques, such as those provided by frameworks like Flask-RESTful, Redis for caching, or custom middleware.']

