class DataProcessor {
    private ConcurrentBag<string> csvFiles;
    private ICryptoTransform decryptor;
    private IRealTimeDataIngestionService ingestionService;
    private IConfigurationService configService;
    private IMemoryPoolAllocator memoryAllocator;
