    public DataProcessor() {
        csvFiles = new ConcurrentBag<string>();
        decryptor = CreateDecryptor();
        ingestionService = new RealTimeDataIngestionService();
        configService = new ConfigurationService();
        memoryAllocator = new MemoryPoolAllocator();
        logger = new Logger();
        mlModel = new MLModel();
        noSqlDB = new NoSQLDatabase();
        cache = new DistributedCache();
        iamService = new IAMService();
    }

    private ICryptoTransform CreateDecryptor() {
        var key = Convert.FromBase64String(configService.GetTripleDESKey());
        var iv = Convert.FromBase64String(configService.GetTripleDESIV());
        return TripleDES.Create().CreateDecryptor(key, iv);
    }

    public async Task ProcessDataAsync() {
        while (true) {
            try {
                var csvFile = await configService.GetNextCSVFileAsync();
                if (csvFile == null) break;

                var data = File.ReadLines(csvFile)
                               .Select(line => Convert.FromBase64String(line))
                               .Select(decryptor.TransformFinalBlock)
                               .ToArray();

                ingestionService.IngestData(data);
                await configService.UpdateLastProcessedTimeAsync(csvFile);

                // Additional processing and monitoring logic here
            } catch (Exception ex) {
                logger.LogError(ex.Message, ex);
            }
        }
