using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Distributed;
using Polly;

[ApiController]
[Route("api/[controller]")]
public class HashServiceController : ControllerBase
{
    private readonly IDistributedCache _cache;
    private readonly HttpClient _authApiClient;
    private readonly AsyncCircuitBreakerPolicy _circuitBreakerPolicy;

    public HashServiceController(IDistributedCache cache, HttpClient authApiClient)
    {
        _cache = cache;
        _authApiClient = authApiClient;

        var policyBuilder = Policy
            .Handle<HttpRequestException>()
            .Or<TaskCanceledException>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

        _circuitBreakerPolicy = policyBuilder.CircuitBreakerAsync(
            onBreak: (exception, breakDuration) =>
            {
                // Log circuit breaker open
            },
            onReset: () =>
            {
                // Log circuit breaker closed
            });
    }

    [HttpPost("hash")]
    public async Task<IActionResult> ComputeHash(string input)
    {
        if (string.IsNullOrEmpty(input))
            return BadRequest("Input cannot be null or empty.");

        var hashKey = $"MD5:{input}";
        var cachedHash = await _cache.GetStringAsync(hashKey);

        if (cachedHash != null)
            return Ok(cachedHash);

        using (var md5 = MD5.Create())
        {
            var hashBytes = md5.ComputeHash(System.Text.Encoding.UTF8.GetBytes(input));
            cachedHash = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
        }

        await _cache.SetStringAsync(hashKey, cachedHash, new DistributedCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10)
        });

        return Ok(cachedHash);
    }

    [HttpGet("invalidate")]
    public async Task<IActionResult> InvalidateHash(string input)
    {
        if (string.IsNullOrEmpty(input))
            return BadRequest("Input cannot be null or empty.");

        var hashKey = $"MD5:{input}";
        await _cache.RemoveAsync(hashKey);

        // Notify downstream systems
        await NotifyDownstreamSystemsOfInvalidation(input);

        return Ok();
    }

    private async Task NotifyDownstreamSystemsOfInvalidation(string input)
    {
        // Implementation depends on the downstream system's API
    }
}

// Program.cs for dependency injection and configuration
public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        services.AddControllers();

        services.AddDistributedMemoryCache();
        services.AddScoped<HttpClient>(provider => new HttpClient { BaseAddress = new Uri("https://authapi.com/") });

        services.AddHttpClient("AuthApi", client =>
        {
            client.DefaultRequestHeaders.Accept.Clear();
            client.DefaultRequestHeaders.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));
        });

        services.AddResiliencePipeline("hash-service-pipeline")
            .AddCircuitBreaker(c => c
                .WithPolicyName("circuit-breaker")
                .WithFailureThreshold(5, TimeSpan.FromSeconds(10))
                .WithDurationOfHalfOpenState(TimeSpan.FromSeconds(30))
                .OnBroken(async (context) =>
                {
                    // Log circuit breaker open
                })
                .OnClosed(async (context) =>
                {
                    // Log circuit breaker closed
                }))
            .AddRateLimiter(l => l
                .WithPolicyName("rate-limiter")
                .WithQueueLimit(10)
                .WithReplenishmentPeriod(TimeSpan.FromSeconds(1))
                .WithAvailableTokens(2));

        services.AddControllers()
            .AddResilienceHttpClients();
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        if (env.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
        }

        app.UseRouting();

        app.UseEndpoints(endpoints =>
        {
            endpoints.MapControllers();
        });
    }
}
