using System;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;

public interface IEncryptionService
{
    Task<string> EncryptDataAsync(Stream data, string key);
    Task<Stream> DecryptDataAsync(string encryptedData, string key);
}

public class EncryptionService : IEncryptionService
{
    private readonly HttpClient _httpClient;
    private byte[] _encryptionKey;

    public EncryptionService(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public void Configure(string encryptionKey)
    {
        _encryptionKey = Convert.FromBase64String(encryptionKey);
    }

    public async Task<string> EncryptDataAsync(Stream data, string key)
    {
        using (var memoryStream = new MemoryStream())
        {
            await data.CopyToAsync(memoryStream);
            var aes = Aes.Create();
            aes.Key = Convert.FromBase64String(key);
            aes.Mode = CipherMode.GCM;
            aes.Padding = PaddingMode.PKCS7;

            using (var cryptoStream = new CryptoStream(memoryStream, aes.CreateEncryptor(), CryptoStreamMode.Write))
            {
                await data.CopyToAsync(cryptoStream);
            }

            return Convert.ToBase64String(memoryStream.ToArray());
        }
    }

    public async Task<Stream> DecryptDataAsync(string encryptedData, string key)
    {
        var aes = Aes.Create();
        aes.Key = Convert.FromBase64String(key);
        aes.Mode = CipherMode.GCM;
        aes.Padding = PaddingMode.PKCS7;

        using (var memoryStream = new MemoryStream(Convert.FromBase64String(encryptedData)))
        using (var cryptoStream = new CryptoStream(memoryStream, aes.CreateDecryptor(), CryptoStreamMode.Read))
        {
            return cryptoStream;
        }
    }

    public async Task<string> CallExternalApiAsync(string endpoint)
    {
        var response = await _httpClient.GetAsync(endpoint);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync();
    }
}

public class EncryptionServiceTests
{
    private readonly IEncryptionService _encryptionService;

    public EncryptionServiceTests()
    {
        _encryptionService = new EncryptionService(new HttpClient());
    }

    [Fact]
    public async Task EncryptDataAsync_ShouldEncryptDataCorrectly()
    {
        var data = "Hello, World!";
        var key = Convert.ToBase64String(Encoding.UTF8.GetBytes("0123456789abcdef"));

        var encryptedData = await _encryptionService.EncryptDataAsync(new MemoryStream(Encoding.UTF8.GetBytes(data)), key);
        Assert.NotEmpty(encryptedData);
    }

    [Fact]
    public async Task DecryptDataAsync_ShouldDecryptDataCorrectly()
    {
        var data = "Hello, World!";
        var key = Convert.ToBase64String(Encoding.UTF8.GetBytes("0123456789abcdef"));

        var encryptedData = await _encryptionService.EncryptDataAsync(new MemoryStream(Encoding.UTF8.GetBytes(data)), key);
        using (var decryptedStream = await _encryptionService.DecryptDataAsync(encryptedData, key))
        using (var reader = new StreamReader(decryptedStream))
        {
            var decryptedData = reader.ReadToEnd();
            Assert.Equal(data, decryptedData);
        }
    }

    [Fact]
    public async Task CallExternalApiAsync_ShouldCallApiCorrectly()
    {
        var endpoint = "https://api.example.com/data";
        var result = await _encryptionService.CallExternalApiAsync(endpoint);
        Assert.NotEmpty(result);
    }
}
