import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.concurrent.ConcurrentHashMap;

public class ObjectDeserializationService {

    private final ConcurrentHashMap<String, Class<?>> classCache = new ConcurrentHashMap<>();
    private final RemoteClassRegistrationService registrationService;

    public ObjectDeserializationService(RemoteClassRegistrationService registrationService) {
        this.registrationService = registrationService;
    }

    public <T> T deserialize(byte[] byteArray, String className) throws IOException, ClassNotFoundException {
        try {
            Class<?> clazz = classCache.get(className);
            if (clazz == null) {
                clazz = registrationService.getClassDefinition(className);
                classCache.putIfAbsent(className, clazz);
            }
            ByteArrayInputStream bis = new ByteArrayInputStream(byteArray);
            ObjectInputStream ois = new SecureObjectInputStream(bis);
            T deserializedObject = (T) ois.readObject();
            return deserializedObject;
        } catch (Exception e) {
            logError(className, "Deserialization failed", e);
            throw new IOException("Deserialization error", e);
        }
    }

    private void logError(String className, String message, Exception e) {
        // Log the error with details including timestamp and stack trace
    }

    public static class SecureObjectInputStream extends ObjectInputStream {

        public SecureObjectInputStream(byte[] buffer) throws IOException {
            super(new ByteArrayInputStream(buffer));
        }

        @Override
        protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
            // Add security checks here to detect common deserialization vulnerabilities
            return super.resolveClass(desc);
        }
    }
}
