from fastapi import FastAPI, WebSocket, Depends, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel
import asyncio
import json

app = FastAPI()

# CORS configuration to allow cross-origin requests from any origin
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

# In-memory document storage
documents = {}

class Document(BaseModel):
    content: str

@app.post("/documents/{document_id}")
async def create_document(document_id: str, document: Document):
    if document_id in documents:
        raise HTTPException(status_code=409, detail="Document already exists")
    documents[document_id] = document.content
    return {"message": "Document created"}

@app.get("/documents/{document_id}")
async def read_document(document_id: str):
    if document_id not in documents:
        raise HTTPException(status_code=404, detail="Document not found")
    return {"content": documents[document_id]}

class DocumentUpdate(BaseModel):
    content: str

@app.websocket("/documents/{document_id}/update")
async def update_document(websocket: WebSocket, document_id: str, data: DocumentUpdate):
    await websocket.accept()
    try:
        while True:
            new_content = data.content
            documents[document_id] = new_content
            await asyncio.sleep(0.1)  # Simulate processing time
            message = {
                "type": "update",
                "content": new_content
            }
            await websocket.send_json(message)
    except WebSocketDisconnect:
        pass

@app.get("/documents/{document_id}/status")
async def document_status(document_id: str):
    if document_id not in documents:
        raise HTTPException(status_code=404, detail="Document not found")
    return {"message": "Document is active"}

# Example usage
if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)
