const express = require('express');
const bodyParser = require('body-parser');
const redis = require('redis');
const bcrypt = require('bcrypt');
const axios = require('axios');
const rateLimit = require('express-rate-limit');
const CircuitBreaker = require('opossum');

const app = express();
app.use(bodyParser.json());

// Redis setup for distributed locking
const lockClient = redis.createClient({ url: 'redis://localhost' });

// Multi-tenant password management API integration
const passwordAPIUrl = 'https://password-manager-api.com/encrypt';

// Circuit breaker configuration
const options = {
  timeout: 3000,
  errorThresholdPercentage: 50,
  resetTimeout: 60 * 1000,
};
const circuitBreaker = new CircuitBreaker(axios, options);

// Rate limiting setup
const limiter = rateLimit({
  windowMs: 1 * 60 * 1000, // 1 minute
  max: 100,
});

app.use(limiter);

// API call caching
const cache = require('memory-cache');
const expireTime = 3600; // Cache for 1 hour

app.post('/update-config', async (req, res) => {
  const { tenantId, config } = req.body;

  try {
    // Acquire lock
    await new Promise((resolve, reject) => {
      lockClient.setnx(`lock:${tenantId}`, 'locked', redis.print);
      if (lockClient.get(`lock:${tenantId}`) === 'locked') {
        resolve();
      } else {
        lockClient.expire(`lock:${tenantId}`, 10); // Expire after 10 seconds
        reject(new Error('Resource locked'));
      }
    });

    // Encrypt sensitive data
    const encryptedConfig = await encryptSensitiveData(config, tenantId);

    // Update configuration in database
    await updateDatabase(tenantId, encryptedConfig);

    res.status(200).send('Configuration updated successfully');

  } catch (error) {
    res.status(500).send('Failed to update configuration');
  } finally {
    // Release lock
    lockClient.del(`lock:${tenantId}`);
  }
});

async function encryptSensitiveData(config, tenantId) {
  const encryptedCredentials = {};

  for (const key in config) {
    if (key.includes('password') || key.includes('secret')) {
      encryptedCredentials[key] = await circuitBreaker.execute(() => 
        axios.post(passwordAPIUrl, { data: config[key], tenantId })
          .then(response => response.data)
          .catch(error => {
            // Fallback to local encryption
            return bcrypt.hashSync(config[key], 10);
          })
      );
    } else {
      encryptedCredentials[key] = config[key];
    }
  }

  return encryptedCredentials;
}

async function updateDatabase(tenantId, config) {
  // Simulate database update
  console.log(`Updating configuration for tenant ${tenantId}:`, config);
}

app.listen(3000, () => {
  console.log('Microservice is running on port 3000');
});
```

