use std::env;
use std::fs::{self, DirEntry};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use tokio::sync::mpsc;
use tokio::task;

#[derive(Debug)]
enum Error {
    EnvVarMissing,
    InvalidDirName,
    ApiError(String),
    IOError(std::io::Error),
}

struct DirectoryManager {
    dir_path: PathBuf,
    api_key: String,
    log_url: String,
    api_lock: Arc<Mutex<()>>,
    log_lock: Arc<Mutex<()>>,
    tx: mpsc::Sender<String>,
}

impl DirectoryManager {
    fn new() -> Result<Self, Error> {
        let dir_path = env::var("DIRECTORY_PATH").map_err(|_| Error::EnvVarMissing)?;
        let api_key = env::var("API_KEY").map_err(|_| Error::EnvVarMissing)?;
        let log_url = env::var("LOG_URL").map_err(|_| Error::EnvVarMissing)?;

        if !dir_path.is_empty() {
            fs::create_dir_all(&dir_path).map_err(Error::IOError)?;
        } else {
            dir_path.push(format!("directory_{}", chrono::Local::now().format("%Y%m%d%H%M%S")));
            fs::create_dir_all(&dir_path).map_err(Error::IOError)?;
        }

        let (tx, rx) = mpsc::channel(10);
        tokio::spawn(Self::log_task(rx));

        Ok(DirectoryManager {
            dir_path,
            api_key,
            log_url,
            api_lock: Arc::new(Mutex::new(())),
            log_lock: Arc::new(Mutex::new(())),
            tx,
        })
    }

    async fn create_directory(&self, name: &str) -> Result<(), Error> {
        let mut lock = self.api_lock.lock().await;
        // Simulate API call
        task::sleep(Duration::from_secs(1)).await;
        if self.is_dir_name_valid(name)? {
            fs::create_dir_all(self.dir_path.join(name)).map_err(Error::IOError)?;
            self.log(format!("Directory created: {}", name))?;
        } else {
            return Err(Error::InvalidDirName);
        }
        Ok(())
    }

    async fn rotate_api_key(&self) -> Result<(), Error> {
        // Simulate API key rotation
        task::sleep(Duration::from_secs(1)).await;
        self.api_key = env::var("API_KEY").map_err(|_| Error::EnvVarMissing)?;
        self.log(format!("API key rotated"))?;
        Ok(())
    }

    async fn log(&self, message: String) -> Result<(), Error> {
        let mut lock = self.log_lock.lock().await;
        // Simulate logging to external service
        task::sleep(Duration::from_secs(1)).await;
        self.tx.send(message).await.map_err(|_| Error::IOError(std::io::ErrorKind::BrokenPipe.into()))?;
        Ok(())
    }

    fn is_dir_name_valid(&self, name: &str) -> Result<bool, Error> {
        // Simulate directory name validation
        if name.contains('\\') || name.contains('/') {
            return Err(Error::InvalidDirName);
        }
        let entries = fs::read_dir(&self.dir_path).map_err(Error::IOError)?;
        for entry in entries {
            let entry: DirEntry = entry.map_err(Error::IOError)?;
            if entry.file_name() == PathBuf::from(name) {
                return Ok(false);
            }
        }
        Ok(true)
    }

    async fn log_task(mut rx: mpsc::Receiver<String>) {
        while let Some(message) = rx.recv().await {
            // Simulate logging to external service
            task::sleep(Duration::from_secs(1)).await;
            println!("Log: {}", message);
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), Error> {
    let manager = DirectoryManager::new()?;
    manager.create_directory("test_dir").await?;
    manager.rotate_api_key().await?;
    Ok(())
}
