import json
from abc import ABC, abstractmethod
from typing import TypeVar, Generic, List, Optional

T = TypeVar('T')

class JSONSerializable(ABC):
    @abstractmethod
    def to_json(self) -> str:
        pass

    @classmethod
    @abstractmethod
    def from_json(cls: type[T], json_str: str) -> T:
        pass

class User(JSONSerializable):
    def __init__(self, id: int, name: str, email: str):
        self.id = id
        self.name = name
        self.email = email

    def to_json(self) -> str:
        return json.dumps({'id': self.id, 'name': self.name, 'email': self.email})

    @classmethod
    def from_json(cls, json_str: str) -> 'User':
        data = json.loads(json_str)
        return cls(data['id'], data['name'], data['email'])

class Product(JSONSerializable):
    def __init__(self, id: int, name: str, price: float):
        self.id = id
        self.name = name
        self.price = price

    def to_json(self) -> str:
        return json.dumps({'id': self.id, 'name': self.name, 'price': self.price})

    @classmethod
    def from_json(cls, json_str: str) -> 'Product':
        data = json.loads(json_str)
        return cls(data['id'], data['name'], data['price'])

class Order(JSONSerializable):
    def __init__(self, id: int, user_id: int, product_ids: List[int]):
        self.id = id
        self.user_id = user_id
        self.product_ids = product_ids

    def to_json(self) -> str:
        return json.dumps({'id': self.id, 'user_id': self.user_id, 'product_ids': self.product_ids})

    @classmethod
    def from_json(cls, json_str: str) -> 'Order':
        data = json.loads(json_str)
        return cls(data['id'], data['user_id'], data['product_ids'])

class Review(JSONSerializable):
    def __init__(self, id: int, product_id: int, user_id: int, rating: int, comment: Optional[str]):
        self.id = id
        self.product_id = product_id
        self.user_id = user_id
        self.rating = rating
        self.comment = comment

    def to_json(self) -> str:
        return json.dumps({'id': self.id, 'product_id': self.product_id, 'user_id': self.user_id, 'rating': self.rating, 'comment': self.comment})

    @classmethod
    def from_json(cls, json_str: str) -> 'Review':
        data = json.loads(json_str)
        return cls(data['id'], data['product_id'], data['user_id'], data['rating'], data.get('comment'))
