// Define Task structure
struct Task {
    int priority;
    std::string payload;
    size_t size;
};

// Define Worker class
class Worker {
public:
    Worker(int id) : worker_id(id), running(true) {}

    void start() {
        thread = std::thread(&Worker::run, this);
    }

    void stop() {
        running = false;
        condition.notify_all();
        if (thread.joinable()) {
            thread.join();
        }
    }

    void execute(Task& task) {
        // Simulate task execution
        std::this_thread::sleep_for(std::chrono::milliseconds(task.size * 10));
        std::cout << "Worker " << worker_id << " executed task: " << task.payload << std::endl;
    }

private:
    void run() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !tasks.empty() || !running; });

            if (!running && tasks.empty()) {
                break;
            }

            Task task = std::move(tasks.front());
            tasks.pop();

            lock.unlock();
            execute(task);
        }
    }

    int worker_id;
    std::queue<Task> tasks;
    std::thread thread;
    std::mutex mutex;
    std::condition_variable condition;
    bool running;
};

// Define Orchestrator class
class Orchestrator {
public:
    void addWorker(Worker* worker) {
        workers.push_back(worker);
    }

    void submitTask(Task task) {
        // Implement adaptive task scheduling logic here
        std::lock_guard<std::mutex> lock(mutex);
        tasks.push(task);
        condition.notify_one();
    }

private:
    std::vector<Worker*> workers;
    std::queue<Task> tasks;
    std::mutex mutex;
    std::condition_variable condition;
};

int main() {
    Orchestrator orchestrator;

    // Create and start multiple workers
    for (int i = 1; i <= 5; ++i) {
        Worker* worker = new Worker(i);
        worker->start();
        orchestrator.addWorker(worker);
    }

    // Submit tasks to the orchestrator
    Task task1 = {3, "Task payload 1", 1024};
    Task task2 = {1, "Task payload 2", 512};
    Task task3 = {2, "Task payload 3", 2048};

    orchestrator.submitTask(task1);
    orchestrator.submitTask(task2);
    orchestrator.submitTask(task3);

    // Stop workers
    for (Worker* worker : orchestrator.workers) {
        worker->stop();
        delete worker;
    }

    return 0;
}
