void serializeEvent(struct Event* event, unsigned char** buffer, size_t* bufferSize) {
    // Implement serialization logic here
    *buffer = customMalloc(*bufferSize + sizeof(time_t) + sizeof(int) + 1 + sizeof(LogDataType));
    memcpy(*buffer + *bufferSize, &event->timestamp, sizeof(time_t));
    *bufferSize += sizeof(time_t);
    memcpy(*buffer + *bufferSize, &event->eventCode, sizeof(int));
    *bufferSize += sizeof(int);

    switch (event->dataType) {
        case LOG_TYPE_INT:
            memcpy(*buffer + *bufferSize, "int", 3);
            *bufferSize += 3;
            memcpy(*buffer + *bufferSize, &event->context.intValue, sizeof(int));
            *bufferSize += sizeof(int);
            break;
        case LOG_TYPE_STRING:
            memcpy(*buffer + *bufferSize, "str", 3);
            *bufferSize += 3;
            memcpy(*buffer + *bufferSize, event->context.stringValue, strlen(event->context.stringValue) + 1);
            *bufferSize += strlen(event->context.stringValue) + 1;
            break;
        case LOG_TYPE_FLOAT:
            memcpy(*buffer + *bufferSize, "flt", 3);
            *bufferSize += 3;
            memcpy(*buffer + *bufferSize, &event->context.floatValue, sizeof(float));
            *bufferSize += sizeof(float);
            break;
    }
}

// Deserialization function
void deserializeEvent(unsigned char* buffer, size_t bufferSize, struct Event* event) {
    // Implement deserialization logic here
    memcpy(&event->timestamp, buffer, sizeof(time_t));
    buffer += sizeof(time_t);
    memcpy(&event->eventCode, buffer, sizeof(int));
    buffer += sizeof(int);

    char type[4];
    memcpy(type, buffer, 3);
    buffer += 3;

    if (strcmp(type, "int") == 0) {
        event->dataType = LOG_TYPE_INT;
        memcpy(&event->context.intValue, buffer, sizeof(int));
    } else if (strcmp(type, "str") == 0) {
        event->dataType = LOG_TYPE_STRING;
        size_t strLen = strlen((const char*)buffer) + 1;
        memcpy(event->context.stringValue, buffer, strLen);
        buffer += strLen;
    } else if (strcmp(type, "flt") == 0) {
        event->dataType = LOG_TYPE_FLOAT;
        memcpy(&event->context.floatValue, buffer, sizeof(float));
    }
}

// Concurrency and thread safety
void logEvent(struct Event* event) {
    // Implement thread-safe logging logic here
    static volatile int lock = 0;
    while (__sync_lock_test_and_set(&lock, 1)) {}
