    public static DataTableReader ProcessQuery(string connectionString, byte[] inputBytes)
    {
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            connection.Open();
            SqlCommand command = new SqlCommand("SELECT * FROM YourTable WHERE YourColumn = @Input", connection);
            command.Parameters.Add("@Input", SqlDbType.VarBinary).Value = inputBytes;

            SqlDataAdapter adapter = new SqlDataAdapter(command);
            DataTable dataTable = new DataTable();
            adapter.Fill(dataTable);

