    ImageBatch* batch = (ImageBatch*)malloc(sizeof(ImageBatch));
    batch->images = (Image**)malloc(initial_capacity * sizeof(Image*));
    batch->count = 0;
    batch->capacity = initial_capacity;
    return batch;
}

void destroy_image_batch(ImageBatch* batch) {
    for (size_t i = 0; i < batch->count; i++) {
        free(batch->images[i]->pixel_data);
        free(batch->images[i]);
    }
    free(batch->images);
    free(batch);
}

int add_image_to_batch(ImageBatch* batch, Image* image) {
    if (batch->count >= batch->capacity) {
        size_t new_capacity = batch->capacity * 2;
        Image** new_images = (Image**)realloc(batch->images, new_capacity * sizeof(Image*));
        if (!new_images) return -1;
        batch->images = new_images;
        batch->capacity = new_capacity;
    }
    batch->images[batch->count++] = image;
    return 0;
}

void process_image_batch(ImageBatch* batch, void (*process_image)(Image*)) {
    pthread_t* threads = (pthread_t*)malloc(batch->count * sizeof(pthread_t));
    for (size_t i = 0; i < batch->count; i++) {
        pthread_create(&threads[i], NULL, (void* (*)(void*))process_image, (void*)batch->images[i]);
    }
    for (size_t i = 0; i < batch->count; i++) {
