// Add an event to the log buffer
void addEvent(LogBuffer* buffer, Event event) {
    pthread_mutex_lock(&buffer->lock);
    if (buffer->size == buffer->capacity) {
        // Double the capacity or handle memory allocation failure
        buffer->capacity *= 2;
        buffer->events = realloc(buffer->events, buffer->capacity * sizeof(Event));
        if (buffer->events == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
    buffer->events[buffer->size++] = event;
    pthread_mutex_unlock(&buffer->lock);
}

// Serialize the log buffer to a binary file
void serializeLogBuffer(LogBuffer* buffer, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    fwrite(&buffer->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < buffer->size; ++i) {
        Event event = buffer->events[i];
        fwrite(&event.timestamp, sizeof(time_t), 1, file);
        fwrite(&event.event_code, sizeof(int), 1, file);
        switch (event.context.int_data) { // Assuming context.int_data is used for type
            case INT_TYPE:
                fwrite(event.context.int_data, sizeof(int), 1, file);
                break;
            case STR_TYPE:
                size_t str_len = strlen(event.context.str_data);
                fwrite(&str_len, sizeof(size_t), 1, file);
                fwrite(event.context.str_data, sizeof(char), str_len, file);
                break;
        }
    }
    fclose(file);
}

// Deserialize the log buffer from a binary file
void deserializeLogBuffer(LogBuffer* buffer, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }
    size_t size;
    fread(&size, sizeof(size_t), 1, file);
    pthread_mutex_lock(&buffer->lock);
    buffer->capacity = size;
    buffer->events = realloc(buffer->events, size * sizeof(Event));
    if (buffer->events == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < size; ++i) {
        Event* event = &buffer->events[i];
        fread(&event->timestamp, sizeof(time_t), 1, file);
        fread(&event->event_code, sizeof(int), 1, file);
        int type;
        fread(&type, sizeof(int), 1, file); // Assuming type is stored before data
        switch (type) {
            case INT_TYPE:
                fread(&event->context.int_data, sizeof(int), 1, file);
                break;
            case STR_TYPE:
                size_t str_len;
                fread(&str_len, sizeof(size_t), 1, file);
                event->context.str_data = malloc(str_len + 1);
                if (event->context.str_data == NULL) {
                    fprintf(stderr, "Memory allocation failed\n");
                    exit(EXIT_FAILURE);
                }
                fread(event->context.str_data, sizeof(char), str_len, file);
                event->context.str_data[str_len] = '\0';
                break;
        }
    }
    buffer->size = size;
    pthread_mutex_unlock(&buffer->lock);
    fclose(file);
}

// Clean up the log buffer
void cleanupLogBuffer(LogBuffer* buffer) {
    for (size_t i = 0; i < buffer->size; ++i) {
        if (buffer->events[i].context.str_data != NULL) {
            free(buffer->events[i].context.str_data);
        }
    }
    pthread_mutex_destroy(&buffer->lock);
    free(buffer->events);
}
