// Define event types
typedef enum {
    EVENT_LOGIN,
    EVENT_LOGOUT,
    EVENT_ERROR
} EventType;

// Flexible union for context data
typedef union {
    int intValue;
    char stringValue[128];
    float floatValue;
} EventContext;

// Event structure
typedef struct {
    time_t timestamp;
    EventType type;
    EventContext context;
} NetworkEvent;

// Thread-safe queue for event storage
typedef struct QueueNode {
    NetworkEvent event;
    struct QueueNode *next;
} QueueNode;

typedef struct {
    QueueNode *front, *rear;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int size;
    int max_size;
} EventQueue;

// Initialize the queue
void init_queue(EventQueue *q, int max_size) {
    q->front = q->rear = NULL;
    pthread_mutex_init(&q->mutex, NULL);
    pthread_cond_init(&q->cond, NULL);
    q->size = 0;
    q->max_size = max_size;
}

// Add an event to the queue
void enqueue_event(EventQueue *q, NetworkEvent event) {
    QueueNode *new_node = (QueueNode *)malloc(sizeof(QueueNode));
    new_node->event = event;
    new_node->next = NULL;

    pthread_mutex_lock(&q->mutex);
    if (q->size == q->max_size) {
        pthread_cond_wait(&q->cond, &q->mutex);
    }
    if (q->rear == NULL) {
        q->front = q->rear = new_node;
    } else {
        q->rear->next = new_node;
        q->rear = new_node;
    }
    q->size++;
    pthread_mutex_unlock(&q->mutex);
}

// Remove an event from the queue
NetworkEvent dequeue_event(EventQueue *q) {
    NetworkEvent event;
    pthread_mutex_lock(&q->mutex);
    while (q->front == NULL) {
        pthread_cond_wait(&q->cond, &q->mutex);
    }
    QueueNode *temp = q->front;
    event = temp->event;
    q->front = q->front->next;
    if (q->front == NULL) {
        q->rear = NULL;
    }
    free(temp);
    q->size--;
    pthread_cond_signal(&q->cond);
    pthread_mutex_unlock(&q->mutex);
    return event;
}

// Thread function to process events
void *process_events(void *arg) {
    EventQueue *q = (EventQueue *)arg;
    while (1) {
        NetworkEvent event = dequeue_event(q);
        // Process the event, e.g., send to external service
        printf("Processing event: %d - %ld\n", event.type, event.timestamp);
    }
}

int main() {
    EventQueue q;
    init_queue(&q, 100);

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, process_events, &q);

    // Simulate logging events
