        NetworkEvent event;
        event.timestamp = time(NULL);
        event.type = EVENT_LOGIN;
        sprintf(event.context.stringValue, "User logged in");
        enqueue_event(&q, event);
    }

    pthread_join(thread_id, NULL);

    return 0;
}
