typedef struct LogEntry {
    NetworkEvent event;
    struct LogEntry* next;
} LogEntry;

// Define a structure for the logging framework
typedef struct Logger {
    LogEntry* head;
    pthread_mutex_t lock;
} Logger;

// Initialize the logger
void initLogger(Logger* logger) {
    logger->head = NULL;
    pthread_mutex_init(&logger->lock, NULL);
}

// Add a log entry to the logger
void addLogEntry(Logger* logger, NetworkEvent event) {
    LogEntry* newEntry = (LogEntry*)malloc(sizeof(LogEntry));
    newEntry->event = event;
    newEntry->next = NULL;

    pthread_mutex_lock(&logger->lock);
    if (logger->head == NULL) {
        logger->head = newEntry;
    } else {
        LogEntry* temp = logger->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newEntry;
    }
    pthread_mutex_unlock(&logger->lock);
}

// Free the memory allocated for the logger
void freeLogger(Logger* logger) {
    LogEntry* current = logger->head;
    while (current != NULL) {
        LogEntry* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&logger->lock);
}
