} LogNode;

typedef struct {
    pthread_mutex_t lock;
    LogNode *head;
    LogNode *tail;
    size_t count;
} LogQueue;

void initializeLogQueue(LogQueue *queue) {
    pthread_mutex_init(&queue->lock, NULL);
    queue->head = queue->tail = NULL;
    queue->count = 0;
}

void enqueueEvent(LogQueue *queue, NetworkEvent event) {
    LogNode *newNode = (LogNode *)malloc(sizeof(LogNode));
    newNode->event = event;
    newNode->next = NULL;

    pthread_mutex_lock(&queue->lock);
    if (queue->tail == NULL) {
        queue->head = queue->tail = newNode;
    } else {
        queue->tail->next = newNode;
        queue->tail = newNode;
    }
    queue->count++;
    pthread_mutex_unlock(&queue->lock);
}

NetworkEvent dequeueEvent(LogQueue *queue) {
    NetworkEvent event = {0};
    pthread_mutex_lock(&queue->lock);
    if (queue->head != NULL) {
        LogNode *temp = queue->head;
        event = temp->event;
        queue->head = temp->next;
        free(temp);
        if (queue->head == NULL) {
            queue->tail = NULL;
        }
        queue->count--;
    }
    pthread_mutex_unlock(&queue->lock);
    return event;
}

void *logProcessingThread(void *arg) {
    LogQueue *queue = (LogQueue *)arg;
    NetworkEvent event;

    while (1) {
        event = dequeueEvent(queue);
        if (event.timestamp == 0 && event.code == INFO && event.data.s == NULL) {
            break; // Exit loop for shutdown signal
        }

