// Logging Framework Code in C

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

typedef enum { INFO, WARNING, ERROR } LogLevel;

typedef union {
    int i;
    float f;
    char* s;
} ContextData;

typedef struct {
    time_t timestamp;
    LogLevel level;
    ContextData data;
} NetworkEvent;

typedef struct {
    NetworkEvent event;
    pthread_mutex_t mutex;
} LogEntry;

typedef struct {
    LogEntry** logQueue;
    size_t front, rear, capacity, count;
    pthread_mutex_t queueMutex;
    pthread_cond_t notFull, notEmpty;
} LogQueue;

LogQueue* createLogQueue(size_t capacity) {
    LogQueue* q = (LogQueue*)malloc(sizeof(LogQueue));
    q->logQueue = (LogEntry**)calloc(capacity, sizeof(LogEntry*));
    q->capacity = capacity;
    q->front = q->rear = q->count = 0;
    pthread_mutex_init(&q->queueMutex, NULL);
    pthread_cond_init(&q->notFull, NULL);
    pthread_cond_init(&q->notEmpty, NULL);
    return q;
}

void enqueueLog(LogQueue* q, LogEntry* entry) {
    pthread_mutex_lock(&q->queueMutex);
    while (q->count == q->capacity) {
        pthread_cond_wait(&q->notFull, &q->queueMutex);
    }
    q->logQueue[q->rear] = entry;
    q->rear = (q->rear + 1) % q->capacity;
    q->count++;
    pthread_cond_signal(&q->notEmpty);
    pthread_mutex_unlock(&q->queueMutex);
}

LogEntry* dequeueLog(LogQueue* q) {
    pthread_mutex_lock(&q->queueMutex);
    while (q->count == 0) {
        pthread_cond_wait(&q->notEmpty, &q->queueMutex);
    }
    LogEntry* entry = q->logQueue[q->front];
    q->front = (q->front + 1) % q->capacity;
    q->count--;
    pthread_cond_signal(&q->notFull);
    pthread_mutex_unlock(&q->queueMutex);
    return entry;
}

void destroyLogQueue(LogQueue* q) {
    free(q->logQueue);
    pthread_mutex_destroy(&q->queueMutex);
    pthread_cond_destroy(&q->notFull);
    pthread_cond_destroy(&q->notEmpty);
    free(q);
}
