    private readonly string _connectionString;

    public LogProcessor(string connectionString)
    {
        _connectionString = connectionString;
    }

    public DataTableReader ProcessLog(byte[] logData)
    {
        using (var connection = new MySqlConnection(_connectionString))
        {
            try
            {
                connection.Open();
                var command = new MySqlCommand("INSERT INTO logs (data) VALUES (@logData)", connection);
                command.Parameters.AddWithValue("@logData", logData);

                var reader = command.ExecuteReader();
                return reader;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing log data: {ex.Message}");
                throw; // or handle the error appropriately
            }
        }
    }
}
