void init_log_queue(LogQueue *queue) {
    queue->count = 0;
    pthread_mutex_init(&queue->lock, NULL);
    sem_init(&queue->semaphore, 0, MAX_LOG_SIZE);
}

void enqueue_log(LogQueue *queue, LogLevel level, time_t timestamp, ContextData context) {
    sem_wait(&queue->semaphore);
    pthread_mutex_lock(&queue->lock);
    queue->logs[queue->count++] = (LogEvent){level, timestamp, context};
    pthread_mutex_unlock(&queue->lock);
}

void process_logs(LogQueue *queue) {
    while (1) {
        if (sem_wait(&queue->semaphore) == 0) {
            pthread_mutex_lock(&queue->lock);
            if (queue->count > 0) {
                LogEvent event = queue->logs[--queue->count];
                // Process the log event
                printf("Log: %s - %ld\n", event.level == LOG_INFO ? "INFO" : event.level == LOG_WARNING ? "WARNING" : "ERROR", event.timestamp);
            }
            pthread_mutex_unlock(&queue->lock);
        } else {
            // Handle semaphore error (e.g., timeout)
        }
    }
}

void *log_processor_thread(void *arg) {
    LogQueue *queue = (LogQueue *)arg;
    process_logs(queue);
    return NULL;
}

