// Include necessary headers
#include <mutex>
#include <unordered_map>
#include <queue>
#include <atomic>
#include <condition_variable>

// Define the CacheItem structure
struct CacheItem {
    std::string data;
    std::chrono::time_point<std::chrono::steady_clock> lastAccessed;
};

// Define the DistributedCache class
class DistributedCache {
public:
    // Constructor
    DistributedCache(size_t capacity) : capacity_(capacity), size_(0) {}

    // Retrieve an item from the cache
    CacheItem* get(const std::string& key);

    // Store an item in the cache
    void put(const std::string& key, const std::string& data);

    // Remove an item from the cache
    void remove(const std::string& key);

private:
    size_t capacity_;
    size_t size_;
    std::unordered_map<std::string, CacheItem> cache_;
    std::mutex mutex_;
    std::queue<std::string> evictionQueue_;
    std::condition_variable cv_;

    // Evict the least recently used item
    void evict();
};

// Implement the get method
CacheItem* DistributedCache::get(const std::string& key) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (cache_.find(key) == cache_.end()) return nullptr;
    CacheItem* item = &cache_[key];
    item->lastAccessed = std::chrono::steady_clock::now();
    return item;
}

// Implement the put method
void DistributedCache::put(const std::string& key, const std::string& data) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (cache_.find(key) != cache_.end()) {
        cache_[key].data = data;
        cache_[key].lastAccessed = std::chrono::steady_clock::now();
    } else {
        if (size_ >= capacity_) evict();
        cache_[key] = {data, std::chrono::steady_clock::now()};
        evictionQueue_.push(key);
        size_++;
    }
}

// Implement the remove method
void DistributedCache::remove(const std::string& key) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (cache_.find(key) != cache_.end()) {
        cache_.erase(key);
        evictionQueue_.remove(key);
        size_--;
    }
}

// Implement the evict method
void DistributedCache::evict() {
    while (!evictionQueue_.empty() && cache_.find(evictionQueue_.front()) == cache_.end()) {
        evictionQueue_.pop();
    }
    if (evictionQueue_.empty()) return;
    std::string key = evictionQueue_.front();
    cache_.erase(key);
    evictionQueue_.pop();
    size_--;
}
