// api-gateway.js

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const passport = require('passport');
const { Strategy: JwtStrategy, ExtractJwt } = require('passport-jwt');
const rateLimit = require('express-rate-limit');
const loadBalancer = require('./loadBalancer');
const serviceRegistry = require('./serviceRegistry');

const app = express();
app.use(helmet());
app.use(cors());

// JWT Authentication
const jwtOptions = {
  jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
  secretOrKey: 'your_jwt_secret',
};

passport.use(new JwtStrategy(jwtOptions, (jwt_payload, done) => {
  // Validate and find user by ID from the token payload
  if (/* user found */) {
    return done(null, user);
  } else {
    return done(null, false);
  }
}));

app.use(passport.initialize());

// Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
});

app.use(limiter);

// Dynamic Service Discovery and Routing
const routeService = (req, res, next) => {
  const serviceId = req.headers['x-service-id'];
  if (!serviceId || !serviceRegistry.has(serviceId)) {
    return res.status(404).send('Service not found');
  }
  const backendUrl = loadBalancer.getNextInstance(serviceId);
  req.backendUrl = backendUrl;
  next();
};

// Example route handling
app.get('/data', passport.authenticate('jwt', { session: false }), routeService, (req, res) => {
  const backendUrl = req.backendUrl;
  // Proxy request to the backend service
  fetch(backendUrl + '/data')
    .then(response => response.json())
    .then(data => res.json(data))
    .catch(error => res.status(500).json({ error: 'Failed to fetch data' }));
});

// Error Handling and Fault Tolerance
const errorHandler = (err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
};

app.use(errorHandler);

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`API Gateway running on port ${PORT}`);
});
