EVP_CIPHER_CTX* create_cipher_context(const char* cipher_name) {
    EVP_CIPHER* cipher = EVP_get_cipherbyname(cipher_name);
    if (cipher == NULL) {
        fprintf(stderr, "Unsupported cipher: %s\n", cipher_name);
        return NULL;
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL)) {
        fprintf(stderr, "Failed to initialize cipher\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void encrypt_data(EVP_CIPHER_CTX* ctx, const unsigned char* plaintext, int plaintext_len, unsigned char* ciphertext) {
    int len = 0;
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        fprintf(stderr, "Failed to update encryption\n");
    }

    int final_len = 0;
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &final_len)) {
        fprintf(stderr, "Failed to finalize encryption\n");
    }

    len += final_len;
}

void calculate_checksum(const unsigned char* data, size_t length, unsigned char* checksum) {
    MD5(data, length, checksum);
}
