int generateNfapiCrcIndications(int N, char *outputBuffer, size_t bufferSize) {
    if (N <= 0 || outputBuffer == NULL || bufferSize < sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return -1; // Invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T *crcIndications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crcIndications == NULL) {
        return -2; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < N; i++) {
        crcIndications[i].RX_UE_INFORMATION_TAG = rand();
        crcIndications[i].RNTI = rand() % 65535;
        crcIndications[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
    }

    size_t totalSize = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (totalSize > bufferSize) {
        free(crcIndications);
        return -3; // Buffer overflow
    }

    memcpy(outputBuffer, crcIndications, totalSize);

    free(crcIndications);
    return 0; // Success
}
