using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

public interface ILogService
{
    void Log(string message);
}

public class FileLogService : ILogService
{
    private string _filePath;

    public FileLogService(string filePath)
    {
        _filePath = filePath;
    }

    public void Log(string message)
    {
        // Implement file logging with appropriate locking and concurrency handling.
        lock (_filePath)
        {
            using (var writer = new System.IO.StreamWriter(_filePath, true))
            {
                writer.WriteLine($"{DateTime.Now}: {message}");
            }
        }
    }
}

public class ConcurrentQueueLogService : ILogService
{
    private readonly ConcurrentQueue<string> _queue;
    private readonly Task _task;
    private readonly ILogService _innerLogger;

    public ConcurrentQueueLogService(ILogService innerLogger)
    {
        _queue = new ConcurrentQueue<string>();
        _innerLogger = innerLogger;
        _task = Task.Run(() => ProcessQueue());
    }

    public void Log(string message)
    {
        _queue.Enqueue(message);
    }

    private async Task ProcessQueue()
    {
        while (true)
        {
            if (_queue.TryDequeue(out var message))
            {
                _innerLogger.Log(message);
                await Task.Delay(10); // Adjust delay based on logging frequency.
            }
            else
            {
                await Task.Delay(100); // Wait before checking the queue again.
            }
        }
    }

    public void Dispose()
    {
        _task.Dispose();
    }
}

public class DynamicRangeGenerator<T> where T : IComparable<T>
{
    private T _minValue;
    private T _maxValue;
    private Random _random;
    private ILogService _logService;

    public DynamicRangeGenerator(T minValue, T maxValue, ILogService logService)
    {
        if (minValue.CompareTo(maxValue) >= 0)
            throw new ArgumentException("Min value must be less than max value.");

        _minValue = minValue;
        _maxValue = maxValue;
        _random = new Random();
        _logService = logService;
    }

    public T GenerateRandom(bool inclusive = true)
    {
        T value;
        do
        {
            value = GenerateNextRandomValue(inclusive);
        } while (value.Equals(_minValue) && !inclusive || value.Equals(_maxValue) && !inclusive);

        _logService.Log($"Generated value: {value}, Range: {_minValue} to {_maxValue}");
        return value;
    }

    private T GenerateNextRandomValue(bool inclusive)
    {
        var min = Convert.ToDouble(_minValue);
        var max = Convert.ToDouble(_maxValue);
        var randomValue = _random.NextDouble() * (max - min) + min;

        if (typeof(T) == typeof(double))
            return (T)(object)Math.Round(randomValue, 10); // Adjust precision for floating-point types.
        else
            return (T)(object)Math.Round(randomValue);
    }

    public void SetRange(T newMinValue, T newMaxValue)
    {
        if (newMinValue.CompareTo(newMaxValue) >= 0)
            throw new ArgumentException("New min value must be less than new max value.");

        _minValue = newMinValue;
        _maxValue = newMaxValue;

        _logService.Log($"Range updated to: {_minValue} to {_maxValue}");
    }

    public void SetSeed(int seed)
    {
        _random = new Random(seed);
    }
}
