using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.NetworkInformation;
using System.Net.Sockets;
using System.Threading.Tasks;

public interface INetworkHealthMonitor
{
    void StartMonitoring();
    void StopMonitoring();
}

public class NetworkHealthMonitor : INetworkHealthMonitor
{
    private readonly Dictionary<string, Endpoint> _endpoints = new Dictionary<string, Endpoint>();
    private bool _isRunning;

    public NetworkHealthMonitor(IEnumerable<Endpoint> endpoints)
    {
        foreach (var endpoint in endpoints)
        {
            _endpoints[endpoint.Id] = endpoint;
        }
    }

    public void StartMonitoring()
    {
        _isRunning = true;
        Task.Run(() => MonitorEndpointsAsync());
    }

    public void StopMonitoring()
    {
        _isRunning = false;
    }

    private async Task MonitorEndpointsAsync()
    {
        while (_isRunning)
        {
            foreach (var endpoint in _endpoints.Values)
            {
                await CheckEndpointAsync(endpoint);
                await Task.Delay(TimeSpan.FromSeconds(endpoint.MonitoringFrequency));
            }
        }
    }

    private async Task CheckEndpointAsync(Endpoint endpoint)
    {
        try
        {
            if (endpoint.Protocol == Protocol.ICMP)
            {
                var ping = new Ping();
                var reply = await ping.SendPingAsync(endpoint.Address);
                bool isHealthy = reply.Status == IPStatus.Success;
                int latency = isHealthy ? (int)reply.RoundtripTime : -1;
                endpoint.UpdateHealth(isHealthy, latency);
            }
            else if (endpoint.Protocol == Protocol.TCP || endpoint.Protocol == Protocol.HTTP)
            {
                using (var client = new TcpClient())
                {
                    bool isHealthy = await client.ConnectAsync(endpoint.Address, endpoint.Port);
                    int latency = isHealthy ? (int)client.ReceiveTimeout : -1;
                    endpoint.UpdateHealth(isHealthy, latency);
                }
            }

            if (!endpoint.IsHealthy)
            {
                AlertService.RaiseAlert(new NetworkAlert
                {
                    EndpointId = endpoint.Id,
                    IsHealthy = endpoint.IsHealthy,
                    Latency = endpoint.Latency
                });
            }
        }
        catch (Exception ex)
        {
            // Log the exception
        }
    }
}

public class Endpoint
{
    public string Id { get; set; }
    public string Address { get; set; }
    public int Port { get; set; }
    public Protocol Protocol { get; set; }
    public int MonitoringFrequency { get; set; }

    private bool _isHealthy;
    private int _latency;

    public bool IsHealthy
    {
        get => _isHealthy;
        private set
        {
            if (_isHealthy != value)
            {
                _isHealthy = value;
                OnHealthChanged?.Invoke(this, EventArgs.Empty);
            }
        }
    }

    public int Latency { get; private set; }

    public event EventHandler HealthChanged;

    public void UpdateHealth(bool isHealthy, int latency)
    {
        IsHealthy = isHealthy;
        Latency = latency;
        HealthChanged?.Invoke(this, EventArgs.Empty);
    }
}

public enum Protocol
{
    ICMP,
    TCP,
    HTTP
}

public class NetworkAlert
{
    public string EndpointId { get; set; }
    public bool IsHealthy { get; set; }
    public int Latency { get; set; }
}

public static class AlertService
{
    public static event EventHandler<NetworkAlert> AlertRaised;

    public static void RaiseAlert(NetworkAlert alert)
    {
        AlertRaised?.Invoke(null, alert);
    }

    // Add methods to integrate with different backend services like Slack, Email, SMS
}
```

This code defines a `NetworkHealthMonitor` class that continuously assesses the health of multiple network endpoints using ICMP, TCP, and HTTP/HTTPS protocols. The `Endpoint` class represents a monitored endpoint with properties for address, port, protocol, and monitoring frequency. The system raises alerts through an alerting framework represented by the `AlertService` static class.

To use this service, you can create instances of `Endpoint` and pass them to the `NetworkHealthMonitor` constructor. Start monitoring using the `StartMonitoring` method and stop it with the `StopMonitoring` method. The `AlertRaised` event can be subscribed to handle alerts as they are raised.

This implementation provides a basic framework that can be extended with additional features such as caching, dynamic threshold adjustment, cloud-native services support, third-party tool integration, detailed logging, and automated testing.']

