    std::mutex mutex_;
    std::condition_variable cv_;
    bool running_;

public:
    DataPipeline() : running_(false) {}

    void start() {
        running_ = true;
        for (int i = 0; i < 4; ++i) {
            std::thread([this]() {
                while (true) {
                    SensorData data;
                    {
                        std::unique_lock<std::mutex> lock(mutex_);
                        cv_.wait(lock, [this] { return !queue_.empty() || !running_; });
                        if (!running_) break;
                        data = queue_.front();
                        queue_.pop();
                    }
                    process_data(data);
                }
            }).detach();
        }
    }

    void stop() {
        running_ = false;
        cv_.notify_all();
    }

    void enqueue(const SensorData& data) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(data);
        cv_.notify_one();
