// Define the structure for a state in the FSA
typedef struct State {
    int id;
    struct State* next;
} State;

// Define the structure for the finite state automaton (FSA)
typedef struct FSA {
    State* states;
    int numberOfStates;
} FSA;

// Function to add a new state to the FSA
FSA* addState(FSA* fsa, int* currentStates, int numStates, int lastState) {
    if (fsa == NULL || currentStates == NULL) {
        return NULL; // Invalid input
    }

    State* newState = (State*)malloc(sizeof(State));
    if (newState == NULL) {
        return NULL; // Memory allocation failed
    }

    newState->id = lastState + 1;
    newState->next = NULL;

    fsa->states[lastState].next = newState;
    currentStates[numStates] = newState->id;
    fsa->numberOfStates++;

    return fsa;
}

