        fclose(logFile);
    }
}

// Function to handle concurrent requests and ensure high performance
void handleConcurrentRequests(int clinicID, int status, const char* ipAddress) {
    FSA* fsa = (FSA*)malloc(sizeof(FSA));
    if (fsa == NULL) {
        handleError("Failed to allocate memory for FSA");
        return;
    }

    fsa->states = (State*)malloc(10 * sizeof(State)); // Assuming max 10 states initially
    if (fsa->states == NULL) {
        free(fsa);
        handleError("Failed to allocate memory for states");
        return;
    }
    memset(fsa->states, 0, 10 * sizeof(State));
    fsa->numberOfStates = 0;

    int currentStates[10] = {0};
    addState(fsa, currentStates, 0, -1); // Initialize with a single state

    if (callExternalAPI(clinicID) != 1) {
        handleError("Failed to call external API");
        free(fsa->states);
        free(fsa);
        return;
    }

    updateDatabase(clinicID, status, ipAddress);

    logEvent("Request processed for clinic ID: %d", clinicID);

    // Free allocated memory
    free(fsa->states);
    free(fsa);
}

int main() {
