public class SensorDataProcessor {
    private ExecutorService executorService;
    private IoTPlatformIntegration ioTPlatformIntegration;
    private AnomalyDetection anomalyDetection;
    private LoggingSystem loggingSystem;

    public SensorDataProcessor(int numberOfThreads) {
        this.executorService = Executors.newFixedThreadPool(numberOfThreads);
        this.ioTPlatformIntegration = new IoTPlatformIntegration();
        this.anomalyDetection = new AnomalyDetection();
        this.loggingSystem = new LoggingSystem();
    }

    public void startProcessing() {
        // Continuously listen for incoming sensor data
        while (true) {
            SensorData data = ioTPlatformIntegration.fetchSensorData();
            if (data != null) {
                executorService.submit(() -> processSensorData(data));
            }
        }
    }

    private void processSensorData(SensorData data) {
        try {
            // Handle missing or out-of-range values
            data = handleMissingValues(data);

            // Update device status and log data
            ioTPlatformIntegration.updateDeviceStatus(data.getDeviceId(), data.getStatus());
            loggingSystem.log(data);

            // Perform anomaly detection
            if (anomalyDetection.detectAnomaly(data)) {
                // Log and notify about anomalies
                loggingSystem.logAnomaly(data);
                ioTPlatformIntegration.notifyOfAnomaly(data);
            }
        } catch (Exception e) {
            // Handle exceptions and retry logic
            loggingSystem.logError(e);
            retryProcessing(data, 3); // Retry up to 3 times
        }
    }

    private SensorData handleMissingValues(SensorData data) {
        // Implement statistical imputation methods here
        return data;
    }

    private void retryProcessing(SensorData data, int retriesLeft) {
        if (retriesLeft > 0) {
            try {
                TimeUnit.SECONDS.sleep((long)Math.pow(2, 5 - retriesLeft));
                processSensorData(data);
            } catch (InterruptedException e) {
                loggingSystem.logError(e);
            }
        } else {
            loggingSystem.logFailedProcessing(data);
        }
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }
}

