#include <iostream>
#include <fstream>
#include <vector>
#include <algorithm>
#include <stdexcept>

// Function to read, sort, and extract sequence number from a file
int extractSequenceNumber(const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open file: " + filename);
    }

    std::vector<std::string> lines;
    std::string line;
    while (std::getline(file, line)) {
        lines.push_back(line);
    }
    file.close();

    if (lines.empty()) {
        return 0; // No sequence number in an empty file
    }

    std::sort(lines.begin(), lines.end());

    try {
        int lastLine = std::stoi(lines.back());
        return lastLine;
    } catch (const std::invalid_argument& e) {
        throw std::runtime_error("Failed to parse last line as integer: " + std::string(e.what()));
    }
}

int main() {
    try {
        int sequenceNumber = extractSequenceNumber("input.txt");
        std::cout << "Extracted sequence number: " << sequenceNumber << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
