#define MAX_HOSTNAME_LEN 256
#define MAX_PAGE_ID_LEN 100
#define MAX_ELEMENT_ID_LEN 100

typedef struct {
    char hostname[MAX_HOSTNAME_LEN];
    int port;
} WebService;

int updateElementWithHTTPPost(const char* pageSectionID, const char* elementID, const char* htmlContent, WebService service) {
    // DNS resolution
    struct sockaddr_in serv_addr;
    if (getaddrinfo(service.hostname, NULL, NULL, &serv_addr) != 0) {
        return -1; // DNS resolution failed
    }

    // Service authentication and validation
    if (!isValidPageAndElement(pageSectionID, elementID)) {
        return -2; // Invalid page or element ID
    }

    // Rate limiting
    if (isRateLimited()) {
        return -3; // Rate limit exceeded
    }

    // Prepare HTTP request
    char http_request[1024];
    snprintf(http_request, sizeof(http_request), "POST /update HTTP/1.1\r\n"
                                             "Host: %s:%d\r\n"
                                             "Content-Type: application/x-www-form-urlencoded\r\n"
                                             "Content-Length: %lu\r\n"
                                             "\r\n"
                                             "pageSectionID=%s&elementID=%s&htmlContent=%s",
             service.hostname, service.port, strlen(htmlContent), pageSectionID, elementID, htmlContent);

    // Send HTTP request
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        return -4; // Socket creation failed
    }
    if (connect(sock, serv_addr, sizeof(serv_addr)) < 0) {
        close(sock);
        return -5; // Connection failed
    }

    if (send(sock, http_request, strlen(http_request), 0) < 0) {
        close(sock);
        return -6; // Send failed
    }

    // Receive HTTP response
    char buffer[1024];
    ssize_t bytes_received = recv(sock, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received <= 0) {
        close(sock);
        return -7; // Receive failed or connection closed
    }
    buffer[bytes_received] = '\0';

    // Close socket
    close(sock);

    // Handle response and log
    if (strstr(buffer, "200 OK") != NULL) {
        printf("Element updated successfully.\n");
        return 0; // Success
    } else {
        printf("Failed to update element: %s\n", buffer);
        return -8; // Update failed
    }
}

