    public String generateBattleReport(String pokemonName, String language) {
        try {
            // Fetch Pokémon details from the internal database or external API
            PokemonDetails pokemonDetails = getPokemonDetails(pokemonName);

            // Fetch real-time battle statistics from a third-party API
            BattleStatistics battleStats = getRealTimeBattleStatistics(pokemonDetails.getId());

            // Fetch historical encounter data from another third-party API
            HistoricalData historicalData = fetchHistoricalEncounterData(pokemonDetails.getId());

            // Get regional preferences (e.g., trainer type, terrain)
            RegionalPreferences preferences = getUserRegionalPreferences(pokemonDetails.getId(), language);

            // Generate the battle report based on the fetched data and user preferences
            String battleReport = generateBattleReportContent(battleStats, historicalData, preferences);

            return battleReport;
        } catch (Exception e) {
            // Log the error and return a fallback message or rethrow the exception
            System.err.println("Error generating battle report: " + e.getMessage());
            return "An error occurred while generating the battle report.";
        }
    }

    private PokemonDetails getPokemonDetails(String pokemonName) {
        // Implement logic to fetch Pokémon details (type, name, regional variations)
        // This could involve calling an internal database or an external API
        return new PokemonDetails(pokemonName, "Egg", "Default");
    }

    private BattleStatistics getRealTimeBattleStatistics(int pokemonId) {
        // Fetch real-time battle statistics from a third-party API (handle rate limits and network errors)
        // Use CompletableFuture for asynchronous request handling
        CompletableFuture<BattleStatistics> future = CompletableFuture.supplyAsync(() -> {
            try {
                return restTemplate.getForObject("https://api.pokemon.com/v2/statistics/" + pokemonId, BattleStatistics.class);
            } catch (Exception e) {
                // Handle exceptions and return a fallback value or rethrow the exception
                System.err.println("Error fetching real-time battle statistics: " + e.getMessage());
                return new BattleStatistics();
            }
        });
        return future.join();
    }

    private HistoricalData fetchHistoricalEncounterData(int pokemonId) {
        // Fetch historical encounter data from another third-party API (handle rate limits and network errors)
        CompletableFuture<HistoricalData> future = CompletableFuture.supplyAsync(() -> {
            try {
                return restTemplate.getForObject("https://api.pokemon.com/v2/historical/" + pokemonId, HistoricalData.class);
            } catch (Exception e) {
                // Handle exceptions and return a fallback value or rethrow the exception
                System.err.println("Error fetching historical encounter data: " + e.getMessage());
                return new HistoricalData();
            }
        });
        return future.join();
    }

    private RegionalPreferences getUserRegionalPreferences(int pokemonId, String language) {
        // Get regional preferences (e.g., trainer type, terrain)
        // This could involve querying a user preferences database or using default values
        return new RegionalPreferences("Rival", "Grassland");
    }

    private String generateBattleReportContent(BattleStatistics battleStats, HistoricalData historicalData, RegionalPreferences preferences) {
        // Generate the battle report content based on the fetched data and user preferences
        StringBuilder report = new StringBuilder();
        report.append("### Battle Report for ").append(battleStats.getName()).append("\n");
        report.append("Type: ").append(battleStats.getType()).append("\n");
        report.append("Strengths: ").append(String.join(", ", battleStats.getStrengths())).append("\n");
        report.append("Weaknesses: ").append(String.join(", ", battleStats.getWeaknesses())).append("\n");
        report.append("## Historical Data\n");
        report.append("Most common encounter location: ").append(historicalData.getCommonLocation()).append("\n");
        report.append("Average encounter frequency: ").append(historicalData.getFrequency()).append("\n");
        report.append("## Regional Preferences\n");
        report.append("Ideal Trainer Type: ").append(preferences.getTrainerType()).append("\n");
        report.append("Optimal Terrain: ").append(preferences.getTerrain());
        return report.toString();
    }
}

