    }

    static void InitializeSemaphore()
    {
        int initialSemaphoreValue = GetInitialSemaphoreValue();
        semaphore = new Semaphore(initialSemaphoreValue, initialSemaphoreValue);
    }

    static int GetInitialSemaphoreValue()
    {
        // Implement logic to determine initial semaphore value
        return 10;
