    NetworkEvent* eventQueue = (NetworkEvent*)arg;
    int index = 0;

    while (1) {
        // Simulate reading an event from the queue
        if (eventQueue[index].timestamp != 0) {
            logEvent(eventQueue[index]);
            eventQueue[index].timestamp = 0; // Clear after logging
        }

        // Sleep for a short period to simulate processing time
        pthread_yield();
    }

    return NULL;
}

int main() {
