    const int QUEUE_SIZE = 100;

    // Allocate memory for the event queue
    NetworkEvent* eventQueue = (NetworkEvent*)malloc(QUEUE_SIZE * sizeof(NetworkEvent));
    if (!eventQueue) {
        fprintf(stderr, "Failed to allocate memory for event queue\n");
        return EXIT_FAILURE;
    }

    // Initialize the event queue with sample events
    for (int i = 0; i < QUEUE_SIZE; ++i) {
        eventQueue[i].timestamp = i * 1000; // Timestamp in milliseconds
        eventQueue[i].eventCode = i % 10;
        eventQueue[i].context.stringValue = "Sample Context";
    }

    // Create multiple threads to process events concurrently
    pthread_t* threads = (pthread_t*)malloc(5 * sizeof(pthread_t));
    if (!threads) {
        fprintf(stderr, "Failed to allocate memory for thread pool\n");
        free(eventQueue);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 5; ++i) {
        if (pthread_create(&threads[i], NULL, processEvents, eventQueue) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            free(eventQueue);
            free(threads);
            return EXIT_FAILURE;
        }
    }

    // Join the threads
    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up resources
    free(eventQueue);
    free(threads);

    return EXIT_SUCCESS;
