# Rate Limiting and Throttling
rate_limit_cache = {}

def rate_limiter(max_requests: int, time_window: float):
    def decorator(func):
        async def wrapper(*args, **kwargs):
            current_time = time.time()
            if func.__name__ not in rate_limit_cache:
                rate_limit_cache[func.__name__] = []
            rate_limit_cache[func.__name__] = [
                x for x in rate_limit_cache[func.__name__]
                if current_time - x < time_window
            ]
            if len(rate_limit_cache[func.__name__]) >= max_requests:
                raise HTTPException(status_code=429, detail="Too Many Requests")
            rate_limit_cache[func.__name__].append(current_time)
            return await func(*args, **kwargs)
        return wrapper
    return decorator

# Caching and Compression
