// Define event structure
struct NetworkEvent {
    std::string timestamp;
    int event_code;
    // Add flexible union for context data
};

// Mock external event-processing service
class EventProcessingService {
public:
    void process(const NetworkEvent& event) {
        // Simulate network delay and processing
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        std::cout << "Processed: " << event.timestamp << ", Code: " << event.event_code << std::endl;
    }
};

// Mock remote database for persistent storage
class RemoteDatabase {
public:
    void store(const NetworkEvent& event) {
        // Simulate database operation
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
        std::cout << "Stored: " << event.timestamp << ", Code: " << event.event_code << std::endl;
    }
};

// Logging framework class
class LoggingFramework {
public:
    LoggingFramework(EventProcessingService& esp, RemoteDatabase& db)
        : esp(esp), db(db), running(true) {
        consumer_thread = std::thread(&LoggingFramework::consumeEvents, this);
    }

    ~LoggingFramework() {
        running.store(false);
        cv.notify_all();
        consumer_thread.join();
    }

    void logEvent(const NetworkEvent& event) {
        // Add event to the queue
        {
            std::lock_guard<std::mutex> lock(mutex);
            event_queue.push(event);
        }
        cv.notify_one();
    }

private:
    EventProcessingService& esp;
    RemoteDatabase& db;
    std::queue<NetworkEvent> event_queue;
    std::mutex mutex;
    std::condition_variable cv;
    std::thread consumer_thread;
    std::atomic<bool> running;

    void consumeEvents() {
        while (running.load()) {
            NetworkEvent event;
            {
                std::unique_lock<std::mutex> lock(mutex);
                cv.wait(lock, [this] { return !event_queue.empty() || !running.load(); });
                if (!running.load()) break;
                event = event_queue.front();
                event_queue.pop();
            }

            // Process and store the event
            try {
                esp.process(event);
                db.store(event);
            } catch (...) {
                // Handle errors gracefully, e.g., log error and retry or fallback
            }
        }
    }
};

int main() {
    EventProcessingService esp;
    RemoteDatabase db;
    LoggingFramework framework(esp, db);

    // Simulate logging events from multiple threads
    std::vector<std::thread> producer_threads;
    for (int i = 0; i < 10; ++i) {
        producer_threads.emplace_back([&framework]() {
            for (int j = 0; j < 5; ++j) {
                NetworkEvent event = {"2023-04-30T12:34:56", j, "Context Data"};
                framework.logEvent(event);
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }
        });
    }

    for (auto& thread : producer_threads) {
        thread.join();
    }

    return 0;
}
