package main

import (
	"context"
	"fmt"
	"log"
	"time"

	"github.com/Shopify/sarama"
)

type Event struct {
	ID     string `json:"id"`
	Type   string `json:"type"`
	Payload []byte `json:"payload"`
}

type EventHandler interface {
	Handle(context.Context, *Event) error
}

type KafkaConsumer struct{}

func (c *KafkaConsumer) Consume(ctx context.Context, topic string, handler EventHandler) error {
	config := sarama.NewConfig()
	config.Consumer.Return.Errors = true

	consumer, err := sarama.NewConsumer([]string{"localhost:9092"}, config)
	if err != nil {
		return fmt.Errorf("failed to start consumer: %w", err)
	}
	defer consumer.Close()

	partitionConsumer, err := consumer.ConsumePartition(topic, 0, sarama.OffsetNewest)
	if err != nil {
		return fmt.Errorf("failed to open partition consumer: %w", err)
	}
	defer partitionConsumer.Close()

	for {
		select {
		case msg := <-partitionConsumer.Messages():
			event := &Event{
				ID:     string(msg.Key),
				Type:   string(msg.Topic),
				Payload: msg.Value,
			}
			if err := handler.Handle(ctx, event); err != nil {
				log.Printf("error handling event %s: %v", msg.Key, err)
			}

		case <-partitionConsumer.Errors():
			return partitionConsumer.Errors().Next()

		case <-ctx.Done():
			return ctx.Err()
		}
	}
}

type EventProcessor struct{}

func (p *EventProcessor) Handle(ctx context.Context, event *Event) error {
	// Implement event processing logic here
	fmt.Printf("Processing event: %s\n", event.ID)
	return nil
}

func main() {
	ctx := context.Background()

	consumer := &KafkaConsumer{}
	handler := &EventProcessor{}

	if err := consumer.Consume(ctx, "events_topic", handler); err != nil {
		log.Fatalf("consumer failed: %v", err)
	}
}
```

