// Define the structure for an FSA state
typedef struct State {
    int id;
    char *name;
    struct State *next;
} State;

// Function to safely add a new state to the FSA with retry and logging
State* add_state(State **fsa, int id, const char *name, int max_retries) {
    for (int i = 0; i <= max_retries; ++i) {
        State *new_state = malloc(sizeof(State));
        if (!new_state) {
            fprintf(stderr, "Memory allocation failed: Attempt %d\n", i + 1);
            continue;
        }

        new_state->id = id;
        new_state->name = strdup(name);
        new_state->next = *fsa;

        // Update the FSA pointer and validate structure
        *fsa = new_state;
        if (new_state->next && new_state->next->id == new_state->id) {
            fprintf(stderr, "Invalid transition detected: Attempt %d\n", i + 1);
            free(new_state->name);
            free(new_state);
            continue;
        }

        printf("State added successfully after %d attempts.\n", i + 1);
        return new_state;
    }

    fprintf(stderr, "Failed to add state after maximum retries.\n");
    return NULL;
}

// Example usage
int main() {
    State *fsa = NULL;

    // Attempt to add states with retry mechanism
    add_state(&fsa, 1, "Waiting", 3);
    add_state(&fsa, 2, "Checking", 3);
    add_state(&fsa, 3, "Diagnosing", 3);

    return 0;
}
