// Function to create a new state list
State* createStateList(State** states, int numStates, FSA* fsa, int lastState) {
    // Allocate memory for the new state list
    State* newStateList = (State*)malloc(numStates * sizeof(State));
    if (newStateList == NULL) {
        return NULL;  // Return NULL if allocation fails
    }

    // Populate the new state list with states from the FSA
    for (int i = 0; i < numStates; i++) {
        newStateList[i] = states[lastState][i];
        newStateList[i].id += lastState + 1;  // Update state IDs to avoid duplicates
    }

    // Update the 'next' pointer of the last state in the original list
    if (lastState >= 0) {
        states[lastState]->next = newStateList;
    }

    return newStateList;
}
