// Include necessary headers for JSON parsing, cryptography, logging, and transport
#include <nlohmann/json.hpp>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/ssl.h>
#include <openssl/tls1_3.h>
#include <log4cpp/Category.hh>
#include <log4cpp/OstreamAppender.hh>
#include <log4cpp/BasicConfigurator.hh>
#include <asio/ip/tcp.hpp>
#include <asio/steady_timer.hpp>

// Define constants for cipher modes and other parameters
const EVP_CIPHER* getCipherMode(const std::string& mode) {
    if (mode == "ECB") return EVP_aes_256_ecb();
    else if (mode == "CBC") return EVP_aes_256_cbc();
    else if (mode == "GCM") return EVP_aes_256_gcm();
    else if (mode == "ChaCha20-Poly1305") return EVP_chacha20_poly1305();
    return nullptr;
}

// Function to encrypt a JSON string using a specified cipher mode
std::string encrypt(const std::string& json, const std::string& key, const std::string& iv, const std::string& mode) {
    EVP_CIPHER* cipher = getCipherMode(mode);
    if (!cipher) throw std::invalid_argument("Unsupported cipher mode");

    // Initialize OpenSSL context and perform encryption
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) throw std::runtime_error("Failed to create EVP_CIPHER_CTX");
    if (1 != EVP_EncryptInit_ex(ctx, cipher, nullptr, reinterpret_cast<const unsigned char*>(key.data()), reinterpret_cast<const unsigned char*>(iv.data()))) {
        EVP_CIPHER_CTX_free(ctx);
        throw std::runtime_error("Encryption initialization failed");
    }

    // Allocate buffer for encrypted data
    size_t len = json.size();
    size_t ciphertext_len = 0;
    unsigned char* ciphertext = new unsigned char[len + EVP_CIPHER_block_size(cipher)];

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len, reinterpret_cast<const unsigned char*>(json.data()), len)) {
        delete[] ciphertext;
        EVP_CIPHER_CTX_free(ctx);
        throw std::runtime_error("Encryption update failed");
    }

    size_t final_len = 0;
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + ciphertext_len, &final_len)) {
        delete[] ciphertext;
        EVP_CIPHER_CTX_free(ctx);
        throw std::runtime_error("Encryption finalization failed");
    }
    ciphertext_len += final_len;

    // Clean up and return result
    EVP_CIPHER_CTX_free(ctx);
    std::string encrypted(reinterpret_cast<char*>(ciphertext), ciphertext_len);
    delete[] ciphertext;
    return encrypted;
}

// Function to decrypt a JSON string using a specified cipher mode
std::string decrypt(const std::string& encrypted, const std::string& key, const std::string& iv, const std::string& mode) {
    EVP_CIPHER* cipher = getCipherMode(mode);
    if (!cipher) throw std::invalid_argument("Unsupported cipher mode");

    // Initialize OpenSSL context and perform decryption
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) throw std::runtime_error("Failed to create EVP_CIPHER_CTX");
    if (1 != EVP_DecryptInit_ex(ctx, cipher, nullptr, reinterpret_cast<const unsigned char*>(key.data()), reinterpret_cast<const unsigned char*>(iv.data()))) {
        EVP_CIPHER_CTX_free(ctx);
        throw std::runtime_error("Decryption initialization failed");
    }

    // Allocate buffer for decrypted data
    size_t len = encrypted.size();
    size_t plaintext_len = 0;
    unsigned char* plaintext = new unsigned char[len];

    if (1 != EVP_DecryptUpdate(ctx, plaintext, &plaintext_len, reinterpret_cast<const unsigned char*>(encrypted.data()), len)) {
        delete[] plaintext;
        EVP_CIPHER_CTX_free(ctx);
        throw std::runtime_error("Decryption update failed");
    }

    size_t final_len = 0;
    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + plaintext_len, &final_len)) {
        delete[] plaintext;
        EVP_CIPHER_CTX_free(ctx);
        throw std::runtime_error("Decryption finalization failed");
    }
    plaintext_len += final_len;

    // Clean up and return result
    EVP_CIPHER_CTX_free(ctx);
    std::string decrypted(reinterpret_cast<char*>(plaintext), plaintext_len);
    delete[] plaintext;
    return decrypted;
}

// Function to handle TLS connections using OpenSSL
void handleTLSConnection(asio::ip::tcp::socket& socket, const std::string& server) {
    SSL_library_init();
    OpenSSL_add_all_algorithms();
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    if (!ctx) throw std::runtime_error("Failed to create SSL_CTX");

    // Set up SSL context options and verify peer
    SSL_CTX_set_options(ctx, SSL_OP_NO_SSLv2 | SSL_OP_NO_SSLv3 | SSL_OP_NO_TLSv1 | SSL_OP_NO_TLSv1_1);
    SSL_CTX_set_verify(ctx, SSL_VERIFY_PEER, nullptr);

    // Connect to server using TLS
    SSL* ssl = SSL_new(ctx);
    if (!ssl) {
        SSL_CTX_free(ctx);
        throw std::runtime_error("Failed to create SSL");
    }
    SSL_set_fd(ssl, socket.native_handle());
    if (1 != SSL_connect(ssl)) {
        SSL_free(ssl);
        SSL_CTX_free(ctx);
        throw std::runtime_error("SSL connection failed");
    }

    // Perform TLS handshake and read/write operations
    try {
        // Read encrypted data from server
        size_t len;
        char buffer[1024];
        while ((len = SSL_read(ssl, buffer, sizeof(buffer) - 1)) > 0) {
            buffer[len] = '\0';
            std::cout << "Received: " << buffer << std::endl;
        }
    } catch (std::exception& e) {
        std::cerr << "Error during TLS read: " << e.what() << std::endl;
    }

    // Clean up
    SSL_shutdown(ssl);
    SSL_free(ssl);
    SSL_CTX_free(ctx);
}

// Main function to demonstrate usage of encryption, decryption, and TLS
int main(int argc, char* argv[]) {
    if (argc < 4) {
        std::cerr << "Usage: " << argv[0] << " <cipher_mode> <key> <iv>" << std::endl;
        return 1;
    }

    std::string cipherMode = argv[1];
    std::string key = argv[2];
    std::string iv = argv[3];

    // Set up logging
    log4cpp::BasicConfigurator::configure();
    log4cpp::Category& logger = log4cpp::Category::getRoot();
    logger.addAppender(new log4cpp::OstreamAppender("cout", &std::cout));
    logger.setPriority(log4cpp::Priority::DEBUG);

    // Encrypt and decrypt a JSON string
    nlohmann::json jsonToken = {
        {"access_token", "example_token"},
        {"expires_in", 3600},
        {"token_type", "Bearer"}
    };
    std::string encrypted = encrypt(jsonToken.dump(), key, iv, cipherMode);
    logger.debug("Encrypted token: %s", encrypted.c_str());

    std::string decrypted = decrypt(encrypted, key, iv, cipherMode);
    nlohmann::json decryptedJson = nlohmann::json::parse(decrypted);
    logger.debug("Decrypted JSON: %s", decryptedJson.dump().c_str());

    // Handle TLS connection
    asio::ip::tcp::resolver resolver;
    asio::ip::tcp::endpoint endpoint = *resolver.resolve("example.com", "443");
    asio::io_context ioContext;
    asio::ip::tcp::socket socket(ioContext);
    socket.connect(endpoint);

    try {
        handleTLSConnection(socket, "example.com");
    } catch (std::exception& e) {
        std::cerr << "Error during TLS connection: " << e.what() << std::endl;
    }

    return 0;
}
```

