#include <pthread.h>

typedef struct {
    EVP_CIPHER *cipher;
    pthread_mutex_t lock;
} EncryptionLibrary;

EncryptionLibrary* create_encryption_library(const char* key_type) {
    EncryptionLibrary* library = (EncryptionLibrary*)malloc(sizeof(EncryptionLibrary));
    if (!library) return NULL;

    if (strcmp(key_type, "DES_ECB") == 0) {
        library->cipher = EVP_des_ecb();
    } else if (strcmp(key_type, "DES_EDE") == 0) {
        library->cipher = EVP_des_ede_cbc();
    } else if (strcmp(key_type, "DES_EDE3") == 0) {
        library->cipher = EVP_des_ede3_cbc();
    } else {
        free(library);
        return NULL;
    }

    pthread_mutex_init(&library->lock, NULL);
    return library;
}

void encrypt_data(EncryptionLibrary* library, const unsigned char* input, int input_length,
                   unsigned char** output, int* output_length) {
    pthread_mutex_lock(&library->lock);
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        pthread_mutex_unlock(&library->lock);
        return;
    }

    if (1 != EVP_EncryptInit_ex(ctx, library->cipher, NULL, NULL, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        pthread_mutex_unlock(&library->lock);
        return;
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx, *output, &len, input, input_length)) {
        EVP_CIPHER_CTX_free(ctx);
        pthread_mutex_unlock(&library->lock);
        return;
    }
    *output_length = len;

    if (1 != EVP_EncryptFinal_ex(ctx, (*output) + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        pthread_mutex_unlock(&library->lock);
        return;
    }

    *output_length += len;
    EVP_CIPHER_CTX_free(ctx);
    pthread_mutex_unlock(&library->lock);
}

void free_encryption_library(EncryptionLibrary* library) {
    if (library) {
        pthread_mutex_destroy(&library->lock);
        free(library);
    }
}
