} EncryptionState;

EncryptionState* create_encryption_state(const char *mode, const unsigned char *key) {
    EncryptionState *state = (EncryptionState*)malloc(sizeof(EncryptionState));
    if (!state) return NULL;

    state->ctx = EVP_CIPHER_CTX_new();
    if (!state->ctx) {
        free(state);
        return NULL;
    }

    if (!EVP_EncryptInit_ex(state->ctx, mode, NULL, key, state->iv)) {
        EVP_CIPHER_CTX_free(state->ctx);
        free(state);
        return NULL;
    }

    return state;
}

void cleanup_encryption_state(EncryptionState *state) {
    if (state) {
        EVP_CIPHER_CTX_free(state->ctx);
        free(state);
    }
}

int encrypt_data(EncryptionState *state, const unsigned char *plaintext, int plaintext_len, unsigned char **ciphertext, int *ciphertext_len) {
    return EVP_EncryptUpdate(state->ctx, ciphertext, ciphertext_len, plaintext, plaintext_len);
}

