import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.logging.Level;
import java.util.logging.Logger;

public class LoggingFramework {
    private static final Logger logger = Logger.getLogger(LoggingFramework.class.getName());
    private ConcurrentHashMap<String, LogHandler> logHandlers;
    private ExecutorService executorService;

    public LoggingFramework() {
        this.logHandlers = new ConcurrentHashMap<>();
        this.executorService = Executors.newCachedThreadPool();
    }

    public void addLogHandler(String source, LogHandler handler) {
        logHandlers.put(source, handler);
    }

    public void removeLogHandler(String source) {
        logHandlers.remove(source);
    }

    public void logEvent(String source, String message, Level level) {
        LogHandler handler = logHandlers.get(source);
        if (handler != null) {
            executorService.submit(() -> handler.log(message, level));
        } else {
            logger.warning("No handler found for source: " + source);
        }
    }

    public void shutdown() {
        executorService.shutdown();
    }

    interface LogHandler {
        void log(String message, Level level);
    }

    public static void main(String[] args) {
        LoggingFramework framework = new LoggingFramework();
        framework.addLogHandler("app", (message, level) -> System.out.println(message));
        framework.logEvent("app", "Application started", Level.INFO);

        // Simulate high load
        for (int i = 0; i < 1000; i++) {
            framework.logEvent("app", "Processing event " + i, Level.INFO);
        }

        framework.shutdown();
    }
}
```

