typedef struct {
    DES_key_schedule key_schedule;
    int mode;
} EncryptionContext;

typedef struct {
    char *buffer;
    size_t capacity;
    size_t length;
    pthread_mutex_t lock;
} Buffer;

void init_encryption_context(EncryptionContext *ctx, const unsigned char *key, int mode) {
    memset(ctx, 0, sizeof(*ctx));
    DES_set_key((DES_cblock *)key, &ctx->key_schedule);
    ctx->mode = mode;
}

void encrypt_data(const EncryptionContext *ctx, const unsigned char *input, unsigned char *output, size_t length) {
    pthread_mutex_lock(&ctx->lock);
    switch (ctx->mode) {
        case DES_MODE_ECB:
            DES_ecb_encrypt((const_DES_cblock *)input, (DES_cblock *)output, &ctx->key_schedule, DES_ENCRYPT);
            break;
        // Add other modes as needed
    }
    pthread_mutex_unlock(&ctx->lock);
}

void init_buffer(Buffer *buf, size_t capacity) {
    buf->buffer = malloc(capacity);
    buf->capacity = capacity;
    buf->length = 0;
    pthread_mutex_init(&buf->lock, NULL);
}

int append_to_buffer(Buffer *buf, const char *data, size_t length) {
    pthread_mutex_lock(&buf->lock);
    if (buf->length + length > buf->capacity) {
        // Handle buffer overflow
        pthread_mutex_unlock(&buf->lock);
        return -1;
    }
    memcpy(buf->buffer + buf->length, data, length);
    buf->length += length;
    pthread_mutex_unlock(&buf->lock);
    return 0;
}

void log_event(const char *event_code, const char *context_data) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[20];
    snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", (long)tv.tv_sec, (long)tv.tv_usec);

    Buffer buffer;
    init_buffer(&buffer, 1024);
    append_to_buffer(&buffer, timestamp, strlen(timestamp));
    append_to_buffer(&buffer, " ", 1);
    append_to_buffer(&buffer, event_code, strlen(event_code));
    append_to_buffer(&buffer, " ", 1);
    append_to_buffer(&buffer, context_data, strlen(context_data));

    // Send buffer to external logging service
    send_log_service(buffer.buffer);

    free(buffer.buffer);
}

void handle_error(const char *error_message) {
    // Log error and report to monitoring services
    log_event("ERROR", error_message);
}
