// Define network event structure
typedef struct {
    time_t timestamp;
    int event_code;
    union {
        int i_data;
        char* s_data;
        double d_data;
    } context;
} NetworkEvent;

// Memory pool allocator structure
typedef struct mem_pool {
    size_t block_size;
    size_t num_blocks;
    void** blocks;
} MemPool;

// Initialize memory pool
MemPool* init_mem_pool(size_t block_size, size_t num_blocks) {
    MemPool* pool = (MemPool*)malloc(sizeof(MemPool));
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->blocks = (void**)malloc(num_blocks * sizeof(void*));
    for (size_t i = 0; i < num_blocks; i++) {
        pool->blocks[i] = malloc(block_size);
    }
    return pool;
}

// Allocate memory from pool
void* mem_pool_alloc(MemPool* pool) {
    void* block = pool->blocks[pool->num_blocks - 1];
    pool->num_blocks--;
    return block;
}

// Free memory back to pool
void mem_pool_free(MemPool* pool, void* block) {
    pool->blocks[pool->num_blocks++] = block;
}

// Log network event using custom allocator
void log_network_event(NetworkEvent* event, MemPool* pool) {
    NetworkEvent* new_event = (NetworkEvent*)mem_pool_alloc(pool);
    *new_event = *event;
    // Process event (e.g., send to external service)
    printf("Logging event: %ld, %d\n", new_event->timestamp, new_event->event_code);
}

// Main function to demonstrate logging framework
int main() {
    MemPool* pool = init_mem_pool(sizeof(NetworkEvent), 100);

    NetworkEvent event;
    event.timestamp = time(NULL);
    event.event_code = 200;
    event.context.i_data = 42;

    log_network_event(&event, pool);

    mem_pool_free(pool, &event);
    free(pool->blocks);
    free(pool);

    return 0;
}
