            newFrame->frameNumber = getFrameNumber(); // Assuming getFrameNumber is a function that fetches frame number from external service
            newFrame->timestamp = time(NULL);
            newFrame->signalStrength = readSignalStrength(); // Assuming readSignalStrength is a function that reads signal strength

            if (validateSignal(newFrame)) {
                break;
            }
            retryCount++;
        }

        if (retryCount == 3) {
            fprintf(stderr, "Failed to read valid signal after retries\n");
            free(newFrame);
        } else {
            frameArray[frameCount++] = newFrame;
            pthread_cond_signal(&cond);
        }

        pthread_mutex_unlock(&mutex);
        usleep(100000); // Simulate 10 frames per second
    }
    return NULL;
}

int validateSignal(FrameHeader *frame) {
    int qualityThreshold = 50;
    int noiseThreshold = 20;

    if (frame->signalStrength < qualityThreshold || frame->signalStrength > (qualityThreshold + noiseThreshold)) {
        printf("Frame %d: Invalid signal strength\n", frame->frameNumber);
        return 0;
    }
    return 1;
}

int getFrameNumber() {
    // Simulated function to fetch frame number from external service
    static int frameNumber = 0;
    return frameNumber++;
}

int readSignalStrength() {
    // Simulated function to read signal strength with potential corruption
    return rand() % 100; // Random value between 0 and 99
}

void* processFrames(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        while (frameCount == 0 && !shutdownFlag) {
            pthread_cond_wait(&cond, &mutex);
        }

        if (shutdownFlag) {
            pthread_mutex_unlock(&mutex);
            break;
        }

        FrameHeader *frame = frameArray[--frameCount];
        printf("Processing frame %d with signal strength %d\n", frame->frameNumber, frame->signalStrength);
        free(frame);

        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

int main() {
    pthread_t readThread[NUM_THREADS], processThread;

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&readThread[i], NULL, readSignal, NULL);
    }

    pthread_create(&processThread, NULL, processFrames, NULL);

    // Simulate running for a while
    sleep(10);

    shutdownFlag = 1;
    pthread_cond_broadcast(&cond);

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(readThread[i], NULL);
    }
    pthread_join(processThread, NULL);

    return 0;
}
```

