DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->frames = (FrameHeader*)malloc(initial_capacity * sizeof(FrameHeader));
    array->records = (Record*)malloc(initial_capacity * sizeof(Record));
    if (!array->frames || !array->records) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    if (!array) return;

    free(array->frames);
    free(array->records);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int add_frame(DynamicArray *array, FrameHeader frame) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 10;
        FrameHeader *new_frames = (FrameHeader*)realloc(array->frames, new_capacity * sizeof(FrameHeader));
        Record *new_records = (Record*)realloc(array->records, new_capacity * sizeof(Record));
        if (!new_frames || !new_records) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failure
        }

        array->frames = new_frames;
        array->records = new_records;
        array->capacity = new_capacity;
    }

    array->frames[array->count] = frame;
    array->count++;
    pthread_mutex_unlock(&array->lock);

