    int count;
    pthread_mutex_t lock;
} UELibrary;

void init_ue_library(UELibrary *library) {
    library->count = 0;
    pthread_mutex_init(&library->lock, NULL);
}

int add_ue_context(UELibrary *library, UEContext context) {
    pthread_mutex_lock(&library->lock);
    if (library->count >= MAX_UE_CONTEXTS) {
        pthread_mutex_unlock(&library->lock);
        return -1; // Library is full
    }
    library->contexts[library->count++] = context;
    pthread_mutex_unlock(&library->lock);
    return 0;
}

int update_ue_context(UELibrary *library, int id, UEContext new_context) {
    pthread_mutex_lock(&library->lock);
    for (int i = 0; i < library->count; i++) {
        if (library->contexts[i].id == id) {
            library->contexts[i] = new_context;
            pthread_mutex_unlock(&library->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&library->lock);
    return -1; // UE context not found
}

int remove_ue_context(UELibrary *library, int id) {
    pthread_mutex_lock(&library->lock);
    for (int i = 0; i < library->count; i++) {
        if (library->contexts[i].id == id) {
            memmove(&library->contexts[i], &library->contexts[i + 1], sizeof(UEContext) * (library->count - i - 1));
            library->count--;
            pthread_mutex_unlock(&library->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&library->lock);
    return -1; // UE context not found
}

void destroy_ue_library(UELibrary *library) {
    pthread_mutex_destroy(&library->lock);
}
