} LTE_UE_Context;

typedef struct UE_List {
    LTE_UE_Context **contexts;
    size_t count;
    size_t capacity;
} UE_List;

UE_List* create_ue_list() {
    UE_List *list = (UE_List *)malloc(sizeof(UE_List));
    if (!list) return NULL;
    list->contexts = NULL;
    list->count = 0;
    list->capacity = 0;
    return list;
}

void destroy_ue_list(UE_List *list) {
    for (size_t i = 0; i < list->count; i++) {
        pthread_mutex_destroy(&list->contexts[i]->lock);
        free(list->contexts[i]);
    }
    free(list->contexts);
    free(list);
}

LTE_UE_Context* find_ue_context(UE_List *list, int id) {
    for (size_t i = 0; i < list->count; i++) {
        pthread_mutex_lock(&list->contexts[i]->lock);
        if (list->contexts[i]->id == id) {
            pthread_mutex_unlock(&list->contexts[i]->lock);
            return list->contexts[i];
        }
        pthread_mutex_unlock(&list->contexts[i]->lock);
    }
    return NULL;
}

int add_ue_context(UE_List *list, int id, int signal_strength, long timestamp, const char *location, const char *subscription_details) {
    if (list->count >= list->capacity) {
        size_t new_capacity = (list->capacity == 0) ? 1 : list->capacity * 2;
        LTE_UE_Context **new_contexts = realloc(list->contexts, new_capacity * sizeof(LTE_UE_Context *));
        if (!new_contexts) return -1;
        list->contexts = new_contexts;
        list->capacity = new_capacity;
    }

    LTE_UE_Context *context = (LTE_UE_Context *)malloc(sizeof(LTE_UE_Context));
    if (!context) return -1;

    context->id = id;
    context->signal_strength = signal_strength;
    context->timestamp = timestamp;
    strncpy(context->location, location, sizeof(context->location) - 1);
    strncpy(context->subscription_details, subscription_details, sizeof(context->subscription_details) - 1);
    pthread_mutex_init(&context->lock, NULL);

    list->contexts[list->count++] = context;
    return 0;
}

int update_ue_context(UE_List *list, int id, int signal_strength, long timestamp, const char *location, const char *subscription_details) {
    LTE_UE_Context *context = find_ue_context(list, id);
    if (!context) return -1;

    pthread_mutex_lock(&context->lock);
    context->signal_strength = signal_strength;
    context->timestamp = timestamp;
    strncpy(context->location, location, sizeof(context->location) - 1);
    strncpy(context->subscription_details, subscription_details, sizeof(context->subscription_details) - 1);
    pthread_mutex_unlock(&context->lock);

    return 0;
}

int remove_ue_context(UE_List *list, int id) {
    LTE_UE_Context *context = find_ue_context(list, id);
    if (!context) return -1;

    pthread_mutex_lock(&context->lock);
    for (size_t i = list->count - 1; i > 0; i--) {
        pthread_mutex_lock(&list->contexts[i - 1]->lock);
        list->contexts[i] = list->contexts[i - 1];
        pthread_mutex_unlock(&list->contexts[i - 1]->lock);
    }
    pthread_mutex_unlock(&context->lock);

    pthread_mutex_destroy(&context->lock);
    free(context);
    list->count--;

    return 0;
}
