using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

namespace NetworkFSA
{
    public class FsaAnalyzer
    {
        private IExternalLogger _logger;

        public FsaAnalyzer(IExternalLogger logger)
        {
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        }

        public async Task AnalyzeAsync(string transitionMatrixJson, CancellationToken cancellationToken = default)
        {
            try
            {
                var transitionMatrix = ParseTransitionMatrix(transitionMatrixJson);
                if (transitionMatrix == null || !transitionMatrix.Any())
                {
                    _logger.LogError("Invalid or empty transition matrix provided.");
                    return;
                }

                var stateReports = GenerateStateReports(transitionMatrix);

                foreach (var report in stateReports)
                {
                    await _logger.LogAsync(report, cancellationToken);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError($"Error during FSA analysis: {ex.Message}");
                throw;
            }
        }

        private List<StateReport> GenerateStateReports(Dictionary<string, Dictionary<string, double>> transitionMatrix)
        {
            var reports = new List<StateReport>();

            foreach (var state in transitionMatrix.Keys)
            {
                var report = new StateReport
                {
                    CurrentState = state,
                    Transitions = transitionMatrix[state].Select(t => new Transition { NextState = t.Key, Probability = t.Value }).ToList()
                };
                reports.Add(report);
            }

            return reports;
        }

        private Dictionary<string, Dictionary<string, double>> ParseTransitionMatrix(string json)
        {
            try
            {
                // Use a JSON parser to convert the JSON string into a dictionary
                var transitionMatrix = JsonSerializer.Deserialize<Dictionary<string, Dictionary<string, double>>>(json);
                return transitionMatrix;
            }
            catch (JsonException ex)
            {
                _logger.LogError($"Error parsing JSON transition matrix: {ex.Message}");
                return null;
            }
        }

        private void Cleanup()
        {
            // Implement resource cleanup if needed
        }
    }

    public class StateReport
    {
        public string CurrentState { get; set; }
        public List<Transition> Transitions { get; set; }
    }

    public class Transition
    {
        public string NextState { get; set; }
        public double Probability { get; set; }
    }

    public interface IExternalLogger
    {
        Task LogAsync(string message, CancellationToken cancellationToken = default);
        void LogError(string errorMessage);
    }
}
