void add_reading_to_event(NetworkEvent *event, SensorReading *reading) {
    event->readings = realloc(event->readings, (event->reading_count + 1) * sizeof(SensorReading));
    memcpy(&event->readings[event->reading_count], reading, sizeof(SensorReading));
    event->reading_count++;
}

void serialize_event_to_json(NetworkEvent *event, char **json_str) {
