        json_object_object_add(reading_obj, "humidity", json_object_new_double(event->readings[i].humidity));
        json_object_object_add(reading_obj, "pressure", json_object_new_double(event->readings[i].pressure));
        json_object_array_add(readings_arr, reading_obj);
    }
    json_object_object_add(obj, "readings", readings_arr);

    *json_str = json_object_to_json_string_ext(obj, JSON_C_TO_STRING_PRETTY);
    json_object_put(obj);
}

