};

// Implement a simple in-memory message broker
class InMemoryMessageBroker : public MessageBroker {
private:
    std::unordered_map<std::string, std::queue<std::string>> topics;

public:
    void publish(const std::string& topic, const std::string& message) override {
        std::lock_guard<std::mutex> lock(mutex);
        topics[topic].push(message);
    }

    void subscribe(const std::string& topic, std::function<void(const std::string&)>& callback) override {
        subscribers[topic].push_back(callback);
    }
};

// Define a data storage interface
