    virtual void saveEvent(const NetworkEvent& event) = 0;
    virtual bool loadEvent(int EventID, NetworkEvent& event) const = 0;
};

// Implement a simple in-memory data storage
class InMemoryDataStorage : public DataStorage {
private:
