using System;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

public class XmlService : IXmlService
{
    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _cache;
    private readonly ILogger<XmlService> _logger;

    public XmlService(HttpClient httpClient, IMemoryCache cache, ILogger<XmlService> logger)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<string> GetXmlAsync(string sourceUrl, string xpathQuery, int? cacheDurationMinutes = null)
    {
        if (string.IsNullOrEmpty(sourceUrl))
            throw new ArgumentException("Source URL cannot be null or empty", nameof(sourceUrl));

        if (string.IsNullOrEmpty(xpathQuery))
            throw new ArgumentException("XPath query cannot be null or empty", nameof(xpathQuery));

        string cachedXml = _cache.Get<string>(sourceUrl);
        if (!string.IsNullOrEmpty(cachedXml))
        {
            return cachedXml;
        }

        string xmlData = await FetchXmlAsync(sourceUrl);
        string parsedXml = ParseXml(xmlData, xpathQuery);

        int cacheDuration = cacheDurationMinutes ?? 5; // Default to 5 minutes
        _cache.Set(sourceUrl, parsedXml, new MemoryCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(cacheDuration)
        });

        return parsedXml;
    }

    private async Task<string> FetchXmlAsync(string sourceUrl)
    {
        try
        {
            HttpResponseMessage response = await _httpClient.GetAsync(sourceUrl);
            response.EnsureSuccessStatusCode();
            string xmlData = await response.Content.ReadAsStringAsync();
            return xmlData;
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Failed to fetch XML from source URL: {SourceUrl}", sourceUrl);
            throw new IOException($"Failed to fetch XML from source URL: {sourceUrl}", ex);
        }
    }

    private string ParseXml(string xmlData, string xpathQuery)
    {
        // Implement your XML parsing logic here using XPath or LINQ to XML
        var xmlDoc = System.Xml.Linq.XDocument.Parse(xmlData);
        var nodes = xmlDoc.XPathSelectElements(xpathQuery).ToList();
        return nodes.Aggregate((current, next) => current + "\n" + next.ToString());
    }
}
