#include <pthread.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    // Add other necessary members for dynamic resizing and thread safety
} CRC_Indication_Library;

CRC_Indication_Library* crc_lib_init(size_t initial_capacity) {
    CRC_Indication_Library* lib = malloc(sizeof(CRC_Indication_Library));
    if (!lib) return NULL;

    lib->pdus = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!lib->pdus) {
        free(lib);
        return NULL;
    }

    lib->capacity = initial_capacity;
    lib->size = 0;
    pthread_mutex_init(&lib->mutex, NULL);

    // Initialize other necessary members for dynamic resizing and thread safety

    return lib;
}

void crc_lib_destroy(CRC_Indication_Library* lib) {
    free(lib->pdus);
    pthread_mutex_destroy(&lib->mutex);
    free(lib);
}

bool crc_lib_add_pdu(CRC_Indication_Library* lib, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&lib->mutex);

    if (lib->size == lib->capacity) {
        size_t new_capacity = lib->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_pdus = realloc(lib->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdus) {
            pthread_mutex_unlock(&lib->mutex);
            return false;
        }
        lib->pdus = new_pdus;
        lib->capacity = new_capacity;
    }

    memcpy(&lib->pdus[lib->size], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    lib->size++;

    pthread_mutex_unlock(&lib->mutex);

    return true;
}

