#include <openssl/evp.h>
#include <openssl/rand.h>

class EncryptionModule {
public:
    EncryptionModule(const std::string& passphrase, int iterations)
        : passphrase(passphrase), iterations(iterations) {}

    ~EncryptionModule() {
        EVP_cleanup();
    }

    std::vector<unsigned char> encrypt(const std::string& data) {
        if (!EVP_EncryptInit_ex(context, EVP_aes_256_cbc(), nullptr, key.data(), iv.data())) {
            throw std::runtime_error("Failed to initialize encryption");
        }
        std::vector<unsigned char> ciphertext(data.size() + EVP_CIPHER_block_size(EVP_aes_256_cbc()));
        int len;
        if (!EVP_EncryptUpdate(context, ciphertext.data(), &len, data.c_str(), data.size())) {
            throw std::runtime_error("Failed to update encryption");
        }
        int ciphertext_len = len;
        if (!EVP_EncryptFinal_ex(context, ciphertext.data() + len, &len)) {
            throw std::runtime_error("Failed to finalize encryption");
        }
        ciphertext_len += len;
        ciphertext.resize(ciphertext_len);
        return ciphertext;
    }

    std::string decrypt(const std::vector<unsigned char>& ciphertext) {
        if (!EVP_DecryptInit_ex(context, EVP_aes_256_cbc(), nullptr, key.data(), iv.data())) {
            throw std::runtime_error("Failed to initialize decryption");
        }
        std::vector<unsigned char> plaintext(ciphertext.size());
        int len;
        if (!EVP_DecryptUpdate(context, plaintext.data(), &len, ciphertext.data(), ciphertext.size())) {
            throw std::runtime_error("Failed to update decryption");
        }
        int plaintext_len = len;
        if (!EVP_DecryptFinal_ex(context, plaintext.data() + len, &len)) {
            throw std::runtime_error("Failed to finalize decryption");
        }
        plaintext_len += len;
        plaintext.resize(plaintext_len);
        return std::string(plaintext.begin(), plaintext.end());
    }

private:
    EVP_CIPHER_CTX* context = EVP_CIPHER_CTX_new();
    std::string passphrase;
    int iterations;
    std::vector<unsigned char> key(32); // 256-bit key
    std::vector<unsigned char> iv(16); // 128-bit IV

    void derive_key_and_iv() {
        if (!PKCS5_PBKDF2_HMAC(passphrase.c_str(), passphrase.size(), nullptr, 0, iterations, EVP_sha256(), key.data(), key.size())) {
            throw std::runtime_error("Failed to derive key and IV");
        }
        if (!RAND_bytes(iv.data(), iv.size())) {
            throw std::runtime_error("Failed to generate IV");
        }
    }

    EncryptionModule() = delete;
};

int main() {
    EncryptionModule encryption("securepassphrase", 10000);
    std::string data = "sensitive data";
    try {
        auto encrypted = encryption.encrypt(data);
        auto decrypted = encryption.decrypt(encrypted);
        if (decrypted != data) {
            throw std::runtime_error("Decryption failed");
        }
        std::cout << "Data successfully encrypted and decrypted: " << decrypted << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
