class DataIngestionPipeline:
    def __init__(self, bootstrap_servers):
        self.producer = KafkaProducer(bootstrap_servers=bootstrap_servers)
        self.spark = SparkSession.builder.appName("DataProcessing").getOrCreate()
        self.anomaly_detector = AnomalyDetector()
        self.data_queue = queue.Queue(maxsize=10000)

    def start_pipeline(self):
        threading.Thread(target=self.ingest_data, daemon=True).start()
        threading.Thread(target=self.process_data, daemon=True).start()
        threading.Thread(target=self.monitor_and_alerts, daemon=True).start()

    def ingest_data(self):
        while True:
            try:
                frame_header = self.read_frame_from_rf_source()
                if frame_header:
                    self.data_queue.put(frame_header)
            except Exception as e:
                print(f"Error reading data from RF source: {e}")
                time.sleep(1)

    def process_data(self):
        while True:
            try:
                frame_header = self.data_queue.get(timeout=5)
                processed_data = self.process_frame(frame_header)
                if processed_data:
                    self.producer.send('processed_data_topic', value=processed_data)
                    self.spark.process(processed_data)
                    self.anomaly_detector.update_model(processed_data)
            except queue.Empty:
                pass
            except Exception as e:
                print(f"Error processing data: {e}")
                self.data_queue.task_done()

    def monitor_and_alerts(self):
