public class ConfigManager {

    private static final ConcurrentHashMap<String, String> configCache = new ConcurrentHashMap<>();
    private static Map<String, String> latestConfig = new HashMap<>();

    public void updateConfig(String serviceName, String key, String value) {
        synchronized (latestConfig) {
            latestConfig.put(key, value);
        }
        broadcastUpdate(serviceName, key, value);
    }

    private void broadcastUpdate(String serviceName, String key, String value) {
        for (String service : getAllServices()) {
            if (!service.equals(serviceName)) {
                ServiceRegistry.getInstance().sendUpdate(service, key, value);
            }
        }
    }

    public String getConfig(String serviceName, String key) {
        return configCache.getOrDefault(key, latestConfig.getOrDefault(key, null));
    }

    private Iterable<String> getAllServices() {
        // Mock implementation
        return ServiceRegistry.getInstance().getAllServiceNames();
