                .unwrap_or(4),
            debug: matches.is_present("debug"),
            output: matches.value_of_lossy("output").unwrap_or_else(|| "output.log".into()),
        }
    }
}

#[tokio::main]
async fn main() {
    let config = Processor::handle_command_line_args();
    let processor = Processor::new(config, 1024);

    processor.run().await;
}
