        response = {
            'state': task.state,
            'current_task': str(task.id),
            'status': 'Task is not started yet'
        }
    elif task.state != 'FAILURE':
        response = {
            'task_id': task.id,
            'state': task.state,
            'current_task': str(task.id),
            'result': task.result
        }
    else:
        response = {
            'state': task.state,
            'current_task': str(task.id),
            'status': str(task.info),  # this is the exception raised
        }
    return jsonify(response)

