public class UserService {

    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final RateLimiter rateLimiter = RateLimiter.create(50.0);
    private final BlockingQueue<Runnable> taskQueue;

    public UserService() {
        this.taskQueue = new ArrayBlockingQueue<>(1000); // Adjust queue size as needed
    }

    public void processRequest(String userId) {
        if (rateLimiter.tryAcquire()) {
            executor.submit(() -> {
                try {
                    String hash = generateHash(userId);
                    fetchUserMetadata(hash);
                } catch (Exception e) {
                    handleException(e);
                }
            });
        } else {
            backoffAndRetry();
        }
    }

    private String generateHash(String userId) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(userId.getBytes());
        return bytesToHex(hashBytes);
    }

    private String fetchUserMetadata(String hash) {
        // Simulate API call to external metadata provider
        try {
            Thread.sleep(100); // Simulated delay for demonstration purposes
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return "User Metadata: " + hash;
    }

    private void handleException(Exception e) {
        // Implement error handling logic here, including logging and fallback mechanisms
        System.err.println("Error processing request: " + e.getMessage());
    }

    private void backoffAndRetry() {
        try {
            Thread.sleep(100); // Simple exponential backoff strategy
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        processRequest(getNextUserId()); // Retry with next user ID
    }

    private String getNextUserId() {
        // Implement logic to retrieve the next user ID from a queue or another source
        return "next-user-id";
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public void shutdown() {
        executor.shutdownNow();
    }

    public static void main(String[] args) {
        UserService userService = new UserService();
        // Simulate processing incoming requests
        for (int i = 0; i < 1000; i++) {
            userService.processRequest("user-" + i);
        }
        userService.shutdown();
    }
}
