import java.util.concurrent.atomic.AtomicInteger;

public class AsyncNetworkManager {

    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final AtomicInteger activeConnections = new AtomicInteger(0);
    private static final int MAX_CONNECTIONS = 100;

    public CompletableFuture<String> sendRequest(String serviceUrl, String request) {
        if (activeConnections.get() >= MAX_CONNECTIONS) {
            return CompletableFuture.failedFuture(new IllegalStateException("Too many connections"));
        }

        activeConnections.incrementAndGet();
        return CompletableFuture.supplyAsync(() -> {
            try {
                // Simulate network request
                TimeUnit.SECONDS.sleep(1);
                return simulateNetworkResponse(request);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException(e);
            } finally {
                activeConnections.decrementAndGet();
            }
        }, executor);
    }

    private String simulateNetworkResponse(String request) {
        // Simulate network response
        return "Response for: " + request;
    }

    public void close() {
        executor.shutdownNow();
    }

    public static void main(String[] args) throws InterruptedException {
        AsyncNetworkManager manager = new AsyncNetworkManager();

        CompletableFuture<String> future1 = manager.sendRequest("http://service1", "request1");
        CompletableFuture<String> future2 = manager.sendRequest("http://service2", "request2");

        System.out.println(future1.get());
        System.out.println(future2.get());

        manager.close();
    }
}
