#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_NUM_TYPES 5
typedef enum {
    INT_TYPE,
    FLOAT_TYPE,
    DOUBLE_TYPE,
    FIXED_POINT_TYPE,
    ARBITRARY_PRECISION_TYPE
} NumericType;

typedef struct {
    NumericType type;
    union {
        int intValue;
        float floatValue;
        double doubleValue;
        // fixed-point and arbitrary precision number types here
    };
} DynamicNumber;

typedef struct {
    DynamicNumber *numbers;
    int count;
    size_t allocatedSize;
} DynamicRangeGenerator;

DynamicRangeGenerator* createDRG() {
    DynamicRangeGenerator *drg = (DynamicRangeGenerator*)malloc(sizeof(DynamicRangeGenerator));
    drg->numbers = NULL;
    drg->count = 0;
    drg->allocatedSize = 0;
    return drg;
}

void addNumber(DynamicRangeGenerator *drg, NumericType type, void *value) {
    if (drg->count >= drg->allocatedSize) {
        size_t newSize = (drg->allocatedSize == 0) ? 1 : drg->allocatedSize * 2;
        DynamicNumber *newNumbers = realloc(drg->numbers, newSize * sizeof(DynamicNumber));
        if (newNumbers == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        drg->numbers = newNumbers;
        drg->allocatedSize = newSize;
    }
    DynamicNumber num;
    num.type = type;
    switch(type) {
        case INT_TYPE:
            num.intValue = *(int*)value;
            break;
        case FLOAT_TYPE:
            num.floatValue = *(float*)value;
            break;
        case DOUBLE_TYPE:
            num.doubleValue = *(double*)value;
            break;
        // handle fixed-point and arbitrary precision types
    }
    drg->numbers[drg->count++] = num;
}

void validateRange(DynamicRangeGenerator *drg) {
    for (int i = 0; i < drg->count - 1; i++) {
        if (drg->numbers[i].type != drg->numbers[i+1].type) {
            fprintf(stderr, "Inconsistent numeric types in range\n");
            exit(1);
        }
        // perform validation based on type
    }
}

void destroyDRG(DynamicRangeGenerator *drg) {
    free(drg->numbers);
    free(drg);
}
