#include <iostream>
#include <vector>
#include <string>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>

class EncryptionLibrary {
public:
    EncryptionLibrary() {}
    ~EncryptionLibrary() {}

    std::string encrypt(const std::string& data, const std::string& key, const std::string& iv) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, (unsigned char*)key.c_str(), (unsigned char*)iv.c_str());
        std::vector<unsigned char> ciphertext(data.length() + EVP_CIPHER_block_size(EVP_des_ede3_cbc()));
        int len;
        EVP_EncryptUpdate(ctx, &ciphertext[0], &len, (unsigned char*)data.c_str(), data.length());
        int ciphertext_len = len;
        EVP_EncryptFinal_ex(ctx, &ciphertext[len], &len);
        ciphertext_len += len;
        EVP_CIPHER_CTX_free(ctx);

        return std::string((char*)&ciphertext[0], ciphertext_len);
    }

    std::string decrypt(const std::string& ciphertext, const std::string& key, const std::string& iv) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_DecryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, (unsigned char*)key.c_str(), (unsigned char*)iv.c_str());
        std::vector<unsigned char> plaintext(ciphertext.length() + EVP_CIPHER_block_size(EVP_des_ede3_cbc()));
        int len;
        EVP_DecryptUpdate(ctx, &plaintext[0], &len, (unsigned char*)ciphertext.c_str(), ciphertext.length());
        int plaintext_len = len;
        EVP_DecryptFinal_ex(ctx, &plaintext[len], &len);
        plaintext_len += len;
        EVP_CIPHER_CTX_free(ctx);

        return std::string((char*)&plaintext[0], plaintext_len);
    }
};

int main() {
    EncryptionLibrary lib;
    std::string data = "Hello, World!";
    std::string key = "123456789012345678901234";
    std::string iv = "12345678";

    std::string encrypted = lib.encrypt(data, key, iv);
    std::cout << "Encrypted: " << encrypted << std::endl;

    std::string decrypted = lib.decrypt(encrypted, key, iv);
    std::cout << "Decrypted: " << decrypted << std::endl;

    return 0;
}
```

