    fn run(&self) {
        // Implement command-line argument parsing and validation
        let args = parse_command_line_arguments();
        if args.contains_key("--help") {
            self.show_help();
            return;
        }
        if args.contains_key("--version") {
            self.show_version();
            return;
        }

