#include <iostream>
#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <fstream>
#include <json/json.h>

class SensorDataProcessor {
public:
    struct TelemetryMessage {
        std::string deviceID;
        Json::Value data;
        long timestamp;
    };

    SensorDataProcessor(size_t maxBufferSize, size_t numThreads)
        : maxBufferSize(maxBufferSize), numThreads(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back(&SensorDataProcessor::workerThread, this);
        }
    }

    ~SensorDataProcessor() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        cv.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void addMessage(const TelemetryMessage& message) {
        {
            std::unique_lock<std::mutex> lock(mutex);
            while (queue.size() >= maxBufferSize) {
                cv.wait(lock, [this] { return queue.size() < maxBufferSize || stop; });
            }
            if (!stop) {
                queue.push(message);
            }
        }
        cv.notify_one();
    }

private:
    void workerThread() {
        while (true) {
            TelemetryMessage message;
            {
                std::unique_lock<std::mutex> lock(mutex);
                cv.wait(lock, [this] { return !queue.empty() || stop; });
                if (stop && queue.empty()) {
                    break;
                }
                message = queue.front();
                queue.pop();
            }
            processMessage(message);
        }
    }

    void processMessage(const TelemetryMessage& message) {
        // Process the telemetry message here
        std::cout << "Processing message from device: " << message.deviceID << std::endl;
    }

    size_t maxBufferSize;
    size_t numThreads;
    std::queue<TelemetryMessage> queue;
    std::mutex mutex;
    std::condition_variable cv;
    bool stop = false;
    std::vector<std::thread> workers;
};
