using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading.Tasks;

public interface IDynamicRangeGenerator<T> where T : IComparable<T>
{
    void SetRange(T min, T max);
    T GenerateRandomNumber(bool inclusive);
}

public class DynamicRangeGenerator<T> : IDynamicRangeGenerator<T> where T : IComparable<T>
{
    private T _min;
    private T _max;
    private ConcurrentDictionary<string, T> _cache = new ConcurrentDictionary<string, T>();
    private Random _random;

    public DynamicRangeGenerator()
    {
        _random = new Random();
    }

    public void SetRange(T min, T max)
    {
        if (min.CompareTo(max) >= 0)
            throw new ArgumentException("Min value must be less than max value.");

        _min = min;
        _max = max;
    }

    public T GenerateRandomNumber(bool inclusive)
    {
        var key = $"{_min}-{_max}";
        if (_cache.TryGetValue(key, out var cachedValue))
            return cachedValue;

        var randomNumber = inclusive
            ? (T)Convert.ChangeType(_random.NextDouble() * (_max.CompareTo(_min).Sign + 1) + _min, typeof(T))
            : (T)Convert.ChangeType(_random.NextDouble() * (_max.CompareTo(_min).Sign) + _min, typeof(T));

        _cache.TryAdd(key, randomNumber);
        return randomNumber;
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        var generator = new DynamicRangeGenerator<int>();
        generator.SetRange(1, 100);

        for (int i = 0; i < 10; i++)
        {
            Console.WriteLine(generator.GenerateRandomNumber(true));
        }
    }
}
