using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.NetworkInformation;
using System.Threading.Tasks;

public class DynamicNetworkHealthMonitor : IDisposable
{
    private readonly Dictionary<string, ServerInstance> _serverInstances = new();
    private readonly List<IMonitoringProtocol> _monitoringProtocols = new();
    private readonly AlertingFramework _alertingFramework;
    private Timer _healthCheckTimer;

    public DynamicNetworkHealthMonitor(List<IMonitoringProtocol> monitoringProtocols, AlertingFramework alertingFramework)
    {
        _monitoringProtocols.AddRange(monitoringProtocols);
        _alertingFramework = alertingFramework;
    }

    public void AddServerInstance(string instanceId, string provider, string endpoint)
    {
        if (_serverInstances.ContainsKey(instanceId))
            throw new ArgumentException("Server instance already exists", nameof(instanceId));

        var serverInstance = new ServerInstance
        {
            InstanceId = instanceId,
            Provider = provider,
            Endpoint = endpoint,
            HealthStatus = HealthStatus.Unknown
        };

        _serverInstances[instanceId] = serverInstance;
    }

    public void StartMonitoring()
    {
        _healthCheckTimer = new Timer(HealthCheck, null, TimeSpan.Zero, TimeSpan.FromSeconds(60));
    }

    private void HealthCheck(object state)
    {
        var tasks = _serverInstances.Values.Select(async instance =>
        {
            try
            {
                var healthStatus = await CheckInstanceHealth(instance);
                if (healthStatus != instance.HealthStatus)
                {
                    instance.HealthStatus = healthStatus;
                    HandleHealthChange(instance);
                }
            }
            catch (Exception ex)
            {
                _alertingFramework.NotifyAlert(new Alert
                {
                    InstanceId = instance.InstanceId,
                    Provider = instance.Provider,
                    Message = $"Health check failed for {instance.Endpoint}: {ex.Message}",
                    Severity = AlertSeverity.Error
                });
            }
        }).ToList();

        await Task.WhenAll(tasks);
    }

    private async Task<HealthStatus> CheckInstanceHealth(ServerInstance instance)
    {
        foreach (var protocol in _monitoringProtocols)
        {
            var healthCheckResult = await protocol.CheckHealth(instance.Endpoint);
            if (!healthCheckResult.IsHealthy)
                return HealthStatus.Unhealthy;

            // Additional custom logic for threshold-based health checks
        }

        return HealthStatus.Healthy;
    }

    private void HandleHealthChange(ServerInstance instance)
    {
        switch (instance.HealthStatus)
        {
            case HealthStatus.Healthy:
                _alertingFramework.NotifyAlert(new Alert
                {
                    InstanceId = instance.InstanceId,
                    Provider = instance.Provider,
                    Message = $"Instance {instance.Endpoint} is now healthy",
                    Severity = AlertSeverity.Info
                });
                break;
            case HealthStatus.Unhealthy:
                _alertingFramework.NotifyAlert(new Alert
                {
                    InstanceId = instance.InstanceId,
                    Provider = instance.Provider,
                    Message = $"Instance {instance.Endpoint} has gone unhealthy",
                    Severity = AlertSeverity.Warning
                });
                break;
        }
    }

    public void Dispose()
    {
        _healthCheckTimer?.Change(Timeout.Infinite, 0);
        _healthCheckTimer?.Dispose();
    }
}

public interface IMonitoringProtocol
{
    Task<HealthCheckResult> CheckHealth(string endpoint);
}

public class HealthCheckResult
{
    public bool IsHealthy { get; set; }
}

public enum HealthStatus
{
    Unknown,
    Healthy,
    Unhealthy
}

public enum AlertSeverity
{
    Info,
    Warning,
    Error
}

public class Alert
{
    public string InstanceId { get; set; }
    public string Provider { get; set; }
    public string Message { get; set; }
    public AlertSeverity Severity { get; set; }
}

public class AlertingFramework
{
    public void NotifyAlert(Alert alert)
    {
        // Implementation for sending alerts to various backends
        Console.WriteLine($"Sending {alert.Severity} alert: {alert.Message}");
    }
}

public class ServerInstance
{
