    std::string source;
    double value;
    std::chrono::system_clock::time_point timestamp;
};

class DataPipeline {
public:
    DataPipeline(int buffer_size) : max_buffer_size(buffer_size), shutdown(false) {}

    void start() {
        ingestion_thread = std::thread(&DataPipeline::ingestData, this);
        processing_thread = std::thread(&DataPipeline::processData, this);
        storage_thread = std::thread(&DataPipeline::storeData, this);
        analysis_thread = std::thread(&DataPipeline::analyzeData, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            shutdown = true;
        }
        condition.notify_all();
        ingestion_thread.join();
        processing_thread.join();
        storage_thread.join();
        analysis_thread.join();
    }

private:
    void ingestData() {
        while (true) {
            SensorData data = fetchDataFromSources(); // Simulated fetch
            if (shutdown) break;
            ingestion_queue.push(data);
            condition.notify_one();
        }
    }

    void processData() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !ingestion_queue.empty() || shutdown; });
            if (shutdown && ingestion_queue.empty()) break;
            SensorData data = ingestion_queue.front();
            ingestion_queue.pop();
            lock.unlock();

            // Simulated processing
            double processedValue = applyTransformations(data.value);

            processing_queue.push(processedValue);
        }
    }

    void storeData() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !processing_queue.empty() || shutdown; });
            if (shutdown && processing_queue.empty()) break;
            double value = processing_queue.front();
            processing_queue.pop();
            lock.unlock();

            // Simulated storage
            saveDataToStore(value);
        }
    }

    void analyzeData() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !processing_queue.empty() || shutdown; });
            if (shutdown && processing_queue.empty()) break;
            double value = processing_queue.front();
            processing_queue.pop();
            lock.unlock();

            // Simulated data analysis
            analyzeValue(value);
        }
    }

    SensorData fetchDataFromSources() {
        // Placeholder for fetching data from various sources
        return {"source1", 42.0, std::chrono::system_clock::now()};
    }

    double applyTransformations(double value) {
        // Placeholder for applying transformations
        return value * 2;
    }

    void saveDataToStore(double value) {
        // Placeholder for saving data to a storage system
        std::cout << "Storing value: " << value << std::endl;
    }

    void analyzeValue(double value) {
        // Placeholder for analyzing data
        std::cout << "Analyzing value: " << value << std::endl;
    }

private:
