class IoTDataProcessor {
public:
    IoTDataProcessor(size_t numThreads) : running(true), numWorkerThreads(numThreads) {
        for (size_t i = 0; i < numWorkerThreads; ++i) {
            workers.emplace_back([this, i]() { workerLoop(i); });
        }
    }

    ~IoTDataProcessor() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            running = false;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void processSensorData(const std::string& data) {
        std::unique_lock<std::mutex> lock(queueMutex);
        queue.push(data);
        lock.unlock();
        condition.notify_one();
    }

private:
    void workerLoop(size_t threadId) {
        while (true) {
            std::string data;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                condition.wait(lock, [this] { return !queue.empty() || !running; });
                if (!running && queue.empty()) {
                    break;
                }
                data = queue.front();
                queue.pop();
            }
            processData(data, threadId);
        }
    }

    void processData(const std::string& data, size_t threadId) {
        // Simulate processing time
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        std::cout << "Thread " << threadId << " processed data: " << data << std::endl;
    }

    std::atomic<bool> running;
    size_t numWorkerThreads;
    std::vector<std::thread> workers;
