import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class SensorDataProcessor {
    private static final int MAX_SENSORS = 500;
    private ExecutorService executorService;
    private IoTPlatformConnector iotPlatformConnector;
    private AnomalyDetector anomalyDetector;
    private DataArchiver dataArchiver;

    public SensorDataProcessor() {
        this.executorService = Executors.newFixedThreadPool(MAX_SENSORS);
        this.iotPlatformConnector = new IoTPlatformConnector();
        this.anomalyDetector = new AnomalyDetector();
        this.dataArchiver = new DataArchiver();
    }

    public void startProcessing() {
        for (int i = 0; i < MAX_SENSORS; i++) {
            executorService.submit(new SensorDataHandler(iotPlatformConnector, anomalyDetector, dataArchiver));
        }
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

