// Define interfaces for different data ingestion sources
class DataIngestionSource {
public:
    virtual ~DataIngestionSource() {}
    virtual void start() = 0;
    virtual void stop() = 0;
};

// Implementations for Kafka, MQTT, and HTTP sources
class KafkaSource : public DataIngestionSource {
public:
    void start() override { /* Implementation */ }
    void stop() override { /* Implementation */ }
