#include <pthread.h>
#include <stdlib.h>
#include <string.h>

// Define the structure for LTE UE context
typedef struct {
    int id;
    int signal_strength;
    long timestamp;
    char location[100];
    // Add more fields as needed
} LTE_UE_Context;

// Define a node in the linked list for dynamic storage
typedef struct Node {
    LTE_UE_Context data;
    struct Node* next;
} Node;

// Define the structure for the dynamic list
typedef struct {
    pthread_mutex_t mutex;
    Node* head;
} LTE_UE_List;

// Function to initialize the dynamic list
void init_lte_ue_list(LTE_UE_List* list) {
    pthread_mutex_init(&list->mutex, NULL);
    list->head = NULL;
}

// Function to add a new UE context to the list
void add_lte_ue_context(LTE_UE_List* list, LTE_UE_Context context) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = context;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
}

// Function to update an existing UE context in the list
void update_lte_ue_context(LTE_UE_List* list, int id, LTE_UE_Context context) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.id == id) {
            current->data = context;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to remove an UE context from the list
void remove_lte_ue_context(LTE_UE_List* list, int id) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    Node* previous = NULL;
    while (current != NULL) {
        if (current->data.id == id) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to find an UE context by ID
LTE_UE_Context* find_lte_ue_context(LTE_UE_List* list, int id) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.id == id) {
            LTE_UE_Context* result = malloc(sizeof(LTE_UE_Context));
            *result = current->data;
            pthread_mutex_unlock(&list->mutex);
            return result;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

// Function to clean up the dynamic list
void cleanup_lte_ue_list(LTE_UE_List* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
}

// Example usage
int main() {
    LTE_UE_List lte_list;
    init_lte_ue_list(&lte_list);

    LTE_UE_Context context1 = {1, -50, 1633072800, "Cell A"};
    add_lte_ue_context(&lte_list, context1);

    LTE_UE_Context context2 = {2, -45, 1633072801, "Cell B"};
    update_lte_ue_context(&lte_list, 2, context2);

    LTE_UE_Context* found_context = find_lte_ue_context(&lte_list, 1);
    if (found_context != NULL) {
        printf("Found UE Context: ID=%d, Signal=%d\n", found_context->id, found_context->signal_strength);
        free(found_context);
    }

    remove_lte_ue_context(&lte_list, 2);

    cleanup_lte_ue_list(&lte_list);

    return 0;
}
