public class ConfigurationManager {
    private final Cache<String, Config> cache;
    private final Map<String, ConfigSource> configSources;

    public ConfigurationManager(Cache<String, Config> cache, Map<String, ConfigSource> configSources) {
        this.cache = cache;
        this.configSources = configSources;
    }

    public Config getConfig(String key) {
        Config cachedConfig = cache.getIfPresent(key);
        if (cachedConfig == null) {
            Config newConfig = fetchConfigFromSource(key);
            cache.put(key, newConfig);
            return newConfig;
        }
        return cachedConfig;
    }

    private Config fetchConfigFromSource(String key) {
        // Fetch config from the appropriate source
        return configSources.get(key).fetchConfig();
    }

    public void updateConfig(String key, String value) {
        Config config = cache.getIfPresent(key);
        if (config != null) {
            config.update(value);
            cache.put(key, config);
            notifyListeners(key, value);
        }
    }

