#include <forward_list>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <optional>
#include "json.hpp" // External library for JSON serialization

namespace {
    std::mutex mtx;
    std::condition_variable cv;
}

void insertAfterTimeout(std::forward_list<std::string>& list, const std::string& key, const std::string& target, std::chrono::milliseconds timeout) {
    std::unique_lock<std::mutex> lock(mtx);
    if (cv.wait_for(lock, timeout, [&list, &key]() -> bool {
        return !list.empty() && list.front() == key;
    })) {
        // Key found within the timeout
        auto& front = list.front();
        list.pop_front(); // Remove the front element (the key)
        list.push_front(front); // Reinsert the key at the front to preserve order
        list.insert_after(list.before_begin(), target);
    } else {
        // Timeout occurred without finding the key
        throw std::runtime_error("Key not found within timeout");
    }
}

std::string serializeToJson(const std::forward_list<std::string>& list) {
    nlohmann::json jsonList;
    for (const auto& item : list) {
        jsonList.push_back(item);
    }
    return jsonList.dump();
}
