class DataProcessor {
public:
    void addData(std::shared_ptr<void> data) {
        std::unique_lock<std::mutex> lock(queueMutex);
        dataQueue.push(data);
        condition.notify_one();
    }

    std::optional<std::shared_ptr<void>> getData() {
        std::unique_lock<std::mutex> lock(queueMutex);
        if (dataQueue.empty()) {
            return {};
        }
        auto data = dataQueue.front();
        dataQueue.pop();
        return data;
    }

private:
    std::queue<std::shared_ptr<void>> dataQueue;
    mutable std::mutex queueMutex;
    std::condition_variable condition;
};

class IoTMiddleware {
public:
    void start() {
        processThread = std::thread(&IoTMiddleware::processData, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(stopMutex);
            stopFlag = true;
        }
        condition.notify_all();
        if (processThread.joinable()) {
            processThread.join();
        }
    }

private:
    void processData() {
        while (true) {
            auto data = dataProcessor.getData();
            if (!data) {
                std::unique_lock<std::mutex> lock(stopMutex);
                if (stopFlag) break;
                condition.wait(lock, [this]{ return stopFlag || !dataProcessor.dataQueue.empty(); });
                continue;
            }
            // Process the data
            process(data.value());
        }
    }

    void process(std::shared_ptr<void> data) {
        // Data processing logic here
        std::cout << "Processing data" << std::endl;
    }

    DataProcessor dataProcessor;
    std::thread processThread;
    std::mutex stopMutex;
    bool stopFlag = false;
    std::condition_variable condition;
};

int main() {
    IoTMiddleware middleware;
    middleware.start();

    // Simulate adding data
    for (int i = 0; i < 1000; ++i) {
        auto data = std::make_shared<void>(nullptr); // Replace with actual data
        middleware.addData(data);
    }

    std::this_thread::sleep_for(std::chrono::seconds(5));
    middleware.stop();

    return 0;
}
