### Encryption and Decryption Module (C with OpenSSL)

```c
#include <openssl/evp.h>
#include <openssl/hmac.h>
#include <openssl/rand.h>

int encrypt_data(const char *plaintext, size_t plaintext_len, const unsigned char *key,
                 const unsigned char *iv, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) return -1;
    int len;
    if (!EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) return -1;
    ciphertext += len;
    int ciphertext_len = len;
    if (!EVP_EncryptFinal_ex(ctx, ciphertext, &len)) return -1;
    ciphertext_len += len;
    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

int decrypt_data(const unsigned char *ciphertext, size_t ciphertext_len, const unsigned char *key,
                 const unsigned char *iv, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) return -1;
    int len;
    if (!EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) return -1;
    plaintext += len;
    int plaintext_len = len;
    if (!EVP_DecryptFinal_ex(ctx, plaintext, &len)) return -1;
    plaintext_len += len;
    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;
}
