#include <iostream>
#include <mutex>
#include <queue>
#include <thread>
#include <atomic>
#include <condition_variable>
#include <memory>
#include <chrono>
#include <string>
#include <variant>

struct LogEntry {
    std::chrono::system_clock::time_point timestamp;
    int event_code;
    std::variant<int, double, std::string> context_data;
};

class NetworkEventProcessor {
public:
    void processLog(const LogEntry& log) {
        // Simulate processing
        std::cout << "Processing log entry: " << log.timestamp.time_since_epoch().count() 
                  << ", Event Code: " << log.event_code << ", Context: " << log.context_data.index() << std::endl;
    }
};

class Logger {
public:
    void addLog(const LogEntry& log) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(log);
        cond_var_.notify_one();
    }

private:
    NetworkEventProcessor processor_;
    std::queue<LogEntry> queue_;
    std::mutex mutex_;
    std::condition_variable cond_var_;

    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cond_var_.wait(lock, [this]{ return !queue_.empty(); });
            LogEntry log = queue_.front();
            queue_.pop();
            lock.unlock();

            processor_.processLog(log);
        }
    }

public:
    Logger() {
        for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
            worker_threads_.emplace_back(&Logger::worker, this);
        }
    }

    ~Logger() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            stop_ = true;
        }
        cond_var_.notify_all();
        for (auto& thread : worker_threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

private:
    bool stop_{false};
    std::vector<std::thread> worker_threads_;
};

int main() {
    Logger logger;
    logger.addLog({std::chrono::system_clock::now(), 1, 42});
    return 0;
}
