// Main class to define the message broker
public class MessageBroker {
    private final Queue<Message> messageQueue = new ConcurrentLinkedQueue<>();
    private final Map<String, Set<Connection>> subscriptions = new ConcurrentHashMap<>();

    public void publish(Message message) {
        for (String topic : message.getTopics()) {
            subscriptions.getOrDefault(topic, Collections.emptySet()).forEach(sub -> sub.send(message));
        }
        if (message.isPersistent()) {
            messageQueue.offer(message);
        }
    }

    public void subscribe(String topic, Connection connection) {
        subscriptions.computeIfAbsent(topic, k -> new HashSet<>()).add(connection);
    }

    public void unsubscribe(String topic, Connection connection) {
        subscriptions.getOrDefault(topic, Collections.emptySet()).remove(connection);
    }

    public void start() {
        // Start processing messages
        while (true) {
            Message message = messageQueue.poll();
            if (message != null) {
                deliverMessage(message);
            }
        }
    }

    private void deliverMessage(Message message) {
        for (String topic : message.getTopics()) {
            subscriptions.getOrDefault(topic, Collections.emptySet()).forEach(sub -> sub.send(message));
        }
    }

    public static void main(String[] args) {
        MessageBroker broker = new MessageBroker();
        // Start the broker
        broker.start();
        // Simulate connections and messages
        // ...
    }
}

// Interface for message delivery
interface Connection {
    void send(Message message);
}

// Class representing a message with topics and persistence flag
