    SECURE_CREDENTIAL_AUTH_TOKEN_MISSING,
    SECURE_CREDENTIAL_SERVICE_UNAVAILABLE,
    SECURE_CREDENTIAL_RATE_LIMIT_EXCEEDED
} SecureCredentialErrorCode;

