angular.module('dialogRefreshService', [])
.service('DialogRefreshService', ['$http', '$q', function($http, $q) {
    // Configuration object for dynamic regular expressions
    this.config = {
        bookNames: ['Genesis', 'Exodus'],
        regexPatterns: {}
    };

    // Method to initialize the regex patterns based on configuration
    this.initRegexPatterns = function() {
        this.config.bookNames.forEach(book => {
            this.config.regexPatterns[book] = new RegExp(`\\b${book}\\b`, 'gi');
        });
    };

    // Method to fetch data from an external API
    this.fetchData = function(url, resourceId) {
        return $http.get(`${url}/${resourceId}`)
            .then(response => response.data)
            .catch(error => {
                console.error('Error fetching data:', error);
                throw error;
            });
    };

    // Method to extract and count book names from text
    this.countBookNames = function(text) {
        let counts = {};
        Object.keys(this.config.regexPatterns).forEach(book => {
            counts[book] = (text.match(this.config.regexPatterns[book]) || []).length;
        });
        return counts;
    };

    // Method to refresh specified dialog fields and notify the parent window
    this.refreshFields = function(url, resourceId, fieldNames) {
        const self = this;
        let promises = [];

        fieldNames.forEach(fieldName => {
            const deferred = $q.defer();
            self.fetchData(url, resourceId).then(data => {
                // Extract text from data (assuming data contains a property named fieldName)
                let fieldText = data[fieldName];
                if (fieldText) {
                    // Count book names in the extracted text
                    let bookCounts = self.countBookNames(fieldText);
                    // Notify parent window with updated field values and metadata
                    window.parent.postMessage({fieldName, fieldValue: fieldText, bookCounts}, '*');
                    deferred.resolve();
                } else {
                    deferred.reject(new Error(`Field ${fieldName} not found in data`));
                }
            }).catch(error => {
                deferred.reject(error);
            });
            promises.push(deferred.promise);
        });

        // Return a promise that resolves when all field refreshes are complete
        return $q.all(promises).then(() => {
            console.log('All fields refreshed successfully');
        }).catch(errors => {
            console.error('Error refreshing fields:', errors);
            throw errors;
        });
    };
}]);

// Example usage of the DialogRefreshService in an AngularJS controller
angular.module('dialogApp', ['dialogRefreshService'])
.controller('DialogController', ['$scope', 'DialogRefreshService', function($scope, DialogRefreshService) {
    $scope.refreshFields = function() {
        const url = 'https://api.example.com/data';
        const resourceId = 123;
        const fieldNames = ['description', 'content'];
        DialogRefreshService.refreshFields(url, resourceId, fieldNames)
            .then(() => {
                console.log('Dialog fields refreshed');
            })
            .catch(error => {
                console.error('Failed to refresh dialog fields:', error);
            });
    };

    // Initialize regex patterns
    DialogRefreshService.initRegexPatterns();
}]);
