        try {
            // Check password strength asynchronously
            $strengthCheckerMessage = new AMQPMessage(json_encode(['userId' => $userId, 'password' => $newPassword]));
            $this->queue->basic_publish($strengthCheckerMessage, '', 'password_strength_checker');

            // Update password in database with distributed lock
            $lockKey = "lock:password_update:$userId";
            while (true) {
                if ($this->cache->setnx($lockKey, 1)) {
                    break;
                }
                usleep(100); // Wait before retrying
