class SensorDataProcessor:
    def __init__(self):
        self._data_store = {}

    async def process_sensor_data(self, protocol: str, data: Any) -> None:
        # Process the sensor data based on the protocol and format
        if protocol == 'Modbus':
            processed_data = self._process_modbus(data)
        elif protocol == 'OPC-UA':
            processed_data = self._process_opcua(data)
