#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>

class TransactionProcessor {
public:
    TransactionProcessor(size_t numThreads)
        : stop(false), workers(numThreads) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back([this] {
                for (;;) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(this->queue_mutex);
                        this->condition.wait(lock, [this] { return this->stop || !this->tasks.empty(); });
                        if (this->stop && this->tasks.empty()) {
                            return;
                        }
                        task = std::move(this->tasks.front());
                        this->tasks.pop();
                    }
                    task();
                }
            });
        }
    }

    template<class F, class... Args>
    void enqueue(F&& f, Args&&... args) {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            if (stop) {
                throw std::runtime_error("enqueue on stopped ThreadPool");
            }
            tasks.emplace([f, args...] { f(args...); });
        }
        condition.notify_one();
    }

    ~TransactionProcessor() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread &worker: workers) {
            worker.join();
        }
    }

private:
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::mutex queue_mutex;
    std::condition_variable condition;
    bool stop;
};

int main() {
    TransactionProcessor tp(4);

    // Example task to process a transaction
    auto processTransaction = [](const std::string& transactionID) {
        // Simulate processing time
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        std::cout << "Processed transaction: " << transactionID << std::endl;
    };

    // Enqueue multiple transactions for processing
    tp.enqueue(processTransaction, "TXN-001");
    tp.enqueue(processTransaction, "TXN-002");
    tp.enqueue(processTransaction, "TXN-003");

    return 0;
}
