#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the context union
union ContextData {
    int intVal;
    double doubleVal;
    char str[256];
};

// Define the event structure
struct NetworkEvent {
    time_t timestamp;
    int code;
    union ContextData context;
};

// Define the log entry structure
struct LogEntry {
    struct NetworkEvent event;
    struct LogEntry *next;
};

// Define the log buffer structure
struct LogBuffer {
    struct LogEntry *head;
    struct LogEntry *tail;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int size;
    int capacity;
};

// Function to initialize the log buffer
void init_log_buffer(struct LogBuffer *buffer, int capacity) {
    buffer->head = NULL;
    buffer->tail = NULL;
    pthread_mutex_init(&buffer->lock, NULL);
    pthread_cond_init(&buffer->cond, NULL);
    buffer->size = 0;
    buffer->capacity = capacity;
}

// Function to add an event to the log buffer
void add_event_to_log(struct LogBuffer *buffer, struct NetworkEvent event) {
    pthread_mutex_lock(&buffer->lock);
    while (buffer->size == buffer->capacity) {
        pthread_cond_wait(&buffer->cond, &buffer->lock);
    }
    struct LogEntry *entry = malloc(sizeof(struct LogEntry));
    entry->event = event;
    entry->next = NULL;
    if (buffer->tail != NULL) {
        buffer->tail->next = entry;
    } else {
        buffer->head = entry;
    }
    buffer->tail = entry;
    buffer->size++;
    pthread_cond_signal(&buffer->cond);
    pthread_mutex_unlock(&buffer->lock);
}

// Function to process events from the log buffer
void *process_events(void *arg) {
    struct LogBuffer *buffer = (struct LogBuffer *)arg;
    while (1) {
        pthread_mutex_lock(&buffer->lock);
        while (buffer->size == 0) {
            pthread_cond_wait(&buffer->cond, &buffer->lock);
        }
        struct LogEntry *entry = buffer->head;
        if (entry != NULL) {
            buffer->head = entry->next;
            if (buffer->tail == entry) {
                buffer->tail = NULL;
            }
            buffer->size--;
            pthread_cond_signal(&buffer->cond);
        }
        pthread_mutex_unlock(&buffer->lock);

        // Process the event
        printf("Processing event: %d, Timestamp: %ld, Context: %s\n", entry->event.code, entry->event.timestamp, (entry->event.context.str[0] != '\0') ? entry->event.context.str : "");
        free(entry);
    }
}

int main() {
    struct LogBuffer buffer;
    init_log_buffer(&buffer, 100);

    pthread_t thread;
    pthread_create(&thread, NULL, process_events, &buffer);

    // Simulate adding events to the log buffer
    for (int i = 0; i < 200; i++) {
        struct NetworkEvent event;
        event.timestamp = time(NULL);
        event.code = i % 10;
        snprintf(event.context.str, sizeof(event.context.str), "Context_%d", i);

        add_event_to_log(&buffer, event);

        // Sleep for a short duration to simulate load
        usleep(10000);
    }

    pthread_join(thread, NULL);

    return 0;
}
