class DataProcessor {
public:
    void startProcessing() {
        processingThread = std::thread(&DataProcessor::processData, this);
    }

    void stopProcessing() {
        stopFlag = true;
        condition.notify_all();
        if (processingThread.joinable()) {
            processingThread.join();
        }
    }

private:
    void processData() {
        while (!stopFlag) {
            SensorData data;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                condition.wait(lock, [this] { return !dataQueue.empty() || stopFlag; });
                if (stopFlag && dataQueue.empty()) break;
                data = dataQueue.front();
                dataQueue.pop();
            }
            // Process the data
            process(data);
        }
    }

    void process(const SensorData& data) {
        // Implementation of data processing logic
        std::cout << "Processing data from " << data.source << std::endl;
    }

    std::queue<SensorData> dataQueue;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool stopFlag = false;
    std::thread processingThread;
};

class DataIngestion {
public:
    void ingestData(const SensorData& data) {
        processor.dataQueue.push(data);
        processor.condition.notify_one();
    }

private:
    DataProcessor processor;
};

// Example usage
