# API credentials and rates
API_CREDENTIALS = {
    'stocks': {'url': 'https://api.stocks.com', 'key': 'YOUR_KEY'},
    'forex': {'url': 'https://api.forex.com', 'key': 'YOUR_KEY'},
    'commodities': {'url': 'https://api.commodities.com', 'key': 'YOUR_KEY'}
}
API_RATE_LIMITS = {
    'stocks': 10,
    'forex': 5,
    'commodities': 8
}

# Caching mechanism
cache = {}
cache_expiry = {}

def cache_data(api, data):
    cache[api] = data
    cache_expiry[api] = time.time() + API_RATE_LIMITS[api]

def get_cached_data(api):
    if api in cache and time.time() < cache_expiry[api]:
        return cache[api]
    else:
        return None

# Rate limiting decorator
def rate_limit(limit):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if limit > 0:
                func(*args, **kwargs)
                limit -= 1
            else:
                raise Exception("Rate limit exceeded")
        return wrapper
    return decorator

# API methods
