const express = require('express');
const bodyParser = require('body-parser');
const redis = require('redis');
const crypto = require('crypto');
const axios = require('axios');
const rateLimit = require('express-rate-limit');
const CircuitBreaker = require('opossum');

const app = express();
app.use(bodyParser.json());

// Redis client setup
const redisClient = redis.createClient();

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 1 * 60 * 1000, // 1 minute
  max: 100 // limit each IP to 100 requests per windowMs
});

app.use(limiter);

// Circuit breaker setup for the password management API
const options = {
  timeout: 3000, // 3 seconds
  errorThresholdPercentage: 50,
  resetTimeout: 60 * 1000 // 1 minute
};

const circuitBreaker = new CircuitBreaker(
  async () => await axios.get('https://password-management-api.com/encrypt'),
  options
);

// Middleware for distributed locking using Redis
app.use(async (req, res, next) => {
  const lockKey = 'config-update-lock';
  const lock = await redisClient.setnx(lockKey, 'locked');

  if (lock === 1) {
    req.releaseLock = () => redisClient.del(lockKey);
    return next();
  } else {
    return res.status(503).send('Service unavailable');
  }
});

// Configuration management endpoint
app.put('/config', async (req, res) => {
  const { tenantId, config, placeholderValues } = req.body;

  // Replace placeholders with provided values
  let updatedConfig = Object.keys(config).reduce((acc, key) => {
    acc[key] = typeof config[key] === 'string' ? config[key].replace(/{{(.*?)}}/g, (match, p1) => placeholderValues[p1]) : config[key];
    return acc;
  }, {});

  // Encrypt sensitive sections
  updatedConfig = Object.keys(updatedConfig).reduce((acc, key) => {
    if (updatedConfig[key] && typeof updatedConfig[key] === 'string' && /password|token/g.test(key)) {
      try {
        const encrypted = await circuitBreaker.fire();
        acc[key] = encrypted.data;
      } catch (error) {
        return res.status(500).send('Encryption failed');
      }
    } else {
      acc[key] = updatedConfig[key];
    }
    return acc;
  }, {});

  // Secure update using Redis transaction for atomicity
  const multi = redisClient.multi();
  Object.keys(updatedConfig).forEach(key => {
    multi.set(`config:${tenantId}:${key}`, updatedConfig[key]);
  });
  await multi.exec();

  res.status(200).send('Configuration updated successfully');
});

// Health check endpoint
app.get('/health', (req, res) => {
  const isHealthy = redisClient.ping() === 'PONG';
  if (isHealthy) {
    res.status(200).send('Service is healthy');
  } else {
    res.status(503).send('Service is not healthy');
  }
});

app.listen(3000, () => {
  console.log('Microservice is running on port 3000');
});
```"]

