use reqwest::Client;
use kafka::{producer::Producer, message::Message};
use redis::{Client as RedisClient, Commands};
use tokio::sync::{mpsc, RwLock};
use std::time::{Duration, Instant};

#[derive(Clone)]
struct FinancialApiClient {
    client: Client,
}

impl FinancialApiClient {
    async fn fetch_data(&self, url: &str) -> Result<String, reqwest::Error> {
        self.client.get(url).send().await?.text().await
    }
}

struct KafkaProducer {
    producer: Producer,
}

impl KafkaProducer {
    async fn send_message(&self, topic: &str, message: String) {
        let mut producer = self.producer.clone();
        tokio::spawn(async move {
            producer.send(Message::new(topic, message));
        });
    }
}

struct RedisCache {
    client: RedisClient,
}

impl RedisCache {
    async fn get(&self, key: &str) -> Option<String> {
        let mut conn = self.client.get_async_connection().await.unwrap();
        conn.get(key).await.ok()
    }

    async fn set(&self, key: &str, value: String, expire_time: Duration) {
        let mut conn = self.client.get_async_connection().await.unwrap();
        conn.set_ex(key, value, expire_time.as_secs()).await.unwrap();
    }
}

struct FinancialDataHandler {
    api_client: RwLock<FinancialApiClient>,
    kafka_producer: KafkaProducer,
    redis_cache: RedisCache,
}

impl FinancialDataHandler {
    async fn new(api_key: String, kafka_broker: String, redis_url: String) -> Self {
        let client = Client::builder()
            .timeout(Duration::from_secs(10))
            .build()
            .unwrap();
        let api_client = RwLock::new(FinancialApiClient { client });
        let producer = Producer::from_str(&kafka_broker).unwrap();
        let kafka_producer = KafkaProducer { producer };
        let redis_client = RedisClient::open(redis_url).unwrap();
        let redis_cache = RedisCache { client: redis_client };

        FinancialDataHandler {
            api_client,
            kafka_producer,
            redis_cache,
        }
    }

    async fn fetch_and_store_data(&self, url: &str, topic: &str) -> Result<(), Box<dyn std::error::Error>> {
        if let Some(data) = self.redis_cache.get(url).await {
            self.kafka_producer.send_message(topic, data).await;
            return Ok(());
        }

        let api_client = self.api_client.read().await;
        let data = api_client.fetch_data(url).await?;
        self.redis_cache.set(url, data.clone(), Duration::from_secs(60)).await;
        self.kafka_producer.send_message(topic, data).await;

        Ok(())
    }
}

#[tokio::main]
async fn main() {
    let api_key = "YOUR_API_KEY".to_string();
    let kafka_broker = "kafka://localhost:9092".to_string();
    let redis_url = "redis://127.0.0.1/".to_string();

    let handler = FinancialDataHandler::new(api_key, kafka_broker, redis_url).await;

    let (mut sender, mut receiver) = mpsc::channel(32);

    tokio::spawn(async move {
        while let Some(url) = receiver.recv().await {
            if let Err(e) = handler.fetch_and_store_data(&url, "financial_data").await {
                eprintln!("Error fetching and storing data: {}", e);
            }
        }
    });

    // Simulate receiving URLs to fetch data
    for url in vec![
        "https://api.example.com/high_freq_data",
        "https://api.example.com/low_latency_order",
    ] {
        if let Err(_) = sender.send(url.to_string()).await {
            eprintln!("Failed to send URL");
        }
    }
}
