use std::collections::HashMap;
use std::fs::{self, DirEntry};
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use tokio::task;
use reqwest::Client;

#[derive(Clone)]
struct DirectoryService {
    directory_path: PathBuf,
    api_keys: HashMap<String, String>,
    log_urls: Vec<String>,
    client: Client,
}

impl DirectoryService {
    fn new() -> Self {
        let directory_path = std::env::var("DIRECTORY_PATH")
            .map(PathBuf::from)
            .unwrap_or_else(|_| PathBuf::from("./default_directory"));

        fs::create_dir_all(&directory_path).expect("Failed to create directory");

        let api_keys = std::env::var("API_KEYS")
            .unwrap_or_else(|| "".to_string())
            .split(',')
            .map(|key| (key.to_string(), key.to_string()))
            .collect();

        let log_urls = std::env::var("LOG_URLS")
            .unwrap_or_else(|| "".to_string())
            .split(',')
            .map(String::from)
            .collect();

        DirectoryService {
            directory_path,
            api_keys,
            log_urls,
            client: Client::new(),
        }
    }

    async fn create_directory(&self, name: &str) -> Result<(), Box<dyn std::error::Error>> {
        let mut lock = self.get_lock();
        if lock.contains_key(name) {
            return Err("Directory already exists".into());
        }

        let unique_name = self.generate_unique_name(name);
        fs::create_dir(&self.directory_path.join(&unique_name))?;
        lock.insert(unique_name.clone(), None);

        // Simulate external API call
        self.call_external_api("CREATE", &unique_name).await?;

        Ok(())
    }

    fn generate_unique_name(&self, name: &str) -> String {
        let mut i = 0;
        loop {
            let candidate = format!("{}-{}", name, i);
            if !self.directory_path.join(candidate).exists() {
                return candidate;
            }
            i += 1;
        }
    }

    async fn call_external_api(&self, action: &str, directory_name: &str) -> Result<(), Box<dyn std::error::Error>> {
        let key = self.api_keys.values().next().unwrap();
        let url = format!("https://api.example.com/{}?key={}&dir={}", action, key, directory_name);

        loop {
            match self.client.post(&url).send().await {
                Ok(response) if response.status().is_success() => break,
                Ok(_) => tokio::time::sleep(tokio::time::Duration::from_secs(2)).await,
                Err(_) => tokio::time::sleep(tokio::time::Duration::from_secs(2)).await,
            }
        }

        Ok(())
    }

    fn get_lock(&self) -> Arc<Mutex<HashMap<String, Option<task::JoinHandle<()>>>>> {
        // Placeholder for lock mechanism
        Arc::new(Mutex::new(HashMap::new()))
    }
}

