#define MAX_CONTEXT_DATA_SIZE 1024

typedef enum {
    EVENT_CODE_1,
    EVENT_CODE_2,
    // Add more event codes as needed
} EventCode;

typedef union {
    int i;
    double d;
    char str[MAX_CONTEXT_DATA_SIZE];
    // Add more data types as needed, up to 16 total
} ContextData;

typedef struct {
    long timestamp;
    EventCode code;
    ContextData data;
} NetworkEvent;

typedef struct {
    NetworkEvent *events;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} LogBuffer;

void init_log_buffer(LogBuffer *buffer, size_t initial_capacity) {
    buffer->events = malloc(initial_capacity * sizeof(NetworkEvent));
    buffer->count = 0;
    buffer->capacity = initial_capacity;
    pthread_mutex_init(&buffer->lock, NULL);
}

void free_log_buffer(LogBuffer *buffer) {
    free(buffer->events);
    pthread_mutex_destroy(&buffer->lock);
}

void add_event_to_buffer(LogBuffer *buffer, NetworkEvent event) {
    pthread_mutex_lock(&buffer->lock);
    if (buffer->count == buffer->capacity) {
        size_t new_capacity = buffer->capacity * 2;
        NetworkEvent *new_events = realloc(buffer->events, new_capacity * sizeof(NetworkEvent));
        if (!new_events) {
            fprintf(stderr, "Failed to resize log buffer\n");
            return;
        }
        buffer->events = new_events;
        buffer->capacity = new_capacity;
    }
    buffer->events[buffer->count++] = event;
    pthread_mutex_unlock(&buffer->lock);
}

void transmit_log_buffer(LogBuffer *buffer) {
    // Implement logic to transmit the log buffer to an external service
    // This could involve network communication, database operations, etc.
    printf("Transmitting %zu events\n", buffer->count);
    for (size_t i = 0; i < buffer->count; ++i) {
        printf("Event: Timestamp=%ld, Code=%d, Data=%.*s\n",
               buffer->events[i].timestamp,
               buffer->events[i].code,
               (buffer->events[i].data.code == EVENT_CODE_1) ? sizeof(buffer->events[i].data.i) : 0,
               (buffer->events[i].data.code == EVENT_CODE_2) ? buffer->events[i].data.str : "");
    }
}

int main() {
    LogBuffer log_buffer;
    init_log_buffer(&log_buffer, 10);

    // Example usage
    NetworkEvent event1 = {time(NULL), EVENT_CODE_1, {.i = 42}};
    NetworkEvent event2 = {time(NULL), EVENT_CODE_2, {.str = "Example"}};
    add_event_to_buffer(&log_buffer, event1);
    add_event_to_buffer(&log_buffer, event2);

    transmit_log_buffer(&log_buffer);

    free_log_buffer(&log_buffer);
    return 0;
}
