#define MAX_TASKS 10000
#define MAX_WORKERS 100

typedef struct {
    int id;
    char *command;
    int status;
} Task;

Task task_queue[MAX_TASKS];
int front = -1, rear = -1;

pthread_mutex_t queue_lock;
pthread_cond_t not_full, not_empty;

void* worker(void* arg) {
    while (1) {
        pthread_mutex_lock(&queue_lock);
        while (front == -1) {
            pthread_cond_wait(&not_empty, &queue_lock);
        }

        int task_id = front++;
        if (front > rear) {
            front = rear = -1;
        }
        pthread_mutex_unlock(&queue_lock);

        // Execute task
        system(task_queue[task_id].command);
        task_queue[task_id].status = 0; // Task completed

        pthread_cond_signal(&not_full);
    }
}

void enqueue(char* command) {
    pthread_mutex_lock(&queue_lock);
    while ((rear + 1) % MAX_TASKS == front) {
        pthread_cond_wait(&not_full, &queue_lock);
    }

    if (front == -1) {
        front = rear = 0;
    } else {
        rear = (rear + 1) % MAX_TASKS;
    }
    task_queue[rear].id = rear;
    strcpy(task_queue[rear].command, command);
    pthread_mutex_unlock(&queue_lock);
    pthread_cond_signal(&not_empty);
}

void dequeue() {
    pthread_mutex_lock(&queue_lock);
    while (front == -1) {
        pthread_cond_wait(&not_empty, &queue_lock);
    }

    int task_id = front;
    if (front == rear) {
        front = rear = -1;
    } else {
        front = (front + 1) % MAX_TASKS;
    }
    pthread_mutex_unlock(&queue_lock);
    pthread_cond_signal(&not_full);

    // Execute task
    system(task_queue[task_id].command);
    task_queue[task_id].status = 0; // Task completed
}

void* command_handler(void* arg) {
    char input[256];
    while (1) {
        fgets(input, sizeof(input), stdin);
        input[strcspn(input, "\n")] = 0;
        enqueue(input);
    }
    return NULL;
}

int main() {
    pthread_t workers[MAX_WORKERS], command_thread;

    pthread_mutex_init(&queue_lock, NULL);
    pthread_cond_init(&not_full, NULL);
    pthread_cond_init(&not_empty, NULL);

    for (int i = 0; i < MAX_WORKERS; i++) {
        pthread_create(&workers[i], NULL, worker, NULL);
    }
    pthread_create(&command_thread, NULL, command_handler, NULL);

    for (int i = 0; i < MAX_WORKERS; i++) {
        pthread_join(workers[i], NULL);
    }

    pthread_join(command_thread, NULL);

    pthread_mutex_destroy(&queue_lock);
    pthread_cond_destroy(&not_full);
    pthread_cond_destroy(&not_empty);

    return 0;
}
