// Worker thread to process incoming data
void workerThread(std::queue<std::future<void>>& taskQueue) {
    while (true) {
        std::future<void> task;
        {
            std::unique_lock<std::mutex> lock(taskQueue.getMutex());
            if (!taskQueue.empty()) {
                task = std::move(taskQueue.front());
                taskQueue.pop();
            } else {
                // Thread will block here until a new task is available
                taskQueue.wait(lock);
            }
        }

        if (task.valid()) {
            try {
                task.get(); // Execute the task
            } catch (...) {
                // Handle exceptions, e.g., log them or rethrow
            }
        }
    }
}

// Main function to process real-time sensor data
void processRealTimeSensorData(std::vector<std::shared_ptr<IoTDevice>>& devices, std::shared_ptr<NoSQLDatabase>& db) {
    const int numThreads = 10;
