package com.globaledge.network;

import java.util.HashMap;
import java.util.Map;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.cloud.openfeign.FeignClient;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;

@RestController
public class GlobalEdgeNetworkManager {

    @FeignClient(name = "cdn-provider", url = "${cdn.provider.url}")
    public interface CdnProviderService {
        @GetMapping("/content")
        ResponseEntity<String> getContent(@RequestParam("region") String region);

        @PostMapping("/updateContent")
        ResponseEntity<Void> updateContent(@RequestBody Map<String, Object> content);
    }

    private final CdnProviderService cdnProviderService;
    private final Map<String, String> cache = new HashMap<>();
    private final Map<String, Long> lastAccessed = new HashMap<>();

    public GlobalEdgeNetworkManager(CdnProviderService cdnProviderService) {
        this.cdnProviderService = cdnProviderService;
    }

    @GetMapping("/content")
    public ResponseEntity<String> getContent(@RequestParam("region") String region) {
        if (cache.containsKey(region)) {
            long lastAccessedTime = lastAccessed.get(region);
            if (System.currentTimeMillis() - lastAccessedTime < 3600000) { // Cache valid for 1 hour
                return ResponseEntity.ok(cache.get(region));
            }
        }

        ResponseEntity<String> response = cdnProviderService.getContent(region);
        if (response.getStatusCode().is2xxSuccessful()) {
            cache.put(region, response.getBody());
            lastAccessed.put(region, System.currentTimeMillis());
        }

        return response;
    }

    @PostMapping("/updateContent")
    public ResponseEntity<Void> updateContent(@RequestBody Map<String, Object> content) {
        cdnProviderService.updateContent(content);
        cache.clear(); // Invalidate cache after content update
        return ResponseEntity.ok().build();
    }
}
