#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a shared data structure to hold PDUs and synchronization primitives
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    int size;
    int head;
    int tail;
    sem_t buffer_full;
    sem_t buffer_empty;
    pthread_mutex_t mutex;
} PduQueue;

// Initialize the PDU queue
void init_pdu_queue(PduQueue *queue, int capacity) {
    queue->pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    queue->size = capacity;
    queue->head = 0;
    queue->tail = 0;
    sem_init(&queue->buffer_full, 0, 0);
    sem_init(&queue->buffer_empty, 0, capacity);
    pthread_mutex_init(&queue->mutex, NULL);
}

// Enqueue a PDU into the queue
void enqueue_pdu(PduQueue *queue, NFAPI_CRC_INDICATION_PDU_T pdu) {
    sem_wait(&queue->buffer_empty);
    pthread_mutex_lock(&queue->mutex);
    queue->pdus[queue->tail] = pdu;
    queue->tail = (queue->tail + 1) % queue->size;
    pthread_mutex_unlock(&queue->mutex);
    sem_post(&queue->buffer_full);
}

// Dequeue a PDU from the queue
NFAPI_CRC_INDICATION_PDU_T dequeue_pdu(PduQueue *queue) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    sem_wait(&queue->buffer_full);
    pthread_mutex_lock(&queue->mutex);
    pdu = queue->pdus[queue->head];
    queue->head = (queue->head + 1) % queue->size;
    pthread_mutex_unlock(&queue->mutex);
    sem_post(&queue->buffer_empty);
    return pdu;
}

// Thread function to process PDUs
void *process_pdu(void *arg) {
    PduQueue *queue = (PduQueue *)arg;
