#include <string.h>
#include <pthread.h>

typedef struct {
    int type;
    union {
        int i;
        float f;
        char *s;
    } data;
} ContextData;

typedef struct {
    long timestamp;
    int event_code;
    ContextData context;
} NetworkEvent;

typedef struct LogEntry {
    NetworkEvent event;
    struct LogEntry *next;
} LogEntry;

typedef struct {
    pthread_mutex_t lock;
    LogEntry *head;
    LogEntry *tail;
    int size;
} Logger;

void logger_init(Logger *logger) {
    pthread_mutex_init(&logger->lock, NULL);
    logger->head = logger->tail = NULL;
    logger->size = 0;
}

void logger_push(Logger *logger, NetworkEvent event) {
    LogEntry *entry = (LogEntry *)malloc(sizeof(LogEntry));
    entry->event = event;
    entry->next = NULL;

    pthread_mutex_lock(&logger->lock);
    if (logger->tail == NULL) {
        logger->head = logger->tail = entry;
    } else {
        logger->tail->next = entry;
        logger->tail = entry;
    }
    logger->size++;
    pthread_mutex_unlock(&logger->lock);
}

void logger_process(Logger *logger, void (*process_event)(NetworkEvent)) {
    LogEntry *entry;
    pthread_mutex_lock(&logger->lock);
    while (logger->head != NULL) {
        entry = logger->head;
        logger->head = logger->head->next;
        if (logger->head == NULL) {
            logger->tail = NULL;
        }
        logger->size--;
        pthread_mutex_unlock(&logger->lock);

        process_event(entry->event);
        free(entry);

        pthread_mutex_lock(&logger->lock);
    }
    pthread_mutex_unlock(&logger->lock);
}

void *network_event_thread(void *arg) {
    Logger *logger = (Logger *)arg;
    NetworkEvent event;

    // Simulate network events
    while (1) {
        // Populate event fields
        // ...

        logger_push(logger, event);
        usleep(10);  // Simulate processing time
    }

    return NULL;
}

void process_event(NetworkEvent event) {
    // Process the log entry
    printf("Timestamp: %ld, Event Code: %d\n", event.timestamp, event.event_code);
}

int main() {
    Logger logger;
    pthread_t thread;

    logger_init(&logger);

    pthread_create(&thread, NULL, network_event_thread, &logger);

    // Simulate processing log entries
    while (1) {
        logger_process(&logger, process_event);
        usleep(100);  // Simulate reporting interval
    }

    return 0;
}
