#include <iostream>
#include <thread>
#include <atomic>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <unordered_map>
#include <openssl/ssl.h>

class SandeshClient {
private:
    std::vector<std::string> serverEndpoints;
    std::vector<SSL_CTX*> sslContexts;
    std::unordered_map<std::string, bool> whitelist;
    std::atomic<bool> running;
    std::mutex mutex;
    std::condition_variable cv;

public:
    SandeshClient(const std::vector<std::string>& endpoints)
        : serverEndpoints(endpoints), running(false) {}

    ~SandeshClient() {
        for (auto& ctx : sslContexts) SSL_CTX_free(ctx);
    }

    void start() {
        running.store(true);
        for (size_t i = 0; i < serverEndpoints.size(); ++i) {
            auto thread = std::thread(&SandeshClient::worker, this, i);
            thread.detach();
        }
    }

    void stop() {
        running.store(false);
        cv.notify_all();
    }

    void worker(size_t index) {
        while (running.load()) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return !whitelist.empty(); });
            auto ip = whitelist.begin()->first;
            lock.unlock();

            // Perform GET request to the server
            performGetRequest(ip);

            // Remove IP from whitelist after processing
            {
                std::lock_guard<std::mutex> guard(mutex);
                whitelist.erase(ip);
            }
        }
    }

    void updateWhitelist(const std::unordered_map<std::string, bool>& newWhitelist) {
        std::unique_lock<std::mutex> lock(mutex);
        whitelist = newWhitelist;
        cv.notify_all();
    }

private:
    void performGetRequest(const std::string& ip) {
        // Implement GET request logic here
        std::cout << "Performing GET request to " << ip << std::endl;
    }
};

int main() {
    SandeshClient client({"server1", "server2"});
    client.start();

    // Simulate dynamic update of whitelist
    std::this_thread::sleep_for(std::chrono::seconds(5));
    std::unordered_map<std::string, bool> newWhitelist = {{"192.168.1.1", true}, {"192.168.1.2", false}};
    client.updateWhitelist(newWhitelist);

    std::this_thread::sleep_for(std::chrono::seconds(5));
    client.stop();

    return 0;
}
```

