from flask import Flask, request, jsonify
from flask_caching import Cache
import requests
from retrying import retry
from prometheus_flask_exporter import PrometheusMetrics
from message_queue_client import MessageQueueClient

app = Flask(__name__)
cache = Cache(app, config={'CACHE_TYPE': 'simple'})
metrics = PrometheusMetrics(app)
message_queue = MessageQueueClient()

# Configuration management
config_cache = {}

@app.route('/update_config', methods=['POST'])
def update_config():
    data = request.json
    environment = data.get('environment')
    config_id = data.get('config_id')

    # Fetch and update configuration from external API or source
    new_config = fetch_external_api(config_id, environment)

    # Store the updated configuration in cache
    config_cache[environment] = new_config

    return jsonify({"message": "Configuration updated successfully"}), 200

@cache.memoize(timeout=50)
def fetch_external_api(config_id, environment):
    # Simulate API call with retry mechanism
    @retry(stop_max_attempt_number=3, wait_fixed=1000)
    def get_config():
        response = requests.get(f'https://api.example.com/config/{config_id}/{environment}')
        response.raise_for_status()
        return response.json()

    return get_config()

@app.route('/get_config', methods=['GET'])
def get_config():
    environment = request.args.get('environment')
    config = config_cache.get(environment, None)

    if not config:
        # Trigger asynchronous update
        message_queue.send_message({'action': 'update_config', 'environment': environment})
        return jsonify({"message": "Configuration is being updated"}), 202

    return jsonify(config), 200

@metrics.do_not_track()
@app.route('/status')
def status():
    # Provide a simple status endpoint for monitoring
    return jsonify({"status": "running"})

if __name__ == '__main__':
    app.run(debug=True, threaded=True)
