  .then(client => {
    db = client.db('iot_data');
    console.log('Connected to MongoDB database');
  })
  .catch(err => console.error('Failed to connect to MongoDB', err));

// Service mesh and circuit breaker setup
const machineLearningServiceUrl = 'your_ml_service_url';
const mlBreaker = new CircuitBreaker(() => axios.get(machineLearningServiceUrl), {
  timeout: 5000,
  errorThresholdPercentage: 30,
  resetTimeout: 10000,
});

mlBreaker.on('fallback', (err) => {
  console.error('Machine learning service fallback triggered:', err);
});

// Route to process IoT data
app.post('/process-data', async (req, res) => {
  const eventData = req.body;

  try {
    // Validate and store data in database
    await db.collection('events').insertOne(eventData);

    // Process data through machine learning service if schema matches
    if (eventData.schemaVersion === 'v1') {
      const result = await mlBreaker.fire();
      console.log('Machine Learning Result:', result.data);
    }

    res.status(200).send({ message: 'Event processed successfully' });
  } catch (error) {
    // Log and handle errors
    console.error('Error processing event', error);
    res.status(500).send({ message: 'Internal server error' });
  }
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
