from typing import Any, Dict

class MultiRegionCacheManager:
    def __init__(self, startup_nodes: List[Dict[str, str]], max_connections_per_node: int = 10):
        self.nodes = startup_nodes
        self.max_connections_per_node = max_connections_per_node
        self.redis_clusters = [RedisCluster(startup_nodes=node, decode_responses=True) for node in self.nodes]

    def get(self, key: str) -> Any:
        for cluster in self.redis_clusters:
            try:
                value = cluster.get(key)
                if value is not None:
                    return value
            except Exception as e:
                print(f"Error fetching {key} from Redis Cluster: {e}")
        return None

    def set(self, key: str, value: Any) -> bool:
        for cluster in self.redis_clusters:
            try:
                result = cluster.set(key, value)
                if result:
                    return True
            except Exception as e:
                print(f"Error setting {key} to Redis Cluster: {e}")
        return False

    def delete(self, key: str) -> bool:
        for cluster in self.redis_clusters:
            try:
                result = cluster.delete(key)
                if result > 0:
                    return True
            except Exception as e:
                print(f"Error deleting {key} from Redis Cluster: {e}")
        return False

