#include <future>
#include <queue>
#include <mutex>
#include <condition_variable>

class TransactionProcessor {
public:
    void start() {
        for (size_t i = 0; i < numThreads_; ++i) {
            workers_.emplace_back(&TransactionProcessor::worker, this);
        }
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stop_ = true;
        }
        cv_.notify_all();
        for (std::thread& worker : workers_) {
            worker.join();
        }
    }

    void processTransaction(const Transaction& transaction) {
        std::promise<void> promise;
        auto future = promise.get_future();

        {
            std::unique_lock<std::mutex> lock(mutex_);
            tasks_.push({std::move(promise), transaction});
        }
        cv_.notify_one();

        future.wait();
    }

private:
    void worker() {
        while (true) {
            Task task;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                cv_.wait(lock, [this] { return stop_ || !tasks_.empty(); });
                if (stop_ && tasks_.empty()) {
                    return;
                }
                task = std::move(tasks_.front());
                tasks_.pop();
            }

            try {
                process(task.transaction);
                task.promise.set_value();
            } catch (...) {
                task.promise.set_exception(std::current_exception());
            }
        }
    }

    void process(const Transaction& transaction) {
        // Process the transaction
    }

    struct Task {
        std::promise<void> promise;
        Transaction transaction;
    };

    std::vector<std::thread> workers_;
    std::queue<Task> tasks_;
    std::mutex mutex_;
    std::condition_variable cv_;
    size_t numThreads_ = 4; // Example number of threads
    bool stop_ = false;
};

int main() {
    TransactionProcessor processor;
    processor.start();

    for (size_t i = 0; i < 100000; ++i) {
        Transaction transaction; // Create a new transaction object
        processor.processTransaction(transaction);
    }

    processor.stop();
    return 0;
}
