// Thread pool class with adaptive sizing
class ThreadPool {
public:
    ThreadPool(size_t numThreads) : stop(false) {
        for(size_t i = 0; i < numThreads; ++i)
            workers.emplace_back([this] {
                for(;;) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(this->queue_mutex);
                        this->condition.wait(lock, [this] { return this->stop || !this->tasks.empty(); });
                        if(this->stop && this->tasks.empty())
                            return;
                        task = std::move(this->tasks.front());
                        this->tasks.pop();
                    }
                    task();
                }
            });
    }

    template<class F, class... Args>
    auto enqueue(F&& f, Args&&... args) -> std::future<typename std::result_of<F(Args...)>::type> {
        using return_type = typename std::result_of<F(Args...)>::type;

        auto task = std::make_shared<std::packaged_task<return_type()>>(
            std::bind(std::forward<F>(f), std::forward<Args>(args)...)
        );

        std::future<return_type> res = task->get_future();
        {
            std::unique_lock<std::mutex> lock(queue_mutex);

            // don't allow enqueueing after stopping the pool
            if(stop)
                throw std::runtime_error("enqueue on stopped ThreadPool");

            tasks.emplace([task]() { (*task)(); });
        }
        condition.notify_one();
        return res;
    }

    ~ThreadPool() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        condition.notify_all();
        for(std::thread &worker: workers)
            worker.join();
    }

private:
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::mutex queue_mutex;
    std::condition_variable condition;
    bool stop;
};

// Function to generate NFAPI CRC indications
void generateNfapiCrcIndications(int N, char* buffer) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> crcIndications(N);

    // Initialize random number generator for CRC flags
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1);

    for(int i = 0; i < N; ++i) {
        crcIndications[i].RX_UE_INFORMATION_TAG = i;
        crcIndications[i].RNTI = i * 100;
        crcIndications[i].CRC_INDICATION_REL8_TAG.CRCFLAG = dis(gen);
    }

    // Serialize data into the output buffer
    for(const auto& indication : crcIndications) {
        memcpy(buffer, &indication, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        buffer += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }
}

int main() {
    ThreadPool pool(4);

    // Enqueue tasks
    for(int i = 0; i < 10; ++i) {
        pool.enqueue([]{
            // Simulate work
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            std::cout << "Task completed" << std::endl;
        });
    }

    return 0;
}
