#include <unordered_map>
#include <memory>

// Define the Message structure
struct Message {
    std::string id;
    std::any payload;
    std::unordered_map<std::string, std::string> metadata;
    std::optional<std::function<void(const std::any&)>> reply_channel;
};

// Define the Subscription class
class Subscription {
public:
    void addSubscriber(std::function<void(const Message&)> subscriber) {
        subscribers.push_back(subscriber);
    }

    void notifySubscribers(const Message& message) {
        for (auto& subscriber : subscribers) {
            subscriber(message);
        }
    }

private:
    std::vector<std::function<void(const Message&)>> subscribers;
};

// Define the MessageBroker class
class MessageBroker {
public:
    void subscribe(const std::string& topic, const std::function<void(const Message&)>& subscriber) {
        subscriptions[topic].addSubscriber(subscriber);
    }

    void publish(const std::string& topic, const Message& message) {
        if (subscriptions.find(topic) != subscriptions.end()) {
            subscriptions[topic].notifySubscribers(message);
        }
    }

private:
    std::unordered_map<std::string, Subscription> subscriptions;
};

int main() {
    MessageBroker broker;

    auto subscriber1 = [](const Message& msg) {
        std::cout << "Subscriber 1 received message: " << msg.id << std::endl;
    };

    auto subscriber2 = [](const Message& msg) {
        std::cout << "Subscriber 2 received message: " << msg.id << std::endl;
    };

    broker.subscribe("topic1", subscriber1);
    broker.subscribe("topic1", subscriber2);

    Message message1 = {"msg1", "Hello, world!", {{"timestamp", "now"}, {"priority", "high"}}, {}};
    Message message2 = {"msg2", 42, {{"timestamp", "now"}, {"priority", "low"}}, {}};

    broker.publish("topic1", message1);
    broker.publish("topic1", message2);

    return 0;
}
```

