// This is a simplified code snippet for educational purposes
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

public class UserHashService {

    private final MessageDigest sha256;
    private final ConcurrentHashMap<String, RateLimiter> rateLimiters;
    private final AtomicLong lastRateCheck;
    private long backoffInterval = 100; // Initial backoff interval in milliseconds

    public UserHashService() throws NoSuchAlgorithmException {
        this.sha256 = MessageDigest.getInstance("SHA-256");
        this.rateLimiters = new ConcurrentHashMap<>();
        this.lastRateCheck = new AtomicLong(System.currentTimeMillis());
    }

    public String hashUserIdentifier(String userId) {
        if (isRateLimited(userId)) {
            handleRateLimitViolation(userId);
        }
        return bytesToHex(sha256.digest(userId.getBytes()));
    }

    private boolean isRateLimited(String userId) {
        RateLimiter rateLimiter = rateLimiters.computeIfAbsent(userId, k -> new RateLimiter(50));
        return rateLimiter.isRateLimited();
    }

    private void handleRateLimitViolation(String userId) {
        // Implement dynamic backoff strategy
        if (System.currentTimeMillis() - lastRateCheck.get() > 1000) {
            long currentTime = System.currentTimeMillis();
            lastRateCheck.set(currentTime);
            double currentInterval = backoffInterval;
            backoffInterval += (backoffInterval * 0.1); // Increase by 10% each time
        }
    }

    private String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private static class RateLimiter {
        private final int limit;
        private long lastResetTime;
        private int requestCount;

        public RateLimiter(int limit) {
            this.limit = limit;
            this.lastResetTime = System.currentTimeMillis();
            this.requestCount = 0;
        }

        public boolean isRateLimited() {
            resetIfNecessary();
            return requestCount >= limit;
        }

        private void resetIfNecessary() {
            long currentTime = System.currentTimeMillis();
            if (currentTime - lastResetTime > 1000) { // Reset every second
                requestCount = 0;
                lastResetTime = currentTime;
            }
        }
    }
}
