#define MAX_LOG_SIZE 1024

typedef enum {
    LOG_CODE_ERROR,
    LOG_CODE_WARNING,
    LOG_CODE_INFO
} log_code_t;

typedef union {
    int i;
    float f;
    char str[64];
} context_data_t;

typedef struct {
    time_t timestamp;
    log_code_t code;
    context_data_t data;
} log_event_t;

typedef struct {
    log_event_t *events;
    size_t capacity;
    size_t count;
} log_buffer_t;

log_buffer_t *create_log_buffer(size_t initial_capacity) {
    log_buffer_t *buffer = malloc(sizeof(log_buffer_t));
    buffer->events = malloc(initial_capacity * sizeof(log_event_t));
    buffer->capacity = initial_capacity;
    buffer->count = 0;
    return buffer;
}

void destroy_log_buffer(log_buffer_t *buffer) {
    free(buffer->events);
    free(buffer);
}

int add_log_event(log_buffer_t *buffer, log_event_t event) {
    if (buffer->count >= buffer->capacity) {
        size_t new_capacity = buffer->capacity * 2;
        log_event_t *new_events = realloc(buffer->events, new_capacity * sizeof(log_event_t));
        if (!new_events) {
            return -1; // Memory allocation failed
        }
        buffer->events = new_events;
        buffer->capacity = new_capacity;
    }
    buffer->events[buffer->count++] = event;
    return 0;
}

void log_thread_function(void *arg) {
    log_buffer_t *buffer = (log_buffer_t *)arg;
    // Simulate adding logs to the buffer
    for (int i = 0; i < 1000; i++) {
        log_event_t event;
        event.timestamp = time(NULL);
        event.code = LOG_CODE_INFO;
        snprintf(event.data.str, sizeof(event.data.str), "Log entry %d", i);
        add_log_event(buffer, event);
    }
}

int main() {
    log_buffer_t *log_buffer = create_log_buffer(100);

    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        if (pthread_create(&threads[i], NULL, log_thread_function, log_buffer) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            return 1;
        }
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_log_buffer(log_buffer);

    return 0;
}
