    pthread_mutex_lock(&queue->mutex);
    if ((queue->tail + 1) % MAX_EVENTS == queue->head) {
        pthread_mutex_unlock(&queue->mutex);
        return -1; // Queue is full
    }
    queue->events[queue->tail] = event;
    queue->tail = (queue->tail + 1) % MAX_EVENTS;
    pthread_mutex_unlock(&queue->mutex);
    return 0;
}

int event_queue_pop(EventQueue *queue, NetworkEvent *event) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->head == queue->tail) {
        pthread_mutex_unlock(&queue->mutex);
        return -1; // Queue is empty
    }
    *event = queue->events[queue->head];
    queue->head = (queue->head + 1) % MAX_EVENTS;
    pthread_mutex_unlock(&queue->mutex);
    return 0;
}

void* log_thread(void *arg) {
    EventQueue *queue = (EventQueue*)arg;
    NetworkEvent event;

    while (1) {
        if (event_queue_pop(queue, &event) == 0) {
            // Process the event
            printf("Logged at %ld, Type: %d, Context Data: %s\n", 
                   event.timestamp, event.type, event.context.data_char);
        } else {
            // No more events to process
            break;
        }
    }

    return NULL;
}

int main() {
    EventQueue queue;
    pthread_t log_thread_id;

    event_queue_init(&queue);

    pthread_create(&log_thread_id, NULL, log_thread, &queue);

    // Simulate logging network events
    for (int i = 0; i < 10; i++) {
        NetworkEvent event;
        time_t now = time(NULL);
        strcpy(event.context.data_char, "Sample data");
        event.timestamp = now;
        event.type = EVENT_TYPE_A;

        if (event_queue_push(&queue, event) == -1) {
            printf("Failed to log event\n");
        }
    }

    pthread_join(log_thread_id, NULL);

    return 0;
}
