class NotificationService {
public:
    // Constructor
    NotificationService();

    // Start the service
    void start();

    // Stop the service
    void stop();

    // Add a notification rule
    void addRule(const std::string& userId, const std::vector<std::pair<std::string, int>>& conditions, const std::string& message);

    // Remove a notification rule
    void removeRule(const std::string& userId, const std::string& messageId);

    // Send notifications based on rules
    void sendNotifications();

private:
    std::map<std::string, std::vector<std::pair<std::string, int>>> userRules;
    std::queue<Notification> notificationQueue;
    std::thread workerThread;
    std::mutex queueMutex;
    std::condition_variable condition;
    bool running;
};

class Notification {
public:
    std::string userId;
    std::string message;
    // Other fields as needed
};

void NotificationService::start() {
    running = true;
    workerThread = std::thread(&NotificationService::sendNotifications, this);
}

void NotificationService::stop() {
    running = false;
    condition.notify_all();
    if (workerThread.joinable()) {
        workerThread.join();
    }
}

void NotificationService::addRule(const std::string& userId, const std::vector<std::pair<std::string, int>>& conditions, const std::string& message) {
    userRules[userId].push_back({message, 0});
}

void NotificationService::removeRule(const std::string& userId, const std::string& messageId) {
    // Implementation to remove rule
}

void NotificationService::sendNotifications() {
    while (running) {
        Notification notification;
        {
            std::unique_lock<std::mutex> lock(queueMutex);
            condition.wait(lock, [this]{ return !notificationQueue.empty() || !running; });
            if (!running && notificationQueue.empty()) {
                break;
            }
            notification = notificationQueue.front();
            notificationQueue.pop();
        }

        // Process and send the notification
        std::cout << "Sending notification to user: " << notification.userId << ", message: " << notification.message << std::endl;
    }
}

int main() {
    NotificationService service;
    service.start();

    // Example usage
    service.addRule("user123", {{"time_of_day", 9}, {"activity_level", 5}}, "Good morning!");
    service.addRule("user456", {{"event_type", 7}}, "Event reminder!");

    std::this_thread::sleep_for(std::chrono::seconds(10));

    service.stop();
    return 0;
}
