package main

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"

	"github.com/Shopify/sarama"
	"github.com/go-redis/redis/v8"
	"gorm.io/driver/mysql"
	"gorm.io/gorm"
)

type Packet struct {
	ID       int
	Payload  []byte
	Time     time.Time
}

type DataAdapter interface {
	ProcessPacket(ctx context.Context, packet Packet) error
}

type RedisDataAdapter struct{}

func (r *RedisDataAdapter) ProcessPacket(ctx context.Context, packet Packet) error {
	// Simulate processing with Redis
	return nil
}

type MySQLDataAdapter struct{}

func (m *MySQLDataAdapter) ProcessPacket(ctx context.Context, packet Packet) error {
	// Simulate processing with MySQL
	return nil
}

type MessageBroker interface {
	Consume(ctx context.Context, topic string, handler func(message []byte) error) error
	Publish(ctx context.Context, topic string, message []byte) error
}

type KafkaMessageBroker struct{}

func (k *KafkaMessageBroker) Consume(ctx context.Context, topic string, handler func(message []byte) error) error {
	config := sarama.NewConfig()
	config.Consumer.Return.Errors = true

	consumerGroupID := "packet-consumer-group"
	brokers := []string{"localhost:9092"}
	group, err := sarama.NewConsumerGroup(brokers, consumerGroupID, config)
	if err != nil {
		return err
	}

	topics := []string{topic}
	for ctx.Err() == nil {
		err := group.Consume(ctx, topics, &sarama.ConsumerGroupSession{})
		if err != nil {
			return err
		}
	}

	return nil
}

func (k *KafkaMessageBroker) Publish(ctx context.Context, topic string, message []byte) error {
	config := sarama.NewConfig()
	publisher, err := sarama.NewSyncProducer([]string{"localhost:9092"}, config)
	if err != nil {
		return err
	}

	partition, offset, err := publisher.SendMessage(&sarama.ProducerMessage{
		Topic: topic,
		Value: sarama.StringEncoder(message),
	})
	if err != nil {
		return err
	}

	fmt.Printf("Published to partition %d at offset %d\n", partition, offset)
	return nil
}

type DataPipeline struct {
	dataAdapter DataAdapter
	messageBroker MessageBroker
	packetQueue chan Packet
	wg sync.WaitGroup
	ctx context.Context
	cancel context.CancelFunc
}

func NewDataPipeline(dataAdapter DataAdapter, messageBroker MessageBroker) *DataPipeline {
	ctx, cancel := context.WithCancel(context.Background())
	return &DataPipeline{
		dataAdapter: dataAdapter,
		messageBroker: messageBroker,
		packetQueue: make(chan Packet, 1000),
		ctx:         ctx,
		cancel:      cancel,
	}
}

func (p *DataPipeline) EnqueuePacket(packet Packet) {
	select {
	case p.packetQueue <- packet:
	default:
		fmt.Println("Packet queue is full")
	}
}

func (p *DataPipeline) ProcessPackets() {
	for {
		select {
		case packet := <-p.packetQueue:
			p.wg.Add(1)
			go func(packet Packet) {
				defer p.wg.Done()
				if err := p.dataAdapter.ProcessPacket(p.ctx, packet); err != nil {
					fmt.Println("Error processing packet:", err)
				}
			}(packet)
		case <-p.ctx.Done():
			return
		}
	}
}

func (p *DataPipeline) Start() error {
	go p.messageBroker.Consume(p.ctx, "downlink_packets", func(message []byte) error {
		packet := Packet{
			Payload: message,
			Time:    time.Now(),
		}
		p.EnqueuePacket(packet)
		return nil
	})

	go p.ProcessPackets()
	return nil
}

func (p *DataPipeline) Stop() {
	p.cancel()
	p.wg.Wait()
	close(p.packetQueue)
}

func main() {
	dataAdapter := &RedisDataAdapter{}
	messageBroker := &KafkaMessageBroker{}

	pipeline := NewDataPipeline(dataAdapter, messageBroker)
	if err := pipeline.Start(); err != nil {
		fmt.Println("Error starting data pipeline:", err)
		return
	}
	defer pipeline.Stop()

	// Simulate enqueuing packets
	for i := 0; i < 10000; i++ {
		pipeline.EnqueuePacket(Packet{ID: i, Payload: []byte(fmt.Sprintf("packet-%d", i))})
	}

	fmt.Println("Data pipeline started")
	select {}
}
