#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <fstream>

// Define a simple logger interface
class Logger {
public:
    virtual void log(const std::string& message) = 0;
};

// Implement a console logger
class ConsoleLogger : public Logger {
public:
    void log(const std::string& message) override {
        std::cout << "Console Log: " << message << std::endl;
    }
};

// Implement an file logger
class FileLogger : public Logger {
private:
    std::ofstream file;

public:
    FileLogger(const std::string& filename) {
        file.open(filename, std::ios::app);
    }

    void log(const std::string& message) override {
        if (file.is_open()) {
            file << "File Log: " << message << std::endl;
        }
    }

    ~FileLogger() {
        if (file.is_open()) {
            file.close();
        }
    }
};

// Define a log processor
class LogProcessor {
private:
    Logger* logger;
    std::mutex queueMutex;
    std::condition_variable condition;
    std::queue<std::string> logQueue;
    bool stop;

public:
    LogProcessor(Logger* logger) : logger(logger), stop(false) {}

    void start() {
        std::thread([this]() {
            while (true) {
                std::unique_lock<std::mutex> lock(queueMutex);
                condition.wait(lock, [this] { return !logQueue.empty() || stop; });
                if (stop && logQueue.empty()) {
                    break;
                }
                std::string message = logQueue.front();
                logQueue.pop();
                lock.unlock();

                logger->log(message);
            }
        }).detach();
    }

    void stopProcessing() {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            stop = true;
        }
        condition.notify_all();
    }

    void addLog(const std::string& message) {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            logQueue.push(message);
        }
        condition.notify_one();
    }
};

int main() {
    // Create a logger
    Logger* logger = new ConsoleLogger();

    // Create a log processor
    LogProcessor processor(logger);

    // Start the log processor
    processor.start();

    // Add some logs
    for (int i = 0; i < 10; ++i) {
        processor.addLog("Log message " + std::to_string(i));
    }

    // Stop processing after adding all logs
    processor.stopProcessing();

    delete logger;
    return 0;
}
