    FORMAT_PLAIN_TEXT
} OutputFormat;

// Define logging service API
typedef struct {
    void (*log_message)(const char *message);
} LoggingServiceAPI;

// Global variables
LogLevel current_log_level = LOG_INFO;
OutputFormat current_format = FORMAT_PLAIN_TEXT;
LoggingServiceAPI external_logging_service = {NULL};

// Function to set log level from environment variable or configuration file
void set_log_level(const char *level) {
    if (strcmp(level, "DEBUG") == 0)
        current_log_level = LOG_DEBUG;
    else if (strcmp(level, "INFO") == 0)
        current_log_level = LOG_INFO;
    else if (strcmp(level, "WARNING") == 0)
        current_log_level = LOG_WARNING;
    else if (strcmp(level, "ERROR") == 0)
        current_log_level = LOG_ERROR;
    else if (strcmp(level, "CRITICAL") == 0)
        current_log_level = LOG_CRITICAL;
}

// Function to set output format from environment variable or configuration file
void set_output_format(const char *format) {
    if (strcmp(format, "JSON") == 0)
        current_format = FORMAT_JSON;
    else if (strcmp(format, "CSV") == 0)
        current_format = FORMAT_CSV;
    else if (strcmp(format, "PLAIN_TEXT") == 0)
        current_format = FORMAT_PLAIN_TEXT;
}

// Function to initialize external logging service API
void init_external_logging_service() {
    // Code to load and initialize the external logging service API
}

// Function to log message asynchronously using pthread
void async_log_message(const char *message) {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, (void *(*)(void *))external_logging_service.log_message, (void *)message);
    pthread_detach(thread_id);
}

// Function to format and log message based on current settings
void log_message(LogLevel level, const char *format, ...) {
    if (level < current_log_level)
        return;

    va_list args;
    va_start(args, format);

    char buffer[1024];
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    switch (current_format) {
        case FORMAT_JSON:
            // Format message as JSON
            break;
        case FORMAT_CSV:
            // Format message as CSV
            break;
        case FORMAT_PLAIN_TEXT:
            // Output plain text
            printf("%s\n", buffer);
            if (external_logging_service.log_message != NULL)
                async_log_message(buffer);
            break;
    }
}

// Main function to demonstrate logging framework usage
int main() {
    set_log_level("INFO");
    set_output_format("PLAIN_TEXT");

    log_message(LOG_INFO, "This is an info message.");
    log_message(LOG_ERROR, "This is an error message.");

    return 0;
