import asyncio
from typing import Dict, Any, Optional
import aiohttp
from cryptography.fernet import Fernet
from aioredis import Redis

class ConfigManager:
    def __init__(self, nodes: List[str], secret_key: bytes):
        self.nodes = nodes
        self.secret_key = secret_key
        self.fernet = Fernet(secret_key)
        self.redis = await Redis.from_url('redis://localhost')

    async def fetch_config(self, node: str) -> Dict[str, Any]:
        async with aiohttp.ClientSession() as session:
            async with session.get(f'http://{node}/config') as response:
                data = await response.json()
                return {key: self.decrypt(value) for key, value in data.items()}

    async def update_config(self, node: str, changes: Dict[str, Any]) -> None:
        encrypted_changes = {key: self.encrypt(value) for key, value in changes.items()}
        async with aiohttp.ClientSession() as session:
            await session.post(f'http://{node}/update', json=encrypted_changes)

    def encrypt(self, data: Any) -> bytes:
        return self.fernet.encrypt(pickle.dumps(data))

    def decrypt(self, encrypted_data: bytes) -> Any:
        return pickle.loads(self.fernet.decrypt(encrypted_data))
