#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int identifier;
} UEIdentifier;

typedef enum {
    RRC_CONNECTED,
    RRC_DISCONNECTED
} RRCState;

typedef struct {
    int sessionId;
    float latency;
    int throughput;
} PDUSessionStats;

typedef struct {
    UEIdentifier ueId;
    RRCState rrcState;
    PDUSessionStats *sessions;
    int sessionCount;
    pthread_mutex_t mutex;
} UEConnectionStatus;

UEConnectionStatus* initializeUEConnection(UEIdentifier ueId, RRCState rrcState) {
    UEConnectionStatus* status = (UEConnectionStatus*)malloc(sizeof(UEConnectionStatus));
    if (status == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    status->ueId = ueId;
    status->rrcState = rrcState;
    status->sessions = NULL;
    status->sessionCount = 0;
    pthread_mutex_init(&status->mutex, NULL);

    return status;
}

void addPDUSession(UEConnectionStatus* status, int sessionId, float latency, int throughput) {
    pthread_mutex_lock(&status->mutex);

    PDUSessionStats *newSessions = (PDUSessionStats*)realloc(status->sessions, (status->sessionCount + 1) * sizeof(PDUSessionStats));
    if (newSessions == NULL) {
        perror("Memory reallocation failed");
        pthread_mutex_unlock(&status->mutex);
        return;
    }

    status->sessions = newSessions;
    status->sessions[status->sessionCount].sessionId = sessionId;
    status->sessions[status->sessionCount].latency = latency;
    status->sessions[status->sessionCount].throughput = throughput;
    status->sessionCount++;

    pthread_mutex_unlock(&status->mutex);
}

void cleanUpUEConnection(UEConnectionStatus* status) {
    if (status != NULL) {
        pthread_mutex_lock(&status->mutex);

        free(status->sessions);
        pthread_mutex_unlock(&status->mutex);

        free(status);
    }
}
```

This code provides a basic structure for initializing and managing an array of `UEConnectionStatus` structures. It includes functions to add PDUSessionStats entries, initialize the connection status with necessary data types, and clean up resources when done. The use of mutexes ensures thread safety for concurrent access to shared data. Error handling is minimal but covers common memory allocation failures. This example can be expanded with more sophisticated error handling, logging mechanisms, and integration with external APIs as required by your task.']

