const express = require('express');
const axios = require('axios');
const redis = require('redis');
const rateLimit = require('express-rate-limit');
const WebSocket = require('ws');
const tracer = require('opentracing').initGlobalTracer();

const app = express();
const client = redis.createClient();
const wss = new WebSocket.Server({ port: 8081 });

// Middleware for logging requests
app.use((req, res, next) => {
    const span = tracer.startSpan(`${req.method} ${req.originalUrl}`);
    req.span = span;
    res.on('finish', () => {
        span.setTag('http.status_code', res.statusCode);
        span.finish();
    });
    next();
});

// Middleware for rate limiting
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per windowMs
});
app.use(limiter);

// Route for submitting transactions (synchronous)
app.post('/submitTransaction', async (req, res) => {
    const span = req.span;
    try {
        const response = await processTransaction(req.body);
        res.status(200).json(response);
    } catch (error) {
        span.setTag('error', true);
        span.log({ event: 'error', message: error.message });
        res.status(500).json({ error: 'Internal Server Error' });
    }
});

// Route for submitting transactions (asynchronous)
app.post('/submitTransactionAsync', async (req, res) => {
    const span = req.span;
