NFAPI_CRC_INDICATION_PDU_T** create_nfaapi_crc_indication_pdu_array(int N, pthread_mutex_t *lock) {
    int result = validate_input(N);
    if (result != 0) {
        fprintf(stderr, "Invalid input: N must be between 1 and 1000\n");
        return NULL;
    }

    size_t total_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T *);
    void *memory = allocate_memory(total_size, lock);
    if (memory == NULL) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T **array = (NFAPI_CRC_INDICATION_PDU_T **)memory;

    size_t element_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    for (int i = 0; i < N; i++) {
        array[i] = (NFAPI_CRC_INDICATION_PDU_T *)allocate_memory(element_size, lock);
        if (array[i] == NULL) {
            // Handle partial failure
            fprintf(stderr, "Failed to allocate memory for element %d\n", i);
            for (int j = 0; j < i; j++) {
                free(array[j]);
            }
            free(array);
            return NULL;
        }
    }

    return array;
}

// Example usage
int main() {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    int N = 100;
    NFAPI_CRC_INDICATION_PDU_T **array = create_nfaapi_crc_indication_pdu_array(N, &lock);
    if (array != NULL) {
        // Use the array...
        for (int i = 0; i < N; i++) {
            free(array[i]);
        }
        free(array);
    }

    pthread_mutex_destroy(&lock);
    return 0;
}
