  .factory('retryService', ['$q', function($q) {
    const maxRetries = 3;

    return {
      retry: function(operation) {
        let attempt = 0;

        const tryOperation = () => {
          return $q.when(operation())
            .catch(error => {
              if (attempt < maxRetries && error.message === 'Too Many Requests') {
                attempt++;
                const delay = Math.pow(2, attempt) * 100; // Exponential backoff
                return $q.delay(delay).then(tryOperation);
              } else {
                throw error;
              }
            });
        };

        return tryOperation();
      }
    };
