#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define constants for log levels
#define LOG_INFO 1
#define LOG_WARNING 2
#define LOG_ERROR 3

// Define a union to handle different types of context data
typedef union {
    int int_val;
    char *str_val;
    // Add more types as needed
} ContextData;

// Define the log entry structure
typedef struct {
    long timestamp;
    int event_code;
    ContextData context;
} LogEntry;

// Define a custom memory allocator structure
typedef struct Allocator {
    size_t total_size;
    size_t used_size;
    char *memory_pool;
    pthread_mutex_t lock; // Mutex for thread-safe allocation
} Allocator;

// Initialize the custom memory allocator
Allocator* init_allocator(size_t size) {
    Allocator *allocator = (Allocator*)malloc(sizeof(Allocator));
    if (!allocator) return NULL;
    allocator->total_size = size;
    allocator->used_size = 0;
    allocator->memory_pool = (char*)malloc(size);
    if (!allocator->memory_pool) {
        free(allocator);
        return NULL;
    }
    pthread_mutex_init(&allocator->lock, NULL);
    return allocator;
}

// Custom memory allocation function
void* custom_malloc(Allocator *allocator, size_t size) {
    pthread_mutex_lock(&allocator->lock);
    if (allocator->used_size + size > allocator->total_size) {
        pthread_mutex_unlock(&allocator->lock);
        return NULL; // Out of memory
    }
    void *ptr = &allocator->memory_pool[allocator->used_size];
    allocator->used_size += size;
    pthread_mutex_unlock(&allocator->lock);
    return ptr;
}

// Custom memory deallocation function (simply resets the pointer for reuse)
void custom_free(Allocator *allocator, void *ptr) {
    // In a real-world scenario, this would reset the memory to a default value
    // For simplicity, we just decrease used_size
    pthread_mutex_lock(&allocator->lock);
    char *mem_ptr = (char*)ptr;
    size_t offset = mem_ptr - allocator->memory_pool;
    if (offset < allocator->used_size) {
        allocator->used_size -= (mem_ptr - allocator->memory_pool);
    }
    pthread_mutex_unlock(&allocator->lock);
}

// Function to log an event
void log_event(Allocator *allocator, int level, const char *message, ContextData context) {
    LogEntry entry;
    entry.timestamp = time(NULL);
    entry.event_code = level;
    entry.context = context;

    // Serialize the log entry (for simplicity, just use memcpy)
    size_t entry_size = sizeof(LogEntry) + strlen(message) + 1;
    void *serialized_entry = custom_malloc(allocator, entry_size);
    if (!serialized_entry) {
        fprintf(stderr, "Memory allocation failed during logging\n");
        return;
    }
    memcpy(serialized_entry, &entry, sizeof(LogEntry));
    char *msg_ptr = (char*)serialized_entry + sizeof(LogEntry);
    strcpy(msg_ptr, message);

    // Process the serialized log entry (e.g., send to external service)
    // For this example, we just print it
    printf("Log: %ld [%d] %s\n", entry.timestamp, entry.event_code, msg_ptr);

    custom_free(allocator, serialized_entry);
}

// Example usage
int main() {
    Allocator *allocator = init_allocator(1024 * 1024); // 1MB allocator
    if (!allocator) return 1;

    ContextData context;
    context.str_val = "User logged in";

    log_event(allocator, LOG_INFO, "User session started", context);

    free(allocator->memory_pool);
    pthread_mutex_destroy(&allocator->lock);
    free(allocator);

    return 0;
}
```

This code provides a basic structure for a custom memory allocator and a simple logging function. It includes a mutex for thread-safe allocation and deallocation, ensuring that the system can handle concurrent access from multiple threads. The `log_event` function demonstrates how to serialize log entries into a buffer using the custom allocator and then process them (in this example, just printing them).']

