class NetworkService {
public:
    bool sendLog(const std::string& data) {
        // Implement network communication logic here
        return true;
    }
};

class LogQueue {
private:
    std::queue<Event> queue_;
    std::mutex mutex_;
    std::condition_variable condition_;

public:
    void push(const Event& event) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push(event);
        condition_.notify_one();
    }

    Event pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (queue_.empty()) {
            condition_.wait(lock);
        }
        Event event = queue_.front();
        queue_.pop();
        return event;
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.empty();
    }
};

class Logger {
private:
    MemoryAllocator allocator_;
    EventProcessor processor_;
    NetworkService networkService_;
    LogQueue logQueue_;
    std::vector<std::thread> workers_;
    std::atomic<bool> running_;

public:
    Logger(int numThreads) : running_(true) {
        for (int i = 0; i < numThreads; ++i) {
            workers_.emplace_back([this]() {
                while (running_) {
                    if (!logQueue_.empty()) {
                        Event event = logQueue_.pop();
                        processEvent(event);
                    }
                }
            });
        }
    }

    ~Logger() {
        running_ = false;
        for (auto& worker : workers_) {
            worker.join();
        }
    }

    void logEvent(const Event& event) {
        logQueue_.push(event);
    }

private:
    void processEvent(const Event& event) {
        if (event.context.stringValue.length() > 1024) {
            // Compress data before processing
            std::string compressedData = compressString(event.context.stringValue);
            processor_.processEvent({event.timestamp, event.event_code, compressedData});
        } else {
            processor_.processEvent(event);
        }
    }

    std::string compressString(const std::string& str) {
        int compressSize = LZ4_compressBound(str.size());
        std::unique_ptr<char[]> compressed(new char[compressSize]);
        int result = LZ4_compress_default(str.c_str(), compressed.get(), str.size(), compressSize);
        if (result > 0) {
            return std::string(compressed.get(), result);
        }
        // Compression failed, return original string
        return str;
    }
};

int main() {
    Logger logger(4);

    // Example usage
    Event event = {123456789, 1001, {"example"}};
    logger.logEvent(event);

    return 0;
}
