// Cryptographic Library for AES and Camellia
class CryptoLibrary {
public:
    static std::string encryptAES(const std::string& plaintext, const std::string& key, const std::string& iv) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) throw std::runtime_error("Failed to create cipher context");

        if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, (unsigned char*)key.c_str(), (unsigned char*)iv.c_str())) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("AES encryption initialization failed");
        }

        unsigned char ciphertext[plaintext.size() + EVP_CIPHER_block_size(EVP_aes_256_cbc())];
        int len, ciphertext_len;
        if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, (unsigned char*)plaintext.c_str(), plaintext.size())) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("AES encryption update failed");
        }
        ciphertext_len = len;

        if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("AES encryption finalization failed");
        }
        ciphertext_len += len;

        EVP_CIPHER_CTX_free(ctx);

        return std::string((char*)ciphertext, ciphertext_len);
    }

    static std::string decryptAES(const std::string& ciphertext, const std::string& key, const std::string& iv) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) throw std::runtime_error("Failed to create cipher context");

        if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, (unsigned char*)key.c_str(), (unsigned char*)iv.c_str())) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("AES decryption initialization failed");
        }

        unsigned char decryptedtext[ciphertext.size()];
        int len, plaintext_len;
        if (1 != EVP_DecryptUpdate(ctx, decryptedtext, &len, (unsigned char*)ciphertext.c_str(), ciphertext.size())) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("AES decryption update failed");
        }
        plaintext_len = len;

        if (1 != EVP_DecryptFinal_ex(ctx, decryptedtext + len, &len)) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("AES decryption finalization failed");
        }
        plaintext_len += len;

        EVP_CIPHER_CTX_free(ctx);

        return std::string((char*)decryptedtext, plaintext_len);
    }

    static std::string encryptCamellia(const std::string& plaintext, const std::string& key, const std::string& iv) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) throw std::runtime_error("Failed to create cipher context");

        if (1 != EVP_EncryptInit_ex(ctx, EVP_camellia_256_cbc(), nullptr, (unsigned char*)key.c_str(), (unsigned char*)iv.c_str())) {
            EVP_CIPHER_CTX_free(ctx);
