        }

        unsigned char ciphertext[plaintext.size() + EVP_CIPHER_block_size(EVP_camellia_256_cbc())];
        int len, ciphertext_len;
        if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, (unsigned char*)plaintext.c_str(), plaintext.size())) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Camellia encryption update failed");
        }
        ciphertext_len = len;

        if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("Camellia encryption finalization failed");
        }
        ciphertext_len += len;

        EVP_CIPHER_CTX_free(ctx);

        return std::string((char*)ciphertext, ciphertext_len);
    }

    static std::string decryptCamellia(const std::string& ciphertext, const std::string& key, const std::string& iv) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) throw std::runtime_error("Failed to create cipher context");

