    pthread_mutex_lock(&framework->mutex);
    for (int i = 0; i < 3; i++) {
        if (framework->adapters[i].log_event != NULL) {
            framework->adapters[i].log_event(event);
        }
    }
    pthread_mutex_unlock(&framework->mutex);
}

