#define MAX_EVENT_SIZE 1024

typedef struct {
    time_t timestamp;
    int event_code;
    union {
        char string_data[MAX_EVENT_SIZE];
        int integer_data;
        double float_data;
    } context;
} Event;

typedef struct {
    Event *events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} LogBuffer;

void init_log_buffer(LogBuffer *buffer, size_t initial_capacity) {
    buffer->capacity = initial_capacity;
    buffer->count = 0;
    buffer->events = (Event *)malloc(initial_capacity * sizeof(Event));
    if (!buffer->events) {
        fprintf(stderr, "Failed to allocate memory for log buffer\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&buffer->lock, NULL);
}

void add_event(LogBuffer *buffer, Event event) {
    pthread_mutex_lock(&buffer->lock);
    if (buffer->count >= buffer->capacity) {
        buffer->capacity *= 2;
        buffer->events = (Event *)realloc(buffer->events, buffer->capacity * sizeof(Event));
        if (!buffer->events) {
            fprintf(stderr, "Failed to reallocate memory for log buffer\n");
            exit(EXIT_FAILURE);
        }
    }
    buffer->events[buffer->count++] = event;
    pthread_mutex_unlock(&buffer->lock);
}

void process_events(LogBuffer *buffer) {
    // Implement logic to process events and integrate with database/cloud service
    for (size_t i = 0; i < buffer->count; ++i) {
        Event event = buffer->events[i];
        printf("Processing event: Timestamp=%ld, Code=%d, Context=%s\n", event.timestamp, event.event_code, event.context.string_data);
    }
}

void free_log_buffer(LogBuffer *buffer) {
    pthread_mutex_destroy(&buffer->lock);
    free(buffer->events);
}

int main() {
    LogBuffer log_buffer;
    init_log_buffer(&log_buffer, 1024);

    Event event;
    event.timestamp = time(NULL);
    event.event_code = 1;
    strcpy(event.context.string_data, "Example event");

    add_event(&log_buffer, event);
    process_events(&log_buffer);

    free_log_buffer(&log_buffer);
    return 0;
}
