// Import necessary libraries
import java.io.IOException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import org.apache.hadoop.conf.Configuration;
import org.apache.hadoop.fs.FileSystem;
import org.apache.hadoop.fs.Path;
import org.apache.hadoop.io.Text;
import org.apache.hadoop.mapreduce.Job;
import org.apache.hadoop.mapreduce.Mapper;
import org.apache.hadoop.mapreduce.Reducer;
import org.apache.hadoop.mapreduce.lib.input.FileInputFormat;
import org.apache.hadoop.mapreduce.lib.output.FileOutputFormat;

public class MetricIngestionPipeline {

    public static void main(String[] args) throws Exception {
        Configuration conf = new Configuration();
        Job job = Job.getInstance(conf, "Metric Ingestion Pipeline");

        job.setJarByClass(MetricIngestionPipeline.class);
        job.setMapperClass(MetricMapper.class);
        job.setReducerClass(MetricReducer.class);

        job.setOutputKeyClass(Text.class);
        job.setOutputValueClass(Text.class);

        FileInputFormat.addInputPath(job, new Path(args[0]));
        FileOutputFormat.setOutputPath(job, new Path(args[1]));

        System.exit(job.waitForCompletion(true) ? 0 : 1);
    }

    public static class MetricMapper extends Mapper<Object, Text, Text, Text> {
        private final static Text metricKey = new Text();
        private final static Text metricValue = new Text();

        public void map(Object key, Text value, Context context) throws IOException, InterruptedException {
            // Parse the input metric
            String[] parts = value.toString().split(",");
            if (parts.length == 5) {
                String timestamp = parts[0];
                String metricName = parts[1];
                String tags = parts[2];
                double value = Double.parseDouble(parts[3]);
                int tenantId = Integer.parseInt(parts[4]);

                // Emit key-value pair for further processing
                metricKey.set(metricName);
                metricValue.set(timestamp + "," + tags + "," + value + "," + tenantId);
                context.write(metricKey, metricValue);
            }
        }
    }

    public static class MetricReducer extends Reducer<Text, Text, Text, Text> {
        private final static Text result = new Text();

        public void reduce(Text key, Iterable<Text> values, Context context) throws IOException, InterruptedException {
            double sum = 0.0;
            int count = 0;

            // Aggregate the metrics for each key
            for (Text val : values) {
                String[] parts = val.toString().split(",");
                if (parts.length == 4) {
                    double value = Double.parseDouble(parts[2]);
                    sum += value;
                    count++;
                }
            }

            result.set(key + "," + sum + "," + count);
            context.write(key, result);
        }
    }
}
```

