#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>

#define MAX_THREADS 10
#define MAX_EVENT_SIZE 256

typedef enum { EVENT_CODE_1, EVENT_CODE_2 } EventCode;

typedef union {
    int intValue;
    float floatValue;
    char stringValue[MAX_EVENT_SIZE];
} ContextData;

typedef struct {
    time_t timestamp;
    EventCode code;
    ContextData context;
} LogEvent;

typedef struct {
    LogEvent *events;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int stop_flag;
} LogQueue;

LogQueue log_queue;

void init_log_queue() {
    log_queue.events = NULL;
    log_queue.count = 0;
    log_queue.capacity = 1024;
    pthread_mutex_init(&log_queue.mutex, NULL);
    pthread_cond_init(&log_queue.cond, NULL);
    log_queue.stop_flag = 0;
}

void enqueue_event(const LogEvent *event) {
    pthread_mutex_lock(&log_queue.mutex);
    while (log_queue.count == log_queue.capacity) {
        pthread_cond_wait(&log_queue.cond, &log_queue.mutex);
    }
    if (!log_queue.events) {
        log_queue.events = malloc(log_queue.capacity * sizeof(LogEvent));
    } else {
        log_queue.events = realloc(log_queue.events, log_queue.capacity * sizeof(LogEvent));
    }
    memcpy(&log_queue.events[log_queue.count], event, sizeof(LogEvent));
    log_queue.count++;
    pthread_cond_signal(&log_queue.cond);
    pthread_mutex_unlock(&log_queue.mutex);
}

void* log_thread_func(void *arg) {
    while (1) {
        pthread_mutex_lock(&log_queue.mutex);
        while (log_queue.count == 0 && !log_queue.stop_flag) {
            pthread_cond_wait(&log_queue.cond, &log_queue.mutex);
        }
        if (log_queue.stop_flag) {
            break;
        }
        LogEvent event = log_queue.events[log_queue.count - 1];
        log_queue.count--;
        pthread_mutex_unlock(&log_queue.mutex);

        // Simulate sending to an external service
        printf("Sending event: %ld, %d, ", (long)event.timestamp, event.code);
        switch (event.context.code) {
            case EVENT_CODE_1:
                printf("%d\n", event.context.intValue);
                break;
            case EVENT_CODE_2:
                printf("%.2f\n", event.context.floatValue);
                break;
        }
    }
    pthread_mutex_unlock(&log_queue.mutex);
    return NULL;
}

int main() {
    init_log_queue();

    // Start log threads
    pthread_t log_threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&log_threads[i], NULL, log_thread_func, NULL);
    }

    // Simulate logging events
    for (int i = 0; i < 100; i++) {
        LogEvent event;
        event.timestamp = time(NULL);
        event.code = (i % 2 == 0) ? EVENT_CODE_1 : EVENT_CODE_2;
        switch (event.code) {
            case EVENT_CODE_1:
                event.context.intValue = i * 10;
                break;
            case EVENT_CODE_2:
                event.context.floatValue = i * 1.5f;
                break;
        }
        enqueue_event(&event);
    }

    // Wait for log threads to finish
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(log_threads[i], NULL);
    }

    // Clean up
    free(log_queue.events);
    pthread_mutex_destroy(&log_queue.mutex);
    pthread_cond_destroy(&log_queue.cond);

    return 0;
}
