        return std::to_string(std::chrono::duration_cast<std::chrono::seconds>(now.time_since_epoch()).count());
    }
};

// Define SensorManager class
class SensorManager {
public:
    void addSensor(const std::string& sensorId, const SensorReading& reading) {
        std::lock_guard<std::mutex> lock(mutex_);
        sensors_[sensorId].push(reading);
        condition_.notify_one();
    }

    void processSensors() {
        while (running_) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this] { return !sensors_.empty() || !running_; });
            if (!sensors_.empty()) {
                auto sensorId = sensors_.begin()->first;
                auto reading = sensors_[sensorId].front();
                sensors_[sensorId].pop();

                // Process the reading
                processReading(sensorId, reading);

                lock.unlock();
                io_service.post([this] { processSensors(); });
            }
        }
    }

private:
    void processReading(const std::string& sensorId, const SensorReading& reading) {
        iotService_.sendReading(reading);
        dashboard_.update(reading);
        logger_.log("Processed reading from " + sensorId);
    }

    IoTServiceAPI iotService_;
    RealTimeAlertingDashboard dashboard_;
    Logger logger_;

    std::map<std::string, std::queue<SensorReading>> sensors_;
    std::mutex mutex_;
    std::condition_variable condition_;
    bool running_ = true;
    boost::asio::io_service io_service;
};

// Define main function
int main() {
    SensorManager sensorManager;

    // Simulate adding sensor readings
    sensorManager.addSensor("sensor1", { "2023-04-01T12:00:00Z", 25.6, 45.2, 1013.2 });
    sensorManager.addSensor("sensor2", { "2023-04-01T12:01:00Z", 26.7, 46.3, 1014.5 });

    // Start processing sensors
    std::thread processingThread(&SensorManager::processSensors, &sensorManager);

    // Wait for processing thread to finish
    processingThread.join();

    return 0;
}
