// Function to initialize the octree with NFAPI data
void initializeOctreeWithNFAPIData(LockFreeQueue<NFAPI_CRC_INDICATION_PDU_T>& queue,
                                   std::mutex& lock,
                                   std::condition_variable& cv) {
