#include <stdlib.h>
#include <time.h>

#define MAX_PDUS 1000000

typedef struct {
    uint16_t RNTI;
    char RX_UE_INFORMATION_TAG[256];
    char CRC_INDICATION_REL8_TAG[256];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_and_populate_pdus(int N, int rnti_range_start, int rnti_range_end) {
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;

    srand(time(NULL));

    for (int i = 0; i < N; ++i) {
        pdus[i].RNTI = rand() % (rnti_range_end - rnti_range_start + 1) + rnti_range_start;
        snprintf(pdus[i].RX_UE_INFORMATION_TAG, sizeof(pdus[i].RX_UE_INFORMATION_TAG), "Tag_%d", i);
        snprintf(pdus[i].CRC_INDICATION_REL8_TAG, sizeof(pdus[i].CRC_INDICATION_REL8_TAG), "Rel8Tag_%d", i);
        pdus[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    }

    return pdus;
}

int main() {
    int N = 500000;
    int rnti_range_start = 1;
    int rnti_range_end = 1000;

    NFAPI_CRC_INDICATION_PDU_T* pdus = generate_and_populate_pdus(N, rnti_range_start, rnti_range_end);
    if (pdus) {
        // Process PDUs
        free(pdus);
    }

    return 0;
}
