#include "google/protobuf/util/message_differencer.h"
#include "nfaapi_crc_indication_pdu.pb.h"

class NFAPIService {
public:
    NFAPIService(size_t max_concurrent_tasks, size_t max_pending_tasks)
        : max_concurrent_tasks_(max_concurrent_tasks),
          max_pending_tasks_(max_pending_tasks) {}

    void start() {
        for (size_t i = 0; i < max_concurrent_tasks_; ++i) {
            workers_.emplace_back([this]() { worker_loop(); });
        }
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            shutdown_ = true;
        }
        cv_.notify_all();
        for (auto& worker : workers_) {
            worker.join();
        }
    }

    void enqueue(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            if (pending_tasks_ >= max_pending_tasks_) {
                throw std::runtime_error("Too many pending tasks");
            }
            pending_tasks_++;
        }
        task_queue_.push(pdu);
        cv_.notify_one();
    }

private:
    void worker_loop() {
        while (true) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                cv_.wait(lock, [this] { return !task_queue_.empty() || shutdown_; });
                if (shutdown_ && task_queue_.empty()) {
                    return;
                }
                pdu = task_queue_.front();
                task_queue_.pop();
                pending_tasks_--;
            }

            // Process the PDU
            process_pdu(pdu);
        }
    }

    void process_pdu(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        // Implement PDU processing logic here
        std::cout << "Processing PDU: " << pdu.DebugString() << std::endl;
    }

private:
    size_t max_concurrent_tasks_;
    size_t max_pending_tasks_;
    std::vector<std::thread> workers_;
    std::queue<NFAPI_CRC_INDICATION_PDU_T> task_queue_;
    std::mutex mutex_;
    std::condition_variable cv_;
    bool shutdown_ = false;
    std::atomic<size_t> pending_tasks_{0};
};

int main() {
    NFAPIService service(10, 1000);
    service.start();

    // Simulate PDU generation
    for (size_t i = 0; i < 1000000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Populate the PDU with data
        service.enqueue(pdu);
    }

    service.stop();
