#include <pthread.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct NetworkEvent {
    // Define the structure for network events
} NetworkEvent;

typedef struct DeviceState {
    int dev_id;
    NetworkEvent** events;
    size_t event_count;
    size_t max_events;
    int ref_count;
    pthread_mutex_t lock;
} DeviceState;

typedef struct DeviceManager {
    DeviceState** devices;
    size_t device_count;
    size_t max_devices;
    pthread_mutex_t lock;
} DeviceManager;

DeviceState* create_device_state(int dev_id, NetworkEvent* initial_event) {
    DeviceState* state = malloc(sizeof(DeviceState));
    if (!state) return NULL;

    state->dev_id = dev_id;
    state->events = malloc(sizeof(NetworkEvent*) * 1);
    if (!state->events) {
        free(state);
        return NULL;
    }
    state->events[0] = initial_event;
    state->event_count = 1;
    state->max_events = 1;
    state->ref_count = 1;

    pthread_mutex_init(&state->lock, NULL);

    return state;
}

void add_network_event(DeviceState* state, NetworkEvent* event) {
    pthread_mutex_lock(&state->lock);
    if (state->event_count == state->max_events) {
        size_t new_size = state->max_events * 2;
        NetworkEvent** new_events = realloc(state->events, sizeof(NetworkEvent*) * new_size);
        if (!new_events) {
            pthread_mutex_unlock(&state->lock);
            return; // Handle memory allocation failure
        }
        state->events = new_events;
        state->max_events = new_size;
    }
    state->events[state->event_count++] = event;
    pthread_mutex_unlock(&state->lock);
}

void acquire_device_state(DeviceState* state) {
    pthread_mutex_lock(&state->lock);
    state->ref_count++;
    pthread_mutex_unlock(&state->lock);
}

void release_device_state(DeviceState* state) {
    pthread_mutex_lock(&state->lock);
    if (--state->ref_count == 0) {
        // Free resources and clean up
        for (size_t i = 0; i < state->event_count; i++) {
            free(state->events[i]);
        }
        free(state->events);
        pthread_mutex_unlock(&state->lock);
        pthread_mutex_destroy(&state->lock);
        free(state);
    } else {
        pthread_mutex_unlock(&state->lock);
    }
}

DeviceManager* create_device_manager() {
    DeviceManager* manager = malloc(sizeof(DeviceManager));
    if (!manager) return NULL;

    manager->devices = malloc(sizeof(DeviceState*) * 1);
    if (!manager->devices) {
        free(manager);
        return NULL;
    }
    manager->device_count = 0;
    manager->max_devices = 1;

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void add_device(DeviceManager* manager, DeviceState* device) {
    pthread_mutex_lock(&manager->lock);
    if (manager->device_count == manager->max_devices) {
        size_t new_size = manager->max_devices * 2;
        DeviceState** new_devices = realloc(manager->devices, sizeof(DeviceState*) * new_size);
        if (!new_devices) {
            pthread_mutex_unlock(&manager->lock);
            return; // Handle memory allocation failure
        }
        manager->devices = new_devices;
        manager->max_devices = new_size;
    }
    manager->devices[manager->device_count++] = device;
    pthread_mutex_unlock(&manager->lock);
}

void remove_device(DeviceManager* manager, DeviceState* device) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->device_count; i++) {
        if (manager->devices[i] == device) {
            free(manager->devices[i]);
            memmove(&manager->devices[i], &manager->devices[i + 1], sizeof(DeviceState*) * (manager->device_count - i - 1));
            manager->device_count--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}
```

