#include <iostream>
#include <unordered_map>
#include <mutex>
#include <chrono>

struct ResourceUsage {
    std::string resource_id;
    double cpu_usage;
    double memory_usage;
    double disk_io;
    std::time_t last_update_time;
};

class DistributedCache {
private:
    std::unordered_map<std::string, ResourceUsage> cache;
    std::mutex mutex;

public:
    void update(const ResourceUsage& usage) {
        std::lock_guard<std::mutex> lock(mutex);
        cache[usage.resource_id] = usage;
    }

    ResourceUsage* get(const std::string& resource_id) {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = cache.find(resource_id);
        if (it != cache.end()) {
            return &it->second;
        }
        return nullptr;
    }

    void expire_entries(std::time_t threshold) {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto it = cache.begin(); it != cache.end();) {
            if (std::difftime(std::time(nullptr), it->second.last_update_time) > threshold) {
                it = cache.erase(it);
            } else {
                ++it;
            }
        }
    }

    void aggregate_cpu_usage() const {
        double total_cpu = 0.0;
        for (const auto& entry : cache) {
            total_cpu += entry.second.cpu_usage;
        }
        std::cout << "Total CPU Usage: " << total_cpu << std::endl;
    }
};

int main() {
    DistributedCache cache;

    ResourceUsage usage1 = {"resource1", 0.8, 4.2, 15.3, std::time(nullptr)};
    ResourceUsage usage2 = {"resource2", 0.6, 3.5, 10.2, std::time(nullptr)};

    cache.update(usage1);
    cache.update(usage2);

    {
        ResourceUsage* usage = cache.get("resource1");
        if (usage) {
            std::cout << "CPU Usage for resource1: " << usage->cpu_usage << std::endl;
        }
    }

    cache.expire_entries(std::chrono::hours(1).count());

    cache.aggregate_cpu_usage();

    return 0;
}
