#include <iostream>
#include <unordered_map>
#include <mutex>
#include <memory>
#include <thread>
#include <condition_variable>

// ResourceUsage class representing data to be cached
class ResourceUsage {
public:
    int id;
    std::string data;

    ResourceUsage(int id, const std::string& data) : id(id), data(data) {}
};

// DistributedCache interface for cache operations
class DistributedCache {
public:
    virtual void set(const std::string& key, const ResourceUsage& value) = 0;
    virtual std::optional<ResourceUsage> get(const std::string& key) = 0;
    virtual void remove(const std::string& key) = 0;
};

// In-MemoryCache implementation using a hash map
class InMemoryCache : public DistributedCache {
private:
    std::unordered_map<std::string, ResourceUsage> cache;
    std::mutex mutex;

public:
    void set(const std::string& key, const ResourceUsage& value) override {
        std::lock_guard<std::mutex> lock(mutex);
        cache[key] = value;
    }

    std::optional<ResourceUsage> get(const std::string& key) override {
        std::lock_guard<std::mutex> lock(mutex);
        auto it = cache.find(key);
        if (it != cache.end()) {
            return it->second;
        }
        return std::nullopt;
    }

    void remove(const std::string& key) override {
        std::lock_guard<std::mutex> lock(mutex);
        cache.erase(key);
    }
};

// CacheManager class to manage distributed cache operations
class CacheManager {
private:
    DistributedCache* cache;
    std::thread monitoringThread;
    std::condition_variable cv;
    bool stop;

public:
    CacheManager(DistributedCache* cache) : cache(cache), stop(false) {}

    void startMonitoring() {
        monitoringThread = std::thread([this]() {
            while (true) {
                std::unique_lock<std::mutex> lock(cv.wait_for(mutex, std::chrono::seconds(10), [this] { return stop; }));
                if (stop) break;
                // Perform cache performance monitoring and adjustment here
                std::cout << "Monitoring cache performance..." << std::endl;
            }
        });
    }

    void stopMonitoring() {
        {
            std::lock_guard<std::mutex> lock(mutex);
            stop = true;
        }
        cv.notify_one();
        if (monitoringThread.joinable()) {
            monitoringThread.join();
        }
    }

    ~CacheManager() {
        stopMonitoring();
    }
};

int main() {
    InMemoryCache cache;
    CacheManager manager(&cache);
    manager.startMonitoring();

    // Example usage of the cache
    ResourceUsage resource(1, "Sample Data");
    manager.cache->set("key1", resource);

    if (auto result = manager.cache->get("key1")) {
        std::cout << "Retrieved data: " << result->data << std::endl;
    }

    manager.stopMonitoring();
    return 0;
}
```

