class ModularFramework {
    constructor() {
        this.scripts = [];
        this.dependencies = {};
        this.loadedScripts = new Set();
    }

    addScript(script, dependencies = []) {
        this.scripts.push(script);
        this.dependencies[script] = dependencies;
    }

    loadScript(scriptName) {
        if (this.loadedScripts.has(scriptName)) return Promise.resolve();

        const scriptDependencies = this.dependencies[scriptName];
        if (scriptDependencies.length > 0) {
            const dependencyPromises = scriptDependencies.map(dep => this.loadScript(dep));
            return Promise.all(dependencyPromises)
                .then(() => this.executeScript(scriptName))
                .catch(error => this.handleError(scriptName, error));
        } else {
            return this.executeScript(scriptName).catch(error => this.handleError(scriptName, error));
        }
    }

    executeScript(scriptName) {
        const script = document.createElement('script');
        script.src = `scripts/${scriptName}.js`;
        script.onload = () => {
            console.log(`${scriptName} loaded successfully`);
            this.loadedScripts.add(scriptName);
        };
        script.onerror = (error) => {
            console.error(`Failed to load ${scriptName}`, error);
        };
        document.head.appendChild(script);
        return new Promise((resolve, reject) => {
            script.onload = resolve;
            script.onerror = reject;
        });
    }

    handleError(scriptName, error) {
        console.error(`Error loading ${scriptName}:`, error);
        // Implement recovery strategies here
        return Promise.reject(error);
    }
}

// Usage example
const framework = new ModularFramework();
framework.addScript('main', ['utils']);
framework.loadScript('main');
