    // Define the structure fields for CRC_INDICATION_REL8_TAG
} CRC_INDICATION_REL8_TAG;

#define MAX_STRUCTURES 1000000

NFAPI_CRC_INDICATION_PDU_T* populate_nfaip_pdu_array(int N, RX_UE_INFORMATION_TAG* ue_tags, RNTI* rntis, CRC_INDICATION_REL8_TAG* crc_tags, int* error_code) {
    if (N > MAX_STRUCTURES || !ue_tags || !rntis || !crc_tags || !error_code) {
        *error_code = -EINVAL;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        *error_code = -ENOMEM;
        return NULL;
    }

    pthread_mutex_t mutex;
    if (pthread_mutex_init(&mutex, NULL)) {
        free(array);
        *error_code = -EAGAIN;
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&mutex);
        // Populate the structure with validated data
        array[i].ue_tag = ue_tags[i];
        array[i].rnti = rntis[i];
        array[i].crc_indication_rel8_tag = crc_tags[i];
        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);
    *error_code = 0;
    return array;
}

