from prometheus_client import start_http_server, Summary

app = Flask(__name__)

# Database connection pooling
db_pool = psycopg2.pool.SimpleConnectionPool(1, 20, user="user", password="password",
                                               host="localhost", port= "5432",
                                               database="financial_transactions")

# Prometheus metrics
REQUEST_TIME = Summary('request_processing_seconds', 'Time spent processing request')

def get_db_connection():
    conn = db_pool.getconn()
    if conn is None:
        raise Exception("Failed to get a connection from the pool")
    return conn

@app.teardown_appcontext
def close_db_connection(exception):
    conn = getattr(g, '_database', None)
    if conn is not None:
        db_pool.putconn(conn)

# Rate limiting decorator
def rate_limit(limit=10, period=60):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = request.remote_addr + func.__name__
            count = cache.get(key, 0) + 1
            if count > limit:
                return jsonify({"error": "Rate limit exceeded"}), 429
            cache.set(key, count, timeout=period)
            return func(*args, **kwargs)
        return wrapper
    return decorator

# Retry logic with exponential backoff
def retry(max_retries=3):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempt = 0
            while attempt < max_retries:
                try:
                    result = func(*args, **kwargs)
                    return result
                except Exception as e:
                    sleep(2 ** attempt)
                    attempt += 1
            raise e
        return wrapper
    return decorator

@app.route('/process_transaction', methods=['POST'])
@REQUEST_TIME.time()
@rate_limit(limit=5, period=60)  # Example rate limit: 5 requests per minute
@retry(max_retries=3)
def process_transaction():
    data = request.json
    transaction_type = data.get('type')
    amount = data.get('amount')
    currency = data.get('currency')

    if not all([transaction_type, amount, currency]):
        return jsonify({"error": "Missing required parameters"}), 400

    conn = get_db_connection()
    cur = conn.cursor()

    # Example query to insert transaction into the database
    cur.execute("INSERT INTO transactions (type, amount, currency) VALUES (%s, %s, %s)", (transaction_type, amount, currency))
    conn.commit()

    # Simulate processing with a third-party payment gateway
    response = requests.post("https://payment-gateway.com/process", json=data)
    if response.status_code != 200:
        raise Exception("Failed to process transaction")

    cur.close()
    return jsonify({"message": "Transaction processed successfully"}), 200

if __name__ == "__main__":
    start_http_server(8000)  # Start Prometheus metrics server
    app.run(debug=True)
