import threading
from collections import defaultdict, deque
import random
import time

class DistributedCache:
    def __init__(self):
        self.cache = defaultdict(lambda: (None, None))
        self.lock = threading.Lock()
        self.shards = {}
        self.shard_locks = {}

    def add_shard(self, shard_id):
        with self.lock:
            if shard_id not in self.shards:
                self.shards[shard_id] = {}
                self.shard_locks[shard_id] = threading.Lock()

    def get_data(self, key):
        shard_id = hash(key) % len(self.shards)
        with self.shard_locks[shard_id]:
            data, timestamp = self.cache[key]
            if data is not None:
                return data
            else:
                # Simulate fetching from remote cache or database
                time.sleep(0.1)
                return f"Data for {key}"

    def set_data(self, key, value):
        shard_id = hash(key) % len(self.shards)
        with self.shard_locks[shard_id]:
            self.cache[key] = (value, time.time())
            # Simulate replicating to other shards or databases
            time.sleep(0.1)

    def remove_data(self, key):
        shard_id = hash(key) % len(self.shards)
        with self.shard_locks[shard_id]:
            if key in self.cache:
                del self.cache[key]
                # Simulate replicating removal to other shards or databases
                time.sleep(0.1)

    def scale_out(self, num_shards):
        for _ in range(num_shards):
            shard_id = random.randint(0, len(self.shards))
            self.add_shard(shard_id)

    def scale_in(self, num_shards):
        for _ in range(num_shards):
            if len(self.shards) > 1:
                shard_id = random.choice(list(self.shards.keys()))
                del self.shards[shard_id]
                del self.shard_locks[shard_id]

# Example usage
cache = DistributedCache()
cache.add_shard(0)
cache.add_shard(1)

cache.set_data('user1', 'session1')
print(cache.get_data('user1'))  # Output: Data for user1

cache.scale_out(2)
cache.set_data('user2', 'session2')
print(cache.get_data('user2'))  # Output: Data for user2
```']

