// Define a union for context data
typedef union {
    int i;
    float f;
    char str[128];
} ContextData;

// Define a structure for network events
typedef struct Event {
    long timestamp;
    int event_code;
    ContextData context;
} Event;

// Define a structure for the logging queue
typedef struct QueueNode {
    Event event;
    struct QueueNode* next;
} QueueNode;

QueueNode* queue_head = NULL;
QueueNode* queue_tail = NULL;
pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t queue_not_empty = PTHREAD_COND_INITIALIZER;
pthread_cond_t queue_not_full = PTHREAD_COND_INITIALIZER;
int queue_size = 0;
int max_queue_size = 1000;

// Custom memory allocator (simplified example)
void* custom_malloc(size_t size) {
    // Implement custom memory allocation logic here
}

void custom_free(void* ptr) {
    // Implement custom memory deallocation logic here
}

// Function to enqueue an event
void enqueue_event(Event event) {
    QueueNode* new_node = (QueueNode*)custom_malloc(sizeof(QueueNode));
    new_node->event = event;
    new_node->next = NULL;

    pthread_mutex_lock(&queue_lock);
    while (queue_size == max_queue_size) {
        pthread_cond_wait(&queue_not_full, &queue_lock);
    }
    if (queue_tail == NULL) {
        queue_head = queue_tail = new_node;
    } else {
        queue_tail->next = new_node;
        queue_tail = new_node;
    }
    queue_size++;
    pthread_cond_signal(&queue_not_empty);
    pthread_mutex_unlock(&queue_lock);
}

// Function to dequeue an event
Event dequeue_event() {
    Event event = {0};
    QueueNode* old_head;

    pthread_mutex_lock(&queue_lock);
    while (queue_size == 0) {
        pthread_cond_wait(&queue_not_empty, &queue_lock);
    }
    old_head = queue_head;
    event = old_head->event;
    queue_head = old_head->next;
    if (queue_head == NULL) {
        queue_tail = NULL;
    }
    queue_size--;
    custom_free(old_head);
    pthread_cond_signal(&queue_not_full);
    pthread_mutex_unlock(&queue_lock);

    return event;
}

// Thread function for logging events
void* log_thread(void* arg) {
    while (1) {
        Event event = dequeue_event();
        // Process the event here (e.g., send to external service)
        printf("Processed event: timestamp=%ld, code=%d\n", event.timestamp, event.event_code);
    }
    return NULL;
}

int main() {
    pthread_t log_tid;
    pthread_create(&log_tid, NULL, log_thread, NULL);

    // Simulate logging events
    for (int i = 0; i < 100; i++) {
        Event event = {time(NULL), i, {.i = i}};
        enqueue_event(event);
    }

    pthread_join(log_tid, NULL);
    return 0;
}
