using Microsoft.Extensions.Logging;

public class DynamicNetworkHealthMonitor
{
    private readonly ILogger<DynamicNetworkHealthMonitor> _logger;
    private readonly Dictionary<string, ServerInstance> _serverInstances;
    private readonly AlertingFramework _alertingFramework;
    private readonly MachineLearningModel _mlModel;
    private readonly IaCProvider _iacProvider;

    public DynamicNetworkHealthMonitor(ILogger<DynamicNetworkHealthMonitor> logger, AlertingFramework alertingFramework, MachineLearningModel mlModel, IaCProvider iacProvider)
    {
        _logger = logger;
        _serverInstances = new Dictionary<string, ServerInstance>();
        _alertingFramework = alertingFramework;
        _mlModel = mlModel;
        _iacProvider = iacProvider;
    }

    public void AddServerInstance(string instanceId, string cloudProvider, string ipAddress)
    {
        if (!_serverInstances.ContainsKey(instanceId))
        {
            _serverInstances[instanceId] = new ServerInstance(instanceId, cloudProvider, ipAddress);
        }
    }

    public async Task MonitorHealthAsync()
    {
        while (true)
        {
            foreach (var serverInstance in _serverInstances.Values)
            {
                try
                {
                    var healthStatus = await CheckServerHealth(serverInstance);
                    if (healthStatus.IsDegraded)
                    {
                        _logger.LogWarning("Server instance {InstanceId} is degraded.", serverInstance.InstanceId);
                        await _alertingFramework.NotifyAsync($"Server {serverInstance.InstanceId} is experiencing issues.");
                    }
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Failed to monitor health of server instance {InstanceId}.", serverInstance.InstanceId);
                }

                await Task.Delay(_mlModel.GetNextMonitoringInterval(serverInstance));
            }
        }
    }

    private async Task<HealthStatus> CheckServerHealth(ServerInstance serverInstance)
    {
        var icmpPing = PingNetwork(serverInstance.IpAddress);
        var tcpConnectivity = await TcpNetworkCheckAsync(serverInstance.IpAddress, 80);
        var httpLatency = await HttpLatencyCheckAsync(serverInstance.IpAddress, "http://example.com");

        return new HealthStatus
        {
            IsDegraded = !icmpPing && !tcpConnectivity && httpLatency > _mlModel.GetThreshold(HealthMetric.HttpLatency)
        };
    }

    private bool PingNetwork(string ipAddress)
    {
        using (var pingSender = new Ping())
        {
            try
            {
                var reply = pingSender.Send(ipAddress, 100);
                return reply.Status == IPStatus.Success;
            }
            catch (PingException)
            {
                _logger.LogWarning("Ping to {IpAddress} failed.", ipAddress);
                return false;
            }
        }
    }

    private async Task<bool> TcpNetworkCheckAsync(string ipAddress, int port)
    {
        using (var tcpClient = new System.Net.Sockets.TcpClient())
        {
            try
            {
                await tcpClient.ConnectAsync(ipAddress, port);
                return true;
            }
            catch (System.Net.Sockets.SocketException)
            {
                _logger.LogWarning("TCP connection to {IpAddress}:{Port} failed.", ipAddress, port);
                return false;
            }
        }
    }

    private async Task<int> HttpLatencyCheckAsync(string ipAddress, string url)
    {
        using (var httpClient = new System.Net.Http.HttpClient())
        {
            try
            {
                var stopwatch = new System.Diagnostics.Stopwatch();
                stopwatch.Start();
                var response = await httpClient.GetAsync(url);
                stopwatch.Stop();
                return (int)stopwatch.Elapsed.TotalMilliseconds;
            }
            catch (System.Net.Http.HttpRequestException)
            {
                _logger.LogWarning("HTTP request to {Url} failed.", url);
                return int.MaxValue;
            }
        }
    }
}

