#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_COMMANDS 1000
#define MAX_THREADS 50

typedef struct {
    char command[256];
    int status;
} Command;

Command commands[MAX_COMMANDS];
int command_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int stop_flag = 0;

void* execute_command(void* arg) {
    while (1) {
        pthread_mutex_lock(&lock);
        while (command_count == 0 && !stop_flag) {
            pthread_cond_wait(&cond, &lock);
        }
        if (stop_flag) {
            pthread_mutex_unlock(&lock);
            break;
        }
        int index = command_count - 1;
        command_count--;
        pthread_mutex_unlock(&lock);

        // Execute the command
        printf("Executing command: %s\n", commands[index].command);
        commands[index].status = system(commands[index].command);

        // Log the result
        FILE* log_file = fopen("/var/log/command_execution.log", "a");
        if (log_file != NULL) {
            fprintf(log_file, "%s: %d\n", commands[index].command, commands[index].status);
            fclose(log_file);
        }
    }
    return NULL;
}

void submit_command(const char* command) {
    pthread_mutex_lock(&lock);
    while (command_count >= MAX_COMMANDS) {
        // Handle backpressure by waiting
        pthread_cond_wait(&cond, &lock);
    }
    strcpy(commands[command_count].command, command);
    commands[command_count].status = -1;
    command_count++;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&lock);
}

void stop_execution() {
    pthread_mutex_lock(&lock);
    stop_flag = 1;
    pthread_cond_broadcast(&cond);
    pthread_mutex_unlock(&lock);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <command>\n", argv[0]);
        return 1;
    }

    // Initialize threads
    pthread_t threads[MAX_THREADS];
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, execute_command, NULL);
    }

    // Submit commands
    for (int i = 1; i < argc; i++) {
        submit_command(argv[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

