#include <forward_list>
#include <string>
#include <atomic>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <unordered_map>
#include <chrono>
#include <thread>

struct Request {
    std::string id;
    std::string metadata;
    int priority;
};

struct RetryConfig {
    int maxAttempts;
    std::chrono::milliseconds initialDelay;
};

class DistributedQueue {
private:
    std::forward_list<Request> queue;
    std::unordered_map<std::string, Request> cache;
    std::mutex mtx;
    std::condition_variable cv;
    std::atomic<bool> paused;

public:
    void processUserRequest(const std::forward_list<Request>& requestList,
                             const std::string& targetId,
                             const std::string& newRequest,
                             bool fetchMetadata,
                             int priority,
                             bool maintenancePause,
                             const RetryConfig& retryConfig) {
        std::unique_lock<std::mutex> lock(mtx);
        if (maintenancePause || queue.empty()) {
            cv.wait(lock, [this] { return !maintenancePause && !queue.empty(); });
        }

        auto it = std::find_if(queue.begin(), queue.end(),
                               [&](const Request& req) { return req.id == targetId; });

        if (it != queue.end()) {
            if (newRequest.find(it->id) != std::string::npos) {
                // Update existing request
                it->metadata = newRequest;
                it->priority = priority;
            } else {
                // Insert new request after target
                it++;
                it = queue.insert_after(prev(it), {newRequest, "", priority});
            }
        } else if (fetchMetadata) {
            // Fetch metadata from external service
            for (int attempt = 0; attempt < retryConfig.maxAttempts; ++attempt) {
                try {
                    std::string fetchedMetadata = fetchMetadataFromService(newRequest);
                    queue.push_front({newRequest, fetchedMetadata, priority});
                    cache[newRequest] = {newRequest, fetchedMetadata, priority};
                    return;
                } catch (const std::exception& e) {
                    if (attempt == retryConfig.maxAttempts - 1) {
                        logError("Failed to fetch metadata", newRequest, e.what());
                        notifyAdmins("Persistent failure fetching metadata for request: " + newRequest);
                    }
                    std::this_thread::sleep_for(retryConfig.initialDelay * std::pow(2.0, attempt));
                }
            }
        }

        if (it != queue.end()) {
            // Reinsert updated request at front based on priority
            auto pq = std::priority_queue<Request>(queue.begin(), queue.end());
            Request top;
            while (!pq.empty() && pq.top().priority >= it->priority) {
                top = pq.top();
                pq.pop();
                queue.erase_after(queue.before_begin());
            }
            queue.insert_after(queue.before_begin(), {it->id, it->metadata, priority});
            pq.push({it->id, it->metadata, priority});
            std::for_each(pq.begin(), pq.end(),
                          [&](const Request& req) { queue.emplace_front(req.id, req.metadata, req.priority); });
        }
    }

private:
    std::string fetchMetadataFromService(const std::string& requestId) {
        // Simulate fetching metadata from an external service
        return "metadata_for_" + requestId;
    }

    void logError(const std::string& operation, const std::string& requestId, const std::string& error) {
        // Log error with timestamp
        auto now = std::chrono::system_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::seconds>(now.time_since_epoch()).count();
        std::cerr << "Error at " << duration << ": " << operation << " failed for request: " << requestId << ", Error: " << error << std::endl;
    }

    void notifyAdmins(const std::string& message) {
        // Implement mechanism to notify system administrators
        std::cout << "Notification to admins: " << message << std::endl;
    }
};
