#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <memory>
#include <atomic>
#include <chrono>

class Image {
public:
    Image(const std::string& format, int width, int height) : format_(format), width_(width), height_(height) {}
    std::string format() const { return format_; }
    int width() const { return width_; }
    int height() const { return height_; }

private:
    std::string format_;
    int width_;
    int height_;
};

class ImageProcessor {
public:
    virtual ~ImageProcessor() = default;
    virtual void process(const Image& image) = 0;
};

class CPUImageProcessor : public ImageProcessor {
public:
    void process(const Image& image) override {
        // Simulate processing on CPU
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }
};

class GPUImageProcessor : public ImageProcessor {
public:
    void process(const Image& image) override {
        // Simulate processing on GPU
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
};

class DynamicImageProcessingFramework {
public:
    DynamicImageProcessingFramework() {
        cpu_processor_ = std::make_unique<CPUImageProcessor>();
        gpu_processor_ = std::make_unique<GPUImageProcessor>();
        task_queue_.reserve(1024);
    }

    void enqueue(const Image& image) {
        std::unique_lock<std::mutex> lock(mutex_);
        task_queue_.push(image);
        condition_.notify_one();
    }

    void start() {
        running_ = true;
        worker_thread_ = std::thread(&DynamicImageProcessingFramework::process_tasks, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            running_ = false;
        }
        condition_.notify_all();
        if (worker_thread_.joinable()) {
            worker_thread_.join();
        }
    }

private:
    void process_tasks() {
        while (true) {
            Image image;
            {
                std::unique_lock<std::mutex> lock(mutex_);
                condition_.wait(lock, [this] { return !task_queue_.empty() || !running_; });
                if (!running_) break;
                image = task_queue_.front();
                task_queue_.pop();
            }
            // Select processor based on image size or format
            if (image.width() > 1024) {
                gpu_processor_->process(image);
            } else {
                cpu_processor_->process(image);
            }
        }
    }

    std::unique_ptr<ImageProcessor> cpu_processor_;
    std::unique_ptr<ImageProcessor> gpu_processor_;
    std::queue<Image> task_queue_;
    std::mutex mutex_;
    std::condition_variable condition_;
    bool running_ = false;
    std::thread worker_thread_;
};

int main() {
    DynamicImageProcessingFramework framework;
    framework.start();
    framework.enqueue(Image("PNG", 1280, 720));
    framework.enqueue(Image("JPEG", 3840, 2160));
    std::this_thread::sleep_for(std::chrono::seconds(5));
    framework.stop();
    return 0;
}
