using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        // Add service discovery and load balancing
        services.AddHttpClient("ExternalAPIClient", client =>
        {
            client.BaseAddress = new Uri("https://external-api.com");
            client.DefaultRequestHeaders.Accept.Clear();
            client.DefaultRequestHeaders.Accept.Add(new System.Net.Http.Headers.MediaTypeWithQualityHeaderValue("application/json"));
        });

        // Add distributed caching
        services.AddStackExchangeRedisCache(options =>
        {
            options.Configuration = "redis-server:6379";
            options.InstanceName = "myTestInstance";
        });

        // Add machine learning model service
        services.AddScoped<IMachineLearningService, MachineLearningService>();

        // Add API gateway for external integrations
        services.AddControllers();

        // Add observability
        services.AddApplicationInsightsTelemetry();
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        if (env.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
        }

        app.UseRouting();

        app.UseEndpoints(endpoints =>
        {
            endpoints.MapControllers();
        });

        // Middleware for rate limiting and circuit breaker
        app.UseMiddleware<RateLimitingMiddleware>();
        app.UseMiddleware<CircuitBreakerMiddleware>();

        // CORS policy
        app.UseCors(builder =>
        {
            builder.WithOrigins("https://example.com")
                   .AllowAnyHeader()
                   .AllowAnyMethod();
        });
    }
}

public interface IMachineLearningService
{
    Task<List<string>> GetRecommendationsAsync(string userId);
}

public class MachineLearningService : IMachineLearningService
{
    private readonly HttpClient _httpClient;
    private readonly IDistributedCache _cache;

    public MachineLearningService(HttpClient httpClient, IDistributedCache cache)
    {
        _httpClient = httpClient;
        _cache = cache;
    }

    public async Task<List<string>> GetRecommendationsAsync(string userId)
    {
        // Fetch recommendations from cache
        var cachedRecommendations = await _cache.GetStringAsync(userId);
        if (cachedRecommendations != null)
        {
            return JsonConvert.DeserializeObject<List<string>>(cachedRecommendations);
        }

        // Call external API for recommendations
        var response = await _httpClient.GetAsync($"https://external-api.com/recommendations?userId={userId}");
        if (response.IsSuccessStatusCode)
        {
            var recommendations = await response.Content.ReadAsStringAsync();
            await _cache.SetStringAsync(userId, recommendations, new DistributedCacheEntryOptions
            {
                AbsoluteExpirationRelativeToNow = TimeSpan.FromHours(1)
            });
            return JsonConvert.DeserializeObject<List<string>>(recommendations);
        }

        // Fallback to default recommendations
        return new List<string> { "defaultRecommendation" };
    }
}

public class RateLimitingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly int _maxRequestsPerMinute;

    public RateLimitingMiddleware(RequestDelegate next, int maxRequestsPerMinute)
    {
        _next = next;
        _maxRequestsPerMinute = maxRequestsPerMinute;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        // Implement rate limiting logic here
        await _next(context);
    }
}

public class CircuitBreakerMiddleware
{
    private readonly RequestDelegate _next;
    private readonly Func<Task<bool>> _isHealthy;

    public CircuitBreakerMiddleware(RequestDelegate next, Func<Task<bool>> isHealthy)
    {
        _next = next;
        _isHealthy = isHealthy;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        if (await _isHealthy())
        {
            await _next(context);
        }
        else
        {
            context.Response.StatusCode = StatusCodes.Status503ServiceUnavailable;
            await context.Response.WriteAsync("Service unavailable");
        }
    }
}
