nosql_store = {}

@app.route('/user/<int:user_id>', methods=['GET'])
def get_user(user_id):
    # Fetch user data from NoSQL store with caching
    user_data = nosql_store.get(user_id, legacy_db.get(user_id))
    return jsonify(user_data)

@app.route('/user/<int:user_id>', methods=['POST'])
def create_or_update_user(user_id):
    user_data = request.json
    version = user_data.get('version', 0)

    # Optimistic locking: Check version before updating
    if version != legacy_db.get(user_id, {}).get('version', 0):
        return jsonify({'error': 'Conflict'}), 409

    # Update legacy database and NoSQL store atomically
    with optimistic_locking():
        legacy_db[user_id] = user_data
        nosql_store[user_id] = user_data
        user_data['version'] += 1
    return jsonify(user_data)

def optimistic_locking():
    """
    Implement a context manager for optimistic locking using locks.
    """
    lock = threading.Lock()
    with lock:
        # Simulate database update
        yield

@app.route('/user/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    if user_id in legacy_db:
        del legacy_db[user_id]
        del nosql_store[user_id]
        return '', 204
    else:
        return jsonify({'error': 'User not found'}), 404

if __name__ == '__main__':
    app.run(debug=True)
