@SpringBootApplication
public class TextContentService {

    public static void main(String[] args) {
        SpringApplication.run(TextContentService.class, args);
    }

    @Autowired
    private TextContentRepository repository;

    @PostMapping("/content")
    public ResponseEntity<TextContent> createContent(@RequestBody TextContent content) {
        return ResponseEntity.ok(repository.save(content));
    }

    @GetMapping("/content/{id}")
    public ResponseEntity<TextContent> getContent(@PathVariable Long id) {
        return ResponseEntity.ok(repository.findById(id).orElse(null));
    }

    @PutMapping("/content/{id}")
    public ResponseEntity<TextContent> updateContent(@PathVariable Long id, @RequestBody TextContent content) {
        if (repository.existsById(id)) {
            content.setId(id);
            return ResponseEntity.ok(repository.save(content));
        } else {
            return ResponseEntity.notFound().build();
        }
    }

    @DeleteMapping("/content/{id}")
    public ResponseEntity<Void> deleteContent(@PathVariable Long id) {
        if (repository.existsById(id)) {
            repository.deleteById(id);
            return ResponseEntity.noContent().build();
        } else {
            return ResponseEntity.notFound().build();
        }
    }
}

