unique_ptr<ISerializer> SerializerFactory::createSerializer(const string& format) {
    if (format == "json") {
        return make_unique<JsonSerializer>();
    } else if (format == "xml") {
        return make_unique<XmlSerializer>();
    } else if (format == "binary") {
        return make_unique<BinarySerializer>();
    }
    throw runtime_error("Unsupported format");
}

// Main application logic
void loadDataAndDeserialize() {
    string activeFormat = ConfigurationManager::getActiveFormat();
    unique_ptr<ISerializer> serializer = SerializerFactory::createSerializer(activeFormat);

    shared_ptr<IDataSource> fileDataSource = make_shared<FileDataSource>();
    future<string> dataFuture = fileDataSource->loadDataAsync();

    try {
        string data = dataFuture.get();
        auto state = serializer->deserialize(data);
        if (!state->validate()) {
            throw runtime_error("Validation failed");
        }
        // Use the state object
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
    }

    fileDataSource->releaseData(data);
}

int main() {
    loadDataAndDeserialize();
    return 0;
}
