// This is a high-level design of a microservices-based supply chain platform in Java.
// Each service represents a component of the platform.

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.client.discovery.EnableDiscoveryClient;
import org.springframework.cloud.openfeign.EnableFeignClients;

@SpringBootApplication
@EnableDiscoveryClient
@EnableFeignClients
public class SupplyChainPlatformApplication {
    public static void main(String[] args) {
        SpringApplication.run(SupplyChainPlatformApplication.class, args);
    }
}

// Order Service
@Service
public class OrderService {
    @Autowired private OrderRepository orderRepository;
    @Autowired private WarehouseService warehouseService;
    @Autowired private LogisticsService logisticsService;

    public Order placeOrder(Order order) {
        // Place new order and notify warehouse for inventory update
        return orderRepository.save(order);
    }

    public void cancelOrder(String orderId) {
        // Cancel order and notify relevant services
        Order order = orderRepository.findById(orderId).orElseThrow(() -> new RuntimeException("Order not found"));
        order.setStatus(OrderStatus.CANCELLED);
        orderRepository.save(order);
        logisticsService.cancelShipment(order.getShipmentId());
    }

    public Order updateShipment(String orderId, ShipmentDetails details) {
        // Update shipment details and notify relevant services
        Order order = orderRepository.findById(orderId).orElseThrow(() -> new RuntimeException("Order not found"));
        order.setShipmentStatus(details.getStatus());
        orderRepository.save(order);
        logisticsService.updateShipment(order.getShipmentId(), details);
        return order;
    }
}

// Warehouse Service
@Service
public class WarehouseService {
    @Autowired private InventoryRepository inventoryRepository;

    public void updateInventory(InventoryUpdate update) {
        // Update inventory and notify other services
        Inventory inventory = inventoryRepository.findById(update.getProductId()).orElseThrow(() -> new RuntimeException("Product not found"));
        inventory.setQuantity(inventory.getQuantity() - update.getAmount());
        inventoryRepository.save(inventory);
    }
}

// Logistics Service
@Service
public class LogisticsService {
    @Autowired private ShipmentRepository shipmentRepository;
    @FeignClient(name = "third-party-logistics")
    private ThirdPartyLogisticsClient logisticsClient;

    public void processShipment(Shipment shipment) {
        // Process shipment and notify relevant services
        shipment.setStatus(ShipmentStatus.IN_TRANSIT);
        shipmentRepository.save(shipment);
        logisticsClient.trackShipment(shipment.getShipmentId());
    }

    public void cancelShipment(String shipmentId) {
        // Cancel shipment and notify relevant services
        Shipment shipment = shipmentRepository.findById(shipmentId).orElseThrow(() -> new RuntimeException("Shipment not found"));
        shipment.setStatus(ShipmentStatus.CANCELLED);
        shipmentRepository.save(shipment);
        logisticsClient.cancelShipment(shipment.getShipmentId());
    }

    public void updateShipment(String shipmentId, ShipmentDetails details) {
        // Update shipment details and notify relevant services
        Shipment shipment = shipmentRepository.findById(shipmentId).orElseThrow(() -> new RuntimeException("Shipment not found"));
        shipment.setStatus(details.getStatus());
        shipmentRepository.save(shipment);
        logisticsClient.updateShipment(shipment.getShipmentId(), details);
    }
}

// Rest Controller for API
@RestController
@RequestMapping("/api/orders")
public class OrderController {
    @Autowired private OrderService orderService;

    @PostMapping
    public ResponseEntity<Order> placeOrder(@RequestBody Order order) {
        return ResponseEntity.ok(orderService.placeOrder(order));
    }

    @DeleteMapping("/{orderId}")
    public ResponseEntity<Void> cancelOrder(@PathVariable String orderId) {
        orderService.cancelOrder(orderId);
        return ResponseEntity.noContent().build();
    }

    @PutMapping("/{orderId}/shipment")
    public ResponseEntity<Order> updateShipment(@PathVariable String orderId, @RequestBody ShipmentDetails details) {
        return ResponseEntity.ok(orderService.updateShipment(orderId, details));
    }
}

// OAuth 2.0 and JWT Configuration
@Configuration
@EnableAuthorizationServer
public class AuthorizationServerConfig extends AuthorizationServerConfigurerAdapter {
    // Implement configuration for OAuth 2.0 and JWT
}

// Third-Party Logistics Integration
@FeignClient(name = "third-party-logistics")
public interface ThirdPartyLogisticsClient {
    @PostMapping("/trackShipment")
    void trackShipment(@RequestParam String shipmentId);

    @PostMapping("/cancelShipment")
    void cancelShipment(@RequestParam String shipmentId);

    @PutMapping("/updateShipment")
    void updateShipment(@RequestParam String shipmentId, @RequestBody ShipmentDetails details);
}

// Monitoring and Alerting System
@Service
public class MonitoringService {
    // Implement monitoring and alerting logic
}

// Caching Layer
@Service
@Cacheable(value = "orders", key = "#orderId")
public Order getOrder(String orderId) {
    return orderRepository.findById(orderId).orElse(null);
}

// Reporting Module
@Service
public class ReportingService {
    @Autowired private OrderRepository orderRepository;
    @Autowired private InventoryRepository inventoryRepository;

    public SupplyChainReport generateReport() {
        // Generate detailed analytics report
        return new SupplyChainReport();
    }
}
