async function runModuleTests(moduleName, testCases, externalServiceClient, testConfig, performanceMetrics, environmentStatus) {
    const { maxConcurrentTests, logLevel } = testConfig;
    const { currentLoad, health } = environmentStatus;
    let concurrencyLimit = Math.min(maxConcurrentTests, 10); // Default to a reasonable limit
    if (health < 80 || currentLoad > 75) {
        concurrencyLimit /= 2; // Scale down concurrency for critical issues or high load
    }

    const testResults = [];
    const queue = [...testCases];
    let activeTests = new Set();

    while (queue.length || activeTests.size) {
        // Add available tests to the running set
        while (queue.length && activeTests.size < concurrencyLimit) {
            const testCase = queue.shift();
            activeTests.add(testCase.label);
            testRun(testCase)
                .then(result => {
                    testResults.push(result);
                    activeTests.delete(testCase.label);
                })
                .catch(error => {
                    console.error(`Test failed: ${testCase.label}`, error);
                    activeTests.delete(testCase.label);
                });
        }

        // Wait for any running tests to complete if the queue is empty
        if (!queue.length && activeTests.size) {
            await Promise.race([...activeTests].map(label => testResults.find(result => result.label === label).promise));
        }
    }

    return testResults;

    async function testRun(testCase) {
        const { label, testCaseFunction, dependencies = [], customSetupFunction, environmentConfig } = testCase;
        console.log(`Starting test: ${label}`);

        if (customSetupFunction) {
            await customSetupFunction();
        }

        const startTime = performance.now();
        let result;
        try {
            result = await testCaseFunction(externalServiceClient, environmentConfig);
            console.log(`Test passed: ${label}`);
        } catch (error) {
            console.error(`Test failed: ${label}`, error);
            if (testConfig.retryOnFail && testConfig.retryCount > 0) {
                // Implement retry logic here
                console.log(`Retrying test: ${label}`);
                result = await testCaseFunction(externalServiceClient, environmentConfig);
                console.log(`Retry passed: ${label}`);
            }
        }

        const endTime = performance.now();
        performanceMetrics.addTestExecutionTime(label, endTime - startTime);

        // Reset blueslip mocking library
        resetBlueslipMocking();

        return { label, result, status: result ? 'pass' : 'fail', startTime, endTime };
    }
}

function resetBlueslipMocking() {
    // Implement blueslip mocking library reset logic here
}
