function renderHeader(components) {
    const cache = {};
    let html = '';

    components.forEach(component => {
        if (!component.type || !component.props) return;

        switch (component.type) {
            case 'text':
                html += `<div id="${component.id}" class="header-text">${component.description}</div>`;
                break;
            case 'image':
                const imgSrc = cache[component.name] || fetchImage(component.name);
                if (imgSrc) {
                    cache[component.name] = imgSrc;
                    html += `<img id="${component.id}" src="${imgSrc}" alt="${component.description}">`;
                } else {
                    html += `<div id="${component.id}" class="header-image-fallback">${component.description}</div>`;
                }
                break;
            case 'interactive':
                html += `<button id="${component.id}" onclick="${component.props.onClick}">${component.description}</button>`;
                break;
            default:
                console.warn(`Unsupported component type: ${component.type}`);
        }
    });

    return html;

    function fetchImage(name) {
        if (!name || !API_URL) return null;

        const cached = cache[name];
        if (cached) return cached;

        try {
            const response = await fetch(`${API_URL}/images/${name}`);
            if (!response.ok) throw new Error('Network response was not ok');
            const data = await response.json();
            return data.url;
        } catch (error) {
            console.error(`Error fetching image ${name}:`, error);
            return null;
        }
    }
}
