package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"sync"

	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
	"github.com/gomodule/redigo/redis"
	"github.com/json-iterator/go"
)

var json = jsoniter.ConfigCompatibleWithStandardLibrary

type Event struct {
	ID     string `json:"id"`
	Type   string `json:"type"`
	Payload interface{} `json:"payload"`
}

type SchemaRegistry struct {
	schemas map[string][]byte
	mu      sync.RWMutex
}

func NewSchemaRegistry() *SchemaRegistry {
	return &SchemaRegistry{
		schemas: make(map[string][]byte),
	}
}

func (sr *SchemaRegistry) RegisterSchema(schemaID string, schema []byte) error {
	sr.mu.Lock()
	defer sr.mu.Unlock()
	if _, exists := sr.schemas[schemaID]; exists {
		return fmt.Errorf("schema already registered")
	}
	sr.schemas[schemaID] = schema
	return nil
}

func (sr *SchemaRegistry) GetSchema(schemaID string) ([]byte, error) {
	sr.mu.RLock()
	defer sr.mu.RUnlock()
	if schema, exists := sr.schemas[schemaID]; exists {
		return schema, nil
	}
	return nil, fmt.Errorf("schema not found")
}

func main() {
	r := chi.NewRouter()

	reg := NewSchemaRegistry()

	r.Use(middleware.Logger)
	r.Use(middleware.Recoverer)

	r.Post("/register/schema", func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			SchemaID string `json:"schemaID"`
			Schema   []byte `json:"schema"`
		}
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			http.Error(w, "Invalid request body", http.StatusBadRequest)
			return
		}

		err := reg.RegisterSchema(req.SchemaID, req.Schema)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}

		w.WriteHeader(http.StatusCreated)
	})

	r.Get("/schema/{schemaID}", func(w http.ResponseWriter, r *http.Request) {
		schemaID := chi.URLParam(r, "schemaID")
		schema, err := reg.GetSchema(schemaID)
		if err != nil {
			http.Error(w, err.Error(), http.StatusNotFound)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		if _, err := w.Write(schema); err != nil {
			log.Printf("Error writing response: %v", err)
		}
	})

	r.Run(":8080")
}
```']

