package main

import (
	"context"
	"encoding/json"
	"log"
	"time"

	"github.com/go-redis/redis/v8"
	"golang.org/x/oauth2"
)

type Session struct {
	UserID      string `json:"user_id"`
	Expiration  time.Time `json:"expiration"`
	Preferences Preferences `json:"preferences"`
}

type Preferences struct {
	Theme   string `json:"theme"`
	Language string `json:"language"`
}

var ctx = context.Background()
var rdb *redis.Client

func init() {
	rdb = redis.NewClient(&redis.Options{
		Addr:     "localhost:6379",
		Password: "", // no password set
		DB:       0,  // use default DB
	})
}

func authenticateWithOAuth2(code string) (*oauth2.Token, error) {
	config := &oauth2.Config{
		ClientID:     "your_client_id",
		ClientSecret: "your_client_secret",
		RedirectURL:  "http://localhost:8080/callback",
		Scopes:       []string{"profile", "email"},
		Endpoint: oauth2.Endpoint{
			AuthURL:  "https://provider.com/oauth/authorize",
			TokenURL: "https://provider.com/oauth/token",
		},
	}
	token, err := config.Exchange(ctx, code)
	if err != nil {
		return nil, err
	}
	return token, nil
}

func createSession(userID string) (*Session, error) {
	session := &Session{
		UserID: userID,
		Expiration: time.Now().Add(30 * time.Minute),
		Preferences: Preferences{
			Theme:   "light",
			Language: "en",
		},
	}
	sessionBytes, err := json.Marshal(session)
	if err != nil {
		return nil, err
	}

	err = rdb.Set(ctx, userID, sessionBytes, 30*time.Minute).Err()
	if err != nil {
		return nil, err
	}
	return session, nil
}

func getUserSession(userID string) (*Session, error) {
	sessionBytes, err := rdb.Get(ctx, userID).Result()
	if err == redis.Nil {
		return nil, ErrSessionNotFound
	} else if err != nil {
		return nil, err
	}

	var session Session
	err = json.Unmarshal([]byte(sessionBytes), &session)
	if err != nil {
		return nil, err
	}
	return &session, nil
}

func updateSessionPreferences(userID string, preferences Preferences) error {
	session, err := getUserSession(userID)
	if err != nil {
		return err
	}
	session.Preferences = preferences

	sessionBytes, err := json.Marshal(session)
	if err != nil {
		return err
	}

	err = rdb.Set(ctx, userID, sessionBytes, 30*time.Minute).Err()
	if err != nil {
		return err
	}
	return nil
}

func invalidateSession(userID string) error {
	return rdb.Del(ctx, userID).Err()
}

func main() {
	// Example usage
	token, err := authenticateWithOAuth2("some_code")
	if err != nil {
		log.Fatalf("Authentication failed: %v", err)
	}

	userID := "user123"
	session, err := createSession(userID)
	if err != nil {
		log.Fatalf("Failed to create session: %v", err)
	}

	log.Printf("Session created for user %s: %+v", userID, session)

	newPreferences := Preferences{
		Theme:   "dark",
		Language: "fr",
	}
	err = updateSessionPreferences(userID, newPreferences)
	if err != nil {
		log.Fatalf("Failed to update preferences: %v", err)
	}

	log.Printf("Updated preferences for user %s", userID)

	err = invalidateSession(userID)
	if err != nil {
		log.Fatalf("Failed to invalidate session: %v", err)
	}
	log.Printf("Session invalidated for user %s", userID)
}
