import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class LoggingAndDataSyncService {
    private static final int THREAD_POOL_SIZE = 10;
    private ExecutorService executorService = Executors.newFixedThreadPool(THREAD_POOL_SIZE);

    public void log(String message) {
        executorService.submit(() -> {
            // Log the message to a file or remote server
        });
    }

    public <T> void syncData(T data, boolean isFullSync) {
        executorService.submit(() -> {
            if (isFullSync) {
                performFullSync(data);
            } else {
                performIncrementalSync(data);
            }
        });
    }

    private <T> void performFullSync(T data) {
        // Logic for full synchronization
    }

    private <T> void performIncrementalSync(T data) {
        // Logic for incremental synchronization
    }

    public void startMonitoring() {
        executorService.submit(() -> {
            while (true) {
                // Monitor and report metrics
                try {
                    Thread.sleep(1000);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }
}
