use Monolog\Logger;
use Monolog\Handler\StreamHandler;

require __DIR__ . '/vendor/autoload.php';

$app = AppFactory::create();

// Configure Monolog for logging
$log = new Logger('image_processor');
$log->pushHandler(new StreamHandler(__DIR__ . '/logs/image_processor.log', Logger::DEBUG));

// Create a Guzzle HTTP client
$httpClient = new Client([
    'base_uri' => 'https://external-image-api.com',
    'timeout'  => 2.0,
]);

$app->post('/update-clinic-status/{clinicId}', function (Request $request, Response $response, array $args) use ($httpClient, $log) {
    $clinicId = $args['clinicId'];
    $imageData = $request->getParsedBodyParam('imageData');

    if (!isset($imageData)) {
        return $response->withStatus(400)->write(json_encode(['error' => 'No image data provided']));
    }

    try {
        // Validate image bits per sample and sample per pixel
        list($bitsPerSample, $samplesPerPixel) = getImageDimensions($imageData);
        if (!in_array($bitsPerSample, [1, 2, 4, 8, 16])) {
            $log->error("Unsupported bit depth: {$bitsPerSample}");
            return $response->withStatus(500)->write(json_encode(['error' => 'Unsupported bit depth']));
        }

        // Process image with external API
        $imageUrl = uploadImage($httpClient, $imageData);
        if (!$imageUrl) {
            $log->warning("Failed to process image for clinic ID {$clinicId}");
            return $response->withStatus(500)->write(json_encode(['error' => 'Failed to process image']));
        }

        // Update database with new status and metadata
        updateClinicStatus($clinicId, [
            'last_modified_ip' => $_SERVER['REMOTE_ADDR'],
            'last_modified_date' => date('Y-m-d H:i:s'),
            'image_url' => $imageUrl,
            'bits_per_sample' => $bitsPerSample,
            'samples_per_pixel' => $samplesPerPixel,
        ]);

        return $response->withStatus(200)->write(json_encode(['message' => 'Clinic status updated successfully']));
    } catch (\Exception $e) {
        $log->error("Error processing clinic ID {$clinicId}: " . $e->getMessage());
        return $response->withStatus(500)->write(json_encode(['error' => 'Internal server error']));
    }
});

