// This is a simplified example of how you might structure the code for a multi-tenant message queuing system in C.
// It does not include actual implementations for interfacing with third-party brokers or sensor protocols.

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* data;
    int tenant_id;
} Message;

typedef struct {
    Message** queue;
    int front, rear, capacity;
    pthread_mutex_t lock;
    pthread_cond_t not_empty, not_full;
} Queue;

Queue* create_queue(int capacity) {
    Queue* q = (Queue*)malloc(sizeof(Queue));
    q->queue = (Message**)malloc(capacity * sizeof(Message*));
    q->front = q->rear = -1;
    q->capacity = capacity;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->not_empty, NULL);
    pthread_cond_init(&q->not_full, NULL);
    return q;
}

void enqueue(Queue* q, Message* msg) {
    pthread_mutex_lock(&q->lock);
    while ((q->rear + 1) % q->capacity == q->front) {
        pthread_cond_wait(&q->not_full, &q->lock);
    }
    if (q->front == -1) q->front = q->rear = 0;
    else q->rear = (q->rear + 1) % q->capacity;
    q->queue[q->rear] = msg;
    pthread_cond_signal(&q->not_empty);
    pthread_mutex_unlock(&q->lock);
}

Message* dequeue(Queue* q) {
    Message* msg = NULL;
    pthread_mutex_lock(&q->lock);
    while (q->front == -1) {
        pthread_cond_wait(&q->not_empty, &q->lock);
    }
    msg = q->queue[q->front];
    if (q->front == q->rear) q->front = q->rear = -1;
    else q->front = (q->front + 1) % q->capacity;
    pthread_cond_signal(&q->not_full);
    pthread_mutex_unlock(&q->lock);
    return msg;
}

void destroy_queue(Queue* q) {
    pthread_mutex_destroy(&q->lock);
    pthread_cond_destroy(&q->not_empty);
    pthread_cond_destroy(&q->not_full);
    free(q->queue);
    free(q);
}
