    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used_count;
} MemoryPool;

void init_memory_pool(MemoryPool *mp, size_t size) {
    mp->pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    mp->pool_size = size;
    mp->used_count = 0;
}

NFAPI_CRC_INDICATION_PDU_T *allocate_from_pool(MemoryPool *mp) {
    if (mp->used_count >= mp->pool_size) return NULL;
    return &mp->pool[mp->used_count++];
}

void free_memory_pool(MemoryPool *mp) {
    free(mp->pool);
}

void* generate_crc_indications(void *arg) {
    MemoryPool *mp = (MemoryPool *)arg;
    NFAPI_CRC_INDICATION_PDU_T *indication;
    for (int i = 0; i < N / NUM_THREADS; i++) {
        indication = allocate_from_pool(mp);
        if (indication != NULL) {
            indication->RX_UE_INFORMATION_TAG = rand() % 1000;
            indication->RNTI = rand() % 65536;
            indication->CRC_INDICATION_REL8_TAG = rand() % 2;
        }
    }
    return NULL;
}

int main() {
    MemoryPool mp;
    init_memory_pool(&mp, N);

    pthread_t threads[NUM_THREADS];
    for (int i = 0; i < NUM_THREADS; i++) {
        if (pthread_create(&threads[i], NULL, generate_crc_indications, &mp) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    free_memory_pool(&mp);

    return 0;
}
