// Thread-safe queue with blocking semantics
template <typename T>
class BlockingQueue {
public:
    void push(const T& value);
    T pop();
private:
    std::queue<T> queue_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

template <typename T>
void BlockingQueue<T>::push(const T& value) {
    std::lock_guard<std::mutex> lock(mutex_);
    queue_.push(value);
    cv_.notify_one();
}

template <typename T>
T BlockingQueue<T>::pop() {
    std::unique_lock<std::mutex> lock(mutex_);
    while (queue_.empty()) {
        cv_.wait(lock);
    }
    T value = queue_.front();
    queue_.pop();
    return value;
}

// Function to process streaming video feed
void process_streaming_video_feed(VideoAnalyticsAPI& api, MemoryPool& pool) {
    const int numThreads = 40;
    BlockingQueue<std::string> frameQueue;
    std::vector<std::thread> threads(numThreads);

    // Worker thread function
    auto workerThread = [&](int id) {
        while (true) {
            std::string frameData = frameQueue.pop();
            if (frameData.empty()) break; // Termination signal

            void* memory = pool.allocate(frameData.size());
            memcpy(memory, frameData.c_str(), frameData.size());

            if (!api.analyzeFrame(frameData)) {
                std::cerr << "Analysis failed for frame: " << frameData << std::endl;
                pool.deallocate(memory, frameData.size());
            } else {
                // Process the analyzed data
                std::cout << "Processed frame: " << frameData << std::endl;
                pool.deallocate(memory, frameData.size());
            }
        }
    };

    // Start worker threads
    for (int i = 0; i < numThreads; ++i) {
        threads[i] = std::thread(workerThread, i);
    }

    // Simulate streaming frames
    for (int i = 0; i < 1000; ++i) {
        frameQueue.push("Frame " + std::to_string(i));
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }

    // Signal worker threads to terminate
    for (auto& thread : threads) {
        frameQueue.push("");
    }

    // Join worker threads
    for (auto& thread : threads) {
        thread.join();
    }
}

int main() {
    VideoAnalyticsAPI api;
    MemoryPool pool;
    process_streaming_video_feed(api, pool);
    return 0;
}
