        unsigned char key[32], iv[16];
        RAND_bytes(key, sizeof(key));
        RAND_bytes(iv, sizeof(iv));

        // Initialize encryption context
        if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
            std::cerr << "Error initializing encryption context" << std::endl;
            return;
        }

        // Encrypt data
        int len;
        unsigned char ciphertext[plaintext.length()];
        if (EVP_EncryptUpdate(ctx, ciphertext, &len, reinterpret_cast<const unsigned char*>(plaintext.c_str()), plaintext.length()) != 1) {
            std::cerr << "Error encrypting data" << std::endl;
            return;
        }
        int ciphertext_len = len;

        // Finalize encryption
        if (EVP_EncryptFinal_ex(ctx, ciphertext + len, &len) != 1) {
            std::cerr << "Error finalizing encryption" << std::endl;
            return;
        }

        ciphertext_len += len;

        // Clean up
        EVP_CIPHER_CTX_free(ctx);

        // Store encrypted data
        encryptedData.push_back({ciphertext, ciphertext_len});
    }

    void decryptData(const std::vector<unsigned char>& ciphertext) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        unsigned char key[32], iv[16];
        RAND_bytes(key, sizeof(key));
        RAND_bytes(iv, sizeof(iv));

        // Initialize decryption context
        if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
            std::cerr << "Error initializing decryption context" << std::endl;
            return;
        }

        // Decrypt data
        int len;
        unsigned char plaintext[256];
        if (EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext.data(), ciphertext.size()) != 1) {
            std::cerr << "Error decrypting data" << std::endl;
            return;
        }
        int plaintext_len = len;

        // Finalize decryption
        if (EVP_DecryptFinal_ex(ctx, plaintext + len, &len) != 1) {
            std::cerr << "Error finalizing decryption" << std::endl;
            return;
        }

        plaintext_len += len;

        // Clean up
        EVP_CIPHER_CTX_free(ctx);

        // Process decrypted data
        std::cout << "Decrypted Data: " << std::string(plaintext, plaintext_len) << std::endl;
    }

