// encryption.c
#include "encryption.h"

EncryptionContext* create_encryption_context() {
    EncryptionContext *ctx = malloc(sizeof(EncryptionContext));
    ctx->ctx = EVP_CIPHER_CTX_new();
    return ctx;
}

void destroy_encryption_context(EncryptionContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}

int encrypt(const unsigned char *plaintext, int plaintext_len,
            const unsigned char *key, const unsigned char *iv,
            unsigned char *ciphertext) {
    int len;
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, key, iv)) return -1;
    if (!EVP_EncryptUpdate(ctx->ctx, ciphertext, &len, plaintext, plaintext_len)) return -1;
    int ciphertext_len = len;
    if (!EVP_EncryptFinal_ex(ctx->ctx, ciphertext + len, &len)) return -1;
    ciphertext_len += len;
    return ciphertext_len;
}

int decrypt(unsigned char *ciphertext, int ciphertext_len,
            const unsigned char *key, const unsigned char *iv,
            unsigned char *plaintext) {
    int len;
    if (!EVP_DecryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, key, iv)) return -1;
    if (!EVP_DecryptUpdate(ctx->ctx, plaintext, &len, ciphertext, ciphertext_len)) return -1;
    int plaintext_len = len;
    if (!EVP_DecryptFinal_ex(ctx->ctx, plaintext + len, &len)) return -1;
    plaintext_len += len;
    return plaintext_len;
}
