                           const unsigned char *key, const unsigned char *iv,
                           unsigned char *encrypted_token) {
    EncryptionContext *ctx = create_encryption_context();
    int ciphertext_len = encrypt(token, token_len, key, iv, encrypted_token);
    if (ciphertext_len < 0) {
        fprintf(stderr, "Encryption failed\n");
    }
    destroy_encryption_context(ctx);
}

void decrypt_oauth2_token(unsigned char *encrypted_token, int encrypted_token_len,
                           const unsigned char *key, const unsigned char *iv,
                           unsigned char *decrypted_token) {
    EncryptionContext *ctx = create_encryption_context();
    int plaintext_len = decrypt(encrypted_token, encrypted_token_len, key, iv, decrypted_token);
    if (plaintext_len < 0) {
        fprintf(stderr, "Decryption failed\n");
    }
    destroy_encryption_context(ctx);
}
