// Define robust retry mechanism with exponential backoff and jitter
template <typename Func>
void retry_with_backoff(Func func, int max_retries = 5) {
    for (int i = 0; i <= max_retries; ++i) {
        try {
            func();
            break;
        } catch (...) {
            if (i == max_retries) throw;
            std::this_thread::sleep_for(std::chrono::milliseconds(1 << i));
        }
    }
}

