// Define a union for various data types
union ContextData {
    int intValue;
    double doubleValue;
    std::string stringValue;

    // Constructors and destructors
    ContextData(int i) : intValue(i) {}
    ContextData(double d) : doubleValue(d) {}
    ContextData(const std::string& s) : stringValue(s) {}
    ~ContextData() {}

    bool operator==(const int& otherInt) const { return intValue == otherInt; }
    bool operator==(const double& otherDouble) const { return doubleValue == otherDouble; }
    bool operator==(const std::string& otherString) const { return stringValue == otherString; }
};

// Define a network event
struct NetworkEvent {
    int timestamp;
    int eventCode;
    ContextData contextData;

    NetworkEvent(int ts, int ec, const ContextData& cd) : timestamp(ts), eventCode(ec), contextData(cd) {}
};

// Define an interface for logging services
class LoggingService {
public:
    virtual void log(const NetworkEvent& event) = 0;
    virtual ~LoggingService() {}
};

// Implement a real-time analytics service
class RealTimeAnalyticsService : public LoggingService {
public:
    void log(const NetworkEvent& event) override {
        // Code to process real-time analytics
        std::cout << "Real-time Analytics Service: Processed event" << std::endl;
    }
};

// Implement a cloud storage provider service
class CloudStorageService : public LoggingService {
public:
    void log(const NetworkEvent& event) override {
        // Code to store data in the cloud
        std::cout << "Cloud Storage Service: Stored event" << std::endl;
    }
};

// Implement a third-party monitoring tool service
class MonitoringToolService : public LoggingService {
public:
    void log(const NetworkEvent& event) override {
        // Code to monitor and alert based on events
        std::cout << "Monitoring Tool Service: Monitored event" << std::endl;
    }
};

// Define the logging framework
class LoggingFramework {
private:
    std::vector<std::shared_ptr<LoggingService>> services;
    std::queue<NetworkEvent> eventQueue;
    std::atomic<bool> running;

public:
    LoggingFramework() : running(false) {}

    void addService(std::shared_ptr<LoggingService> service) {
        services.push_back(service);
    }

    void start() {
        running.store(true);
        std::thread([this]() {
            while (running.load()) {
                if (!eventQueue.empty()) {
                    NetworkEvent event = eventQueue.front();
                    eventQueue.pop();
                    for (const auto& service : services) {
                        service->log(event);
                    }
                }
            }
        }).detach();
    }

    void stop() {
        running.store(false);
    }

    void log(const NetworkEvent& event) {
        if (running.load()) {
            eventQueue.push(event);
        }
    }
};

int main() {
    // Create logging framework
    LoggingFramework framework;

    // Add services to the framework
    framework.addService(std::make_shared<RealTimeAnalyticsService>());
    framework.addService(std::make_shared<CloudStorageService>());
    framework.addService(std::make_shared<MonitoringToolService>());

    // Start the framework
    framework.start();

    // Log some events
    framework.log(NetworkEvent(1633072800, 1, ContextData(42)));
    framework.log(NetworkEvent(1633072801, 2, ContextData(3.14)));

    // Stop the framework
    framework.stop();

    return 0;
}
