#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    uint64_t timestamp;
    int event_code;
    union {
        int integer_data;
        float float_data;
        char* string_data;
    } context_data;
} NetworkEvent;

NetworkEvent* generateNetworkEvents(int num_events) {
    NetworkEvent* events = (NetworkEvent*)malloc(num_events * sizeof(NetworkEvent));
    if (!events) return NULL;

    srand(time(NULL));

    for (int i = 0; i < num_events; ++i) {
        events[i].timestamp = time(NULL);
        events[i].event_code = rand() % 100;

        int random_type = rand() % 3;
        switch (random_type) {
            case 0:
                events[i].context_data.integer_data = rand();
                break;
            case 1:
                events[i].context_data.float_data = (float)rand() / RAND_MAX * 100.0f;
                break;
            case 2:
                events[i].context_data.string_data = "Example";
                break;
        }
    }

    return events;
}

void freeNetworkEvents(NetworkEvent* events, int num_events) {
    for (int i = 0; i < num_events; ++i) {
        if (events[i].context_data.string_data) {
            free(events[i].context_data.string_data);
        }
    }
    free(events);
}

int main() {
    int num_events = 10;
    NetworkEvent* events = generateNetworkEvents(num_events);

    if (events) {
        for (int i = 0; i < num_events; ++i) {
            printf("Event %d: Timestamp=%lu, Event Code=%d, Context Data=", i, events[i].timestamp, events[i].event_code);
            switch (rand() % 3) {
                case 0:
                    printf("%d\n", events[i].context_data.integer_data);
                    break;
                case 1:
                    printf("%.2f\n", events[i].context_data.float_data);
                    break;
                case 2:
                    printf("%s\n", events[i].context_data.string_data);
                    break;
            }
        }
        freeNetworkEvents(events, num_events);
    } else {
        printf("Failed to allocate memory for network events.\n");
    }

    return 0;
}
