    }

    public class MemoryDataCache : IDataCache
    {
        private readonly ConcurrentDictionary<string, CacheItem> _cache = new ConcurrentDictionary<string, CacheItem>();

        public bool TryGetValue(string key, out List<string> value)
        {
            if (_cache.TryGetValue(key, out var cacheItem))
            {
                value = cacheItem.Value;
                return true;
            }

            value = null;
            return false;
        }

        public void Set(string key, List<string> value, TimeSpan expirationTime)
        {
            _cache.TryAdd(key, new CacheItem(value, DateTime.UtcNow + expirationTime));
        }
    }

    public class CacheItem
    {
        public List<string> Value { get; set; }
        public DateTime ExpirationTime { get; set; }

        public CacheItem(List<string> value, DateTime expirationTime)
        {
            Value = value;
            ExpirationTime = expirationTime;
        }
    }
