typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_PDUS];
    int count;
    pthread_mutex_t lock;
} LogFramework;

LogFramework logFramework;

void init_log_framework() {
    memset(&logFramework, 0, sizeof(logFramework));
    pthread_mutex_init(&logFramework.lock, NULL);
}

void add_network_event(NetworkEvent event) {
    pthread_mutex_lock(&logFramework.lock);
    if (logFramework.count < MAX_PDUS) {
        logFramework.pdus[logFramework.count++] = event;
    }
    pthread_mutex_unlock(&logFramework.lock);
}

void* process_events(void* arg) {
    while (1) {
        for (int i = 0; i < logFramework.count; i++) {
            NetworkEvent event = logFramework.pdus[i];
            // Process the event
            printf("Processing PDU: Timestamp=%ld, EventCode=%d\n", event.timestamp, event.event_code);
        }
        logFramework.count = 0;
    }
    return NULL;
}

int main() {
    init_log_framework();

    pthread_t processor_thread;
    pthread_create(&processor_thread, NULL, process_events, NULL);

    NetworkEvent new_event;
    time_t current_time;

    while (1) {
        time(&current_time);
        new_event.timestamp = current_time;
        new_event.event_code = rand() % 100; // Random event code
        strcpy(new_event.context_data.data, "Example Context");

        add_network_event(new_event);

        sleep(1); // Simulate network traffic
    }

    pthread_join(processor_thread, NULL);
    return 0;
}
