class FinancialDataProcessor {
public:
    FinancialDataProcessor(size_t numThreads) : stop(false), threads(numThreads, &FinancialDataProcessor::worker, this) {}

    ~FinancialDataProcessor() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        cv.notify_all();
        for (auto& t : threads) {
            t.join();
        }
    }

    void process(const std::string& data) {
        std::lock_guard<std::mutex> lock(mutex);
        queue.push(data);
        cv.notify_one();
    }

private:
    void worker() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return stop || !queue.empty(); });
            if (stop && queue.empty()) {
                return;
            }
            auto data = queue.front();
            queue.pop();
            lock.unlock();

            // Process the financial data
            processFinancialData(data);
        }
    }

    void processFinancialData(const std::string& data) {
        // Implement data processing logic here
        std::cout << "Processing data: " << data << std::endl;
    }

    std::mutex mutex;
    std::condition_variable cv;
    std::vector<std::thread> threads;
    bool stop;
    std::queue<std::string> queue;
};

int main() {
    FinancialDataProcessor processor(4);

    // Simulate data ingestion
    for (size_t i = 0; i < 10; ++i) {
        processor.process("Data" + std::to_string(i));
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }

    return 0;
}
