#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define BUFFER_SIZE 1024

typedef enum {
    ECB,
    EDE,
    EDE3,
    CFB
} EncryptionMode;

void encrypt_data(const unsigned char *key, const unsigned char *iv, 
                   EncryptionMode mode, const unsigned char *data, 
                   int data_len, unsigned char *output) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return;
    }

    EVP_EncryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, key, iv);
    int len;
    EVP_EncryptUpdate(ctx, output, &len, data, data_len);
    int total = len;

    EVP_EncryptFinal_ex(ctx, output + len, &len);
    total += len;

    EVP_CIPHER_CTX_free(ctx);

    memcpy(output, &total, sizeof(total));
}

void decrypt_data(const unsigned char *key, const unsigned char *iv, 
                   EncryptionMode mode, const unsigned char *data, 
                   int data_len, unsigned char *output) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return;
    }

    EVP_DecryptInit_ex(ctx, EVP_des_ede3_cbc(), NULL, key, iv);
    int len;
    EVP_DecryptUpdate(ctx, output, &len, data + sizeof(int), data_len - sizeof(int));
    int total = len;

    EVP_DecryptFinal_ex(ctx, output + len, &len);
    total += len;

    EVP_CIPHER_CTX_free(ctx);

    memcpy(output, &total, sizeof(total));
}

int main() {
    unsigned char key[24];
    unsigned char iv[EVP_MAX_IV_LENGTH];
    unsigned char data[BUFFER_SIZE] = "Hello, World!";
    unsigned char encrypted_data[BUFFER_SIZE];
    unsigned char decrypted_data[BUFFER_SIZE];

    // Generate random key and IV
    if (!RAND_bytes(key, sizeof(key)) || !RAND_bytes(iv, EVP_CIPHER_iv_length(EVP_des_ede3_cbc()))) {
        fprintf(stderr, "Failed to generate random bytes\n");
        return 1;
    }

    EncryptionMode mode = EDE3;

    encrypt_data(key, iv, mode, data, strlen(data), encrypted_data);
    decrypt_data(key, iv, mode, encrypted_data, sizeof(encrypted_data), decrypted_data);

    printf("Original: %s\n", data);
    printf("Decrypted: %s\n", decrypted_data);

    return 0;
}
```

