// Define a simple custom allocator for demonstration purposes
template<typename T>
class CustomAllocator {
public:
    using value_type = T;

    CustomAllocator() noexcept {}
    template<typename U> CustomAllocator(const CustomAllocator<U>&) noexcept {}

    T* allocate(std::size_t n) {
        return static_cast<T*>(::operator new(n * sizeof(T)));
    }

    void deallocate(T* p, std::size_t n) {
        ::operator delete(p);
    }
};

// Define a simple network event structure
struct NetworkEvent {
    std::chrono::system_clock::time_point timestamp;
    int eventCode;
    union ContextData {
        int intValue;
        double doubleValue;
        std::string stringValue;

        ContextData() {}
        ~ContextData() {}

        bool operator==(const ContextData& other) const {
            return (intValue == other.intValue || doubleValue == other.doubleValue || stringValue == other.stringValue);
        }
    } context;

    NetworkEvent(int eventCode, int intValue)
        : timestamp(std::chrono::system_clock::now()), eventCode(eventCode), context{.intValue = intValue} {}

    NetworkEvent(int eventCode, double doubleValue)
        : timestamp(std::chrono::system_clock::now()), eventCode(eventCode), context{.doubleValue = doubleValue} {}

    NetworkEvent(int eventCode, const std::string& stringValue)
        : timestamp(std::chrono::system_clock::now()), eventCode(eventCode), context{.stringValue = stringValue} {}
};

// Define a simple logging framework
class LoggingFramework {
public:
    static LoggingFramework& getInstance() {
        static LoggingFramework instance;
        return instance;
    }

    void log(const NetworkEvent& event) {
        std::lock_guard<std::mutex> lock(mutex_);
        events_.push_back(event);
    }

    void startProcessing() {
        processingThread_ = std::thread([this]() {
            while (true) {
                if (!events_.empty()) {
                    auto event = events_.front();
                    events_.pop_front();
                    processEvent(event);
                } else {
                    std::unique_lock<std::mutex> lock(mutex_);
                    condition_.wait(lock, [this] { return !events_.empty(); });
                }
            }
        });
    }

    void stopProcessing() {
        processingThread_.join();
    }

private:
    LoggingFramework() {}
    ~LoggingFramework() {}

    LoggingFramework(const LoggingFramework&) = delete;
    LoggingFramework& operator=(const LoggingFramework&) = delete;

    std::mutex mutex_;
    std::condition_variable condition_;
    std::deque<NetworkEvent> events_;
    std::thread processingThread_;

    void processEvent(const NetworkEvent& event) {
        // Simulate processing logic
        std::cout << "Processing event: " << event.eventCode << ", Timestamp: " << event.timestamp.time_since_epoch().count() << std::endl;
    }
};

int main() {
    LoggingFramework& logger = LoggingFramework::getInstance();
    logger.startProcessing();

    NetworkEvent event1(1, 42);
    NetworkEvent event2(2, 3.14);
    NetworkEvent event3(3, "Hello");

    logger.log(event1);
    logger.log(event2);
    logger.log(event3);

    std::this_thread::sleep_for(std::chrono::seconds(5));
    logger.stopProcessing();

    return 0;
}
```

