typedef struct Node {
    NetworkEvent event;
    struct Node* next;
} EventNode;

typedef struct {
    EventNode* head;
    EventNode* tail;
} EventQueue;

void initialize_queue(EventQueue* queue) {
    queue->head = NULL;
    queue->tail = NULL;
}

void enqueue_event(EventQueue* queue, NetworkEvent event) {
    EventNode* new_node = (EventNode*)malloc(sizeof(EventNode));
    if (new_node == NULL) {
        // Handle memory allocation failure
        return;
    }
    new_node->event = event;
    new_node->next = NULL;

    if (queue->tail != NULL) {
        queue->tail->next = new_node;
    } else {
        queue->head = new_node;
    }
    queue->tail = new_node;
}

NetworkEvent dequeue_event(EventQueue* queue) {
    if (queue->head == NULL) {
        // Handle empty queue
        NetworkEvent empty_event = {0};
        return empty_event;
    }

    EventNode* temp = queue->head;
    NetworkEvent event = temp->event;

    queue->head = queue->head->next;
    if (queue->head == NULL) {
        queue->tail = NULL;
    }
    free(temp);

    return event;
}

void process_events(EventQueue* queue, void (*process_func)(NetworkEvent)) {
    while (!is_queue_empty(queue)) {
        NetworkEvent event = dequeue_event(queue);
        process_func(event);
    }
