#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_THREADS 100
#define RETRY_INTERVAL 500
#define MAX_RETRIES 3

typedef struct {
    time_t timestamp;
    int event_code;
    union {
        char text[256];
        int number;
        double floating_point;
    } context;
} LogEvent;

typedef struct {
    LogEvent *events;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} LogBuffer;

void log_event(LogBuffer *buffer, LogEvent event) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count == buffer->capacity) {
        // Resize the buffer
        buffer->capacity *= 2;
        buffer->events = realloc(buffer->events, buffer->capacity * sizeof(LogEvent));
    }
    buffer->events[buffer->count++] = event;
    pthread_mutex_unlock(&buffer->mutex);
}

void* log_thread(void *arg) {
    LogBuffer *buffer = (LogBuffer*)arg;
    // Simulate logging events
    for (int i = 0; i < 10; ++i) {
        LogEvent event;
        event.timestamp = time(NULL);
        event.event_code = rand() % 100;
        strcpy(event.context.text, "Sample log message");
        log_event(buffer, event);
        usleep(10000); // Simulate some delay
    }
    return NULL;
}

int main() {
    LogBuffer buffer;
    pthread_t threads[MAX_THREADS];
    buffer.events = malloc(sizeof(LogEvent) * 100);
    buffer.count = 0;
    buffer.capacity = 100;
    pthread_mutex_init(&buffer.mutex, NULL);

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_create(&threads[i], NULL, log_thread, &buffer);
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Process and transmit logs
    for (size_t i = 0; i < buffer.count; ++i) {
        LogEvent event = buffer.events[i];
        printf("Timestamp: %s, Event Code: %d, Context: %s\n", ctime(&event.timestamp), event.event_code, event.context.text);
    }

    free(buffer.events);
    pthread_mutex_destroy(&buffer.mutex);

    return 0;
}
