#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    EVENT_TYPE_ERROR,
    EVENT_TYPE_WARNING,
    EVENT_TYPE_INFO
} EventType;

typedef union {
    int intValue;
    float floatValue;
    char stringValue[256];
} ContextData;

typedef struct Event {
    long timestamp;
    EventType type;
    ContextData data;
} Event;

typedef struct LogEntry {
    Event event;
    struct LogEntry *next;
} LogEntry;

LogEntry *logHead = NULL;
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

void logEvent(Event *event) {
    pthread_mutex_lock(&logMutex);
    LogEntry *newEntry = (LogEntry *)malloc(sizeof(LogEntry));
    newEntry->event = *event;
    newEntry->next = logHead;
    logHead = newEntry;
    pthread_mutex_unlock(&logMutex);
}

void printLogs() {
    pthread_mutex_lock(&logMutex);
    LogEntry *entry = logHead;
    while (entry != NULL) {
        printf("Timestamp: %ld, Type: %d, Data: %s\n", entry->event.timestamp, entry->event.type, entry->event.data.stringValue);
        entry = entry->next;
    }
    pthread_mutex_unlock(&logMutex);
}

void *workerThread(void *arg) {
    // Simulate event processing
    Event newEvent;
    newEvent.timestamp = time(NULL);
    newEvent.type = EVENT_TYPE_INFO;
    snprintf(newEvent.data.stringValue, sizeof(newEvent.data.stringValue), "Processing events");
    logEvent(&newEvent);
    return NULL;
}

int main() {
    pthread_t threads[10];

    // Create multiple worker threads
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, workerThread, NULL);
    }

    // Wait for all threads to complete
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    printLogs();

    return 0;
}
```

