import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class LogProcessingApplication {

    private ExecutorService executorService = Executors.newFixedThreadPool(100);
    private LogStorage storage = new DistributedNoSqlStorage();
    private LogProcessor processor = new MultiFormatLogProcessor();

    public void start() {
        KafkaConsumer<String, String> consumer = new KafkaConsumer<>("log-topic");
        consumer.subscribe(new ArrayList<>(Arrays.asList("web-server", "app-server", "cloud-logs")));

        while (true) {
            ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
            for (ConsumerRecord<String, String> record : records) {
                LogEntry logEntry = processor.process(record.value());
                executorService.submit(() -> storage.save(logEntry));
            }
        }
    }

