// Define a structure for network events
typedef struct NetworkEvent {
    char timestamp[20];
    int event_code;
    union {
        int int_data;
        double double_data;
        char str_data[100];
    } context;
} NetworkEvent;

// Function to serialize a NetworkEvent to a binary format
void serialize_event(NetworkEvent* event, unsigned char* buffer, size_t* buffer_size) {
    // Serialize timestamp
    strcpy((char*)buffer, event->timestamp);
    buffer += 20;
    *buffer_size -= 20;

    // Serialize event_code
    memcpy(buffer, &event->event_code, sizeof(int));
    buffer += sizeof(int);
    *buffer_size -= sizeof(int);

    // Serialize context data based on type
    switch (event->event_code) {
        case INT_EVENT:
            memcpy(buffer, &event->context.int_data, sizeof(int));
            buffer += sizeof(int);
            *buffer_size -= sizeof(int);
            break;
        case DOUBLE_EVENT:
            memcpy(buffer, &event->context.double_data, sizeof(double));
            buffer += sizeof(double);
            *buffer_size -= sizeof(double);
            break;
        case STR_EVENT:
            strcpy((char*)buffer, event->context.str_data);
            buffer += strlen(event->context.str_data) + 1;
            *buffer_size -= strlen(event->context.str_data) + 1;
            break;
    }
}

// Function to deserialize a binary buffer back into a NetworkEvent
void deserialize_event(unsigned char* buffer, NetworkEvent* event) {
    // Deserialize timestamp
    strcpy(event->timestamp, (char*)buffer);
    buffer += 20;

    // Deserialize event_code
    memcpy(&event->event_code, buffer, sizeof(int));
    buffer += sizeof(int);

    // Deserialize context data based on type
    switch (event->event_code) {
        case INT_EVENT:
            memcpy(&event->context.int_data, buffer, sizeof(int));
            buffer += sizeof(int);
            break;
        case DOUBLE_EVENT:
            memcpy(&event->context.double_data, buffer, sizeof(double));
            buffer += sizeof(double);
            break;
        case STR_EVENT:
            strcpy(event->context.str_data, (char*)buffer);
            buffer += strlen((char*)buffer) + 1;
            break;
    }
}

// Define a thread-safe logging function
void log_event(NetworkEvent* event, MemoryAllocator* allocator) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    // Serialize and store the event using the custom allocator
    unsigned char* buffer = (unsigned char*)custom_malloc(allocator, 256);
    size_t buffer_size = 256;
    serialize_event(event, buffer, &buffer_size);

    // Transmit the serialized event to a remote server or persistent storage
    // ...

    custom_free(allocator, buffer);

    pthread_mutex_unlock(&lock);
}

// Main function to demonstrate usage
int main() {
    MemoryAllocator* allocator = init_memory_allocator();

    NetworkEvent event;
    strcpy(event.timestamp, "2023-10-05 14:30:00");
    event.event_code = INT_EVENT;
    event.context.int_data = 123;

    log_event(&event, allocator);

    free(allocator);
    return 0;
}
