    int event_code;
    union {
        int i_val;
        float f_val;
        char* s_val;
    } context_data;
} NetworkEvent;

typedef enum {
    EVENT_TYPE_INT,
    EVENT_TYPE_FLOAT,
    EVENT_TYPE_STRING
} ContextType;

NetworkEvent log_queue[1024];
int front = 0, rear = 0;
sem_t queue_sem;
pthread_mutex_t queue_lock;

void enqueue_event(NetworkEvent event) {
    pthread_mutex_lock(&queue_lock);
    sem_wait(&queue_sem);
    if (rear == sizeof(log_queue) / sizeof(log_queue[0])) {
        printf("Log buffer overflow!\n");
        pthread_mutex_unlock(&queue_lock);
        return;
    }
    log_queue[rear++] = event;
    sem_post(&queue_sem);
    pthread_mutex_unlock(&queue_lock);
}

NetworkEvent dequeue_event() {
    NetworkEvent event = {0};
    pthread_mutex_lock(&queue_lock);
    sem_wait(&queue_sem);
    if (front == rear) {
        printf("No events in log buffer!\n");
        pthread_mutex_unlock(&queue_lock);
        return event;
    }
    event = log_queue[front++];
    sem_post(&queue_sem);
    pthread_mutex_unlock(&queue_lock);
    return event;
}

void* process_events(void* arg) {
    while (1) {
        NetworkEvent event = dequeue_event();
        if (!event.timestamp) break; // Exit condition
        // Process the event by sending it to the external service
        printf("Processing event with timestamp: %ld, code: %d\n", event.timestamp, event.event_code);
        // Example processing: simulate network delay
        usleep(10000); // 10ms delay
    }
    return NULL;
}

int main() {
    sem_init(&queue_sem, 0, sizeof(log_queue) / sizeof(log_queue[0]));
    pthread_mutex_init(&queue_lock, NULL);
    pthread_t thread_ids[4];

    for (int i = 0; i < 4; i++) {
        pthread_create(&thread_ids[i], NULL, process_events, NULL);
    }

    // Simulate logging events
    NetworkEvent event;
    while (1) {
        event.timestamp = time(NULL);
        event.event_code = rand() % 100;
        switch (rand() % 3) {
            case EVENT_TYPE_INT:
                event.context_data.i_val = rand();
                break;
            case EVENT_TYPE_FLOAT:
                event.context_data.f_val = (float)rand() / RAND_MAX * 100.0f;
                break;
            case EVENT_TYPE_STRING:
                snprintf(event.context_data.s_val, sizeof(event.context_data.s_val), "String %d", rand());
                break;
        }
        enqueue_event(event);
        usleep(5000); // Simulate event generation
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(thread_ids[i], NULL);
    }

    sem_destroy(&queue_sem);
    pthread_mutex_destroy(&queue_lock);

    return 0;
}
