// Define the event structure with a flexible union for context data
union EventContext {
    int intValue;
    double doubleValue;
    std::string stringValue;

    EventContext() {}
    ~EventContext() {}

    bool operator==(const EventContext& other) const {
        if (this->intValue == other.intValue && this->doubleValue == other.doubleValue && this->stringValue == other.stringValue) {
            return true;
        }
        return false;
    }
};

struct NetworkEvent {
    std::chrono::system_clock::time_point timestamp;
    int eventCode;
    EventContext context;

    bool operator==(const NetworkEvent& other) const {
        if (this->timestamp == other.timestamp && this->eventCode == other.eventCode && this->context == other.context) {
            return true;
        }
        return false;
    }
};

// Define the logging framework
class LoggingFramework {
public:
    LoggingFramework(int maxEventsPerSecond, int maxRetries)
        : maxEventsPerSecond(maxEventsPerSecond), maxRetries(maxRetries), eventsProcessed(0), backoffInterval(std::chrono::milliseconds(1)) {}

    void logEvent(const NetworkEvent& event) {
        std::lock_guard<std::mutex> lock(mutex);
        if (eventQueue.size() >= maxEventsPerSecond) {
            // Implement backoff strategy
            std::this_thread::sleep_for(backoffInterval);
            backoffInterval *= 2;
        }
        eventQueue.push(event);
    }

private:
    int maxEventsPerSecond;
    int maxRetries;
    std::queue<NetworkEvent> eventQueue;
    std::mutex mutex;
    std::condition_variable cv;
    std::atomic<int> eventsProcessed;
    std::chrono::milliseconds backoffInterval;
};

// Example usage
int main() {
    LoggingFramework loggingFramework(10, 5);

    NetworkEvent event1 = {std::chrono::system_clock::now(), 1, EventContext{.intValue = 42}};
    NetworkEvent event2 = {std::chrono::system_clock::now(), 2, EventContext{.doubleValue = 3.14}};
    NetworkEvent event3 = {std::chrono::system_clock::now(), 3, EventContext{.stringValue = "Hello"}};

    loggingFramework.logEvent(event1);
    loggingFramework.logEvent(event2);
    loggingFramework.logEvent(event3);

    return 0;
}
