#include <iostream>
#include <vector>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pem.h>

struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
};

std::vector<NFAPI_CRC_INDICATION_PDU_T> createNFAPIList(int n) {
    std::vector<NFAPI_CRC_INDICATION_PDU_T> list(n);
    for (int i = 0; i < n; ++i) {
        list[i].RX_UE_INFORMATION_TAG = i;
        list[i].RNTI = rand() % 65536; // Random RNTI
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG
    }
    return list;
}

void generateEncryptionKeyAndIV(const std::string& passphrase, unsigned char* key, unsigned char* iv) {
    const unsigned int keyLength = EVP_CIPHER_key_length(EVP_aes_256_cbc());
    const unsigned int ivLength = EVP_CIPHER_iv_length(EVP_aes_256_cbc());

    if (!RAND_bytes(iv, ivLength)) {
        std::cerr << "Error generating IV" << std::endl;
        return;
    }

    EVP_PKEY* pkey = EVP_PKEY_new();
    EVP_PKEY_assign_private_key(pkey, EVP_PKEY_CTX_new_id(EVP_PKEY_EC, NULL));

    if (!EVP_EncryptInit_ex(nullptr, EVP_aes_256_cbc(), nullptr, passphrase.c_str(), iv)) {
        std::cerr << "Error initializing encryption" << std::endl;
        return;
    }

    // Generate key using PBKDF2
    int derivedKeyLength = keyLength;
    if (!PKCS5_PBKDF2_HMAC(passphrase.c_str(), passphrase.length(), NULL, 0, 10000, EVP_sha256(), derivedKeyLength, key)) {
        std::cerr << "Error generating key" << std::endl;
        return;
    }
}
