use std::process::{Command, Stdio};
use tokio::task;
use docker_api::{DockerClient, BuildOptions};

async fn run_build_with_docker(client: DockerClient, build_options: BuildOptions) -> Result<(), String> {
    let mut process = client.run_build(&build_options).await.map_err(|e| e.to_string())?;

    let status = process.wait().await.map_err(|e| format!("Failed to wait for docker build: {}", e))?;
    if !status.success() {
        return Err(format!("Build failed with exit code: {}", status.code().unwrap_or(1)));
    }

    Ok(())
}

fn dns_resolution(hostname: &str) -> Result<[u8; 4], String> {
    let output = Command::new("nslookup")
        .arg(hostname)
        .output()
        .map_err(|e| format!("Failed to execute nslookup: {}", e))?;

    if !output.status.success() {
        return Err(format!("DNS resolution failed with status code: {}", output.status.code().unwrap_or(1)));
    }

    let ip_str = String::from_utf8_lossy(&output.stdout);
    let ip_address = ip_str.split_whitespace()
        .find(|&s| s.parse::<std::net::IpAddr>().is_some())
        .and_then(|ip| ip.parse::<std::net::Ipv4Addr>().ok());

    match ip_address {
        Some(ip) => Ok(ip.octets()),
        None => Err(String::from("Invalid IP address")),
    }
}

async fn build_system_with_docker() -> Result<(), String> {
    let client = DockerClient::new();

    for platform in ["linux/x86_64", "linux/arm64"].iter() {
        let build_options = BuildOptions {
            context: PathBuf::from("."),
            file: PathBuf::from("Dockerfile"),
            tags: vec![format!("my-image:{}-{}", "latest", platform)],
            platform,
            ..Default::default()
        };

        task::spawn(run_build_with_docker(client.clone(), build_options))
            .await
            .map_err(|e| e.to_string())?;
    }

    Ok(())
}
```

