#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

typedef enum { LOG_INFO, LOG_ERROR, LOG_DEBUG } LogLevel;

typedef union {
    int intValue;
    double floatValue;
    char* stringValue;
} ContextData;

typedef struct LogEntry {
    time_t timestamp;
    LogLevel level;
    ContextData context;
} LogEntry;

typedef struct LogQueue {
    LogEntry** entries;
    size_t front, rear, capacity;
    pthread_mutex_t mutex;
    pthread_cond_t not_empty, not_full;
} LogQueue;

LogQueue* create_log_queue(size_t capacity) {
    LogQueue* queue = malloc(sizeof(LogQueue));
    if (!queue) return NULL;

    queue->entries = malloc(capacity * sizeof(LogEntry*));
    if (!queue->entries) {
        free(queue);
        return NULL;
    }

    queue->front = queue->rear = 0;
    queue->capacity = capacity;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    pthread_cond_init(&queue->not_full, NULL);

    return queue;
}

void enqueue(LogQueue* queue, LogEntry entry) {
    pthread_mutex_lock(&queue->mutex);
    while ((queue->rear + 1) % queue->capacity == queue->front)
        pthread_cond_wait(&queue->not_full, &queue->mutex);

    queue->entries[queue->rear] = malloc(sizeof(LogEntry));
    if (queue->entries[queue->rear]) {
        memcpy(queue->entries[queue->rear], &entry, sizeof(LogEntry));
        queue->rear = (queue->rear + 1) % queue->capacity;
        pthread_cond_signal(&queue->not_empty);
    }

    pthread_mutex_unlock(&queue->mutex);
}

LogEntry dequeue(LogQueue* queue) {
    LogEntry entry = {0};
    pthread_mutex_lock(&queue->mutex);
    while (queue->front == queue->rear)
        pthread_cond_wait(&queue->not_empty, &queue->mutex);

    memcpy(&entry, queue->entries[queue->front], sizeof(LogEntry));
    free(queue->entries[queue->front]);
    queue->entries[queue->front] = NULL;
    queue->front = (queue->front + 1) % queue->capacity;
    pthread_cond_signal(&queue->not_full);

    pthread_mutex_unlock(&queue->mutex);
    return entry;
}

void destroy_log_queue(LogQueue* queue) {
    for (size_t i = queue->front; i != queue->rear; ) {
        free(queue->entries[i]);
        queue->entries[i] = NULL;
        i = (i + 1) % queue->capacity;
    }
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->not_empty);
    pthread_cond_destroy(&queue->not_full);
    free(queue->entries);
    free(queue);
}

void* log_thread(void* arg) {
    LogQueue* queue = (LogQueue*)arg;

    while (1) {
        LogEntry entry = dequeue(queue);
        // Process the log entry
        printf("Log entry: %s\n", ctime(&entry.timestamp));
        free(entry.context.stringValue); // Free dynamically allocated string data
    }

    return NULL;
}

int main() {
    size_t queue_capacity = 1000;
    LogQueue* log_queue = create_log_queue(queue_capacity);
    if (!log_queue) {
        fprintf(stderr, "Failed to create log queue\n");
        return EXIT_FAILURE;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, log_thread, log_queue)) {
        fprintf(stderr, "Failed to create log processing thread\n");
        destroy_log_queue(log_queue);
        return EXIT_FAILURE;
    }

    // Example usage: Enqueue a log entry
    LogEntry new_entry = {time(NULL), LOG_INFO, {.stringValue=strdup("Sample log message")}};
    enqueue(log_queue, new_entry);

    pthread_join(thread_id, NULL);
    destroy_log_queue(log_queue);

    return EXIT_SUCCESS;
}
```

This code provides a basic implementation of a logging framework in C. It includes a queue for log entries, a thread to process these entries, and basic synchronization mechanisms. This setup can be expanded and customized further to meet specific requirements such as external event-processing integration, error handling, serialization, and more.']

