#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

// Define event structure
typedef struct {
    char timestamp[20];
    int code;
    union {
        int intValue;
        float floatValue;
        char stringValue[100];
    } context;
} Event;

// Define file metadata structure
typedef struct {
    char filename[100];
    long size;
    char tiffMetadata[500]; // Placeholder for TIFF metadata
} FileMetadata;

// Function to generate filenames dynamically based on metadata
void generateFilename(FileMetadata *metadata) {
    sprintf(metadata->filename, "file_%ld_tiff_%s", metadata->size, metadata->tiffMetadata);
}

// Thread-safe logging function
void logEvent(Event event, pthread_mutex_t *logMutex) {
    pthread_mutex_lock(logMutex);
    printf("Timestamp: %s, Code: %d, Context: %f\n", event.timestamp, event.code, event.context.floatValue);
    pthread_mutex_unlock(logMutex);
}

// Function to simulate file upload and logging
void* handleFileUpload(void *arg) {
    FileMetadata metadata;
    Event event;

    // Simulate file upload process
    sleep(1); // Simulate time delay for file upload

    // Generate filename based on metadata
    generateFilename(&metadata);

    // Populate event data
    strcpy(event.timestamp, "2023-04-10 12:34:56");
    event.code = 1;
    event.context.floatValue = 123.45;

    // Log the event
    logEvent(event, (pthread_mutex_t *)arg);

    return NULL;
}

int main() {
    pthread_t threads[10];
    pthread_mutex_t logMutex;

    // Initialize mutex for thread-safe logging
    pthread_mutex_init(&logMutex, NULL);

    // Create multiple threads to simulate concurrent file uploads
    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, handleFileUpload, &logMutex) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Destroy mutex
    pthread_mutex_destroy(&logMutex);

    return 0;
}
```

