#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>

#define MAX_LOG_SIZE 1024 * 1024 // 1MB per log entry
#define MAX_THREAD_POOL_SIZE 16
#define COMPRESSION_THRESHOLD 1024 * 1024 * 10 // 10MB

typedef enum {
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

typedef union {
    int intValue;
    float floatValue;
    char stringValue[256];
} ContextData;

typedef struct LogEntry {
    time_t timestamp;
    LogLevel level;
    ContextData context;
} LogEntry;

typedef struct Logger {
    sem_t log_queue_lock;
    LogEntry *log_queue[MAX_LOG_SIZE];
    size_t head, tail, count;
    pthread_t thread_pool[MAX_THREAD_POOL_SIZE];
    int running;
    int (*serialize)(LogEntry *, char **);
    void (*deserialize)(char *, LogEntry *);
    void (*compress)(char **);
    void (*transmit)(char *);
} Logger;

void log_entry_init(LogEntry *entry, LogLevel level, ContextData context) {
    entry->timestamp = time(NULL);
    entry->level = level;
    entry->context = context;
}

int logger_init(Logger *logger, int (*serialize_func)(LogEntry *, char **), void (*deserialize_func)(char *, LogEntry *),
               void (*compress_func)(char **), void (*transmit_func)(char *)) {
    sem_init(&logger->log_queue_lock, 0, 1);
    logger->serialize = serialize_func;
    logger->deserialize = deserialize_func;
    logger->compress = compress_func;
    logger->transmit = transmit_func;
    logger->head = logger->tail = logger->count = 0;
    logger->running = 1;

    for (int i = 0; i < MAX_THREAD_POOL_SIZE; ++i) {
        pthread_create(&logger->thread_pool[i], NULL, logger_worker, logger);
    }

    return 0;
}

void *logger_worker(void *arg) {
    Logger *logger = (Logger *)arg;
    while (1) {
        sem_wait(&logger->log_queue_lock);

        if (!logger->running && logger->count == 0)
            break;

        char *buffer = NULL;
        int buffer_size = logger->serialize(logger->log_queue[logger->head], &buffer);
        if (buffer_size > COMPRESSION_THRESHOLD) {
            logger->compress(&buffer);
        }

        sem_post(&logger->log_queue_lock);

        logger->transmit(buffer);
        free(buffer);
    }

    return NULL;
}

int logger_add_log(Logger *logger, LogLevel level, ContextData context) {
    LogEntry entry;
    log_entry_init(&entry, level, context);

    sem_wait(&logger->log_queue_lock);
    if (logger->count >= MAX_LOG_SIZE) {
        sem_post(&logger->log_queue_lock);
        return -1; // Queue full
    }

    logger->log_queue[logger->tail] = &entry;
    logger->tail = (logger->tail + 1) % MAX_LOG_SIZE;
    logger->count++;
    sem_post(&logger->log_queue_lock);

    return 0;
}

int main() {
    Logger logger;
    ContextData context;
    context.intValue = 42;

    if (logger_init(&logger, serialize_log_entry, deserialize_log_entry, compress_log_data, transmit_log_data) != 0) {
        fprintf(stderr, "Failed to initialize logger\n");
        return 1;
    }

    logger_add_log(&logger, LOG_INFO, context);

    for (int i = 0; i < MAX_THREAD_POOL_SIZE; ++i) {
        pthread_join(logger.thread_pool[i], NULL);
    }

    sem_destroy(&logger.log_queue_lock);

    return 0;
}
