using System;
using System.Collections.Generic;

public class CdnManagementSystem
{
    private List<CdnProvider> cdnProviders;
    private List<DataCenter> dataCenters;
    private LoggingService loggingService;
    private ThirdPartyApi thirdPartyApi;

    public CdnManagementSystem(List<CdnProvider> cdnProviders, List<DataCenter> dataCenters, LoggingService loggingService, ThirdPartyApi thirdPartyApi)
    {
        this.cdnProviders = cdnProviders;
        this.dataCenters = dataCenters;
        this.loggingService = loggingService;
        this.thirdPartyApi = thirdPartyApi;
    }

    public void AdjustCdnConfiguration()
    {
        // Detect anomalies and reroute traffic
        foreach (var provider in cdnProviders)
        {
            if (!provider.IsHealthy())
            {
                provider.MarkAsUnhealthy();
                RerouteTraffic(provider);
            }
        }

        // Switch between CDN providers
        if (thirdPartyApi.IsAvailable())
        {
            var apiProvider = new CdnProvider("API Provider");
            if (apiProvider.IsCheaperThan(cdnProviders))
            {
                SwitchCdnProvider(apiProvider);
            }
        }

        // Scale CDN capacity
        ScaleCdnCapacity();
    }

    private void RerouteTraffic(CdnProvider unhealthyProvider)
    {
        foreach (var center in dataCenters)
        {
            if (!center.IsOverloaded())
            {
                center.RerouteTraffic(unhealthyProvider);
                break;
            }
        }
    }

    private void SwitchCdnProvider(CdnProvider newProvider)
    {
        foreach (var provider in cdnProviders)
        {
            if (provider.Name == newProvider.Name)
            {
                provider.SetAsPrimary();
                loggingService.Log("Switched to new CDN provider.");
                break;
            }
        }
    }

    private void ScaleCdnCapacity()
    {
        foreach (var center in dataCenters)
        {
            if (center.IsOverloaded())
            {
                center.ScaleUp();
                loggingService.Log($"Scaled up capacity at {center.Name}.");
            }
        }
    }
}

