// Define a flexible union for context data
union ContextData {
    std::string text;
    int number;
    // Add more types as needed

    ContextData() {}
    ~ContextData() {}

    bool operator==(const ContextData& other) const {
        return (this->text == other.text || this->number == other.number);
    }
};

// Define a log entry structure
struct LogEntry {
    std::chrono::system_clock::time_point timestamp;
    int eventCode;
    ContextData context;

    LogEntry(int eventCode, ContextData context)
        : timestamp(std::chrono::system_clock::now()), eventCode(eventCode), context(context) {}
};

// Define a custom memory allocator
class CustomAllocator {
public:
    void* allocate(size_t size) {
        // Implement allocation logic here
        return ::operator new(size);
    }

    void deallocate(void* ptr, size_t size) {
        // Implement deallocation logic here
        ::operator delete(ptr);
    }
};

// Define a logging and encryption framework class
class LoggingFramework {
public:
    LoggingFramework(CustomAllocator* allocator)
        : allocator_(allocator), running_(true), shutdown_cv_() {}

    void start() {
        for (size_t i = 0; i < num_threads_; ++i) {
            workers_.emplace_back(&LoggingFramework::worker_thread, this);
        }
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            running_ = false;
        }
        shutdown_cv_.notify_all();
        for (std::thread& worker : workers_) {
            worker.join();
        }
    }

    template <typename T>
    void log(int eventCode, const T& context) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.emplace(eventCode, ContextData{context});
    }

private:
    CustomAllocator* allocator_;
    std::vector<std::thread> workers_;
    std::queue<LogEntry> queue_;
    std::mutex mutex_;
    std::condition_variable shutdown_cv_;
    std::atomic<bool> running_;
    size_t num_threads_ = 4; // Number of worker threads
};

int main() {
    CustomAllocator allocator;
    LoggingFramework framework(&allocator);
    framework.start();

    // Simulate logging from multiple threads
    for (size_t i = 0; i < 10; ++i) {
        std::thread([i, &framework]() {
            framework.log(i, "Context data for event " + std::to_string(i));
        }).detach();
    }

    // Stop the framework after some time
    std::this_thread::sleep_for(std::chrono::seconds(5));
    framework.stop();

    return 0;
}
```

