    NFAPI_CRC_INDICATION_PDU_T packet;
    struct PacketNode *next;
} PacketNode;

// Define the pool structure
typedef struct PacketPool {
    PacketNode *head;
    pthread_mutex_t lock;
    int size;
} PacketPool;

// Initialize the packet pool
void initPacketPool(PacketPool *pool, int capacity) {
    pool->head = NULL;
    pthread_mutex_init(&pool->lock, NULL);
    pool->size = capacity;
}

// Allocate a packet from the pool
NFAPI_CRC_INDICATION_PDU_T* allocatePacket(PacketPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->head == NULL) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool is empty
    }
    PacketNode *node = pool->head;
    pool->head = node->next;
    pthread_mutex_unlock(&pool->lock);
    return &node->packet;
}

// Free a packet back to the pool
void freePacket(PacketPool *pool, NFAPI_CRC_INDICATION_PDU_T* packet) {
    PacketNode *node = (PacketNode*)malloc(sizeof(PacketNode));
    node->packet = *packet;
    node->next = NULL;
    pthread_mutex_lock(&pool->lock);
    node->next = pool->head;
    pool->head = node;
    pthread_mutex_unlock(&pool->lock);
}

// Example usage
int main() {
    PacketPool packetPool;
    initPacketPool(&packetPool, 1000);

    NFAPI_CRC_INDICATION_PDU_T* packet = allocatePacket(&packetPool);
    if (packet != NULL) {
        // Use the packet
        freePacket(&packetPool, packet);
    }

    return 0;
}
