class RateLimiter:
    def __init__(self, max_requests, time_window):
        self.max_requests = max_requests
        self.time_window = time_window
        self.requests = defaultdict(list)

    def limit(self):
        @wraps(self.app)
        def wrapper(*args, **kwargs):
            if not self.check_rate_limit():
                return jsonify({"message": "Rate limited"}), 429
            return self.app(*args, **kwargs)
        return wrapper

    def check_rate_limit(self):
        current_time = time.time()
        for request_time in self.requests[request.remote_addr]:
            if current_time - request_time < self.time_window:
                if len(self.requests[request.remote_addr]) >= self.max_requests:
                    return False
                else:
                    self.requests[request.remote_addr].append(current_time)
                    return True
        self.requests[request.remote_addr] = [current_time]
