        var selectedProvider = GetSelectedProvider(operationType);

        try
        {
            if (operationType == "Read")
            {
                using (var reader = await selectedProvider.ExecuteReaderAsync(query, parameters))
                {
                    while (await reader.ReadAsync())
                    {
                        // Process each row
                    }
                }
            }
            else if (operationType == "Write")
            {
                await selectedProvider.ExecuteNonQueryAsync(query, parameters);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error during database operation");
            throw;
        }
    }

    private IDatabaseProvider GetSelectedProvider(string operationType)
