class ImageFrame {
    // Define the structure of an image frame
};

class ImageAnalysisService {
public:
    virtual std::future<std::string> AnalyzeImage(const ImageFrame& image) = 0;
    virtual void SetApiVersion(int version) = 0;
    virtual ~ImageAnalysisService() {}
};

class MockImageAnalysisService : public ImageAnalysisService {
private:
    std::mutex serviceMutex;
    int apiVersion;

public:
    MockImageAnalysisService(int initialVersion) : apiVersion(initialVersion) {}

    std::future<std::string> AnalyzeImage(const ImageFrame& image) override {
        // Simulate an analysis operation
        std::promise<std::string> promise;
        auto future = promise.get_future();
        std::thread([this, &image, &promise]() {
            // Simulate processing time
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            promise.set_value("Analysis Result");
        }).detach();
        return future;
    }

    void SetApiVersion(int version) override {
        std::lock_guard<std::mutex> lock(serviceMutex);
        apiVersion = version;
    }
};

class ImageProcessingPipeline {
private:
    ImageAnalysisService* service;
    std::queue<ImageFrame> imageQueue;
    std::vector<std::thread> workerThreads;
    std::mutex queueMutex;
    std::condition_variable notEmpty;
    bool stop;

public:
    ImageProcessingPipeline(ImageAnalysisService* service, int numWorkers)
        : service(service), stop(false) {
        for (int i = 0; i < numWorkers; ++i) {
            workerThreads.emplace_back(&ImageProcessingPipeline::workerThread, this);
        }
    }

    ~ImageProcessingPipeline() {
        {
            std::lock_guard<std::mutex> lock(queueMutex);
            stop = true;
        }
        notEmpty.notify_all();
        for (auto& thread : workerThreads) {
            thread.join();
        }
    }

    void EnqueueImage(const ImageFrame& image) {
        std::lock_guard<std::mutex> lock(queueMutex);
        imageQueue.push(image);
        notEmpty.notify_one();
    }

private:
    void workerThread() {
        while (true) {
            ImageFrame image;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                notEmpty.wait(lock, [this] { return stop || !imageQueue.empty(); });
                if (stop && imageQueue.empty()) break;
                image = imageQueue.front();
                imageQueue.pop();
            }
            service->AnalyzeImage(image);
        }
    }
};

int main() {
    MockImageAnalysisService service(1);
    ImageProcessingPipeline pipeline(&service, 5);

    // Simulate enqueuing images
    for (int i = 0; i < 10000; ++i) {
        pipeline.EnqueueImage(ImageFrame());
    }

    return 0;
}
