        for (double data : sensorData) {
            if (isDataIntact(data)) {
                processData(data);
            }
        }
    }

private:
    std::mutex mutex_;
    std::condition_variable cond_;
    std::queue<double> dataQueue_;

    // Check if the data is intact
    bool isDataIntact(double data) {
        // Implement data integrity check logic here
        return true;
    }

    // Process the data
    void processData(double data) {
        // Implement data processing logic here
        double movingAverage = calculateMovingAverage(data);
        detectAnomalies(movingAverage);
    }

    // Calculate moving average
    double calculateMovingAverage(double data) {
        static std::deque<double> movingAvgQueue;
        static int windowSize = 5; // Example window size

        movingAvgQueue.push_back(data);
        if (movingAvgQueue.size() > windowSize) {
            movingAvgQueue.pop_front();
        }

        double sum = 0.0;
        for (double val : movingAvgQueue) {
            sum += val;
        }
        return sum / movingAvgQueue.size();
    }

    // Detect anomalies
    void detectAnomalies(double average) {
        static const double threshold = 2.0; // Example threshold

        if (std::abs(average - calculateMovingAverage(average)) > threshold) {
            std::cout << "Anomaly detected: Average value is far from moving average." << std::endl;
        }
    }
};

