func createDirectoryAndSetEnv(dirName string) error {
	if _, err := os.Stat(dirName); os.IsNotExist(err) {
		if err := os.Mkdir(dirName, 0755); err != nil {
			return err
		}
	}

	dirPath, err := os.Getwd()
	if err != nil {
		return err
	}
	os.Setenv("MY_DIR_PATH", dirPath)
	return nil
}

func main() {
	dirName := "my_directory"
	if err := createDirectoryAndSetEnv(dirName); err != nil {
		fmt.Println("Error:", err)
		return
	}
	fmt.Println("Directory created and environment variable set successfully.")
}
