#include <openssl/evp.h>
#include <openssl/rand.h>

// Define constants for encryption modes and padding
#define MODE_ECB EVP_CIPHER_mode(EVP_cipher_by_name("des-ecb"))
#define MODE_CBC EVP_CIPHER_mode(EVP_cipher_by_name("des-cbc"))
#define MODE_CFB EVP_CIPHER_mode(EVP_cipher_by_name("des-cfb"))
#define MODE_OFB EVP_CIPHER_mode(EVP_cipher_by_name("des-ofb"))
#define PADDING_PKCS7 EVP_PKEY_type(EVP_PKEY_RSA)

// Function to initialize the OpenSSL library
void init_openssl() {
    SSL_load_error_strings();
    OpenSSL_add_all_algorithms();
}

// Function to clean up resources
void cleanup_resources() {
    EVP_cleanup();
    ERR_free_strings();
}

// Function to encrypt data using a given algorithm and mode
int encrypt_data(const unsigned char *plaintext, int plaintext_len, const unsigned char *key, const unsigned char *iv, unsigned char **ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    int len;
    if (1 != EVP_EncryptInit_ex(ctx, MODE_CBC, NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        free(*ciphertext);
        return -1;
    }
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, (*ciphertext) + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        free(*ciphertext);
        return -1;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

// Function to decrypt data using a given algorithm and mode
int decrypt_data(const unsigned char *ciphertext, int ciphertext_len, const unsigned char *key, const unsigned char *iv, unsigned char **plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    int len;
    if (1 != EVP_DecryptInit_ex(ctx, MODE_CBC, NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (1 != EVP_DecryptUpdate(ctx, *plaintext, &len, ciphertext, ciphertext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        free(*plaintext);
        return -1;
    }
    plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, (*plaintext) + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        free(*plaintext);
        return -1;
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

// Function to encrypt a file
int encrypt_file(const char *in_filename, const char *out_filename, const unsigned char *key, const unsigned char *iv) {
    FILE *infile = fopen(in_filename, "rb");
    if (!infile) return -1;

    FILE *outfile = fopen(out_filename, "wb");
    if (!outfile) {
        fclose(infile);
        return -1;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fclose(infile);
        fclose(outfile);
        return -1;
    }

    if (1 != EVP_EncryptInit_ex(ctx, MODE_CBC, NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        fclose(infile);
        fclose(outfile);
        return -1;
    }

    unsigned char inbuf[1024], outbuf[1024];
    int inlen, outlen;

    while ((inlen = fread(inbuf, 1, sizeof(inbuf), infile)) > 0) {
        if (1 != EVP_EncryptUpdate(ctx, outbuf, &outlen, inbuf, inlen)) {
            EVP_CIPHER_CTX_free(ctx);
            fclose(infile);
            fclose(outfile);
            return -1;
        }
        fwrite(outbuf, 1, outlen, outfile);
    }

    if (1 != EVP_EncryptFinal_ex(ctx, outbuf, &outlen)) {
        EVP_CIPHER_CTX_free(ctx);
        fclose(infile);
        fclose(outfile);
        return -1;
    }
    fwrite(outbuf, 1, outlen, outfile);

    EVP_CIPHER_CTX_free(ctx);
    fclose(infile);
    fclose(outfile);
    return 0;
}

// Function to decrypt a file
int decrypt_file(const char *in_filename, const char *out_filename, const unsigned char *key, const unsigned char *iv) {
    FILE *infile = fopen(in_filename, "rb");
    if (!infile) return -1;

    FILE *outfile = fopen(out_filename, "wb");
    if (!outfile) {
        fclose(infile);
        return -1;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fclose(infile);
        fclose(outfile);
        return -1;
    }

    if (1 != EVP_DecryptInit_ex(ctx, MODE_CBC, NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        fclose(infile);
        fclose(outfile);
        return -1;
    }

    unsigned char inbuf[1024], outbuf[1024];
    int inlen, outlen;

    while ((inlen = fread(inbuf, 1, sizeof(inbuf), infile)) > 0) {
        if (1 != EVP_DecryptUpdate(ctx, outbuf, &outlen, inbuf, inlen)) {
            EVP_CIPHER_CTX_free(ctx);
            fclose(infile);
            fclose(outfile);
            return -1;
        }
        fwrite(outbuf, 1, outlen, outfile);
    }

    if (1 != EVP_DecryptFinal_ex(ctx, outbuf, &outlen)) {
        EVP_CIPHER_CTX_free(ctx);
        fclose(infile);
        fclose(outfile);
        return -1;
    }
    fwrite(outbuf, 1, outlen, outfile);

    EVP_CIPHER_CTX_free(ctx);
    fclose(infile);
    fclose(outfile);
    return 0;
}
