using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json.Linq;

public class ConfigManager
{
    private readonly HttpClient _httpClient;
    private Dictionary<string, JToken> _configCache;
    private DateTime _cacheExpiryTime;
    private const int CacheTtl = 60; // Cache TTL in seconds

    public ConfigManager(HttpClient httpClient)
    {
        _httpClient = httpClient;
        _configCache = new Dictionary<string, JToken>();
    }

    public async Task<JToken> GetConfigAsync(string key)
    {
        if (_cacheExpiryTime <= DateTime.Now)
        {
            await UpdateCacheAsync();
        }
        return _configCache.ContainsKey(key) ? _configCache[key] : null;
    }

    private async Task UpdateCacheAsync()
    {
        try
        {
            var response = await _httpClient.GetAsync("https://api.example.com/config");
            if (response.IsSuccessStatusCode)
            {
                var configJson = await response.Content.ReadAsStringAsync();
                _configCache = JObject.Parse(configJson).ToObject<Dictionary<string, JToken>>();
                _cacheExpiryTime = DateTime.Now.AddSeconds(CacheTtl);
            }
        }
        catch
        {
            // Handle error, e.g., log and use cached data or fallback to default values
        }
    }
}
