// Define a union for flexible context data
union EventContext {
    int intValue;
    double doubleValue;
    std::string stringValue;

    EventContext() {}
    ~EventContext() {}

    void reset() {
        std::visit([](auto& arg) { arg = {}; }, *this);
    }
};

// Define the event structure
struct NetworkEvent {
    std::chrono::time_point<std::chrono::system_clock> timestamp;
    int eventCode;
    EventContext context;

    // Custom destructor to reset context union
    ~NetworkEvent() {
        context.reset();
    }
};

// Logging framework class
class LoggingFramework {
public:
    // Add an event to the queue for processing
    void addEvent(const NetworkEvent& event) {
        std::lock_guard<std::mutex> lock(mutex_);
        eventQueue_.push(event);
        condition_.notify_one();
    }

    // Start the logging process
    void start() {
        running_ = true;
        workerThread_ = std::thread(&LoggingFramework::processEvents, this);
    }

    // Stop the logging process
    void stop() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            running_ = false;
        }
        condition_.notify_all();
        if (workerThread_.joinable()) {
            workerThread_.join();
        }
    }

private:
    std::queue<NetworkEvent> eventQueue_;
    std::mutex mutex_;
    std::condition_variable condition_;
    bool running_ = false;
    std::thread workerThread_;

    // Process events from the queue
    void processEvents() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait(lock, [this] { return !eventQueue_.empty() || !running_; });

            if (!running_ && eventQueue_.empty()) {
                break;
            }

            NetworkEvent event = std::move(eventQueue_.front());
            eventQueue_.pop();
            lock.unlock();

            // Process the event (e.g., send to third-party services, store locally)
            processEvent(event);
        }
    }

    // Placeholder for event processing logic
    void processEvent(const NetworkEvent& event) {
        std::cout << "Processing event: " << event.eventCode << ", Timestamp: " 
                  << std::chrono::duration_cast<std::chrono::milliseconds>(event.timestamp.time_since_epoch()).count() << std::endl;
    }
};

int main() {
    LoggingFramework framework;
    framework.start();

    // Simulate adding events
    for (int i = 0; i < 10; ++i) {
        NetworkEvent event{std::chrono::system_clock::now(), i, EventContext{.intValue = i}};
        framework.addEvent(event);
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }

    framework.stop();
    return 0;
}
