    int statusCode;
    std::string content;
};

// Cache key definition
using CacheKey = std::pair<std::string, std::string>;

// CDN Edge Server class
class CdnEdgeServer {
public:
    void handleRequest(const HttpRequest& request) {
        // Check cache for the requested resource
        auto it = cache_.find(CacheKey(request.method, request.url));
        if (it != cache_.end()) {
            // Cache hit - deliver content directly from cache
            sendResponse(it->second);
        } else {
            // Cache miss - fetch and store content in cache
            fetchAndCacheContent(request);
        }
    }

private:
    void fetchAndCacheContent(const HttpRequest& request) {
        // Simulate fetching content from a backend server
        HttpResponse response = fetchFromBackendServer(request);

        // Store the fetched content in cache
        std::lock_guard<std::mutex> lock(cacheMutex_);
        cache_[CacheKey(request.method, request.url)] = response;

        // Send the fetched content to the client
        sendResponse(response);
    }

    HttpResponse fetchFromBackendServer(const HttpRequest& request) {
        // Simulate fetching content from a backend server
        // This is a placeholder for actual network operations
        HttpResponse response;
        response.statusCode = 200;
        response.content = "Content fetched from backend";
        return response;
