    if (info == NULL || info->title == NULL || info->data == NULL) {
        printf("Connection info validation failed: Null pointers\n");
        return -1;
    }
    time_t current_time = time(NULL);
    if ((current_time - info->last_active) > 7 * 24 * 60 * 60) {
        printf("Connection info validation failed: Last active too old\n");
        return -1;
    }
    printf("Connection info validation successful\n");
    callback();
    return 0;
}

// Function to validate callback
