using System;
using System.Collections.Generic;

public class FiniteStateAutomaton
{
    private Dictionary<int, Dictionary<char, int>> transitions;
    private int initialState;

    public FiniteStateAutomaton(int initialState)
    {
        this.transitions = new Dictionary<int, Dictionary<char, int>>();
        this.initialState = initialState;
    }

    public void AddTransition(int fromState, char input, int toState)
    {
        if (!transitions.ContainsKey(fromState))
        {
            transitions[fromState] = new Dictionary<char, int>();
        }
        transitions[fromState][input] = toState;
    }

    public List<int> FindStates(string input)
    {
        List<int> states = new List<int>();
        states.Add(initialState);
        foreach (char c in input)
        {
            states = GetNextStates(states, c);
        }
        return states;
    }

    private List<int> GetNextStates(List<int> currentStateSet, char input)
    {
        HashSet<int> nextStates = new HashSet<int>();

        foreach (int state in currentStateSet)
        {
            if (transitions.ContainsKey(state) && transitions[state].ContainsKey(input))
            {
                nextStates.Add(transitions[state][input]);
            }
        }

        return new List<int>(nextStates);
    }
}

// Example usage:
public class Program
{
    public static void Main()
    {
        FiniteStateAutomaton fsa = new FiniteStateAutomaton(0);
        fsa.AddTransition(0, 'a', 1);
        fsa.AddTransition(1, 'b', 2);
        fsa.AddTransition(2, 'c', 3);

        List<int> states = fsa.FindStates("abc");
        Console.WriteLine(string.Join(", ", states)); // Output: 0, 1, 2, 3
    }
}
