from abc import ABC, abstractmethod
import time

class GraphDatabase(ABC):
    @abstractmethod
    def add_vertex(self, vertex_id, properties):
        pass

    @abstractmethod
    def add_edge(self, edge_id, source_vertex, target_vertex, properties):
        pass

    @abstractmethod
    def remove_vertex(self, vertex_id):
        pass

    @abstractmethod
    def remove_edge(self, edge_id):
        pass

    @abstractmethod
    def bulk_import(self, dataset):
        pass

    @abstractmethod
    def undo_operations(self, n):
        pass

    @abstractmethod
    def log_operation(self, operation, user_id):
        pass

    @abstractmethod
    def monitor_performance(self):
        pass

class FlexibleSchemaGraphDatabase(GraphDatabase):
    def __init__(self):
        self.vertices = {}
        self.edges = {}
        self.operations_log = []

    def add_vertex(self, vertex_id, properties):
        if vertex_id in self.vertices:
            raise ValueError(f"Vertex {vertex_id} already exists")
        self.vertices[vertex_id] = properties
        self.log_operation("ADD_VERTEX", None)

    def add_edge(self, edge_id, source_vertex, target_vertex, properties):
        if edge_id in self.edges:
            raise ValueError(f"Edge {edge_id} already exists")
        if source_vertex not in self.vertices or target_vertex not in self.vertices:
            raise ValueError("Source or target vertex does not exist")
        self.edges[edge_id] = {
            "source": source_vertex,
            "target": target_vertex,
            "properties": properties
        }
        self.log_operation("ADD_EDGE", None)

    def remove_vertex(self, vertex_id):
        if vertex_id not in self.vertices:
            raise ValueError(f"Vertex {vertex_id} does not exist")
        for edge_id, edge in list(self.edges.items()):
            if edge["source"] == vertex_id or edge["target"] == vertex_id:
                del self.edges[edge_id]
        del self.vertices[vertex_id]
        self.log_operation("REMOVE_VERTEX", None)

    def remove_edge(self, edge_id):
        if edge_id not in self.edges:
            raise ValueError(f"Edge {edge_id} does not exist")
        del self.edges[edge_id]
        self.log_operation("REMOVE_EDGE", None)

    def bulk_import(self, dataset):
        for item in dataset:
            if item["type"] == "VERTEX":
                self.add_vertex(item["id"], item["properties"])
            elif item["type"] == "EDGE":
                self.add_edge(item["id"], item["source"], item["target"], item["properties"])

    def undo_operations(self, n):
        for _ in range(n):
            if not self.operations_log:
                break
            last_operation = self.operations_log.pop()
            if last_operation[0] == "ADD_VERTEX":
                self.remove_vertex(last_operation[1])
            elif last_operation[0] == "ADD_EDGE":
                self.remove_edge(last_operation[1])

    def log_operation(self, operation, user_id):
        self.operations_log.append((operation, user_id))

    def monitor_performance(self):
        # Simple performance monitoring
        current_time = time.time()
        print(f"Current Time: {current_time}")
        # Add more metrics as needed

# Example usage
db = FlexibleSchemaGraphDatabase()
db.add_vertex("v1", {"name": "Alice"})
db.add_vertex("v2", {"name": "Bob"})
db.add_edge("e1", "v1", "v2", {"type": "FRIEND"})
db.bulk_import([{"type": "VERTEX", "id": "v3", "properties": {"name": "Charlie"}}])
db.undo_operations(1)
```

This code defines an abstract base class `GraphDatabase` with methods for adding and removing vertices and edges, bulk importing datasets, undoing operations, logging operations, and monitoring performance. The `FlexibleSchemaGraphDatabase` class provides a concrete implementation of these methods to create a scalable graph database extension that can handle dynamic schema changes and large-scale data processing.']

