#include <iostream>
#include <unordered_map>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <atomic>
#include <chrono>

class Attack {
public:
    Attack(std::string name, int cooldown) : name(name), cooldown(cooldown), available(true), lastUsed(0) {}

    std::string getName() const { return name; }
    int getCooldown() const { return cooldown; }
    bool isAvailable() const { return available.load(); }

    void use() {
        if (available.exchange(false)) {
            lastUsed = std::chrono::steady_clock::now();
        }
    }

private:
    std::string name;
    int cooldown;
    std::atomic<bool> available;
    std::chrono::time_point<std::chrono::steady_clock> lastUsed;
};

class AttackManager {
public:
    void addAttack(const std::string& name, int cooldown) {
        std::lock_guard<std::mutex> lock(mutex);
        attacks[name] = std::make_shared<Attack>(name, cooldown);
    }

    bool useAttack(const std::string& name) {
        std::lock_guard<std::mutex> lock(mutex);
        if (auto attack = attacks.find(name); attack != attacks.end() && attack->second->isAvailable()) {
            attack->second->use();
            return true;
        }
        return false;
    }

    void update() {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto& pair : attacks) {
            if (!pair.second->isAvailable()) {
                auto now = std::chrono::steady_clock::now();
                if (now - pair.second->lastUsed >= std::chrono::seconds(pair.second->getCooldown())) {
                    pair.second->available.store(true);
                }
            }
        }
    }

private:
    std::mutex mutex;
    std::unordered_map<std::string, std::shared_ptr<Attack>> attacks;
};

int main() {
    AttackManager manager;
    manager.addAttack("Fireball", 2);
    manager.addAttack("Heal", 1);

    if (manager.useAttack("Fireball")) {
        std::cout << "Fireball used!" << std::endl;
    } else {
        std::cout << "Fireball is on cooldown." << std::endl;
    }

    std::this_thread::sleep_for(std::chrono::seconds(3));
    manager.update();

    if (manager.useAttack("Fireball")) {
        std::cout << "Fireball used!" << std::endl;
    } else {
        std::cout << "Fireball is on cooldown." << std::endl;
    }

    return 0;
}
