type LogConfig struct {
	Sources []LogSource `json:"sources"`
}

type LogSource struct {
	Type        string            `json:"type"`
	URL         string            `json:"url"`
	Format      string            `json:"format"`
	FilterRules map[string]string `json:"filterRules"`
}

func parseAndProcessLogs(configFile string) ([]LogEvent, error) {
	var logConfig LogConfig
	configData, err := ioutil.ReadFile(configFile)
	if err != nil {
		return nil, fmt.Errorf("failed to read config file: %v", err)
	}

	err = json.Unmarshal(configData, &logConfig)
	if err != nil {
		return nil, fmt.Errorf("failed to parse config file: %v", err)
	}

	var logEvents []LogEvent
	for _, source := range logConfig.Sources {
		logs, err := fetchLogs(source.URL, source.Format)
		if err != nil {
			log.Printf("Error fetching logs from %s: %v", source.URL, err)
			continue
		}

		filteredLogs := applyFilterRules(logs, source.FilterRules)
		for _, logEntry := range filteredLogs {
			event, err := createLogEvent(logEntry)
			if err != nil {
				log.Printf("Error creating log event: %v", err)
				continue
			}
			logEvents = append(logEvents, event)
		}
	}

	return logEvents, nil
}

