        print(f"Processed {config_id} with new config: {updated_config}")
    except Exception as e:
        app.logger.error(f"Processing error for {config_id}: {e}")

if __name__ == '__main__':
    start_http_server(8000)
    app.run(host='0.0.0.0', port=5000)
