#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <dirent.h>

#define MAX_FILENAME_LENGTH 256

typedef struct {
    char directory[MAX_FILENAME_LENGTH];
    pthread_mutex_t lock;
} FileManagementService;

void initialize_service(FileManagementService *service, const char *directory) {
    strcpy(service->directory, directory);
    pthread_mutex_init(&service->lock, NULL);
}

int rename_file_with_version(FileManagementService *service, const char *old_filename, int *version) {
    pthread_mutex_lock(&service->lock);

    DIR *dir;
    struct dirent *entry;
    char new_filename[MAX_FILENAME_LENGTH];
    time_t current_time = time(NULL);
    int new_version = *version + 1;

    snprintf(new_filename, MAX_FILENAME_LENGTH, "%s_%ld_v%d", old_filename, current_time, new_version);

    // Check if the new filename already exists and increment version number accordingly
    dir = opendir(service->directory);
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, new_filename) == 0) {
            closedir(dir);
            pthread_mutex_unlock(&service->lock);
            *version = new_version;
            return rename_file_with_version(service, old_filename, version);
        }
    }

    closedir(dir);

    // Rename the file
    int result = rename(old_filename, new_filename);
    if (result == 0) {
        (*version)++;
    }

    pthread_mutex_unlock(&service->lock);
    return result;
}

void finalize_service(FileManagementService *service) {
    pthread_mutex_destroy(&service->lock);
}
