#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_THREADS 10

typedef struct {
    // Transaction log fields
    char timestamp[20];
    int transaction_id;
    int user_id;
    float amount;
    char status[20];
} Transaction;

typedef struct {
    Transaction transactions[MAX_THREADS];
    sem_t semaphore;
} TransactionQueue;

TransactionQueue queue;

void* process_transaction(void* arg) {
    pthread_t thread_id = (pthread_t)arg;
    while (1) {
        sem_wait(&queue.semaphore);
        // Process the transaction from the queue
        printf("Processing transaction %d\n", queue.transactions[0].transaction_id);
        sem_post(&queue.semaphore);
        sleep(1); // Simulate processing time
    }
    pthread_exit(NULL);
}

void add_transaction(Transaction* transaction) {
    sem_wait(&queue.semaphore);
    int i;
    for (i = 0; i < MAX_THREADS; i++) {
        if (queue.transactions[i].transaction_id == 0) {
            queue.transactions[i] = *transaction;
            break;
        }
    }
    sem_post(&queue.semaphore);
}

int main() {
    pthread_t threads[MAX_THREADS];
    int rc;
    int i;

    sem_init(&queue.semaphore, 0, MAX_THREADS);

    for (i = 0; i < MAX_THREADS; i++) {
        rc = pthread_create(&threads[i], NULL, process_transaction, (void*)&threads[i]);
        if (rc) {
            printf("Error creating thread %d\n", rc);
            exit(-1);
        }
    }

    // Simulate adding transactions to the queue
    for (i = 0; i < MAX_THREADS * 2; i++) {
        Transaction transaction;
        snprintf(transaction.timestamp, sizeof(transaction.timestamp), "2023-10-%02d %02d:%02d:00", (i / 6) + 1, (i % 6) * 10, i % 6);
        transaction.transaction_id = i;
        transaction.user_id = i * 100;
        transaction.amount = (float)i * 10.5;
        snprintf(transaction.status, sizeof(transaction.status), "Completed");
        add_transaction(&transaction);
    }

    for (i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&queue.semaphore);

    return 0;
}
