#include <vector>
#include <random>
#include <cstring>
#include <atomic>

struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
};

std::vector<NFAPI_CRC_INDICATION_PDU_T> generateNfapiCrcIndications(int numPackets) {
    static std::atomic<int> tagCounter(0);
    static std::mt19937 gen(std::random_device{}());
    static std::uniform_int_distribution<> rntiDist(1, 16383);

    std::vector<NFAPI_CRC_INDICATION_PDU_T> packets(numPackets);
    for (int i = 0; i < numPackets; ++i) {
        NFAPI_CRC_INDICATION_PDU_T& packet = packets[i];
        packet.RX_UE_INFORMATION_TAG = tagCounter.fetch_add(1, std::memory_order_relaxed);
        packet.RNTI = rntiDist(gen);
        packet.CRC_INDICATION_REL8_TAG.CRCFLAG = (gen() % 2) == 0;
    }
    return packets;
}
