#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <functional>
#include <atomic>
#include <memory>

class ThreadSafeQueue {
public:
    void push(int value) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(value);
        condition_.notify_one();
    }

    int pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        condition_.wait(lock, [this] { return !queue_.empty(); });
        int value = queue_.front();
        queue_.pop();
        return value;
    }

private:
    std::queue<int> queue_;
    mutable std::mutex mutex_;
    std::condition_variable condition_;
};

class EventProcessor {
public:
    void processEvent(int event) {
        // Simulate event processing
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        std::cout << "Processed event: " << event << std::endl;
    }
};

class LoggingSystem {
public:
    LoggingSystem(EventProcessor& processor, int queueSize)
        : processor_(processor), stop_(false) {
        for (int i = 0; i < 5; ++i) {
            workers_.emplace_back([this] {
                while (true) {
                    int event = queue_.pop();
                    if (stop_) return;
                    processor_.processEvent(event);
                }
            });
        }
    }

    void addEvent(int event) {
        queue_.push(event);
    }

    ~LoggingSystem() {
        stop_ = true;
        for (auto& worker : workers_) {
            worker.join();
        }
    }

private:
    EventProcessor& processor_;
    ThreadSafeQueue queue_;
    std::vector<std::thread> workers_;
    std::atomic<bool> stop_;
};

int main() {
    EventProcessor processor;
    LoggingSystem loggingSystem(processor, 100);

    for (int i = 0; i < 1000; ++i) {
        loggingSystem.addEvent(i);
    }

    return 0;
}
