// Function to dynamically insert a new HTML element into the DOM after the first occurrence of a target element
function dynamicInsertElement(selectors, targetSelector, newElement, callback) {
    // Helper function to traverse the DOM efficiently
    function findTarget(selector) {
        return document.querySelector(selector);
    }

    // Helper function to insert a new element after a specified target
    function insertAfter(target, newElm) {
        if (target) {
            target.parentNode.insertBefore(newElm, target.nextSibling);
        } else {
            console.error('Target element not found');
        }
    }

    // Asynchronous handler for fetching and inserting the new element
    async function handleInsertion() {
        try {
            const target = findTarget(targetSelector);
            if (target) {
                let elmToInsert = newElement;
                if (typeof callback === 'function') {
                    elmToInsert = await callback();
                }
                insertAfter(target, elmToInsert);
                console.log('Element inserted successfully');
            } else {
                console.error('Failed to find target element for insertion');
            }
        } catch (error) {
            console.error('Error during element insertion:', error);
        }
    }

    // Execute the insertion logic asynchronously
    handleInsertion();
}

// Example usage:
// Assuming 'newElement' is a DOM Element object and 'callback' is an async function that fetches data to create the new element
dynamicInsertElement(['body'], '.target-class', newElement, () => {
    return fetchDataFromAPI().then(data => createNewElement(data));
});
