import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.UUID;

public class UserHashMicroservice {

    private static final int RATE_LIMIT = 50;
    private static final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private static final ConcurrentHashMap<String, Long> lastRequestTimes = new ConcurrentHashMap<>();
    private static long backoffInterval = 100; // milliseconds

    public String processUserIdentifier(String userIdentifier) {
        if (!isRateLimitExceeded(userIdentifier)) {
            String hash = generateHash(userIdentifier);
            recordRequestTime(userIdentifier);
            return hash;
        } else {
            retryWithBackoff();
            return null;
        }
    }

    private boolean isRateLimitExceeded(String userIdentifier) {
        long currentTime = System.currentTimeMillis();
        Long lastTime = lastRequestTimes.get(userIdentifier);
        if (lastTime != null && currentTime - lastTime < 1000) { // 1 second window
            return true;
        }
        return false;
    }

    private void recordRequestTime(String userIdentifier) {
        lastRequestTimes.put(userIdentifier, System.currentTimeMillis());
    }

    private String generateHash(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hashBytes = digest.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-256 algorithm not found");
        }
    }

    private void retryWithBackoff() {
        scheduler.schedule(() -> {
            backoffInterval *= 2; // Exponential backoff
            processUserIdentifier(UUID.randomUUID().toString()); // Retry with a new identifier
        }, backoffInterval, TimeUnit.MILLISECONDS);
    }

    public static void main(String[] args) {
        UserHashMicroservice service = new UserHashMicroservice();
        for (int i = 0; i < 100; i++) {
            String hash = service.processUserIdentifier("user" + i);
            if (hash != null) {
                System.out.println("Processed user " + i + " with hash: " + hash);
            }
        }
    }
}
