#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <dirent.h>
#include <unistd.h>
#include <time.h>

#define MAX_FILES 10000
#define FILE_SIZE_LIMIT 1024 * 1024 // 1MB
#define RETRY_MAX 5

typedef struct {
    char* path;
    int should_process;
} FileEntry;

FileEntry file_entries[MAX_FILES];
int num_files = 0;

void* process_file(void* arg) {
    FileEntry* entry = (FileEntry*)arg;
    if (entry == NULL || entry->path == NULL) {
        return NULL;
    }

    FILE* file = fopen(entry->path, "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", entry->path);
        return NULL;
    }

    char buffer[256];
    if (fgets(buffer, sizeof(buffer), file) == NULL || strlen(buffer) > 1024) {
        fclose(file);
        printf("Malformed line or large file size for: %s\n", entry->path);
        return NULL;
    }

    // Simulate content analysis and extension modification
    if (strncmp(buffer, "process_as_csv", 14) == 0) {
        // Modify file extension to .csv
        char* ext = strrchr(entry->path, '.');
        if (ext != NULL) {
            *ext = '\0';
        }
        strcat(entry->path, ".csv");
    } else {
        printf("Unsupported format for: %s\n", entry->path);
    }

    fclose(file);
    return NULL;
}

void handle_directory(const char* directory_path) {
    DIR* dir;
    struct dirent* ent;
    if ((dir = opendir(directory_path)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            if (num_files < MAX_FILES) {
                file_entries[num_files].path = malloc(strlen(ent->d_name) + 1);
                strcpy(file_entries[num_files].path, ent->d_name);
                num_files++;
            }
        }
        closedir(dir);
    } else {
        perror("Error opening directory");
    }

    pthread_t threads[MAX_FILES];
    for (int i = 0; i < num_files; i++) {
        if (pthread_create(&threads[i], NULL, process_file, &file_entries[i]) != 0) {
            fprintf(stderr, "Failed to create thread for file: %s\n", file_entries[i].path);
            free(file_entries[i].path);
        }
    }

    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
        free(file_entries[i].path);
    }
}

int main() {
    const char* directory_path = "/path/to/directory";
    handle_directory(directory_path);

    return 0;
}
```

