#define MAX_USERS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_CRC_POOL_T;

NFAPI_CRC_POOL_T* nfaapi_crc_pool_create(size_t initial_capacity) {
    NFAPI_CRC_POOL_T *pool = (NFAPI_CRC_POOL_T*)malloc(sizeof(NFAPI_CRC_POOL_T));
    if (!pool) return NULL;

    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    pool->size = 0;
    pool->capacity = initial_capacity;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void nfaapi_crc_pool_destroy(NFAPI_CRC_POOL_T *pool) {
    if (pool->pool) free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int nfaapi_crc_pool_resize(NFAPI_CRC_POOL_T *pool, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T*)realloc(pool->pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pool) return -1;

    pool->pool = new_pool;
    pool->capacity = new_capacity;
    return 0;
}

int nfaapi_crc_pool_add_user(NFAPI_CRC_POOL_T *pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->size >= pool->capacity && nfaapi_crc_pool_resize(pool, pool->capacity * 2) != 0) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *user = &pool->pool[pool->size++];
    user->RX_UE_INFORMATION_TAG = rand();
    user->RNTI = rand();
    user->CRC_INDICATION_REL8_TAG = rand() % 2;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* nfaapi_crc_pool_get_user(NFAPI_CRC_POOL_T *pool, size_t index) {
    if (index >= pool->size) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *user = &pool->pool[index];
    user->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomize CRCFLAG for demonstration
    return user;
}

void nfaapi_crc_pool_sync(NFAPI_CRC_POOL_T *pool, void (*sync_function)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->size; ++i) {
        sync_function(&pool->pool[i]);
    }

    pthread_mutex_unlock(&pool->lock);
}
