#include <time.h>

#define MAX_USERS 10000
#define MINOR_SYNCH_INTERVAL 5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    int front, rear, size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} PriorityQueue;

PriorityQueue *create_priority_queue(int capacity) {
    PriorityQueue *pq = (PriorityQueue *)malloc(sizeof(PriorityQueue));
    pq->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pq->front = -1;
    pq->rear = -1;
    pq->size = capacity;
    pthread_mutex_init(&pq->mutex, NULL);
    pthread_cond_init(&pq->cond, NULL);
    return pq;
}

void enqueue(PriorityQueue *pq, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&pq->mutex);
    while (pq->front == (pq->rear + 1) % pq->size) {
        pthread_cond_wait(&pq->cond, &pq->mutex);
    }
    if (pq->front == -1) pq->front = pq->rear = 0;
    else pq->rear = (pq->rear + 1) % pq->size;
    pq->data[pq->rear] = item;
    pthread_cond_signal(&pq->cond);
    pthread_mutex_unlock(&pq->mutex);
}

NFAPI_CRC_INDICATION_PDU_T dequeue(PriorityQueue *pq) {
    pthread_mutex_lock(&pq->mutex);
    while (pq->front == -1) {
        pthread_cond_wait(&pq->cond, &pq->mutex);
    }
    NFAPI_CRC_INDICATION_PDU_T item = pq->data[pq->front];
    if (pq->front == pq->rear) pq->front = pq->rear = -1;
    else pq->front = (pq->front + 1) % pq->size;
    pthread_cond_signal(&pq->cond);
    pthread_mutex_unlock(&pq->mutex);
    return item;
}

void *sync_task(void *arg) {
    PriorityQueue *pq = (PriorityQueue *)arg;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T item = dequeue(pq);
        // Perform synchronization with external signaling system
        // Update CRCFLAG randomly to avoid predictable patterns
        item.CRC_INDICATION_REL8_TAG = rand() % 2;
        // Log and store the updated structure in a database
        printf("Synchronized PDU: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n",
               item.RX_UE_INFORMATION_TAG, item.RNTI, item.CRC_INDICATION_REL8_TAG);
        // Sleep for MINOR_SYNCH_INTERVAL milliseconds
        usleep(MINOR_SYNCH_INTERVAL * 1000);
    }
}

int main() {
    srand(time(NULL));
    PriorityQueue *pq = create_priority_queue(MAX_USERS);

    pthread_t sync_thread;
    pthread_create(&sync_thread, NULL, sync_task, pq);

    // Simulate adding items to the priority queue
    for (int i = 0; i < MAX_USERS; i++) {
        NFAPI_CRC_INDICATION_PDU_T item = {i, rand() % 1000, rand() % 2};
        enqueue(pq, item);
        // Sleep for a short interval to simulate high load
        usleep(10 * 1000);
    }

    pthread_join(sync_thread, NULL);
    free(pq->data);
    free(pq);

    return 0;
}
