#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_USERS 10000
#define MIN_PRIORITY 1
#define MAX_PRIORITY 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    int priority;
} PriorityQueueNode;

typedef struct {
    PriorityQueueNode *nodes[MAX_USERS];
    int size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} PriorityQueue;

PriorityQueue *create_priority_queue() {
    PriorityQueue *queue = (PriorityQueue *)malloc(sizeof(PriorityQueue));
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->cond, NULL);
    return queue;
}

void destroy_priority_queue(PriorityQueue *queue) {
    for (int i = 0; i < queue->size; i++) {
        free(queue->nodes[i]);
    }
    free(queue);
}

void enqueue(PriorityQueue *queue, NFAPI_CRC_INDICATION_PDU_T pdu, int priority) {
    pthread_mutex_lock(&queue->lock);
    PriorityQueueNode *node = (PriorityQueueNode *)malloc(sizeof(PriorityQueueNode));
    node->pdu = pdu;
    node->priority = priority;

    while (queue->size > 0 && queue->nodes[queue->size - 1]->priority <= priority) {
        queue->size--;
    }

    for (int i = queue->size; i < MAX_USERS; i++) {
        PriorityQueueNode *temp = queue->nodes[i];
        queue->nodes[i] = node;
        node = temp;
    }
    queue->size++;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->lock);
}

PriorityQueueNode *dequeue(PriorityQueue *queue) {
    pthread_mutex_lock(&queue->lock);
    while (queue->size == 0) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }
    PriorityQueueNode *node = queue->nodes[0];
    for (int i = 1; i < queue->size; i++) {
        queue->nodes[i - 1] = queue->nodes[i];
    }
    queue->size--;
    pthread_mutex_unlock(&queue->lock);
    return node;
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    srand(time(NULL));
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = rand();
    pdu.CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set to 0 or 1
    return pdu;
}
