    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct QueueNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct QueueNode* next;
} QueueNode;

typedef struct PriorityQueue {
    QueueNode* head;
    QueueNode* tail;
} PriorityQueue;

PriorityQueue* create_priority_queue() {
    PriorityQueue* pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    pq->head = NULL;
    pq->tail = NULL;
    return pq;
}

void enqueue(PriorityQueue* pq, NFAPI_CRC_INDICATION_PDU_T data) {
    QueueNode* node = (QueueNode*)malloc(sizeof(QueueNode));
    node->data = data;
    node->next = NULL;

    if (pq->tail == NULL) {
        pq->head = pq->tail = node;
    } else {
        pq->tail->next = node;
        pq->tail = node;
    }
}

NFAPI_CRC_INDICATION_PDU_T dequeue(PriorityQueue* pq) {
    if (pq->head == NULL) {
        NFAPI_CRC_INDICATION_PDU_T empty = {0};
        return empty;
    }

    QueueNode* temp = pq->head;
    NFAPI_CRC_INDICATION_PDU_T data = temp->data;
    pq->head = temp->next;

    if (pq->head == NULL) {
        pq->tail = NULL;
    }

    free(temp);
    return data;
}

