#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_USERS 10000
#define POOL_SIZE 2 * 1024 * 1024 // 2 MB

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    int priority;
} PriorityQueueElement;

typedef struct {
    PriorityQueueElement *elements;
    int size;
    int capacity;
} PriorityQueue;

PriorityQueue* create_priority_queue() {
    PriorityQueue *pq = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    pq->elements = (PriorityQueueElement*)malloc(100 * sizeof(PriorityQueueElement)); // Initial capacity
    pq->size = 0;
    pq->capacity = 100;
    return pq;
}

void enqueue(PriorityQueue *pq, PriorityQueueElement element) {
    if (pq->size == pq->capacity) {
        pq->elements = realloc(pq->elements, pq->capacity * 2 * sizeof(PriorityQueueElement));
        pq->capacity *= 2;
    }
    int i = pq->size++;
    while (i > 0 && element.priority > pq->elements[(i - 1) / 2].priority) {
        pq->elements[i] = pq->elements[(i - 1) / 2];
        i = (i - 1) / 2;
    }
    pq->elements[i] = element;
}

PriorityQueueElement dequeue(PriorityQueue *pq) {
    PriorityQueueElement result = pq->elements[0];
    int i = 0, child;
    while (2 * i + 1 < pq->size) {
        child = 2 * i + 1;
        if (child + 1 < pq->size && pq->elements[child].priority < pq->elements[child + 1].priority)
            child++;
        if (pq->elements[i].priority >= pq->elements[child].priority)
            break;
        pq->elements[i] = pq->elements[child];
        i = child;
    }
    pq->elements[i] = pq->elements[--pq->size];
    return result;
}

void generate_random_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = (uint16_t)rand() % 0xFFFF;
    pdu->CRC_INDICATION_REL8_TAG = (uint8_t)(rand() % 2);
}

void* process_updates(void *arg) {
    PriorityQueue *pq = (PriorityQueue*)arg;
    while (1) {
        if (pq->size > 0) {
            PriorityQueueElement element = dequeue(pq);
            // Process the pdu
            printf("Processing PDU with RNTI: %d\n", element.pdu.RNTI);
        }
        usleep(50); // Simulate processing time
    }
}

int main() {
    srand(time(NULL));
    PriorityQueue *pq = create_priority_queue();

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, process_updates, pq);

    for (int i = 0; i < MAX_USERS; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        generate_random_pdu(&pdu);
        enqueue(pq, (PriorityQueueElement){.pdu = pdu, .priority = rand() % 100});
    }

    pthread_join(thread_id, NULL);
    free(pq->elements);
    free(pq);

    return 0;
}
