    pthread_mutex_init(&pdu_queue.mutex, NULL);
    queue_init(&pdu_queue.pdus_queue);
}

void enqueue_pdu(NFAPI_CRC_INDICATION_PDU *pdu) {
    pthread_mutex_lock(&pdu_queue.mutex);
    queue_enqueue(&pdu_queue.pdus_queue, pdu);
    pthread_mutex_unlock(&pdu_queue.mutex);
}

NFAPI_CRC_INDICATION_PDU* dequeue_pdu() {
    NFAPI_CRC_INDICATION_PDU *pdu;
    pthread_mutex_lock(&pdu_queue.mutex);
    if (queue_is_empty(&pdu_queue.pdus_queue)) {
        pdu = NULL;
    } else {
        pdu = queue_dequeue(&pdu_queue.pdus_queue);
    }
    pthread_mutex_unlock(&pdu_queue.mutex);
    return pdu;
}

void *generate_pdus(void *params) {
