    int in_use;
} Slab;

Slab pool[MAX_USERS / SLAB_SIZE];

pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < MAX_USERS / SLAB_SIZE; i++) {
        if (!pool[i].in_use) {
            pool[i].in_use = 1;
            pthread_mutex_unlock(&pool_lock);
            return &pool[i].data[0];
        }
    }
    pthread_mutex_unlock(&pool_lock);
    return NULL;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    int index = (int)((char*)pdu - (char*)&pool[0]) / sizeof(Slab);
    pthread_mutex_lock(&pool_lock);
    pool[index].in_use = 0;
    pthread_mutex_unlock(&pool_lock);
}

