#include <atomic>
#include <condition_variable>
#include <mutex>
#include <vector>
#include <queue>
#include <memory>

class NetworkPacket {
public:
    uint64_t timestamp;
    size_t packetSize;
    std::string sourceIP;
    std::string destinationIP;
    int destinationPort;

    // Constructor, getters, and setters
};

class PacketPool {
private:
    struct PoolItem {
        NetworkPacket* packet;
        bool inUse;
    };

    std::vector<std::unique_ptr<PoolItem>> pool;
    std::queue<size_t> freeIndices;
    std::mutex poolMutex;
    std::condition_variable availableCond;
    size_t maxSize;

public:
    PacketPool(size_t maxPackets) : maxSize(maxPackets), pool(maxSize) {
        for (size_t i = 0; i < maxSize; ++i) {
            pool[i] = std::make_unique<PoolItem>();
            pool[i]->packet = new NetworkPacket();
            freeIndices.push(i);
        }
    }

    ~PacketPool() {
        for (auto& item : pool) {
            delete item->packet;
        }
    }

    NetworkPacket* getPacket() {
        std::unique_lock<std::mutex> lock(poolMutex);
        availableCond.wait(lock, [this] { return !freeIndices.empty(); });
        size_t index = freeIndices.front();
        freeIndices.pop();
        pool[index]->inUse = true;
        lock.unlock();

        return pool[index]->packet;
    }

    void releasePacket(NetworkPacket* packet) {
        std::unique_lock<std::mutex> lock(poolMutex);
        for (size_t i = 0; i < maxSize; ++i) {
            if (pool[i]->packet == packet) {
                pool[i]->inUse = false;
                freeIndices.push(i);
                break;
            }
        }
        lock.unlock();
        availableCond.notify_one();
    }

    // Additional methods for error handling, logging, and failover strategy
};
