class IOTLibrary {
public:
    // Function to process real-time sensor data
    void process_realtime_sensor_data(const SensorData& data) {
        // Implement the function logic here
        // Ensure thread safety and performance optimizations
    }

private:
    std::mutex data_mutex_;
    std::condition_variable data_condition_;
    std::queue<SensorData> data_queue_;
    std::atomic<bool> running_{true};

    // Thread function to handle data processing in a separate thread
    void process_data_thread() {
        while (running_) {
            std::unique_lock<std::mutex> lock(data_mutex_);
            data_condition_.wait(lock, [this] { return !data_queue_.empty(); });
            SensorData data = std::move(data_queue_.front());
            data_queue_.pop();
            lock.unlock();

            // Process the sensor data
            process_realtime_sensor_data(data);
        }
    }

