    IOTLibrary() {
        std::thread([this]() { this->process_data_thread(); }).detach();
    }

    // Function to stop processing and join threads
    ~IOTLibrary() {
        running_ = false;
        data_condition_.notify_all();
        // Join the processing thread if needed
    }
