// Logging Framework
#include <iostream>
#include <fstream>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <queue>
#include <memory>

class Logger {
public:
    void log(const std::string& message) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(message);
        cv_.notify_one();
    }

private:
    std::mutex mutex_;
    std::condition_variable cv_;
    std::queue<std::string> queue_;

    friend class LogWorker;
};

class LogWorker {
public:
    LogWorker(Logger& logger) : logger_(logger), running_(true) {
        thread_ = std::thread(&LogWorker::work, this);
    }

    ~LogWorker() {
        {
            std::unique_lock<std::mutex> lock(logger_.mutex_);
            running_ = false;
        }
        logger_.cv_.notify_one();
        thread_.join();
    }

private:
    void work() {
        while (true) {
            std::string message;
            {
                std::unique_lock<std::mutex> lock(logger_.mutex_);
                cv_.wait(lock, [this] { return !logger_.queue_.empty() || !running_; });
                if (!running_) break;
                message = logger_.queue_.front();
                logger_.queue_.pop();
            }
            // Log the message (e.g., to a file)
            std::cout << "Log: " << message << std::endl;
        }
    }

    Logger& logger_;
    bool running_;
    std::thread thread_;
};

