void triple_des_encrypt(const std::string& key, const std::string& data) {}
void triple_des_decrypt(const std::string& key, const std::string& data) {}
void aes_encrypt(const std::string& key, const std::string& data, int mode) {}
void aes_decrypt(const std::string& key, const std::string& data, int mode) {}

