#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NetworkResourceUsage {
    int cpu_usage;
    int memory_usage;
    int network_bandwidth;
    struct NetworkResourceUsage *next;
} NetworkResourceUsage;

typedef struct NetworkEvent {
    long long timestamp;
    char event_type[256];
    NetworkResourceUsage *resource_usages;
    struct NetworkEvent *prev, *next;
} NetworkEvent;

typedef struct EventList {
    NetworkEvent *head, *tail;
    pthread_mutex_t lock;
} EventList;

void init_event_list(EventList *list) {
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_event_list(EventList *list) {
    NetworkEvent *current = list->head;
    while (current != NULL) {
        NetworkEvent *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

void add_network_event(EventList *list, long long timestamp, const char *event_type, NetworkResourceUsage *resource_usages) {
    pthread_mutex_lock(&list->lock);
    NetworkEvent *new_event = (NetworkEvent *)malloc(sizeof(NetworkEvent));
    new_event->timestamp = timestamp;
    strncpy(new_event->event_type, event_type, sizeof(new_event->event_type) - 1);
    new_event->resource_usages = resource_usages;
    new_event->prev = list->tail;
    if (list->tail != NULL) {
        list->tail->next = new_event;
    } else {
        list->head = new_event;
    }
    list->tail = new_event;
    pthread_mutex_unlock(&list->lock);
}

void remove_network_event(EventList *list, NetworkEvent *event) {
    pthread_mutex_lock(&list->lock);
    if (event->prev != NULL) {
        event->prev->next = event->next;
    } else {
        list->head = event->next;
    }
    if (event->next != NULL) {
        event->next->prev = event->prev;
    } else {
        list->tail = event->prev;
    }
    pthread_mutex_unlock(&list->lock);
    free(event);
}

NetworkResourceUsage* create_network_resource_usage(int cpu, int memory, int bandwidth) {
    NetworkResourceUsage *usage = (NetworkResourceUsage *)malloc(sizeof(NetworkResourceUsage));
    usage->cpu_usage = cpu;
    usage->memory_usage = memory;
    usage->network_bandwidth = bandwidth;
    usage->next = NULL;
    return usage;
}

void free_network_resource_usage(NetworkResourceUsage *usage) {
    free(usage);
}
```

