#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define structures
typedef struct NetworkResourceUsage {
    double cpu_usage;
    double memory_usage;
    double network_bandwidth;
} NetworkResourceUsage;

typedef struct NetworkEvent {
    int event_id;
    char* event_type;
    pthread_mutex_t mutex;
    NetworkResourceUsage* resource_usages;
    struct NetworkEvent* prev;
    struct NetworkEvent* next;
} NetworkEvent;

typedef struct DoublyLinkedList {
    NetworkEvent* head;
    NetworkEvent* tail;
} DoublyLinkedList;

// Function declarations
NetworkEvent* create_network_event(int event_id, char* event_type);
void free_network_event(NetworkEvent* event);
void add_event_to_list(DoublyLinkedList* list, NetworkEvent* event);
void remove_event_from_list(DoublyLinkedList* list, NetworkEvent* event);

// Main function
int main() {
    DoublyLinkedList* network_events = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    network_events->head = NULL;
    network_events->tail = NULL;

    // Create and add events to the list
    NetworkEvent* event1 = create_network_event(1, "Connection Established");
    add_event_to_list(network_events, event1);

    NetworkEvent* event2 = create_network_event(2, "Data Transfer");
    add_event_to_list(network_events, event2);

    // Remove an event from the list
    remove_event_from_list(network_events, event1);
    free_network_event(event1);

    free(network_events);
    return 0;
}

// Implementations of functions
NetworkEvent* create_network_event(int event_id, char* event_type) {
    NetworkEvent* new_event = (NetworkEvent*)malloc(sizeof(NetworkEvent));
    new_event->event_id = event_id;
    new_event->event_type = strdup(event_type);
    pthread_mutex_init(&new_event->mutex, NULL);
    new_event->resource_usages = NULL;
    new_event->prev = NULL;
    new_event->next = NULL;
    return new_event;
}

void free_network_event(NetworkEvent* event) {
    if (event != NULL) {
        free(event->event_type);
        pthread_mutex_destroy(&event->mutex);
        // Free resource_usages
        NetworkResourceUsage* current_usage = event->resource_usages;
        while (current_usage != NULL) {
            NetworkResourceUsage* next_usage = current_usage->next;
            free(current_usage);
            current_usage = next_usage;
        }
        free(event);
    }
}

void add_event_to_list(DoublyLinkedList* list, NetworkEvent* event) {
    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = event;
        list->tail = event;
    } else {
        list->tail->next = event;
        event->prev = list->tail;
        list->tail = event;
    }
    pthread_mutex_unlock(&list->mutex);
}

void remove_event_from_list(DoublyLinkedList* list, NetworkEvent* event) {
    pthread_mutex_lock(&list->mutex);
    if (event == list->head) {
        list->head = event->next;
    }
    if (event == list->tail) {
        list->tail = event->prev;
    }
    if (event->prev != NULL) {
        event->prev->next = event->next;
    }
    if (event->next != NULL) {
        event->next->prev = event->prev;
    }
    pthread_mutex_unlock(&list->mutex);
}
