using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net.Sockets;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

public class LogProcessor : ILogProcessor
{
    private readonly ILogger<LogProcessor> _logger;
    private readonly IConfiguration _configuration;
    private readonly ConcurrentDictionary<string, TcpClient> _clients = new();
    private readonly ConcurrentQueue<string> _logQueue = new();

    public LogProcessor(ILogger<LogProcessor> logger, IConfiguration configuration)
    {
        _logger = logger;
        _configuration = configuration;
    }

    public async Task StartProcessing()
    {
        var regionalSources = GetRegionalSources();
        foreach (var source in regionalSources)
        {
            await ConnectToSource(source);
        }

        while (true)
        {
            if (_logQueue.TryDequeue(out var logEntry))
            {
                await SendLogEntry(logEntry);
            }
            else
            {
                await Task.Delay(10); // Adjust based on load
            }
        }
    }

    private async Task ConnectToSource(string source)
    {
        try
        {
            if (!_clients.ContainsKey(source))
            {
                var client = new TcpClient(source, _configuration.GetValue<int>("LogServerPort"));
                _clients[source] = client;
                await ProcessLogsFromClient(client);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to connect to log source: {Source}", source);
        }
    }

    private async Task ProcessLogsFromClient(TcpClient client)
    {
        var streamReader = new StreamReader(client.GetStream());
        while (!streamReader.EndOfStream)
        {
            try
            {
                string line;
                while ((line = await streamReader.ReadLineAsync()) != null)
                {
                    _logQueue.Enqueue(line);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error reading logs from client");
            }

            // Reconnect logic goes here if needed
        }
    }

    private async Task SendLogEntry(string logEntry)
    {
        foreach (var client in _clients.Values)
        {
            try
            {
                var networkStream = client.GetStream();
                await networkStream.WriteAsync(Encoding.UTF8.GetBytes(logEntry + Environment.NewLine), 0, Encoding.UTF8.GetByteCount(logEntry + Environment.NewLine));
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error sending log entry to server");
            }
        }
    }

    private string[] GetRegionalSources()
    {
        // Retrieve regional sources from configuration or other sources
        return _configuration.GetValue<string>("RegionalSources").Split(',');
    }
}

public interface ILogProcessor
{
    Task StartProcessing();
}
