#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct NetworkResourceUsage {
    float cpu_usage;
    float memory_usage;
    float bandwidth_consumption;
    struct NetworkResourceUsage *next;
} NetworkResourceUsage;

typedef struct NetworkEvent {
    long timestamp;
    char event_type[50];
    NetworkResourceUsage *resource_usages;
    struct NetworkEvent *prev, *next;
} NetworkEvent;

NetworkEvent* network_event_create(long timestamp, const char* event_type) {
    NetworkEvent* event = (NetworkEvent*)malloc(sizeof(NetworkEvent));
    if (!event) return NULL;

    event->timestamp = timestamp;
    strcpy(event->event_type, event_type);
    event->resource_usages = NULL;
    event->prev = event->next = NULL;

    return event;
}

void network_event_destroy(NetworkEvent* event) {
    NetworkResourceUsage* usage = event->resource_usages;
    while (usage) {
        NetworkResourceUsage* next_usage = usage->next;
        free(usage);
        usage = next_usage;
    }
    free(event);
}

NetworkResourceUsage* network_resource_usage_create(float cpu, float memory, float bandwidth) {
    NetworkResourceUsage* usage = (NetworkResourceUsage*)malloc(sizeof(NetworkResourceUsage));
    if (!usage) return NULL;

    usage->cpu_usage = cpu;
    usage->memory_usage = memory;
    usage->bandwidth_consumption = bandwidth;
    usage->next = NULL;

    return usage;
}

void network_event_add_resource_usage(NetworkEvent* event, NetworkResourceUsage* resource_usage) {
    if (!event->resource_usages) {
        event->resource_usages = resource_usage;
    } else {
        NetworkResourceUsage* current = event->resource_usages;
        while (current->next) {
            current = current->next;
        }
        current->next = resource_usage;
    }
}

void network_event_insert(NetworkEvent** head, NetworkEvent* new_event) {
    pthread_mutex_lock(&event_list_mutex);
    if (*head == NULL || (*head)->timestamp > new_event->timestamp) {
        new_event->next = *head;
        if (*head) (*head)->prev = new_event;
        *head = new_event;
    } else {
        NetworkEvent* current = *head;
        while (current->next && current->next->timestamp <= new_event->timestamp) {
            current = current->next;
        }
        new_event->next = current->next;
        new_event->prev = current;
        if (current->next) current->next->prev = new_event;
        current->next = new_event;
    }
    pthread_mutex_unlock(&event_list_mutex);
}

void network_event_delete(NetworkEvent** head, NetworkEvent* event_to_delete) {
    pthread_mutex_lock(&event_list_mutex);
    if (event_to_delete == *head) {
        *head = event_to_delete->next;
        if (*head) (*head)->prev = NULL;
    } else {
        if (event_to_delete->prev) event_to_delete->prev->next = event_to_delete->next;
        if (event_to_delete->next) event_to_delete->next->prev = event_to_delete->prev;
    }
    network_event_destroy(event_to_delete);
    pthread_mutex_unlock(&event_list_mutex);
}

// Example usage
int main() {
    NetworkEvent* head = NULL;

    NetworkEvent* event1 = network_event_create(1633072800, "Network Down");
    NetworkResourceUsage* resource_usage1 = network_resource_usage_create(5.0, 2048.0, 1024.0);
    network_event_add_resource_usage(event1, resource_usage1);

    NetworkEvent* event2 = network_event_create(1633072860, "Network Up");
    NetworkResourceUsage* resource_usage2 = network_resource_usage_create(3.0, 1536.0, 512.0);
    network_event_add_resource_usage(event2, resource_usage2);

    network_event_insert(&head, event1);
    network_event_insert(&head, event2);

    // Process and remove events as needed

    return 0;
}
```

This code provides a basic framework for managing a distributed system's network event history using a thread-safe, doubly-linked list. It includes functions for creating, inserting, deleting, and destroying `NetworkEvent` and `NetworkResourceUsage` objects. The library ensures minimal impact on the system under heavy load by optimizing data structure operations and implementing custom memory management strategies.

To fully implement the required features, additional code would be needed for real-time data distribution, external data source integration, error handling, and distributed tracing.']

