public class TiffMetadataExtractor {
    public static Map<String, Object> extractMetadata(File tiffFile) {
        try (ImageInputStream stream = ImageIO.createImageInputStream(tiffFile)) {
            BufferedImage image = ImageIO.read(stream);
            if (!(image instanceof IIOMetadataNode)) return new HashMap<>();

            IIOMetadata metadata = image.getMetadata();
            if (metadata == null) return new HashMap<>();

            // Extract TIFF metadata here
            Map<String, Object> result = new HashMap<>();
            result.put("bitsPerSample", ((IIOMetadataNode) metadata).getAttribute("BitsPerSample"));
            result.put("samplesPerPixel", ((IIOMetadataNode) metadata).getAttribute("SamplesPerPixel"));
            return result;
        } catch (IOException e) {
            throw new RuntimeException("Failed to extract TIFF metadata", e);
        }
    }
}
