// Define a node for the linked list
typedef struct PduNode {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct PduNode* next;
} PduNode;

// Define a mutex for thread-safe operations
pthread_mutex_t pduListMutex = PTHREAD_MUTEX_INITIALIZER;

// Global pointer to the head of the PDU list
PduNode* pduListHead = NULL;

// Function to generate random RNTI
int generateRandomRnti() {
    // Implement logic to generate a unique RNTI
    static int lastRnti = 0;
    pthread_mutex_lock(&pduListMutex);
    lastRnti = (lastRnti + 1) % 65536; // Simple round-robin generator
    pthread_mutex_unlock(&pduListMutex);
    return lastRnti;
}

// Function to generate random CRCFLAG
int generateRandomCrcFlag() {
    return rand() % 2; // Binary flag for CRC check
}

// Function to add a new PDU to the list
void addPduToList(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&pduListMutex);
    PduNode* newNode = (PduNode*)malloc(sizeof(PduNode));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    newNode->pdu = pdu;
    newNode->next = pduListHead;
    pduListHead = newNode;
    pthread_mutex_unlock(&pduListMutex);
}

// Function to generate and persist PDU list
void generateAndPersistNfalibPduList(int numberOfPDUs) {
